window.__BIRINCI_STORIES__ = {"site_title":"İbrətamiz deyimlər və hekayələr","lang":"az","categories":[{"title":"İman və mənəviyyat","slug":"iman-ve-meneviyyat","blurb":"İnanç, ibadət və ruhi yol axtarışına dair hekayələr.","count":36,"stories":[{"stem":"friend-of-allah","title":"Allahın dostu","hasAudio":false,"hasImage":true,"paragraphs":["Yaşlı bir kişi küçədə ayaqyalın bir uşaq gördü. Onu yaxınlıqdakı ayaqqabı dükanına aparıb bir cüt ayaqqabı aldı.","Uşaq təzə ayaqqabıları əlinə götürüb bir müddət səssizcə baxdı. Sonra başını qaldırıb soruşdu:","— Sən Allahsan?","Kişi kövrəldi. Gözləri doldu, uşağın qarşısında əyilib dedi:","— Yox, balam. Mən də sənin kimi bir insanam.","Uşaq bir az düşündü, sonra astadan dilləndi:","— Onda yəqin, Allahın dostusan. Dünən gecə ağlaya-ağlaya Ona demişdim ki, ayaqqabım yoxdur.","Kişi cavab verə bilmədi. Uşağın ayaqqabılarını geyinməsinə kömək etdi.","İbrət: Bəzən bir insanın duasında dilədiyi kömək başqasının mərhəməti ilə ona çatır. Sənin üçün kiçik görünən bir yaxşılıq kiminsə qəlbində böyük bir ümid oyada bilər."]},{"stem":"pleasure-of-allah","title":"Allahın rizası","hasAudio":false,"hasImage":true,"paragraphs":["Hacə Ubeydullah Əhrara aid edilən bir kəlamda deyilir:","«Allahın rizasına aparan yolları araşdırdım; ən qısa yolun insanların könlünü sevindirmək olduğunu gördüm.","İnsanı Allahın rizasından uzaqlaşdıran yolları araşdırdım; ən təhlükəli yolun könül qırmaq olduğunu gördüm.»","İbrət: Allahın rizasını insanların könlünü sevindirərək axtar. Bir qəlbə sevinc bəxş etmək səni Ona yaxınlaşdırar, qəlb qırmaq isə uzaqlaşdırar."]},{"stem":"gifts-of-allah","title":"Allahın verdiyi nemətlər","hasAudio":false,"hasImage":true,"paragraphs":["Allahın verdiyi hər nemət insana bir məsuliyyət də yükləyir. İnsan yalnız nəyə sahib olduğuna görə deyil, ona verilənlərin haqqını necə ödədiyinə görə də sorğuya çəkiləcək:","Güc verilibsə — onu nə qədər ədalətlə işlətdiyinə;","Vəzifə verilibsə — insanlarla nə qədər mərhəmətlə davrandığına;","Sərvət verilibsə — ondan nə qədər dürüst istifadə etdiyinə və onu xeyirxah məqsədlərə sərf etdiyinə;","Rahatlıq verilibsə — qədrini bilib şükür etdiyinə;","Ömür-gün yoldaşı verilibsə — ona nə qədər sədaqət və qayğı göstərdiyinə;","Övlad verilibsə — onu nə qədər sevgi, səbir və məsuliyyətlə böyütdüyünə.","İbrət: Hər nemət həm də bir imtahandır. İnsanın kimliyini sahib olduqları deyil, onların qədrini necə bildiyi və onlardan necə istifadə etdiyi göstərir."]},{"stem":"moderation-and-honesty","title":"Az yeyən və düz gedən","hasAudio":false,"hasImage":true,"paragraphs":["“Az yeyənin həkimlə, düz gedənin hakimlə işi olmaz”, — deyiblər.","Bu sözün hikməti yeməkdə ölçünü, davranışda dürüstlüyü qorumaqdadır.","“Az yemək” ac qalmaq deyil, bədəninin ehtiyacını duyub qədərində yeməkdir. “Düz getmək” isə başqasının haqqına girmədən, vicdanla və ədalətlə yaşamaqdır.","Əlbəttə, nə ölçülü qidalanmaq xəstəlikdən tam sığortalayır, nə də dürüstlük insanı hər haqsızlıqdan qoruyur. Bu kəlam bir zəmanət deyil, insanı öz seçimlərinə diqqətlə yanaşmağa çağıran öyüddür.","İbrət: Süfrədə ölçünü, həyatda dürüstlüyü qoru. Öz sağlamlığına qayğı, başqasının haqqına hörmət göstər."]},{"stem":"dervishs-robe","title":"Dərviş əbası","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün yaralı bir quş padşahın hüzuruna gəlib şikayət etdi:","— Bir dərviş qanadımı qırıb. Sizdən ədalət istəyirəm.","Padşah həmin adamı çağırtdırıb soruşdu:","— Bu quşun qanadını niyə qırmısan?","Dərviş əbalı adam özünə bəraət qazandırmağa çalışdı:","— Padşah sağ olsun, onu ovlamaq istəyirdim. Yaxınlaşdım, qaçmadı. Bir az da irəlilədim, yenə yerindən tərpənmədi. Elə bildim, onu asanlıqla tuta bilərəm. Amma əlimi uzadanda çırpınıb qaçmağa çalışdı. Qanadı da o vaxt qırıldı.","Padşah quşa tərəf döndü:","— Bəs sən onun yaxınlaşdığını görəndə niyə uçub getmədin?","Quş cavab verdi:","— Əynində dərviş əbası vardı. Ovçu olduğunu bilsəydim, uçub gedərdim. Düşündüm ki, Allahdan qorxan, mərhəmətli bir adamdır, mənə zərər verməz. Məni yerimdə saxlayan onun əbasına duyduğum inam idi.","Padşah bir an susdu, sonra qəzəblə əmr etdi:","— Elə isə onun da qolunu qırın!","Quş dərhal dilləndi:","— Yox, padşahım, bunu etməyin!","— Niyə? — deyə padşah təəccübləndi.","— Qolu sağalar, yenə kiməsə zərər verər. Siz onun əynindən dərviş əbasını çıxartdırın ki, mənim kimi başqaları da o libasa aldanıb ona güvənməsin.","İbrət: Etibar doğuran bir libas geyinmək o etibara layiq olmaq demək deyil. İnsanın kimliyini geyimi və adı deyil, davranışı göstərir. Libasa yox, əmələ bax."]},{"stem":"dervishs-long-spoons","title":"Dərviş qaşıqları","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün dərvişdən soruşdular:","— Həqiqətən sevənlə sevgidən yalnız danışan arasında nə fərq var?","— Bunu sizə göstərim, — deyə dərviş cavab verdi.","Əvvəlcə sevgidən çox danışan bir neçə adamı süfrəyə dəvət etdi. Qarşılarına isti şorba və sapı çox uzun olan qaşıqlar qoydurdu.","— Bir şərtim var, — dedi. — Qaşıqları yalnız saplarının ən ucundan tutacaqsınız.","Qonaqlar yeməyə başladılar. Amma qaşıqlar o qədər uzun idi ki, heç kim şorbanı öz ağzına çatdıra bilmirdi. Nə qədər çalışsalar da, şorba tökülür, qaşıqlar bir-birinə dəyirdi. Hər kəs yalnız özünü doyurmağa çalışırdı. Axırda yorulub ac halda süfrədən qalxdılar.","Sonra dərviş sevgisini əməlləri ilə göstərən insanları çağırdı. Onlara da eyni şorba, eyni qaşıqlar verildi, eyni şərt qoyuldu.","Qonaqlardan biri qaşığını doldurub qarşısındakına uzatdı. O biri də eyni cür cavab verdi. Az sonra hamı bir-birini yedirdirdi. Süfrə söhbət və gülüşlə canlandı, heç kim ac qalmadı.","Qonaqlar gedəndən sonra dərviş ona sual verənlərə üz tutdu:","— Qaşıqlar da eyni idi, şorba da. Fərq insanların bir-birinə münasibətində idi. Birinci süfrədə hər kəs yalnız özünü düşündü. İkincidə isə hər kəs qarşısındakının da qayğısına qaldı.","İbrət: Sevgi yalnız sözdə deyil, qayğıkeş əməllərdə görünür. Bir-birimizin ehtiyacını görəndə və köməyimizi əsirgəməyəndə çətinliyi birlikdə aşa bilərik."]},{"stem":"dervishs-appearance","title":"Dərvişin üst-başı","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün dərvişdən soruşdular:","— Üst-başın niyə belə səliqəsizdir?","Dərviş cavab verdi:","— İç dünyamı gözəlləşdirməyə o qədər başım qarışıb ki, üst-başıma baxmağa vaxt ayırmamışam.","İbrət: İnsanı yalnız geyiminə görə qiymətləndirmə. Səliqəli görünmək gözəldir, amma insanın əsl dəyəri qəlbinin təmizliyində və başqalarına münasibətində üzə çıxır."]},{"stem":"staying-on-the-right-path","title":"Doğru yoldan ayrılmamaq","hasAudio":false,"hasImage":true,"paragraphs":["Bir adam işləmədən, günlərini avara keçirərək mirasdan qalan var-dövləti xərcləyirdi. Nəhayət, bu həyatdan bezib padşahın yanına gəldi, dürüst və mənalı yaşamaq üçün ondan yol göstərməsini istədi.","Padşah bir qədər düşünüb dedi:","— Ağzınacan zeytun yağı ilə dolu bu küpü götür, bir damla belə tökmədən şəhərin o biri başına apar. Bircə damla töksən, boynunu vurduracağam.","Sonra ona nəzarət etmək üçün yanına iki əsgər qoşdu.","Adam bütün diqqətini küpə yönəltdi. Hər addımını ehtiyatla ataraq yağı bir damla da tökmədən deyilən yerə çatdırdı. Sonra saraya qayıdıb padşahın hüzuruna çıxdı:","— Padşah sağ olsun, əmrinizi qüsursuz yerinə yetirdim.","Padşah soruşdu:","— Bəs şəhərdə nə gördün? Yol boyu nələrə şahid oldun?","Həmin gün şəhərdə bazar qurulmuşdu. Küçələr elə izdihamlı idi ki, iynə atsaydın, yerə düşməzdi. Amma adam belə cavab verdi:","— Padşah sağ olsun, canımın hayında idim. Yağı tökməmək üçün elə diqqətlə gedirdim ki, gözümü bir an belə küpdən ayırıb ətrafa baxmadım. Nə adamları gördüm, nə də baş verənlərə fikir verdim.","Padşah dedi:","— Axtardığın dərs elə budur. Gördüyün işə, üzərinə götürdüyün vəzifəyə bu cür diqqət və məsuliyyətlə yanaş. Özünü işinə ver və Allahın səni hər zaman gördüyünü unutma. Onda doğru yoldan ayrılmamaq sənin üçün daha asan olar.","İbrət: Doğru yolda qalmaq gündəlik seçimlərdən başlayır. İşinə diqqətlə, öhdəliyinə məsuliyyətlə yanaşmaq və Allah qarşısında cavabdeh olduğunu unutmamaq insanı yanlış addımlardan çəkindirir."]},{"stem":"prayer-finds-you","title":"Dua gəlib tapsın səni","hasAudio":false,"hasImage":true,"paragraphs":["Ağsaqqallarımız deyiblər:","Bir yoxsula dayaq, bir möhtacın döyə biləcəyi qapı, bir yetimin başını sığallayan əl, bir uşağın ayağını soyuqdan qoruyan başmaq ol.","Darda qalana yol aç, çətinliyə düşənə kömək et ki, ehtiyac duyduğun dua özü gəlib səni tapsın.","İbrət: Ürəkdən edilən yaxşılıq kiminsə qəlbində minnətdarlığa, dilində duaya çevrilir. Bəzən insanın özü üçün dilədiyi xeyir başqasına göstərdiyi mərhəmətdən doğur."]},{"stem":"prayer-for-relief","title":"Ey Allahım, dərdlərimizə çarə et","hasAudio":false,"hasImage":true,"paragraphs":["Ey Allahım!","Rəhman və Rəhim adlarınla dərdlərimizə çarə et.","Qəffar və Təvvab adlarınla günahlarımızı bağışla, tövbələrimizi qəbul et.","Rəzzaq adınla ruzimizə bərəkət ver.","Şafi adınla xəstələrimizə şəfa ver.","Fəttah adınla üzümüzə xeyirli qapılar aç.","İbrət: Səmimi dua insanın həm acizliyini, həm də ümidini ifadə edir. Allaha üz tutmaq qəlbə təsəlli, çətinliklər qarşısında dözüm verə bilər."]},{"stem":"give-to-me-last","title":"Ey Allahım, əvvəlcə dağa-daşa ver","hasAudio":false,"hasImage":true,"paragraphs":["Türk ellərində söyləndiyi rəvayət olunan bir dua var:","— Ey Allahım, nemətini əvvəlcə dağa-daşa, meşəyə, heyvanlara, sulara ver. Sonra insanlara, qapı qonşuma, möhtac olana ver. Bir şey qalarsa, ən sonda mənə ver!","İbrət: Comərdlik yalnız əlindəkini bölüşmək deyil, diləyində də başqasına yer ayırmaqdır. Bu dua insanı bütün canlıların ruzisini və rifahını düşünməyə çağırır."]},{"stem":"my-alif-has-been-dotted","title":"Əlifim nöqtələndi","hasAudio":false,"hasImage":true,"paragraphs":["Türkiyə türkcəsində «elifim noktalandı» — «əlifim nöqtələndi» deyə bir ifadə var. Bu ifadə «ah çəkirəm, qəlbim ağrıyır» mənasında işlənir; sevincin kədərə dönməsini obrazlı şəkildə dilə gətirir.","İfadənin bir izahı əski Osmanlı yazısındakı hərflərin görünüşü ilə bağlıdır. «Əlif» (ا) hərfinin yanına «hə» (ه) gələndə «ah» sözü yaranır. Əlifin yanında kiçik, yumru görünən «hə» nöqtəyə bənzədilir. «Əlifim nöqtələndi» deyimi də bu bənzətmə ilə açıqlanır.","Bu poetik yozumda dik və incə əlif gözəlliyi, sərbəstliyi xatırladır. Yanına gələn bükülü «hə» isə sanki dərdin ağırlığını daşıyır. İki hərf birləşir və bir ah səsinə çevrilir.","Beləcə, hərflərin görünüşündə insan qəlbinin halı ifadə olunur: bir az əvvəl sevinc olan yerdə indi kədər var.","İbrət: Bəzən kiçik bir dəyişiklik böyük bir duyğunu ifadə edir. Dil yalnız düşüncələrimizi deyil, sevincimizin və kədərimizin izlərini də yaşadır."]},{"stem":"hands-at-work-hope-in-god","title":"Əlin işdə, ümidin Allahda","hasAudio":false,"hasImage":true,"paragraphs":["Bir zamanlar bir dərviş varmış. Gününün çoxunu tənhalığa çəkilib ibadətlə keçirərmiş. Dolanışığını isə öz zəhməti ilə təmin edərmiş: hər gün bir qədər işləyər, qazandığı pulla çörək alar, ehtiyacından artıq qalanı yoxsullarla bölüşərmiş.","Bir gün səhrada ibadət edərkən ayaqları şikəst bir tülkü görür. Heyvan sürünə-sürünə güclə irəliləyirmiş. Dərviş düşünür:","«Bu tülkü necə dolanır? Ov edə bilmir, heç rahat yeriyə də bilmir. Görəsən, Allah onun ruzisini necə yetirir?»","Elə bu vaxt uzaqdan bir aslan görünür. Ağzında ovladığı ceyranı sürüyüb gətirir. Ovunu yerə qoyur, doyunca yeyir, qalanını orada qoyub gedir.","Kənarda gözləyən tülkü sürünə-sürünə yaxınlaşır, qalan ətdən yeyib qarnını doyurur.","Dərviş gördüklərinə heyran qalır. Tülkünün ruzisini aslanın vasitəsilə yetirən Allaha həmd edir. Sonra öz-özünə deyir:","«Tülküyə ruzi yetirən Allah məni də ac qoymaz. İşə ayırdığım vaxtı ibadətlə keçirərəm. Daha işləməyə ehtiyac yoxdur».","Həmin gündən işi buraxıb bütün vaxtını ibadətə həsr edir. Lakin gözlədiyi ruzi gəlmir. Nə qapısını döyən olur, nə də ona bir tikə çörək gətirən. Gün keçdikcə zəifləyib taqətdən düşür.","Nəhayət, bir gün qeybdən bir səs eşidir:","— Sənə işləmək üçün güc və sağlamlıq verdim. Bəs niyə özünü yeriyə bilməyən tülküyə bənzətdin? Niyə aslandan nümunə götürmədin? Qalx, çalış, ruzini qazan. Qoy sənin zəhmətindən köməyə ehtiyacı olanlar da faydalansın. Həm özün ye, həm də möhtacı doyur.","Dərviş gördüklərindən yanlış nəticə çıxardığını anlayır. Tövbə edib əvvəlki həyatına qayıdır. Yenidən öz zəhməti ilə dolanır, qazandığını ehtiyacı olanlarla bölüşür.","İbrət: Təvəkkül əlini işdən çəkmək deyil, əlindən gələni edib Allaha güvənməkdir. Gücün və imkanın varsa, çalış ki, həm özün dolanasan, həm də başqasına dayaq olasan."]},{"stem":"lifes-finest-blessing","title":"Ən gözəl nəsib","hasAudio":false,"hasImage":true,"paragraphs":["Dərvişdən soruşdular:","— İnsana nəsib ola biləcək ən gözəl şey nədir?","Dərviş cavab verdi:","— Səni ürəkdən dinləmək istəyən birinə rast gəlmək.","İbrət: Səni dinləməyə könüllü olan insan sənə vaxtını və diqqətini bəxş edir. Səmimiyyətlə dinlənilmək insana dəyərli olduğunu və tək olmadığını hiss etdirir."]},{"stem":"honestly-earned-morsel","title":"Halal tikə","hasAudio":false,"hasImage":true,"paragraphs":["Un təzə, su tərtəmiz olsa da, maya xarabdırsa, xəmir yaxşı acımaz. Belə xəmirdən yaxşı çörək də alınmaz.","Gözəl əxlaqlı övlad böyütmək üçün onu halal qazancla əldə edilmiş tikə ilə bəsləmək lazımdır.","— İmam Qəzaliyə aid edilən fikir","İbrət: Övladın mənəvi tərbiyəsi ailədə gördüyü nümunədən başlayır. Halal zəhmətlə qazanılan ruzi, dürüstlük və başqasının haqqına hörmət bu tərbiyənin möhkəm təməlidir."]},{"stem":"power-of-justice","title":"Haqqın qüdrəti","hasAudio":false,"hasImage":true,"paragraphs":["Haqqın nə qılıncı əyilər, nə də biləyi bükülər.","İbrət: Haqqın gücü vəzifədən, sərvətdən və zorakılıqdan gəlmir. Zaman dəyişsə də, ədalətin dəyəri dəyişməz. Haqqın yanında durmaq insana mənəvi güc verir."]},{"stem":"hajj-pilgrimage","title":"Həcc ziyarəti","hasAudio":false,"hasImage":true,"paragraphs":["Bir rəvayətə görə, həcc ziyarətində olan bir adam şeytana daş atmaq mərasimi zamanı daşları özünə tərəf yönəldir. Bunu görən bir gənc təəccüblə soruşur:","— Ay dayı, nə edirsən? Niyə özünü daşlayırsan?","Adam cavab verir:","— Oğul, buradakı şeytanı daşlamaqla iş bitmir. İnsan əvvəl öz içindəki pisliyə qalib gəlməli, nəfsini tərbiyə etməli, qəlbini təmizləməlidir.","Hərarət oddadır, sacda deyildir, Kəramət başdadır, tacda deyildir. Hər nə axtarırsansa, özündə axtar, Qüdsdə, Məkkədə, həcdə deyildir.","İbrət: İnsanın ən çətin mübarizəsi öz nəfsi ilədir. Bu rəvayətdə özünə yönələn daş daxili hesabatın rəmzidir: məqsəd bədənə əzab vermək deyil, qəlbi kindən, təkəbbürdən və tamahdan təmizləməkdir. Ziyarətin mənası da insanın daxilində yaratdığı dəyişikliklə tamamlanır."]},{"stem":"confidence-is-half-the-battle","title":"İnam uğurun yarısıdır!","hasAudio":false,"hasImage":true,"paragraphs":["Bir ibrətamiz hekayədə deyilir ki, məktəb direktoru bir neçə müəllimi yanına çağırıb belə bir tapşırıq verdi:","— Siz məktəbimizin ən bacarıqlı müəllimlərindənsiniz. Buna görə də seçdiyimiz istedadlı şagirdlərdən ibarət bir sinfi sizə həvalə edirik. İstəyirik ki, bu il onların bacarıqlarını daha da inkişaf etdirəsiniz.","Müəllimlər bu etimaddan ruhlandılar. Dərslərə həvəslə hazırlaşır, yeni üsullar sınayır, çətinlik çəkən şagirdlərə səbirlə kömək edirdilər. Uşaqlar da onlara göstərilən inamı hiss edir, sual verməkdən və çətin tapşırıqlara girişməkdən çəkinmirdilər.","Dərs ilinin sonunda sinif yüksək nəticələr göstərdi. Müəllimlər də, şagirdlər də sevinirdilər.","Direktor müəllimləri təbrik edib dedi:","— Sizə bir həqiqəti açıqlamalıyam. Bu uşaqları xüsusi qabiliyyətlərinə görə seçməmişdik. Sinif təsadüfi seçimlə yaradılmışdı.","Müəllimlər bir-birinə baxdılar. Deməli, uşaqların irəliləyişində onların zəhmətinin böyük payı vardı.","Direktor davam etdi:","— Sizi də müsabiqə ilə seçməmişdim. Adlarınızı püşklə müəyyənləşdirmişdim.","Otağa sükut çökdü.","— Siz həm öz bacarığınıza, həm də uşaqların bacarığına inandınız, — direktor dedi. — Sonra bu inamı zəhmətə, səbrə və qayğıya çevirdiniz. Nəticəni yaradan da elə bu oldu.","İbrət: İnam təkbaşına uğur yaratmır, amma insanı cəhd etməyə, öyrənməyə və davam etməyə ruhlandıra bilər. Birinin bacaracağına inanırsansa, ona bunu göstər və inkişafı üçün dayaq ol."]},{"stem":"devil-out-of-work","title":"İşsiz şeytan","hasAudio":false,"hasImage":true,"paragraphs":["Bir dərviş fikrə dalmışdı. Birdən yanında sakitcə oturan şeytanı görüb soruşdu:","— Nə olub, belə sakit oturmusan? Heç kimi yoldan çıxarmırsan?","Şeytan yorğun halda başını qaldırdı:","— Siz insanlar bir-birinizə o qədər zərər verir, elə əzab çəkdirirsiniz ki, mənə daha iş qalmır.","İbrət: İnsanların bir-birinə verdiyi əzabı azaltmaq öz əlimizdədir. İncitmək əvəzinə anlayış göstərmək, haqsızlığa susmamaq və çətinlik çəkənə dayaq olmaq bunun yoludur."]},{"stem":"door-to-the-heart","title":"Kainat işığı","hasAudio":false,"hasImage":true,"paragraphs":["Britaniyalı rəssam Uilyam Holman Hantın «Kainat işığı» əsəri Londondakı Kral İncəsənət Akademiyasında nümayiş etdirilmişdi. Rəsmdə gecə vaxtı əlində fənər tutaraq bağlı qapını döyən İsa Məsih təsvir olunur. O, qapının açılmasını gözləyir.","Rəvayətə görə, əsərə diqqətlə baxan bir sənətşünas rəssamdan soruşur:","— Gözəl rəsmdir, amma bir məqamı anlamıram. Bu qapı necə açılacaq? Bəlkə, dəstəyini çəkməyi unutmusunuz?","Hant gülümsəyərək cavab verir:","— Bu, adi qapı deyil, insan qəlbinin qapısıdır. Ona görə də bayır tərəfində dəstəyi yoxdur. Bu qapı yalnız içəridən açılır. İçəridəki açmasa, heç kim oraya girə bilməz.","İbrət: Qəlbin qapısı yalnız içəridən açılır. Sevgi və xeyirxahlıq o qapını döyə bilər, amma onları içəri buraxmaq insanın öz seçimidir."]},{"stem":"church-bell","title":"Kilsə zəngi","hasAudio":false,"hasImage":true,"paragraphs":["Deyilənə görə, qədim zamanlarda bir ölkədə belə bir adət varmış: adi vətəndaş vəfat edəndə kilsənin zəngi bir dəfə, zadəgan öləndə iki dəfə, kralın yaxınlarından biri dünyasını dəyişəndə üç dəfə, kralın özü öləndə isə dörd dəfə çalınarmış.","Bir gün insanların haqq-ədalət tapmaq ümidi ilə üz tutduğu məhkəmə günahsız bir adamı məhkum etdi.","Həmin gün kilsənin zəngi beş dəfə çalındı.","Təəccüblənən camaat kilsənin qarşısına toplaşıb keşişdən soruşdu:","— Kraldan da mühüm kim ölüb ki, zəngi beş dəfə çaldınız?","Keşiş kədərlə cavab verdi:","— Ədalət. Bu gün ədalət öldü.","İbrət: Ədalətsiz hökm yalnız bir insanı incitmir, hamının haqqa inamını sarsıdır. Haqsızlığa susmamaq təkcə zərər çəkəni deyil, cəmiyyətin vicdanını da qorumaqdır."]},{"stem":"vizier-and-the-scholar","title":"Vəzir və alim","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün uzaq bir məmləkətdən padşahın yanına bir alim gəldi. Tərcüməçi vasitəsilə xeyli söhbət etdikdən sonra yerli alimlərlə görüşüb elmi mübahisə aparmaq istədiyini bildirdi.","Padşah ölkənin alimlərini bir yerə topladı. Lakin heç biri əcnəbi alimlə mübahisəyə girişməyə cəsarət etmədi. Onların tərəddüdünü görən vəzir axırda irəli çıxdı:","— Mən danışaram onunla!","Məclis quruldu. Əcnəbi alim yerdə bir dairə çəkib vəzirə baxdı. Vəzir bir qədər düşündükdən sonra dairəni iki yerə böldü. Alimin dinmədiyini görüb bir xətt də çəkdi, dairəni dörd yerə ayırdı. Sonra üç hissəni özünə götürürmüş, birini isə qonağa verirmiş kimi işarə etdi. Alim razılıqla başını tərpətdi.","Sonra qonaq əlini ovucu yuxarı olmaqla tutub cavab gözlədi. Vəzir də əlini tərsinə çevirdi, barmaqlarını aşağı yönəltdi. Alim bu cavabdan da razı qaldı.","Üçüncü dəfə alim özünü göstərib yemək yeyirmiş kimi hərəkət etdi. Vəzir dərhal cibindən bir yumurta çıxardı, sonra qollarını quş qanadı kimi çırpdı. Alim gülümsəyərək vəzirin əlindən öpdü. Vəzir də məclisdən ayrıldı.","Padşah tərcüməçi vasitəsilə qonaqdan soruşdu:","— Bu işarələrlə bir-birinizə nə dediniz? Biz heç nə anlamadıq.","Alim həvəslə izah etdi:","— Dairəni çəkməklə Yerin kürə şəklində olduğunu bildirdim və vəzirinizin bu barədə fikrini öyrənmək istədim. Maşallah, o, dərhal ekvatoru çəkdi! Sonra dairəni dörd yerə bölərək Yer səthinin təxminən dörddə üçünün su, bir hissəsinin isə quru olduğunu göstərdi.","Bir qədər dayanıb davam etdi:","— Sonra bitkilərin necə yaşadığını soruşdum. O da onların yağış və günəş işığı sayəsində yaşadığını işarələrlə izah etdi. Axırda insanlarla heyvanlar haqqında fikrini bilmək istədim. Yumurtanı göstərib qanad çalmaqla quşları da unutmadığını bildirdi. Çox bilikli adamdır!","Qonaq gedəndən sonra padşah vəziri çağırdı:","— İndi də sən danış görək, alimlə nə söhbət edirdiniz?","Vəzir əlini yellədi:","— Eh, alim!.. Mən də elə bilirdim, dərin düşüncəli adamdır. Sən demə, fikri-zikri yeməkdə imiş! Əvvəl yerdə dairə çəkdi ki, kaş burada bir tava qayğanaq olaydı. Mən də yarıya böldüm ki, hamısı sənə çatmaz, biz də varıq!","— Bəs sonra? — deyə padşah soruşdu.","— Gördüm, dinmir. Elə bildim, yarı bölməyə razı deyil. Mən də qayğanağı dörd yerə bölüb üç payını özümə götürdüm ki, acgözlük eləsən, belə olar! Gördü, qayğanaq əldən gedir, tez razılaşdı.","Vəzir sözünə davam etdi:","— Sonra ovucunu yuxarı tutdu ki, bir qazan plova nə deyirsən? Mən də əlimi üzüaşağı tutdum ki, üstündə qarası da olsa, yeyərəm. Axırda qarnını göstərib dedi ki, yoldan gəlmişəm, acam. Mən də yumurtanı çıxardım ki, vallah, mən səndən də acam, cibimdə də elə bircə yumurta var. Heç istəmə, verə bilməyəcəyəm!","İbrət: Eyni söz və işarəni hər kəs öz düşüncəsinə görə anlaya bilər. Qarşılıqlı razılıq həmişə bir-birini anlamaq demək deyil; nəticə çıxarmazdan əvvəl qarşı tərəfin nə demək istədiyini dəqiqləşdirmək lazımdır."]},{"stem":"price-of-a-miracle","title":"Möcüzənin qiyməti","hasAudio":false,"hasImage":true,"paragraphs":["Liza valideynlərinin kiçik qardaşı Oliver haqqında danışdıqlarını eşidəndə səkkiz yaşında idi. Bildiyi yalnız bu idi: qardaşı ağır xəstədir, ata-anasının isə onun müalicəsinə pulu çatmır.","Oliveri yalnız çox bahalı bir əməliyyat xilas edə bilərdi. Ailəyə borc verəcək kimsə də yox idi. Liza atasının gözüyaşlı anasına çarəsizcə pıçıldadığını eşitdi:","— İndi onu ancaq möcüzə xilas edə bilər.","Qız otağına keçdi, şkafda gizlətdiyi şüşə qabı çıxardı. Yığdığı qəpikləri yerə töküb bir neçə dəfə saydı. Sonra hamısını yenidən qaba yığdı, qapağını bağladı və arxa qapıdan çıxıb aptekə yollandı.","İçəri girib əczaçının ona diqqət yetirməsini gözlədi. Amma əczaçı söhbətə elə aludə olmuşdu ki, qızcığazı görmürdü. Liza gah tərpənir, gah boğazını arıtlayırdı. Nəhayət, qabdan bir neçə qəpik çıxarıb şüşə piştaxtaya qoydu. Qəpiklərin cingiltisinə əczaçı dönüb baxdı:","— Nə istəyirsən, qızım? — deyə səbirsizliklə soruşdu. — Çoxdandır görmədiyim qardaşımla danışıram.","— Mən də sizinlə qardaşım haqqında danışmaq istəyirəm, — Liza qətiyyətlə dedi. — O xəstədir. Onu sağaltmaq üçün mənə möcüzə lazımdır.","— Möcüzə?","— Qardaşımın adı Oliverdir. Beynində pis bir şey böyüyür. Atam deyir ki, indi onu yalnız möcüzə xilas edə bilər. Bir möcüzə neçəyədir?","Əczaçının səsi yumşaldı:","— Biz burada möcüzə satmırıq, qızım. Bağışla, sənə kömək edə bilməyəcəyəm.","— Axı mənim pulum var. Çatmasa, qalanını da tapıb gətirərəm. Siz bircə qiymətini deyin.","Söhbəti dinləyən səliqəli geyimli kişi — əczaçının qardaşı — əyilib qızdan soruşdu:","— Qardaşına necə bir möcüzə lazımdır?","— Bilmirəm, — Liza cavab verdi. — Bircə onu bilirəm ki, çox xəstədir. Anamla atam deyirlər, əməliyyat olunmalıdır. Onların pulu yoxdur. Ona görə öz pulumu gətirmişəm.","— Nə qədər pulun var?","— Bir dollar on bir sent, — qız asta səslə dedi. — Bütün pulum budur. Amma lazım olsa, bir az da taparam.","Kişi gülümsədi:","— Bir dollar on bir sent… Nə gözəl təsadüfdür! Qardaşına lazım olan möcüzənin qiyməti elə bu qədərdir.","O, qızın pulunu aldı, əlindən tutub dedi:","— Məni evinizə apar. Qardaşını görmək, valideynlərinlə danışmaq istəyirəm. Görək, axtardığın möcüzə üçün nə edə bilərik.","Bu kişi neyrocərrah doktor Karlton Armstronq idi.","Əməliyyat üçün ailədən pul alınmadı. Çox keçmədən Oliver sağalıb evə qayıtdı. Ata-anasının sevincinin həddi yox idi.","Bir gün anası atasına pıçıldadı:","— Bu, əsl möcüzə idi. Görəsən, o əməliyyat bizə neçəyə başa gələrdi?","Liza gülümsədi. O, möcüzənin qiymətini yaxşı bilirdi: bir dollar on bir sent və qardaşının xilas olacağına sarsılmaz inam.","İbrət: Ümid insanı kömək axtarmağa, mərhəmət isə dərd çəkənə əl uzatmağa sövq edir. Bəzən bir uşağın saf inamı bir insanın biliyi və xeyirxahlığı ilə birləşəndə mümkünsüz görünənə çarə tapılır."]},{"stem":"begin-with-self-examination","title":"Əvvəl özünə nəzər sal","hasAudio":false,"hasImage":true,"paragraphs":["Dərvişdən soruşurlar:","— Müsibət nədən gəlir?","Dərviş cavab verir:","— Əvvəlcə öz əməllərinə nəzər sal:","Gözünü yoxla — harama baxmısanmı?","Dilini, qulağını yoxla — qeybət etmisənmi, dedi-qoduya qulaq asmısanmı?","Əlini yoxla — harama əl uzadıb ruzinə haram qatmısanmı?","Addımlarını yoxla — getməməli olduğun yerə getmisənmi?","İbrət: Hər müsibət insanın öz əməlindən doğmur. Amma özünə dürüst nəzər salmaq, səhvini görüb düzəltmək insanın məsuliyyətidir. Baxışına, sözünə, qazancına və getdiyin yola diqqət et."]},{"stem":"adversity-and-blessing","title":"Müsibət və nemət","hasAudio":false,"hasImage":true,"paragraphs":["Səni Allaha yaxınlaşdıran müsibətin içində bir nemət gizlənə bilər.","Səni Allahdan uzaqlaşdıran nemət isə müsibətə çevrilə bilər.","İbrət: Yaşadıqlarını yalnız gətirdiyi ağrı və ya rahatlıqla ölçmə. Onların sənin qəlbində nəyi dəyişdirdiyinə, səni hansı yola yönəltdiyinə də bax."]},{"stem":"why-wait","title":"Niyə dünyanın son gününü gözləyirsiniz?","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün Amerikada bir universitet müəllimi dərsə belə bir sualla başlayır:","— Təsəvvür edin ki, bu gün dünyanın son günüdür. Sabah bu vaxt hər şey bitəcək və bundan xilas olmaq mümkün deyil. Qalan vaxtınızı necə keçirərdiniz?","Tələbələr bir-bir cavab verirlər:","— İbadət edər, Allahdan günahlarımı bağışlamasını diləyərdim.","— Bütün sevdiklərimlə vidalaşardım.","— Qalan vaxtımı ailəmlə keçirərdim.","— Valideynlərimə baş çəkərdim.","— Sevdiyim yeməklərdən son dəfə dadardım.","— Doyunca yatardım.","— Meşədə gəzər, təbiətin gözəlliyindən zövq alardım.","— Günəşin doğuşunu və batışını seyr edərdim.","— Gecə ulduzlara baxardım.","— Ən sevdiyim yeməyi bişirib əzizlərimi bir süfrə başına yığardım.","— Həmişə görmək arzusunda olduğum yerə gedər, son anlarımı orada keçirərdim.","— İncitdiyim insanları tapıb üzr istəyər, məni bağışlamalarını xahiş edərdim.","Müəllim bütün cavabları lövhəyə yazır. Sonra gülümsəyib soruşur:","— Bəs bütün bunları etmək üçün niyə dünyanın son gününü gözləyirsiniz?","İbrət: Həyatında ən qiymətli olanları son günə saxlama. Sevgini bildir, üzr istə, əzizlərinə vaxt ayır, sadə sevinclərin qədrini bu gün bil."]},{"stem":"fasting","title":"Oruclu olmaq","hasAudio":false,"hasImage":true,"paragraphs":["Ramazan ayında bir neçə gənc bir kənarda oturub yemək yeyən yaşlı kişini gördü. Ona yaxınlaşıb istehza ilə soruşdular:","— Xeyir ola, dayı? Yemək yeyirsən? Bəs oruclu deyilsən?","Yaşlı kişi sakitcə cavab verdi:","— Orucluyam, balalarım. Sadəcə yeyib-içirəm.","Gənclər gülüşdülər:","— Bu necə orucdur?","Qoca dedi:","— Dilimi yalandan, gözümü pis baxışdan, əlimi başqasının malından saxlayıram. Heç kimi ələ salmır, alçaltmır, qeybət etmirəm. İsrafdan çəkinirəm. Xəstəliyimə görə ac qala bilmirəm, amma çalışıram, sözüm və əməlim bu ayın ruhuna uyğun olsun.","Sonra soruşdu:","— Bəs siz necə, oruclusunuz?","Gənclər xəcalətlə başlarını aşağı saldılar:","— Deyəsən, biz sadəcə yemək yemirik...","İbrət: Orucun mənəvi dəyəri yalnız aclığa dözməkdə deyil, dili, düşüncəni və davranışı da tərbiyə etməkdədir. Başqasını mühakimə etməzdən əvvəl onun halını anlamağa, öz əməllərinə nəzər salmağa çalış."]},{"stem":"my-lifes-journey","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/my-lifes-journey.webp","title":"Ömür yolum","hasAudio":false,"hasImage":true,"paragraphs":["Ömrüm boyu işıq saçar həyatıma arzularım","İllərimə nur ələyər xoş ovqatlı hər sabahım","Ümidlərim azalanda, çoxalanda qayğılarım","Yol göstərən pənahımdır uca Tanrım — qibləgahım!","Xoşbəxt odur — sağlam ola, təmiz qəlbli insan ola","Əməlləri gözəl, dürüst, tutduğu yol düzgün ola","Öz nəfsinə qalib olub, xoş niyyətə sadiq ola","Çətin gündə nicatımdır uca Tanrım — ümidgahım!","Möcüzələr sərgilənər təbiətin naxışında","Həyat məna kəsb eləyər hərənin öz baxışında","Hikmət parlar hər sınağın, çətinliyin arxasında","Həyatımdır, varlığımdır uca Tanrım — səcdəgahım!","Etibar Siracsoy"]},{"stem":"gratitude-at-the-sink","title":"Qab-qacağınızı yuyarkən dua edin","hasAudio":false,"hasImage":true,"paragraphs":["Qab-qacağınızı yuyarkən dua edin. Yuyulacaq qablarınızın olduğuna görə şükür edin. O qablar süfrənizdə yemək olduğunun, özünüzü və ya sevdiklərinizi doyurduğunuzun, qayğı göstərdiyinizin izidir.","Həmin an yeməyə bir tikə çörək tapmayanları, süfrəsini bölüşəcək kimsəsi olmayanları da xatırlayın. Duanızda onlara da yer ayırın.","İbrət: Gündəlik qayğıların içində gözdən qaçırdığımız nemətlər var. Bəzən yuyulmağı gözləyən bir qab belə şükür üçün səbəbdir. Minnətdarlıq bu nemətləri görməkdən, mərhəmət isə onlardan məhrum olanları unutmamaqdan başlayır."]},{"stem":"fortieth-day-rite","title":"Qırx çıxarma","hasAudio":false,"hasImage":true,"paragraphs":["Bəzi türk toplumlarında doğuşdan sonrakı ilk qırx gün ana ilə körpənin xüsusi qayğı ilə əhatə olunduğu dövr sayılır. Bu müddətdə evdən çıxmaq və qonaq qəbul etmək barədə adətlər bölgədən-bölgəyə, ailədən-ailəyə dəyişir.","“Qırx çıxarma” ilə bağlı nəql olunan adətlərdən birində qırx gün tamam olanda ana ilə körpə yaxınlarının evinə dəvət edilir. Körpə üçün hazırlanan kiçik sovqatların hər biri bir xoş arzu daşıyır:","Xırda pul — ruzisi bol olsun deyə;","Pambıq — saçları ağaranadək yaşasın, qəlbi yumşaq olsun deyə;","Şəkər — ömrü şirin, üzü gülər olsun deyə;","Düyü — evindən bərəkət əskik olmasın deyə;","Duz — həyatının dadı-duzu qaçmasın deyə;","Yumurta — qarnı tox, canı sağlam olsun deyə.","Bunlar körpənin gələcəyini müəyyən edən əşyalar deyil, onun üçün dilənən gözəl bir ömrün rəmzləridir.","İbrət: Bəzən kiçik bir hədiyyənin içində böyük bir arzu yaşayır. Bu adətin gözəlliyi sovqatların qiymətində yox, ana ilə körpəyə göstərilən qayğıda və gələcəyə ünvanlanan xeyir-duadadır."]},{"stem":"if-fate-allows","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/if-fate-allows.webp","title":"Qismət olarsa, görüşərik","hasAudio":false,"hasImage":true,"paragraphs":["Həmişə «görüşərik» deyən adam indi «qismət olsa, görüşərik» deyir. Burada bir qəriblik var. Mən dəyişməmişəm, ona münasibətim də əvvəlki kimi istidir. Onunla yenə böyük məmnuniyyətlə görüşmək istərdim. Amma bu «qismət olsa» sanki aramızda bir sədd olub. Mən onun qismətindən xəbərsizəm, o da mənimkindən. Görəsən, bu iki qismətin bir-birindən xəbəri varmı, öz aralarında razılaşıb bizi görüşdürə bilərlərmi?","Bəlkə, qismətdən heç nə gözləmək lazım deyil? Bəlkə, bu da “gözdən uzaq, könüldən iraq” dedikləridir?","Heç sevmədim mən bu «qismət olsa» ifadəsini.","İbrət: Sevdiklərinlə arana soyuqluq buraxma. «Qismət olsa» deyib təxirə salma — bu gün görüş, bu gün könül al.","Bəxtiyar Siracov"]},{"stem":"sacrificial-meat","title":"Qurban əti","hasAudio":false,"hasImage":true,"paragraphs":["Beşinci sinifdə oxuyurdum. Dolanışığımız pis deyildi, heç kimə möhtac deyildik. Bənna işləyən atam mənzil-tikinti kooperativinə üzv olmuşdu. «Altı-yeddi aya öz evimizə köçərik», — deyə ümidlə günləri sayırdıq.","Bir səhər güclü silkələnməyə oyandıq. Zəlzələ olmuşdu. Şükür ki, nə ailəmizə, nə də yaxın ətrafımızdakılara bir zərər dəymişdi. Binamızda hamı sağ-salamat idi. Amma zəlzələ həyatımıza başqa bir çətinlik gətirdi: tikintilər dayandı, atam işsiz qaldı.","Nə qədər qənaət etsək də, onun arabir tapdığı təmir işlərindən qazandığı pul dolanışığımıza çatmırdı. Qış boyu atam iş axtardı. Hər səhər ümidlə çıxır, axşam pərişan qayıdırdı.","Ramazan bayramına bir neçə gün qalmış evə sevinclə gəldi. İş tapmışdı!","— «Sənədlərini hazırla, gəl», — dedilər. Bu gün çatdırmalıyam!","Sənədlərini götürüb tələsik çıxdı.","Bir neçə saat sonra qapı qonşumuz təlaşla içəri girdi. Üzündəki ifadə ürəyimizi sıxdı.","— Qorxmayın, atanız qəza keçirib… — dedi.","Xəstəxanada atamı görəndə rəngi ağappaq idi. Qolu və ayaqları sarınmışdı. Qırmızı işıqda dayanmayan bir maşın onu vurmuşdu.","Biz sağ qaldığına şükür edirdik. O isə göz yaşlarını gizlətməyə çalışırdı:","— Kaş belə olmayaydı… İndi bir də mənim yükümü çəkəcəksiniz.","Bir müddət sonra evə qayıtdı. Sobamız yanmırdı, otaqlar soyuq idi. Qonşulardan bir neçəsi bələdiyyəyə zəng edib bizim üçün kömür istəmişdi. Amma «əvvəlcədən qeydiyyatdan keçmək lazım idi» deyib verməmişdilər.","Şirniyyatsız, sovqatsız Ramazan bayramımız da beləcə keçdi.","Havalar yavaş-yavaş isindi. Atamın qolundakı sarğı açıldı, amma ayağı hələ sağalmamışdı.","Sonra Qurban bayramı gəldi.","İçimdə bir ümid vardı: «Binamızda on iki mənzil var. Qonşuların bir çoxu qurban kəsəcək. Yəqin, bizə də pay gətirərlər. Anam da sevdiyim ət yeməklərindən bişirər».","Pəncərədən baxırdım. Qarşıdakı boş sahədə qurbanlar kəsildi, ətlər bölündü, dolu ləyənlər evlərə daşındı. Qapılar açıldıqca qovrulan ətin ətri bizə qədər gəlib çatırdı.","Amma bizim qapımız döyülmədi. Heç kim bir tikə ət də gətirmədi.","Həmin gün nənəm kənddən zəng vurub bayramımızı təbrik etdi. Səsimdən bir şey olduğunu duydu.","— Nə olub, bala? Atanın halı pisləşib? — deyə narahatlıqla soruşdu.","— Yox, — dedim astadan. — Qonşular bizə qurban əti vermədilər.","Yayda nənəmgilə gedərdik. Bir inəyi, beş-altı toyuğu vardı. İnəyi bol süd verirdi. Nənəm onu sağanda həmişə mahnı oxuyardı.","Bayramın üçüncü günü səhər tezdən qapımız döyüldü.","Nənəm gəlmişdi.","Sevinclə üstünə qaçdıq. O, göz yaşları içində hamımızı qucaqladı:","— Quzularım… Sizə çoxlu ət gətirmişəm!","Soyuducumuz ətlə doldu. Bacım dərhal bir azını doğramağa başladı. Az sonra ocaqdan iki gündür gözlədiyim yeməyin ətri gəlməyə başladı.","Süfrənin açılmasını gözləyə bilmirdim. Ocağın yanında dayanıb çəngəllə bir tikə götürdüm. Üfürə-üfürə ağzıma aparırdım ki, atamın sözlərini eşitdim:","— Ay ana… Niyə kəsdin o inəyi?","Əlim havada qaldı.","Ürəyim bulandı, başım gicəlləndi. Çəngəli yerə qoyub bayıra qaçdım.","Nənəmin dolanışığına dayaq olan, hər gün mahnı oxuya-oxuya sağdığı o inək… Mənim canım ət istədi deyəmi kəsilmişdi?","Süfrə açılanda məni də çağırdılar. İstəmədim, amma israr edib yanlarında oturtdular.","Utana-utana bir tikə götürdüm. Boğazımdan keçmirdi. Gözlərimdən yaş süzüldü.","— Nə oldu, bala? Nəyin var?","— Dişim… — deyə bildim. — Dişim çox ağrıyır…","İbrət: Bayramın sevinci paylaşdıqca tamamlanır. Yaxınımızda ehtiyac içində yaşayanları görmək üçün onların dilə gəlib kömək istəməsini gözləməməliyik. Vaxtında bölüşülən kiçik bir pay kiminsə böyük bir fədakarlığa məcbur qalmasının qarşısını ala bilər."]},{"stem":"ramadan-prayer","title":"Ramazan duası","hasAudio":false,"hasImage":true,"paragraphs":["Uca Allah dualarımızı qəbul etsin, ruzimizə bərəkət versin, xəstələrimizə şəfa bəxş etsin, günahlarımızı bağışlasın. Üzümüzə xeyirli qapılar açsın, qəlblərimizi sevgi və mərhəmətlə doldursun!","Ramazan bayramınız mübarək olsun!","İbrət: Ürəkdən edilən dua ümidimizi gücləndirir, qəlbimizdə mərhəmət oyadır. Özümüzlə yanaşı başqalarına da bərəkət, şəfa və bağışlanma diləmək bizi həm Yaradana, həm də bir-birimizə yaxınlaşdırır."]},{"stem":"prayer-for-everyone","title":"Sən özün yardım et, uca Allahım!","hasAudio":false,"hasImage":true,"paragraphs":["Hüzursuz olana, evsiz qalana,","Yetim olana, kimsəsiz qalana,","Möhtac olana, ac-susuz qalana,","Xəstə olana, əli darda qalana,","Könlü yarda olana, gözü yolda qalana,","Ümidsiz olana, çarəsiz qalana,","Qəflətdə olana, nursuz qalana,","Arzusu olana, xəyallar qurana,","İmansız olana, Sənsiz qalana —","Sən özün yardım et, uca Allahım!","İbrət: Dua yalnız öz dərdini söyləmək deyil, başqasının ağrısını da ürəyində daşımaqdır. Yaradana üz tutarkən köməyə ehtiyacı olanları unutmayaq."]},{"stem":"stoning-the-devil","title":"Şeytanı daşlamaq","hasAudio":false,"hasImage":true,"paragraphs":["Həcc ziyarətində bir adam şeytana daş atmaq vaxtı çatanda daşı atmaq əvəzinə onunla özünü vurmağa başlayır. Bunu görən bir gənc təəccüblə soruşur:","— Dayı, niyə özünü daşla vurursan?","Adam cavab verir:","— Oğlum, buradakı şeytanı daşlamaqdan əvvəl içimizdəkinə baxmalı deyilikmi? Əvvəl nəfsimizi tərbiyə etməli, qəlbimizi təmizləməliyik.","İbrət: İnsanın ən çətin mübarizələrindən biri öz nəfsi ilədir. Mənəvi təmizlənmə özünə əzab vermək deyil, qüsurlarını görüb davranışını düzəltməkdir. Başqasını qınamazdan əvvəl özünə nəzər sal."]},{"stem":"drinking-the-sherbet-of-martyrdom","title":"Şəhadət şərbəti içmək","hasAudio":false,"hasImage":true,"paragraphs":["Bir rəvayətə görə, Osmanlı dövründə döyüşdə ağır yaralanmış, son anlarını yaşayan əsgərlərə ağızlarında şirin bir dad qalsın deyə şərbət verilərmiş. Həkimlərin bu içkini zəmzəm suyu ilə hazırlayıb kiçik çəlləklərdə daşıdıqları söylənir.","“Şəhadət şərbəti içmək” ifadəsini bu rəvayətlə əlaqələndirirlər. Lakin bunu ifadənin sübut olunmuş mənşəyi kimi deyil, onun haqqında danışılan bir hekayə kimi qəbul etmək lazımdır.","Rəvayətin yadda qalan tərəfi isə son anlarında belə insanı qayğıdan məhrum etməmək düşüncəsidir.","İbrət: Dilimiz keçmişin xatirələrini, inanclarını və rəvayətlərini yaşadır. Bu mirası qorumaq həm onun mənasını anlamaq, həm də rəvayətlə tarixi faktı bir-birindən ayırmaqdır."]}]},{"title":"Ailə və tərbiyə","slug":"aile-ve-terbiye","blurb":"Ana-ata sevgisi, övlad tərbiyəsi və yuva qurmaq.","count":22,"stories":[{"stem":"hour-with-dad","title":"Ailənizin dəyəri","hasAudio":false,"hasImage":true,"paragraphs":["Bir axşam balaca oğlan atasına yaxınlaşıb soruşdu:","— Ata, sənə bir sual verə bilərəm?","— Əlbəttə, oğlum.","— Bir saat işləyəndə nə qədər pul qazanırsan?","Ata bu sualdan narazı qaldı:","— Bunu niyə soruşursan?","— Sadəcə bilmək istəyirəm. De də, ata.","Ata nəhayət cavab verdi:","— Saatda yüz dollar qazanıram.","Oğlan başını aşağı salıb bir an susdu. Sonra çəkinə-çəkinə soruşdu:","— Mənə əlli dollar borc verə bilərsən?","Ata hirsləndi:","— Deməli, bunun üçün soruşurdun! Yəqin, yenə hansısa lazımsız oyuncaq almaq istəyirsən. Mən bütün günü bunun üçün işləmirəm. Get otağına, yat!","Oğlan heç nə demədən otağına çəkilib qapını sakitcə örtdü.","Ata bir müddət otaqda var-gəl etdi. Hirsi soyuyanda düşündü ki, oğlunun pulu nəyə istədiyini heç soruşmamışdı. Bəlkə, onun üçün vacib bir səbəb vardı?","Peşman olub oğlunun otağına getdi və qapını yavaşca döydü:","— Yatmısan, oğlum?","— Yox, ata, oyağam.","Ata içəri girib onun yanında oturdu:","— Bayaq sənə hirsləndiyim üçün bağışla. Çətin gün keçirmişdim, acığımı səndən çıxdım. Al, bu da istədiyin əlli dollar.","Oğlan sevinclə atasına təşəkkür etdi. Sonra yastığının altından yığdığı pulları çıxarıb saymağa başladı.","Pulları görən ata yenidən hirsləndi:","— Pulun var idisə, məndən niyə istəyirdin?","Oğlan pulları bir yerə yığıb atasına baxdı:","— Çünki çatmırdı. İndi isə düz yüz dollarım var. Ata, bir saatını ala bilərəm? Sabah işdən tez gəl, birlikdə yemək yeyək.","Atanın gözləri doldu. Oğlunu bağrına basıb bir daha üzr istədi.","İbrət: Ailənin qayğısına qalmaq təkcə pul qazanmaq deyil. Uşağın sevgiyə, diqqətə və səninlə keçirdiyi vaxta ehtiyacı var — bunları heç bir hədiyyə əvəz etmir."]},{"stem":"weeds","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/weeds.webp","title":"Alaq otları","hasAudio":false,"hasImage":true,"paragraphs":["Məktəbli olarkən yay tətillərini ailəmizlə birlikdə bağımızda keçirərdik. Rəhmətlik atam bizi zəhmətə alışdırmaq istəyirdi. Özü işdə olduğu günlərdə bağ işlərini bizə tapşırardı. Bostan əkmişdi, sulamaq da bizim vəzifəmiz idi. Quyumuzun suyu içməyə yaramadığı üçün qonşumuz Ağasəlim dayının bağındakı quyudan içməli su daşıyardıq.","Torpağı belləməyi öyrənmişdik. Alaq işini də görürdük: belin köməyi ilə torpağın altını üstünə çevirər, alaq otlarını əzib qırardıq. Amma onlar o qədər də asanlıqla təmizlənmirdi. Bir gün atam bizi yanına çağırıb izah etdi: «Alaq otunu məhv etmək istəyirsinizsə, beli dərindən vurun; köklərini qoparmadan iş bitmir.»","İbrət: Problemin və pis vərdişin kökünü kəsməsən, üzdən düzəltmək fayda verməz. Bir müddət sonra yenə üzə çıxar.","Bəxtiyar Siracov"]},{"stem":"mothers-love","title":"Ana sevgisi","hasAudio":false,"hasImage":true,"paragraphs":["Bir yaşım var — çox xoşbəxtəm. Anam həmişə yanımdadır.","İki yaşım var — anam artıq hər an yanımda deyil. Görəsən, nə dəyişib?","Üç yaşım var — anam işdədir, yanımda dayəm var.","Beş yaşım var — anam iclasdadır, mən nənəmləyəm.","Yeddi yaşım var — anam seminardadır, mən məktəbdəyəm. Yanımda müəllimim var.","On üç yaşım var — yeniyetməyəm. Anam hələ də işləməyə məcburdur. Mən daha çox dostlarımla vaxt keçirirəm.","On yeddi yaşım var — anam işdən yorğun qayıdır. Mən isə ya dərsdəyəm, ya da dostlarımla kafedə.","İyirmi yaşım var — gəncəm, həyat məni öz ardınca aparır. Anam evdə olmayanda yanımda dostlarım olur.","İyirmi üç yaşım var — işə başlamışam. İndi anam evdədir, mən isə işdə.","Otuz yaşım var — düşünürəm: anamla son dəfə nə vaxt rahatca oturub söhbət etmişik? Nə vaxt birlikdə gözəl bir gün keçirmişik? Nəyisə gözdən qaçırmışam…","Otuz beş yaşım var — evliyəm. Anam öz evindədir, mən öz evimdə.","Qırx yaşım var — anam yolumu gözləyir. Vaxtilə mən onun yolunu gözlədiyim kimi.","Əlli yaşım var — mən də yaşa dolmuşam. Amma bir arzum heç qocalmayıb: anama sarılmaq, başımı dizlərinə qoymaq, onun yanında yenə uşaq olmaq.","Əlli beş yaşım var — yanımda övladlarımın anası var. Mənim anam isə artıq həyatda deyil. Onun həsrəti ilə yaşayıram.","Gündəlik qayğıların içində bəzən ən əziz insanlara ayıracağımız vaxtı sonraya saxlayırıq. İşlər bitmir, görüşlər təxirə düşür, söhbətlər yarımçıq qalır. Bu arada uşaqlar böyüyür, valideynlər yaşlanır.","Həyat gözümüzün önündə axıb gedən bir filmə bənzəyir. Amma onun ötən səhnələrini geri qaytarmaq, bir anı dayandırıb yenidən yaşamaq olmur.","Övladını bu gün qucaqla, əlindən tut, onu dinlə. Anana, atana bu gün vaxt ayır. Bu günün yaxınlığını sabaha saxlama: sabah artıq başqa bir gün olacaq.","Erix Frommun «Sevmək sənəti» əsərindəki fikrini sərbəst ifadə etsək, ana sevgisi şərtsiz qəbul və sığınacaqdır; onu nə məcburiyyətlə yaratmaq, nə də tələb etməklə qazanmaq olar.","İbrət: Sevgi yalnız qəlbdə saxlananda deyil, ayrılan vaxtda və göstərilən diqqətdə duyulur. Sevdiklərimizlə bölüşdüyümüz bu günü sabah geri qaytarmaq mümkün deyil."]},{"stem":"mother-and-son","title":"Ana və oğul","hasAudio":false,"hasImage":true,"paragraphs":["Kişi əlindəki çamadanları divarın dibinə qoydu. Dikəlib dərindən nəfəs aldı:","— Ana, bura çox gözəl yer imiş.","— Əlbəttə, gözəldir, oğlum, — yaşlı qadın cavab verdi.","Bir müddət susub otağa baxdılar.","Qadın kiçik çamadanını açdı. Gecə paltarını, şəppişlərini, bir neçə dəsmalı və çərçivəyə salınmış bir şəkli çıxardı. Şəkli çarpayının yanındakı masaya qoydu.","Şəkildə məktəbli geyimində, əsgər kimi dimdik dayanmış bir oğlan vardı. Gözləri dolmuş, dodaqları büzülmüşdü.","Kişi pəncərəyə yaxınlaşıb pərdəni kənara çəkdi. Otağa solğun gün işığı yayıldı. Bayırda şaxta vardı. Əllərini qızdırıcıya söykəyib küçədən keçən palçıqlı maşınlara baxdı.","— Bu şkaf sənə bəs edər, ana? — deyə başını çevirmədən soruşdu.","Qadın onu eşitmədi. Çarpayının üstündə bir az yana əyilmiş, gözlərini köhnə çərçivədəki ürkək uşağa dikmişdi.","Şəkil oğlunun məktəbə getdiyi ilk gün çəkilmişdi.","Qadının yaddaşında həmin gün yenidən canlandı. Əvvəlki axşam məktəbin nə qədər gözəl yer olduğunu saatlarla danışmışdı. Yenə də səhər oğlunu sinfə güclə sala bilmişdi. Bütün günü məktəbdə qalmış, hər tənəffüsdə yanına gedib demişdi:","— Mən buradayam, oğlum. Səni gözləyirəm.","Uşaq isə hər dəfə onun əlindən daha bərk yapışıb ağlamışdı:","— Məni qoyub getmə, ana. Çox qorxuram.","Günəş batmaq üzrə idi. Kişi əllərini qızdırıcıdan çəkib buğlanmış pəncərə şüşəsinə qoydu.","— O biri çamadanı da aç, ana. Əşyalarını yerləşdirək.","— Sən yubanma, oğlum. Özüm yerləşdirərəm. Onsuz da çox əşyam yoxdur.","Qadın titrək əlləri ilə oğlunun əlindən tutdu. Deyəsən, nəsə söyləmək istəyirdi. Amma fikrindən daşındı. Udqunub əlavə etdi:","— Uşaqlar da nigaran qalar.","Qapı cırıldayaraq bağlandı.","Yaşlı qadın boyası tökülmüş otaqda şəkildəki ürkək oğlanla tək qaldı. Bir az çarpayının kənarında oturdu. Sonra şəppişlərini geyib pəncərəyə yaxınlaşdı.","Oğlu maşına minirdi.","Qadın qorxurdu. Əvvəlki gün buranın nə qədər gözəl yer olduğunu saatlarla dinləmişdi. Amma yenə də qorxurdu.","Şüşənin üstündə oğlunun əl izi qalmışdı. Yanağını ehmalca həmin izə söykədi. Gözləri doldu, dodaqları büzüldü.","— Məni qoyub getmə, oğlum. Çox qorxuram, — deyə pıçıldadı.","Sözləri buğlanmış şüşədə əriyib qaldı. Bayırda, maşında oturan oğlu isə ona əl edirdi.","Həmin gecə eyni mərtəbədə qalanlar onun hıçqırıqlarını eşitdilər. Qocalar evinin dəhlizləri belə səslərə yad deyildi.","İbrət: Yaşa dolmaq insanın doğmalığa və sevgiyə ehtiyacını azaltmır. Valideynə qayğı yalnız ona rahat yer ayırmaq və gündəlik ehtiyaclarını ödəmək deyil, ona unudulmadığını, tək olmadığını da hiss etdirməkdir."]},{"stem":"father-and-son","title":"Ata və oğul","hasAudio":false,"hasImage":true,"paragraphs":["Oğul atası ilə ağır mübahisədən sonra evi tərk etmişdi. Qəlbi qırılan ata da qəzəbinə yenilmiş, evdə oğlunun adının çəkilməsini belə istəməmişdi.","Ana isə hər gecə oğlunun otağına girir, yatağının kənarında oturub yastığını bağrına basırdı.","— Oğlum üçün darıxıram. Nə olar, gedib onu tapaq, evə gətirək, — deyirdi.","Ata susur, söhbəti bağlayırdı.","Beləcə, günlər həftələrə, həftələr aylara çevrildi.","Bir gün arvadının göz yaşlarına dözməyən ata cibindən qatlanmış bir kağız çıxarıb ona uzatdı:","— Bu ünvana get. Onu orada taparsan. Amma ünvanı mənim verdiyimi demə.","Sonra bir neçə söz də əlavə etdi. Ana diqqətlə dinlədi, amma fikri artıq oğlunun yanında idi.","Ünvana çatanda qarşısında bir təmirxana gördü. Oğlu iş paltarında çalışırdı. Ana bir müddət qapıda dayanıb onu seyr etdi. Sonra titrək səslə adını çəkdi.","Oğlan başını qaldırdı. Bir an gözlərinə inanmadı, sonra anasına tərəf qaçıb onu qucaqladı.","Hamının halını soruşdu. Atasını isə axıra saxladı:","— O necədir? Hələ də mənə qəzəblidir?","Ana oğlunun üzünə baxdı:","— Gəl evə, bala. Çox darıxmışıq.","Oğlanın üzü tutuldu:","— Yox, ana. Məni bir dəfə də axtarmayan adamın yanına qayıtmaq istəmirəm. Yəqin, mənsiz daha rahatdır.","Ana gətirdiyi şirniyyatı ona uzatdı. Sonra sakitcə dedi:","— Səni məcbur etməyəcəyəm. Amma atanın bir sözünü çatdırmalıyam. Dedi, son bir ayda dostlaşdığın adamdan ehtiyatlı olasan. Köhnə dostunla da barışsan, yaxşı olar.","Oğlan donub qaldı:","— Atam… bunları haradan bilir?","Ana cavab vermədi. Oğlunu bir daha qucaqlayıb yola düşdü.","Evə çatan kimi ərindən soruşdu:","— Harada olduğunu bilirdinsə, niyə mənə demirdin? Nə vaxtdan xəbərdarsan?","Atanın gözləri doldu:","— Getdiyi gündən. Bəzən günorta təmirxananın yanından keçirdim, görüm yemək yeyibmi, yaxşıdırmı. Axşamlar da uzaqdan görüb qayıdırdım.","— Bəs niyə yaxınlaşıb danışmırdın?","Ata başını aşağı saldı:","— Qürurum qoymurdu. Elə bilirdim, ilk addımı o atmalıdır… Amma hər gün yolunu gözləyirdim. O mənim balamdır.","Bu vaxt qapı döyüldü.","Ana qapını açanda oğlunu gördü. Oğlan içəri girib atasının qarşısında dayandı. Bir neçə an heç biri danışmadı.","Sonra ata bir addım irəli gəldi:","— Gərək səni axtarıb danışaydım, oğlum.","Oğlanın gözləri yaşardı:","— Mən də elə sözlər dedim ki… Bağışla, ata.","Bir-birinə sarıldılar. Ana da onlara qoşuldu.","Aralarındakı inciklik bir anda silinməmişdi. Amma onu danışıb aradan qaldırmaq üçün artıq eyni evdə, bir-birinin yanında idilər.","İbrət: Sevgi ürəkdə qalıb dilə və əmələ çevrilməyəndə qarşı tərəf özünü sevgidən məhrum hiss edə bilər. Barışmaq üçün ilk addımı kimin atdığından çox, o addımın vaxtında atılması vacibdir."]},{"stem":"fathers-footsteps","title":"Atanın izləri","hasAudio":false,"hasImage":true,"paragraphs":["Ata oğluna dedi:","— Oğlum, addımlarına diqqət et. Hara getdiyinə yaxşı bax.","Oğlu cavab verdi:","— Sən də öz addımlarına diqqət et, ata. Mən sənin izlərinlə gedirəm.","İbrət: Uşağa yol göstərmək yalnız nəsihət vermək deyil, o yolu özün də düzgün getməkdir. Çünki uşaq sözlərindən dərs alır, əməllərindən isə nümunə götürür."]},{"stem":"stay-calm-arif","title":"Baba və nəvəsi bazarlıqda","hasAudio":false,"hasImage":true,"paragraphs":["Bir baba nəvəsi ilə supermarketə getmişdi. Rəflərin arasından keçib lazım olan ərzaqları səbətə yığırdılar. Uşaq isə gördüyü hər şeyi istəyirdi:","— Bunu da al! Onu da istəyirəm!","İstəyi yerinə yetməyəndə səsini daha da qaldırır, mağazanı başına götürürdü. Baba isə hər dəfə aramla deyirdi:","— Sakit ol, Arif. Az qalıb, alış-verişi bitirib evə gedəcəyik.","Nəhayət, uşaq hirslənib rəfdən bir şokolad yumurta götürdü, yerə atıb ayağı ilə əzdi.","Baba dərindən nəfəs aldı:","— Sakit ol, Arif. Bir az da səbir et, indi evə gedəcəyik.","Sonra yaxınlıqdakı işçiyə dönüb dedi:","— Çox üzr istəyirəm. Bunun da pulunu ödəyəcəyəm.","Kassada hesabı ödəyib mağazadan çıxdılar. Bütün bunları görən bir xanım onların ardınca gəlib babaya yaxınlaşdı:","— Səbrinizə heyran qaldım! Arif nə qədər dəcəllik etsə də, bir dəfə də səsinizi qaldırmadınız.","Baba təşəkkür edib gülümsədi:","— Uşağın adı Rafiqdir. Arif mənəm.","İbrət: Gərgin anda əsl güc özünü ələ almağı bacarmaqdır. Bəzən «sakit ol» sözünü başqasından əvvəl özümüzə deməliyik."]},{"stem":"festive-gift","title":"Bayrama hədiyyə","hasAudio":false,"hasImage":true,"paragraphs":["Bir ağsaqqaldan soruşdum:","— Bayram üçün nə alım?","Gülümsəyib dedi:","— Bir neçə adamın könlünü al. Uşaqları sevindir, üzlərini güldür. İmkanın varsa, ehtiyacı olanın yükünü yüngülləşdir, duasını al. Bayram sevincindən başqalarına da pay ver.","İbrət: Hədiyyənin dəyəri təkcə qiymətində deyil, daşıdığı qayğıdadır. Bayramı gözəlləşdirən yalnız aldıqlarımız yox, bölüşdüyümüz sevincdir."]},{"stem":"nails-lesson","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/nails-lesson.webp","title":"Bir mismarın hekayəsi","hasAudio":false,"hasImage":true,"paragraphs":["Bir kənddə çox əsəbi və hövsələsiz bir oğlan yaşayırdı. O, ən kiçik bir sözə belə qəzəblənər, hirslənəndə qarşısındakını incitməkdən çəkinməzdi.","Atası oğlunun bu xasiyyətindən çox narahat idi. Bir gün ona bir torba mismar verib dedi:","— Oğlum, hər dəfə kiməsə əsəbiləşib pis söz deyəndə bu mismarlardan birini həyətin hasarına vur.","Oğlan əvvəlcə bunun mənasız bir iş olduğunu düşündü. Amma ertəsi gün əsəbiləşdi və hasara bir mismar vurdu. Sonra yenə hirsləndi, daha bir mismar vurdu. Günlər keçdikcə hasarda mismarların sayı artmağa başladı.","Bir müddət sonra oğlan öz davranışına fikir verməyə başladı. Hər dəfə qəzəblənəndə əlinin mismara getməsi onu düşündürürdü. Nəhayət, bir gün atasının yanına gəlib dedi:","— Ata, daha əsəbiləşməməyə çalışacağam.","Atası gülümsəyib cavab verdi:","— Çox yaxşı. İndi isə özünü saxlayıb heç kimi incitmədiyin hər gün hasardan bir mismar çıxart.","Oğlan belə də etdi. Günlər keçdi, aylar ötdü və nəhayət, bütün mismarlar hasardan çıxarıldı.","Oğlan sevinclə atasını çağırdı:","— Ata, bax! Bütün mismarları çıxartdım.","Atası onu hasarın yanına aparıb sakitcə dedi:","— Mismarların hamısını çıxardın. Amma bax, hasarda onların yerləri qalıb. Sən əsəbiləşib birinə söz atanda da belə olur. Sonra üzr istəyə bilərsən, peşman ola bilərsən, hətta o insan səni bağışlaya bilər. Amma qəlbdə yaranan yara bəzən izsiz sağalmır.","Oğlan uzun müddət hasardakı dəliklərə baxdı.","Həmin gündən sonra o, qəzəblənəndə əvvəlcə susmağı, sonra düşünməyi öyrəndi.","İbrət: Qəzəblə deyilən söz qəlbdə elə bir iz qoya bilər ki, üzr istəmək də onu silməyə yetməz. Ona görə hirslənəndə dayanıb düşünmək, sonra danışmaq lazımdır.","Etibar Siracsoy"]},{"stem":"only-my-mother-truly-weeps","title":"Bir tək anam ağlar","hasAudio":false,"hasImage":true,"paragraphs":["Bir tək anam ağlar, qalanı yalan ağlar!","İbrət: Bu söz ana sevgisinin dərinliyini ifadə edir. Ananın övladının dərdini öz dərdi kimi duyması onun təmənnasız sevgisinin ən kövrək təzahürlərindəndir."]},{"stem":"rotten-seed","title":"Çürük toxum","hasAudio":false,"hasImage":true,"paragraphs":["Həyat yoldaşı vəfat etdikdən sonra bir ata tez-tez xəstələnən balaca oğluna baxmaq istəmədi. Onu «çürük toxum» adlandırıb xor gördü, axırda uşaq evinə verdi.","İllər keçdi.","Bir gün ata artıq böyümüş oğlunu bir məktəbin qarşısında gördü. Gözlərinə inanmadı. Qarşısında gözləri parıldayan, sağlam, cüssəli bir gənc dayanmışdı.","Oğluna peşmanlıqla baxıb həyəcan içində dedi:","— Mən sənin sağalacağına, belə böyüyüb güclənəcəyinə inanmırdım. Pəhləvan kimi oğlan olmusan! Bu necə baş verdi? Xəstəliklərdən necə qurtuldun?","Gəncin gözləri doldu. Bir vaxtlar onu xor görən atasına baxdı, sonra gülümsəyərək onlara yaxınlaşan yaşlı bir xanımı göstərdi:","— Sən «çürük toxum cücərməz» deyib məni uşaq evinə qoyandan sonra bu xanım məni övladlığa götürdü. «Sevgi ilə sulanan toxuma boy atmaq üçün fürsət vermək lazımdır», — dedi. Nə sevgisini, nə də qayğısını məndən əsirgədi.","İbrət: Uşağın dəyəri onun sağlamlığı ilə ölçülmür. Alçaldıcı sözlər ümidini qıra bilər, sevgi və davamlı qayğı isə ona öz gücünü tapmaq üçün dayaq olar. Heç bir uşaq «çürük toxum» deyil."]},{"stem":"waiting-for-the-teeth","title":"Dişləri gözləyirəm","hasAudio":false,"hasImage":true,"paragraphs":["Soyuq bir qış axşamı yaşlı bir cütlük McDonald’s-a girib masa arxasında əyləşdi. Kişi kassaya yaxınlaşıb bir hamburger, bir böyük porsiya kartof qızartması və bir böyük kola aldı.","Masaya qayıdanda hamburgeri iki yerə bölüb yarısını xanımının qabağına qoydu. Kartofları da bir-bir sayaraq bərabər böldü. Sonra koladan bir qurtum içib içkini xanımına uzatdı.","Ətrafdakılar onlara baxıb düşünürdülər: «Yəqin, pulları çatmır. Bir nəfərlik yeməyi ikisi bölüşür».","Kişi iştahla yeməyə başladı. Qadın isə qarşısındakı yeməyə toxunmur, ərinə baxır, arabir koladan bir qurtum içirdi.","Bunu görən gənc işçilərdən biri yaxınlaşdı:","— Bağışlayın, dayı. Fikir verdim ki, siz yeyirsiniz, xanımınız isə yeməyə əl vurmur. Bəlkə, başqa bir şey istəyir? İcazə versəniz, gətirim.","Kişi gülümsədi:","— Çox sağ ol, oğlum, amma hər şey qaydasındadır. Altmış ildir evliyik. Hər şeyimizi beləcə bölüşürük.","Gənc yenə də qadının niyə yemədiyini anlamadı. Üzünü ona tutub soruşdu:","— Bəs siz nəyi gözləyirsiniz, xala?","Qadın ərini göstərib aramla dedi:","— Dişləri, bala… Dişləri gözləyirəm!","İbrət: Hər insanın öz yaşayış tərzi, hər ailənin öz vərdişləri var. Bizə qəribə gələn bir davranış başqası üçün gündəlik həyatın adi bir hissəsi ola bilər."]},{"stem":"hold-my-hand","title":"Əlimi tut","hasAudio":false,"hasImage":true,"paragraphs":["Bir ata balaca qızı ilə körpüdən keçirdi. Aşağıda axan çaya baxıb bir az narahat oldu:","— Qızım, əlimdən möhkəm tut ki, yıxılmayasan.","Qızcığaz başını qaldırıb dedi:","— Yox, ata, sən mənim əlimdən tut.","Ata təəccüblə soruşdu:","— Nə fərqi var ki?","— Böyük fərqi var! Mən sənin əlindən tutsam, qorxanda buraxa bilərəm. Amma sən mənim əlimdən tutsan, bilirəm ki, nə olsa da, buraxmazsan.","İbrət: Güvən — çətin anda uzatdığın əlin boş qalmayacağını bilməkdir. Sevdiklərinin kömək istəməsini gözləmə; ehtiyac duyduqları anda yanlarında ol, əllərindən tut."]},{"stem":"most-beautiful-gift","title":"Ən gözəl hədiyyə","hasAudio":false,"hasImage":true,"paragraphs":["Ataya — ehtiram, anaya — hörmət, övlada — şəfqət, həyat yoldaşına — sevgi, dosta — vəfa, cəmiyyətə — xidmət, dünyadan köçənə — dua, dünyaya — insanlıq, axirət üçün — bu dünyada edilən yaxşılıq.","İbrət: Ən gözəl hədiyyələr həmişə pulla alınmır. Hörmət, sevgi, şəfqət və sədaqət münasibətləri yaşadır; insanlara edilən yaxşılıq isə ömrə məna verir."]},{"stem":"mothers-lasting-lesson","title":"Fakir Baykurtun unutmadığı ana nəsihəti","hasAudio":false,"hasImage":true,"paragraphs":["Türk yazıçısı Fakir Baykurt haqqında danışılan bir xatirəyə görə, o, uşaq vaxtı bir gün anasına deyir:","— Ana, ürəyim çay istəyir. Gəl bir çay içək.","Anası oğlunun istəyini geri çevirmir. Onu yaxınlıqdakı Topal Hüseynin çayxanasına aparır:","— Usta, zəhmət olmasa, balama bir stəkan çay gətir.","Çay gələndə uşaq səbirsizliklə stəkanı götürüb böyük bir qurtum içir. Ağzı yandığı üçün stəkanı əlindən buraxır. Stəkan torpağa düşür, amma qırılmır.","Uşaq qorxa-qorxa anasına baxır. Elə bilir, indi bir şillə gələcək. Anası isə sakitcə çayxana sahibini çağırıb bir stəkan da çay istəyir.","Bu dəfə uşaq çayını üfləyə-üfləyə, kiçik qurtumlarla içir.","İllər keçir. Baykurt o günü unutmur. Hər dəfə anasından niyə ona hirslənmədiyini, şillə vurmadığını soruşanda cavabsız qalır.","Cavabı illər sonra, müəllim işlədiyi kənd məktəbində alır.","Bir gün anası Elif xanım onun dərsində oturur. Baykurt dərs zamanı əsəbiləşir, səsini qaldırır, uşaqları sərt danlayır. Dərsdən sonra anasından soruşur:","— Necə oldu, ana? Müəllimliyimi bəyəndinmi?","— Nə deyim, oğlum… Pis deyildi.","Bu cavab onu qane etmir:","— Ana, müfəttişlər gəlib dərsimə baxır, bəyənir, yüksək qiymət verirlər. Sən isə «pis deyildi» deyirsən?","Anası üzünü ona tutub deyir:","— İllərdir soruşursan ki, o gün çayı tökəndə niyə səni vurmadım. İndi deyəcəyəm, yaxşı qulaq as.","Bir an susub davam edir:","— O gün sənə hirslənsəydim, içindəki aslan küsərdi. Səni döysəydim, o aslan ölərdi. Bəlkə də, bu gün belə müəllim ola bilməzdin. Sən də səbirli ol, oğlum. Bu uşaqların içindəki aslanı qışqırıqla, kötəklə öldürmə.","İbrət: Uşağın səhvinə verilən cavab onun özünə inamını ya gücləndirər, ya da sarsıdar. Səbir və sevgi ilə verilən tərbiyə uşağa həm səhvindən öyrənməyə, həm də öz dəyərinə inanmağa kömək edir."]},{"stem":"spinach","title":"İspanaq","hasAudio":false,"hasImage":true,"paragraphs":["Ucqar bir kənddə yaşayırdıq. Düz-əməlli yolumuz belə yox idi. Anam isə hey ispanaq bişirirdi. Uşaq ağlımla düşünürdüm ki, bəlkə, atamın ölümündən sonra anam özündə deyil...","— Bol-bol yeyin, sizə güc verər, — deyirdi.","Səhər də, günorta da, axşam da süfrəmizdə ispanaqla qarğıdalı çörəyi olurdu. Artıq ispanaqdan bezmişdim, onu görməyə gözüm yox idi.","Bir gün anama dedim:","— Böyüyüb işə düzələndə, ailə quranda evimə heç vaxt ispanaq almayacağam. Bizim evdə ispanaq bişməyəcək!","Anam gülümsədi. O günləri səbirsizliklə gözlədiyini söylədi, hətta nə qədər qocalsa da, toyumda oynayacağına söz verdi.","Vaxt gəldi, orta məktəbdə təhsilimi davam etdirmək üçün kənddən şəhərə köçdüm. Kiçik təqaüdümlə birtəhər dolanırdım. Ayda bir dəfə evə gələndə anamın süfrəyə qoyduğu ispanaqdan bir qaşıq da yemək istəmirdim. Yataqxanaya qayıdıb başqa, daha dadlı yeməklər yeməyin xəyalını qururdum.","Oxudum. Dövlətin verdiyi təhsil krediti ilə universiteti, sonra magistraturanı və doktoranturanı bitirdim. O vaxta qədər anamın beli bükülmüş, özü xeyli qocalmışdı.","Evlənəcəyim qızla kəndə gəlib toy etdik. Anam o gün həm ağladı, həm də illər əvvəl söz verdiyi kimi oynadı. Oynaya-oynaya niyə göz yaşı tökdüyünü o vaxt anlamırdım.","İllər keçdi. Anamı iki il əvvəl itirdim.","Bir gün onun köhnə sandığında vaxtilə yazdığı bir gündəlik tapdım. Səhifələrdən birində belə yazılmışdı:","«Əlimdə bircə ispanaq toxumu qalmışdı. İspanaq, bir az da qarğıdalı əkib-becərirdim. Nə əldə vardı, nə ovucda. Balalarım ac qalmasın deyə hey eyni yeməyi bişirirdim. Amma şikayət etmirdim.","“İspanaq çox faydalıdır, ona görə sizə gündə üç dəfə verirəm”, — deyəndə ürəyim sızıldayırdı. Onlar üçün əlimdən gələn yalnız bu idi. Balalarımı canımdan çox sevirəm.»","İspanağı əlli yaşımda sevdim.","İndi həyat yoldaşım evə niyə bu qədər tez-tez ispanaq aldığımı təəccüblə soruşur. Elə bilir, dadını çox sevirəm.","Bilmir ki, hər dəfə o yeməyin qoxusunu duyanda anamın bizi böyütmək üçün çəkdiyi zəhməti, toyumda ağlaya-ağlaya oynamasını xatırlayıram...","İbrət: Bəzən uşaqlıqda bezdiyimiz bir yeməyin arxasında anamızın bizdən gizlətdiyi yoxsulluq və səssiz fədakarlıq dayanır. Sevginin dəyərini anlamaq üçün illərin keçməsini gözləməyək."]},{"stem":"fathers-advice","title":"Müdrik atanın oğluna öyüd-nəsihətlərindən","hasAudio":false,"hasImage":true,"paragraphs":["Əziz oğlum!","Həyat yolunda ağlını özünə bələdçi et. İnsanlarla münasibətdə düşüncəli, sözündə ölçülü, davranışında ədalətli ol. Ağıl yalnız öz xeyrini görmək deyil, başqasının haqqını da nəzərə almaqdır.","Ömrün qədrini bil. Onun dəyəri təkcə uzunluğunda deyil, necə yaşanmasındadır. Hər günün içində öyrənməyə, sevməyə və yaxşılıq etməyə yer ayır.","Meyvə yetişdikcə şirinləşdiyi kimi, insan da yaşadıqlarından nəticə çıxardıqca kamilləşir. Təcrübəli insanları dinlə. Amma unutma: müdriklik yalnız yaşa dolmaqla deyil, gördüklərindən dərs almaqla yaranır.","Gənclikdə düşünmədən atılan bir addım illər sonra da ürəyi incidə bilər. Ona görə qərar verərkən yalnız bugünkü istəyini deyil, sabahkı vicdan rahatlığını da düşün. Səhv etsən, boynuna al, bacardığın qədər düzəlt və ondan öyrən.","Gəncliyində əkdiyin yaxşılığın bəhrəsini sonrakı illərdə görə bilərsən. Dürüstlük, zəhmət və insanlara hörmət ömrün boyu sənə dayaq olar.","Güclü olmaq yaxşıdır. Amma güc ağlın və vicdanın xidmətində olmalıdır. Onu kimisə əzməyə deyil, qorumağa və qurmağa sərf et.","Unutma ki, bu dünya heç birimiz üçün əbədi məskən deyil. Uca Allahın bəxş etdiyi ömrü qiymətləndir. Ölümü xatırlamaq səni həyatdan soyutmasın; bu günün, yanında olan insanların qədrini bilməyə sövq etsin.","Mən öz həyatımda iki sadə vərdişi qorumağa çalışmışam: yeməkdə həddi aşmamaq və hərəkətsiz qalmamaq. Bunları sənə hər dərdə çarə kimi deyil, özümə qayğının bir hissəsi kimi söyləyirəm. Sən də bədəninin ehtiyaclarını dinlə, ona laqeyd yanaşma.","Oğlum, insanın öyrənməyə münasibətinə də fikir ver.","Eləsi var ki, düşünür, soruşur, addımının nəticəsini götür-qoy edir.","Eləsi var ki, yolunu hələ tapa bilməyib, amma dinləməyə və öyrənməyə hazırdır. Yaxşı bir məsləhət ona istiqamət verə bilər.","Eləsi də var ki, nə bilmədiyini görür, nə də başqasını dinləyir. Hər şeyi bildiyinə inandığı üçün öyrənməyin qapısını öz üzünə bağlayır.","Çalış, düşünənlərdən ol. Bilməyəndə soruşmaqdan çəkinmə. Məsləhəti dinlə, ağlında ölçüb-biç. Ən çox da “Mən hər şeyi bilirəm” düşüncəsindən uzaq dur.","Mənim sənə arzum budur: ağlın aydın, vicdanın rahat, qəlbin öyrənməyə açıq olsun.","İbrət: Müdriklik hər şeyi bilmək deyil, bilmədiyini qəbul edib öyrənməyə hazır olmaqdır. Ağlını bələdçi, vicdanını ölçü et; gücünü də onların xidmətinə ver."]},{"stem":"raising-a-child","title":"Övlad tərbiyəsi","hasAudio":false,"hasImage":true,"paragraphs":["Bir ailədə valideynlərinin sözünə tez-tez qarşı çıxan bir oğlan böyüyürdü. Ona nə desələr, əksini edirdi. Məktəbdə də işləri yaxşı getmirdi: dərslərə həvəs göstərmir, ev tapşırıqlarını yarımçıq qoyurdu.","Anası əsəbiləşib onu döyür, atası isə cəzalandırmaq üçün otağa salırdı. Amma bunların heç biri vəziyyəti düzəltmirdi.","Bir gün ana oğlunu məktəbə apararkən yolda ayı oynadan bir adama rast gəldi. Ətrafına xeyli adam yığılmışdı. Adam qaval çalır, burnuna halqa keçirilmiş ayı da onun hərəkətlərinə uyğun tullanıb oynayırdı.","Qadın dayanıb düşündü: «Mən bir uşağın öhdəsindən gələ bilmirəm, bu adam isə ayını belə sözünə baxdırır!»","Yaxınlaşıb soruşdu:","— Oğlum sözümə baxmır. Siz bu heyvanı necə öyrətmisiniz?","Adam gülümsədi:","— Hər işin bir yolu var. Mənim də öz üsulum var.","— Bəlkə, mənə də kömək edəsiniz?","Ayı oynadan oğlana baxıb dedi:","— Bir həftə yanıma gətirin, sözünüzə baxmağı öyrədərəm.","Qadın sevindi. Hər gün oğlunu həmin adamın yanına aparıb-gətirməyə başladı.","Bir neçə gündən sonra uşaq dəyişdi. Daha anasına etiraz etmir, deyilənləri sakitcə yerinə yetirirdi. Həftənin sonunda qadın istədiyinə çatdığını düşünürdü. Adama təşəkkür edib dualar etdi.","Qonşular da heyrətlənirdilər: əvvəlki nadinc uşaq indi sakit və itaətkar görünürdü. Müəllimi də bu dəyişikliyə sevinib ananı təbrik etdi.","Lakin çox keçmədən başqa problemlər üzə çıxdı. Oğlan əvvəlki kimi açıq etiraz etmirdi, amma sinif yoldaşlarının əşyalarını gizlicə götürür, etdiklərini ört-basdır edir, yalan danışırdı.","Müəllim anaya zəng vurdu:","— Oğlunuzun davranışında məni narahat edən dəyişikliklər var. Başqalarının əşyalarını götürür, sonra da danır. Bunun səbəbini anlamağa çalışmalıyıq.","Qadın pərişan halda ayı oynadan adamı axtardı. Amma o, artıq oradan çıxıb getmişdi.","Valideynlərin çarəsizliyini görən dünyagörmüş bir qonşu dedi:","— Xeyirxah, müdrik bir adam tanıyıram. Gedin, onunla danışın. Bəlkə, sizə yol göstərər.","Ana oğlunu götürüb həmin adamın yanına getdi, baş verənləri danışdı. Müdrik adam dedi:","— Bir həftə ərzində oğlunuzla bir neçə dəfə görüşüm. Onu tanımağa, nə yaşadığını anlamağa çalışım.","İkinci görüşdən sonra adam ananı söhbətə çağırdı. Çox qayğılı görünürdü:","— Oğlunuz səhvini etiraf etməkdən qorxur. Elə bilir ki, həqiqəti desə, mütləq cəzalandırılacaq. Onunla necə davranmısınız?","Qadın evdə verdikləri cəzalardan, sonra da uşağı ayı oynadan adamın yanına aparmasından danışdı.","Müdrik adam dərindən köks ötürdü:","— Siz uşağınızın davranışını dəyişmək istəyirdiniz, amma onun nə hiss etdiyini anlamağa çalışmamısınız. Qorxu uşağı bir müddət susdura bilər. Lakin susmaq hələ anlamaq, itaət etmək də doğru ilə yanlışı ayırd etməyi öyrənmək deyil. Cəzadan qorxan uşaq bəzən səhvini düzəltmək əvəzinə onu gizlətməyə çalışır.","Bir qədər dayanıb davam etdi:","— Tərbiyə uşağın iradəsini sındırmaq deyil, onunla qarşılıqlı etimada əsaslanan münasibət qurmaqdır. Oğlunuzu dinləyin, ona vaxt ayırın, sevginizi göstərin. Qaydaları aydın izah edin, özünüz də onlara əməl edin. Səhv edəndə onu alçaltmadan etdiyinin nəticəsini anlamağa və düzəltməyə kömək edin.","Sonra sözünü tamamladı:","— Mən sizə yol göstərə bilərəm, amma evdəki münasibəti sizin yerinizə dəyişə bilmərəm. Dəyişiklik övladınızın sizin yanınızda özünü təhlükəsiz, sevilən və eşidilən hiss etməsindən başlayır.","İbrət: Tərbiyənin məqsədi qorxudan susan deyil, doğru ilə yanlışı anlayan uşaq yetişdirməkdir. Sevgi, etibar, aydın qaydalar və valideynin şəxsi nümunəsi bu yolun əsas dayaqlarıdır."]},{"stem":"puppies-for-sale","title":"Satılıq küçüklər","hasAudio":false,"hasImage":true,"paragraphs":["Dükanın pəncərəsində «Satılıq küçüklər» elanını görən balaca bir oğlan içəri girdi.","— Küçüklər neçəyədir? — deyə soruşdu.","— Otuz dollardan əlli dollara qədər. Hərəsinin öz qiyməti var, — dükan sahibi cavab verdi.","Oğlan cibindəki bütün pulu çıxarıb piştaxtaya qoydu və diqqətlə saydı.","— Cəmi on üç dollar iyirmi yeddi sentim var, — deyə məyus halda dilləndi. Sonra ümidlə soruşdu:","— Heç olmasa, onlara baxa bilərəm?","Dükançı gülümsəyib arxa otaqdakı həyat yoldaşını çağırdı. Bir azdan qadın, onun ardınca da beş şirin, toppuş küçük göründü. Küçüklərdən biri isə digərlərindən geri qalır, çətinliklə yeriyirdi.","Oğlan gözünü ondan çəkmədi:","— Bunun ayağına nə olub?","— Baytar dedi ki, ayağında anadangəlmə sümük qüsuru var. Həmişə yeriməkdə çətinlik çəkəcək.","Oğlan dərhal dedi:","— Mən elə onu almaq istəyirəm!","Dükançı təəccübləndi:","— Bala, onu seçəcəyini düşünməzdim. İstəyirsənsə, sənə hədiyyə edərəm.","Oğlanın üz ifadəsi dəyişdi. Dükançının gözlərinə baxıb qətiyyətlə dedi:","— Onu mənə hədiyyə etməyinizi istəmirəm. O da o biri küçüklər qədər dəyərlidir. İndi sizə on üç dollar iyirmi yeddi sent verərəm. Qalanını da otuz dollar tamam olanadək hər həftə beş dollar ödəyərəm.","Dükançı yenə onu fikrindən daşındırmağa çalışdı:","— Amma o, başqa küçüklər kimi səninlə qaçıb oynaya bilməyəcək.","— Ona da bir fürsət vermək lazımdır. O da digərləri qədər qiymətlidir, — oğlan cavab verdi.","Sonra əyilib şalvarının balağını qaldırdı. Uşaq iflicindən zədələnmiş ayağı metal dayaqlarla bərkidilmişdi.","Oğlan dükançıya baxıb sakitcə dedi:","— Əmi, mən də qaçıb oynaya bilmirəm. Bu küçüyün də, mənim də bizi anlayan, bizə dayaq olan bir dosta ehtiyacımız var.","İbrət: Bir canlının dəyəri onun nəyi bacarıb-bacarmaması ilə ölçülmür. Əsl dostluq fərqləri görüb uzaqlaşmaq deyil, bir-birini anlayıb dayaq olmaqdır."]},{"stem":"fallen-teeth","title":"Tökülən dişlər","hasAudio":false,"hasImage":true,"paragraphs":["Bir şah yuxusunda bütün dişlərinin töküldüyünü gördü. Səhər yuxuyozan çağırtdırıb soruşdu:","— Bu yuxunun mənası nədir?","Yuxuyozan dedi:","— Şah sağ olsun, bütün yaxınlarınız sizdən əvvəl dünyasını dəyişəcək. Axıra tək siz qalacaqsınız.","Şah bu sözlərdən sarsıldı, sonra qəzəblənib adamı qovdu.","Başqa bir yuxuyozan çağırtdırdı və yuxusunu ona da danışdı.","İkinci yuxuyozan cavab verdi:","— Şah sağ olsun, bu yuxunu belə yozmaq olar: ailənizdə ən uzunömürlü siz olacaqsınız.","Şahın üzü güldü. Yuxuyozanı mükafatlandırıb yola saldı.","İki yozumun mənası eyni idi. Amma biri şahın diqqətini itkiyə, digəri isə uzun ömrə yönəltmişdi.","İbrət: Sözün təsiri yalnız mənasından deyil, necə deyilməsindən də asılıdır. Həqiqəti gizlətmədən, qarşındakının hisslərini nəzərə alaraq danışmaq da müdriklikdir."]},{"stem":"im-tired-mom","title":"Yoruldum, ana","hasAudio":false,"hasImage":true,"paragraphs":["— Yoruldum, ana...","— Nədən, oğlum?","— Hər şeydən: işləməkdən, dostlardan, gəzməkdən, hamını razı salmağa çalışmaqdan... Çox yorulmuşam.","— Başını qoy dizimə, rahatlan, oğul. Bir anlıq hər şeyi unut… Ağrılarını mənə ver…","— Sağ ol, ana, yaxşı ki, varsan. Yanında yaşımı da, yaşadıqlarımı da unuduram. Var ol!","— Ana həyat verəndir, oğlum, həmişə yanındayam.","— Anam, bizlər də səni çox yoruruq, bağışla bizi.","— Məni siz yormursunuz, oğlum. Mənim yorğunluğum anasızlığımdır. Başımı qoymağa ana dizim yoxdur, oğlum… Sən yorulma, əlindəkilərin qədrini bil…","İbrət: Ana qucağı dünyanın ən rahat sığınacağıdır. Anası olan yorğunluğunu qoyacağı bir yer həmişə tapar — əlindəkinin qədrini bil."]},{"stem":"nest-builder","title":"Yuvanın qurucusu","hasAudio":false,"hasImage":true,"paragraphs":["“Yuvanı dişi quş qurar”, — deyiblər. Bu söz ailəyə istilik verən, qayğısı və zəhməti ilə evi doğma ocağa çevirən qadının əməyini xatırladır. O əməyin qədrini bilmək isə yalnız təşəkkür etmək deyil, qayğını və məsuliyyəti bölüşməkdir.","İbrət: Qadının ailə üçün çəkdiyi zəhməti görün və qiymətləndirin. Yuva qarşılıqlı sevgi, hörmət və ortaq əməklə möhkəmlənir."]}]},{"title":"Sevgi və evlilik","slug":"sevgi-ve-evlilik","blurb":"Eşq, vəfa və birgə ömrün sınaqları.","count":20,"stories":[{"stem":"purple-jacket","title":"Bənövşəyi çəpkən","hasAudio":false,"hasImage":true,"paragraphs":["Yörük obaları haqqında danışılan bir rəvayətdə deyilir ki, ərə gedən qızların cehizinə bənövşəyi çəpkən də qoyularmış. Bu qısa üst geyimi sandığın lap dibində saxlanar, qızın onu heç vaxt geyinməyə ehtiyac duymaması arzulanarmış.","Çünki bənövşəyi çəpkən adi libas deyil, kömək çağırışı imiş.","Qadın onu geyinib evin damına, kənd meydanına və ya hamının görə biləcəyi başqa bir yerə çıxanda demək istəyərmiş:","— Bu evlilikdə əziyyət çəkirəm. Razılığım olmadan evləndirilmişəm, yaxud ərim mənə zülm edir. Ayrılmaq istəyirəm. Mənə kömək edin!","Rəvayətə görə, bu çağırış cavabsız qalmazmış. Kənd camaatı qadının yanına gələr, onu müdafiə edər, ərindən isə hesab soruşarmış. Ayıb sayılan qadının kömək istəməsi deyil, kişinin onu bu həddə çatdırması imiş.","Bənövşəyi çəpkən görünən kimi gündəlik həyat sanki dayanarmış. İnək sağan, yun əyirən, kilim toxuyan əllər işdən ayrılar; analar, nənələr hər şeyi kənara qoyub qadının yanına tələsərmişlər.","Toy varsa, musiqi susar, şənlik dayanarmış. Bir qadının belə dara düşməsi bütün obanın dərdi sayılarmış.","Arvadına zülm etmiş kişi camaat arasına çıxmağa utanar, çayxanada belə üzünə baxan olmazmış. Qadının ayrılmaq istəyinə qarşı dura bilməz, yenidən ailə qurmaq istəyəndə isə ona etibar edən çətin tapılarmış.","Bu rəvayətdə bənövşəyi çəpkən qadının tək qalmayacağına verilən bir söz kimidir: «Səsini eşidəcəyik, yanında olacağıq.»","İbrət: Zorakılığa məruz qalan qadının kömək istəməsi ayıb deyil; ayıb ona zülm etmək və buna göz yummaqdır. Həmrəylik qadının səsini eşitmək, təhlükəsizliyini qorumaq və qərarlarına hörmət etməkdən başlayır."]},{"stem":"friendship-and-love","title":"Dostluq və sevgi","hasAudio":false,"hasImage":true,"paragraphs":["Küsülülüyü yarpaqlara yaz ki, payız gələndə saralıb tökülsün, inciklik də onlarla getsin.","Qəzəbi buludlara yaz ki, yağışla boşalsın, səma açıldıqca ürəyin də durulsun.","Nifrəti qarın üstünə yaz ki, günəş doğanda əriyib yox olsun.","Dostluğu və sevgini isə uşaqların qəlbinə yaz — xoş sözünlə, qayğınla, əməlinlə. Qoy onlar böyüdükcə içlərindəki sevgi də böyüsün, başqalarının qəlbinə yol tapsın.","İbrət: İncikliyi bəsləyib böyütmə, sevgini böyüt. Qəlblərdə yaşatdığımız yaxşılıq bizdən sonra da yoluna davam edə bilər."]},{"stem":"early-marriage","title":"Erkən evlilik","hasAudio":false,"hasImage":true,"paragraphs":["Universiteti yenicə bitirib bir məktəbdə müəllim işləməyə başlamışdım. Bir gün müəllimlər otağında şagirdlərin imtahan vərəqlərini yoxlayırdım. Bəzi qızların səhv cavablarını silib düzəldirdim ki, sinifdə qalmasınlar.","Elə bu vaxt otağa tanımadığım bir adam girdi. Bir qədər məni müşahidə etdikdən sonra soruşdu:","— Qızların cavablarını niyə dəyişirsiniz?","Əlimdəki qələmi saxladım.","— Bu qızlardan bəziləri imtahandan kəsilsə, ataları onları məktəbdən çıxarıb on iki-on üç yaşında ərə verəcəklər. Sinfi keçsələr, bəlkə, daha bir neçə il oxuya bilərlər. O illərdə nəsə öyrənər, özlərinə inanar, bəlkə də, həyatları üçün başqa bir yol taparlar.","Adam bir müddət susdu. Sonra sağollaşıb çıxdı.","Təxminən yarım saat sonra direktor məni yanına çağırdı:","— Müəllimlər otağında bir nəfərlə danışmısan. Ona nə demisən?","Narahat oldum:","— Məndən şikayət edib?","— Xeyr. O, məktəbə yoxlama üçün gəlmişdi.","Ürəyim sıxıldı. Direktor sözünə davam etdi:","— Dedi ki, burada uşaqların gələcəyini düşünən bir gənc müəllim var. Sənə təşəkkürünü çatdırmağımı istədi.","Rahat nəfəs aldım. Amma içimdəki narahatlıq keçmədi. Bir neçə cavabı dəyişmək bu qızların gələcəyini qorumağa yetməzdi. Onların məktəbdə qalmaq haqqı nə bir imtahan qiymətindən, nə də bir müəllimin gizli müdaxiləsindən asılı olmalı idi.","İbrət: Bir müəllimin qayğısı uşağın həyatında dönüş yarada bilər. Amma heç bir qız uşaqlığını və təhsilini qorumaq üçün belə bir təsadüfə möhtac qalmamalıdır. Erkən evliliyə göz yummamaq, qızların oxumasına və gələcəklərini özlərinin qurmasına dayaq olmaq hamımızın məsuliyyətidir."]},{"stem":"eraser-in-marriage","title":"Evlilikdə pozan","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün ata yenicə evlənmiş oğlundan bir vərəq ağ kağız, karandaş və pozan gətirməsini istəyir.","— Nə üçün, ata? — deyə oğul soruşur.","— Sən gətir, görəcəksən.","Oğul kağızla karandaşı gətirir, amma pozan tapa bilmir.","— Get, bir pozan da al gətir, — deyir ata.","Oğul təəccüblənsə də, gedib pozan alır və atasının yanında oturur.","— Yaz, — deyir ata.","— Nə yazım?","— Ürəyindən nə keçir, onu yaz.","Oğul bir cümlə yazır.","— İndi sil.","Oğul yazdığını silir.","— Başqa bir cümlə yaz.","— Ay ata, axı nə etmək istəyirsən?","— Bir az səbirli ol. Yenə yaz.","Oğul yazır, atası da yenə sildirir. Bu, bir neçə dəfə təkrarlanır. Axırda ata soruşur:","— Kağızda yazdıqların qalıbmı?","— Yox, ata, hamısını sildim. Bəs bunun mənası nədir?","Ata əlini oğlunun çiyninə qoyur:","— Oğlum, ailə həyatında da belə bir pozana ehtiyac var. Həyat yoldaşının xırda səhvlərini bağışlamağı, hər incikliyi ürəyində saxlamamağı bacarmalısan. Onun da belə bir pozanı olmalıdır ki, sənin səhvlərinə anlayışla yanaşsın. Yoxsa ailə həyatınızın səhifəsi tezliklə giley-güzarla dolar.","Sonra əlavə edir:","— Sevgi və hörmət gözləyirsinizsə, ikiniz də onları bir-birinizdən əsirgəməyin. Səhv edəndə üzr istəməyi, səhvinizi düzəltməyi, bir-birinizi bağışlamağı unutmayın. Pozan hər ikinizin əlində olmalıdır.","İbrət: Evlilikdə sevgi və hörməti yaşadan təkcə səhvləri bağışlamaq deyil, öz səhvini anlayıb düzəltməkdir. Qarşılıqlı anlayış xırda incikliklərin böyük küskünlüklərə çevrilməsinə imkan vermir."]},{"stem":"before-you-marry","title":"Ailə qurmağa hazırlaşanlara tövsiyələr","hasAudio":false,"hasImage":true,"paragraphs":["Ailə qurmağa hazırlaşan gənc bir cütlüyə dünyagörmüş böyüklər belə nəsihət verdilər:","“Öz ailənizi başqalarının ailəsi ilə müqayisə etməyin. ‘Filankəsin əri belədir’, ‘filankəsin arvadı elədir’ deməyin. Kənardan baxmaqla heç bir evin içində nə yaşandığını bilmək olmaz. Siz öz yuvanızı qurun.","Bir-birinizdə qüsursuzluq axtarmayın. Hər kəsin çatışmayan cəhətləri var. Hansını anlayışla qarşılamaq, hansını birlikdə aradan qaldırmaq lazım olduğunu ayırd etməyi öyrənin. Keçmiş səhvləri hər mübahisədə yenidən üzə vurmayın.","Ürəyinizdən keçənləri dilə gətirmədən həyat yoldaşınızın sizi anlamasını gözləməyin. İstəklərinizi, narahatlıqlarınızı, incikliklərinizi açıq və sakit dillə söyləyin. Bir-birinizi cavab vermək üçün deyil, anlamaq üçün dinləyin.","Bir ömrü bölüşsəniz də, hər birinizin öz düşüncələri, maraqları və bəzən tək qalmaq ehtiyacı olacaq. Kirpilər də bir-birinə elə yaxınlaşırlar ki, həm bir-birini isitsinlər, həm də tikanları ilə yaralamasınlar. Siz də yaxınlığınızı qoruyun, amma bir-birinizi sıxmayın.","Bir-birinizə hökm edən və ya kor-koranə tabe olan deyil, ömür yolunu yanaşı gedən iki insan olun. Qərarları birlikdə verin, qayğıları bölüşün, hər birinizin öz fikrini söyləməyə haqqı olduğunu unutmayın.","‘Hər şey həmişə gözəl olacaq’ deyə söz verməyin. Bunun əvəzinə deyin: ‘Çətin günündə səni tək qoymayacağam’.","Bir-birinizdən incik olsanız belə, yatmazdan əvvəl ‘Gecən xeyrə qalsın’ deməyi unutmayın. Hər mübahisə bir axşamda həll olunmaya bilər. Amma inciklik içində də mehribanlığı qorumaq mümkündür. Qoy yeni gün bir-birinizi dinləmək və barışmaq üçün fürsət olsun.”","İbrət: Möhkəm ailəni iki qüsursuz insan deyil, bir-birini dinləməyi, anlamağı və incitmədən danışmağı bacaran iki insan qurur. Bir yuvanı bölüşmək bir-birinə sahib olmaq deyil, bir-birinə dayaq olmaqdır."]},{"stem":"i-kiss-your-eyes","title":"Gözlərindən öpərəm","hasAudio":false,"hasImage":true,"paragraphs":["Bilirsinizmi, niyə «gözlərindən öpərəm» deyirlər?","Çünki həsrətin acısını ən çox gözlər çəkir: yollara dikilir, göz yaşı tökür, sevdiyini axtarır. Bəlkə də, buna görə vüsalın sevincinə ən çox onlar layiqdir.","İbrət: Gözlər dilə gəlməyən həsrəti daşıyır. Sevdiyinin gözlərindən öpmək sanki onun çəkdiyi həsrətə nəvazişlə toxunmaqdır."]},{"stem":"flower","title":"Gül","hasAudio":false,"hasImage":true,"paragraphs":["Gülü çox sulasan, çürüyər, az sulasan, quruyar. Ehtiyacı qədər sulasan, boy atıb çiçəklənər.","İbrət: Sevgidə də, tərbiyədə də qayğının ölçüsü qarşı tərəfin ehtiyacıdır. Nə sıxıb boğmaq, nə də diqqətsiz qoymaq — böyüməyə yer verən qayğı yaşadır."]},{"stem":"true-love","title":"Həqiqi eşq","hasAudio":false,"hasImage":true,"paragraphs":["Bir zamanlar bütün duyğuların yaşadığı bir ada vardı.","Bir gün adanın batmaqda olduğu xəbəri yayıldı. Hamı təlaşla qayıqlarını hazırlayıb adanı tərk etməyə başladı.","Təkcə Eşq getməyə tələsmirdi. Sanki bir möcüzənin adanı xilas edəcəyinə inanır, son ana qədər gözləyirdi. Su hər tərəfi bürüyəndə isə kömək istəməkdən başqa çarəsi qalmadı.","Elə bu vaxt Zənginlik böyük bir qayıqla yanından keçirdi.","— Zənginlik, məni də özünlə apararsan? — deyə Eşq səsləndi.","— Apara bilmərəm. Qayığım qızıl-gümüşlə doludur, sənə yer yoxdur.","Eşq bu dəfə gözəl bir yelkənli qayıqda uzaqlaşan Təkəbbürə üz tutdu:","— Təkəbbür, xahiş edirəm, mənə kömək et!","— Səni götürə bilmərəm. Üst-başın su içindədir, qayığımı korlayarsan.","Yaxınlıqdan Kədər keçirdi.","— Kədər, səninlə gələ bilərəm?","— Ah, Eşq, o qədər kədərliyəm ki... Tək qalmaq istəyirəm.","Xoşbəxtlik də uzaqda deyildi. Amma sevincinə elə qapılmışdı ki, Eşqin çağırışını eşitmədi.","Birdən bir səs gəldi:","— Eşq, gəl, səni mən apararam!","Eşq o qədər sevindi ki, ona kömək edənin kim olduğunu soruşmaq ağlına belə gəlmədi. Sahilə çatanda xilaskarı onu düşürüb yoluna davam etdi.","Eşq yalnız onda ona nə qədər borclu olduğunu anladı. Qarşısına çıxan bir müdrikə başına gələnləri danışıb soruşdu:","— Məni xilas edən kim idi?","— Zaman, — deyə müdrik cavab verdi.","— Zaman? Bəs niyə məhz o mənə kömək etdi?","Müdrik gülümsədi:","— Çünki Eşqin əsl dəyərini yalnız Zaman bilir.","İbrət: Həqiqi sevginin dəyəri zamanla üzə çıxır. Onu yaşadan təkcə gözəl sözlər deyil, illər boyu göstərilən qayğı, sədaqət və çətin gündə bir-birinə dayaq olmaqdır."]},{"stem":"what-women-endure","title":"Nələr çəkdi qadın bu dünyada...","hasAudio":false,"hasImage":true,"paragraphs":["Nələr çəkdi qadın bu dünyada...","Nağıllarda belə ona gah cadugər, gah zalım ögey ana donu biçdilər.","Haqqında nələr söyləmədilər...","Özü olmağa imkan vermədilər. Halbuki arzuları, düşüncələri, sevgisi ilə bütöv bir insan olduğunu görməliydilər.","Qadın...","«Saçı uzun, ağlı qısadır», — dedilər.","«Əlin unlu, yerində otur, belə işlərə qarışma», — dedilər.","Ah, qadın, nələr çəkdin bu dünyada...","Qədrini bilən az oldu.","Sevgini, qəlbini, yaxşılığını görən az oldu.","Haqqını istəyəndə pis oldun, susanda sadəlövh.","Sevgini göstərəndə bəziləri sənə sahib olduqlarını sandılar.","Məhəbbətinlə göylərə qaldırdığın insanlar bəzən oradan sənə baxmağı belə unutdular.","«Necəsən?» — deyə soruşmadılar.","Varlığını, yoxluğunu duymadılar.","Sənin də bir ruhun olduğunu unutdular.","İnsan olduğunu unutdular.","İncitdilər, əzdilər, yox saydılar...","Sən isə həyatı gözəlləşdirmək, dayaq olmaq, nəyisə yaxşılığa doğru dəyişmək istəyirdin.","Sevgi verən qəlbin sevgiyə möhtac qaldı.","Sənə cənnətdən danışıb cəhənnəm yaşatdılar.","Gözlərinin içinə baxa-baxa oradakı ağrını belə inkar etdilər.","İçindən qopan fəryadı eşitmədilər.","Sən ən çox ana olmağı sevdin.","Övladının gözlərinə sevgi ilə baxmağı sevdin.","Elə anlar oldu ki, bu dünyada yalnız onun qucağındakı sevgiyə ürəkdən inana bildin.","İbrət: Qadına dəyər vermək onun fədakarlığını tərifləməklə bitmir. Onun səsini eşitmək, əməyini görmək, seçimlərinə və ləyaqətinə hörmət etmək lazımdır. Sevgi və dinclik bərabər dəyər gördüyümüz yerdə yaranır."]},{"stem":"woman-and-the-mirror","title":"Qadın və güzgü","hasAudio":false,"hasImage":true,"paragraphs":["Bir qadın səhər oyanıb güzgüyə baxır. Görür ki, başında cəmi üç tel saç qalıb.","«Nə yaxşı, bu gün saçımı hörərəm», — deyə düşünür.","Saçını hörür və gözəl bir gün keçirir.","Ertəsi səhər güzgüyə baxanda başında iki tel saç qaldığını görür.","«Bu gün də saçımı ortadan ayıraram», — deyir.","Dediyini edir və yenə günü xoş keçir.","Üçüncü səhər başında bircə tel saç qaldığını görür.","«Eybi yoxdur, bu gün də at quyruğu yığaram!»","Elə də edir və gününü xoş əhvalda keçirir.","Növbəti səhər güzgüyə baxanda görür ki, başında heç saç qalmayıb.","Sevinclə deyir:","— Lap yaxşı! Bu gün heç saçımı düzəltməyə də ehtiyac yoxdur!","İbrət: Hər vəziyyəti dəyişdirə bilməsək də, ona necə yanaşacağımızı seçə bilərik. Bəzən bir az yumor və fərqli baxış çətin günü yüngülləşdirir."]},{"stem":"red-dress","title":"Qırmızı don","hasAudio":false,"hasImage":true,"paragraphs":["Qırmızı don anamın qarderobunda asılmışdı. İllərlə geydiyi köhnə, rəngi solmuş paltarların arasında sanki işıq saçırdı.","Anama baş çəkməyə gəlmişdim. Onu görən kimi anladım ki, ömrünün son anlarını yaşayır.","Qarderobdakı dona baxıb dedim:","— Ana, nə gözəl dondur! Bunu heç əynində görməmişəm.","— Heç geyinməmişəm, qızım, — deyə astadan cavab verdi. — Gəl, yanımda otur. Getməmişdən əvvəl sənə bir söz demək istəyirəm.","Yatağının kənarında əyləşdim. Anam dərindən nəfəs aldı:","— Çox vaxtım qalmayıb. Elə bilirdim, sizə həmişə yaxşı nümunə olmuşam. İndi isə anlayıram ki, bəzi şeyləri yanlış öyrətmişəm.","— Nə danışırsan, ana?","— Qulaq as, qızım. Ömrüm boyu inandım ki, yaxşı qadın özünü həmişə axırıncı düşünməlidir. Əvvəl hamının istəyini yerinə yetirməli, yalnız sonra özünü yada salmalıdır. Mənim arzularım başqalarının istəklərinin altında qaldı. Düşündüm ki, bir gün mənim də növbəm çatar. Amma o gün gəlmədi. Ömrüm atan, bacı-qardaşların və sənin üçün etdiyim fədakarlıqlarla keçdi.","— Sən bizim üçün bir ananın edə biləcəyi hər şeyi etdin.","— Sizi sevdiyimə, sizə qayğı göstərdiyimə peşman deyiləm. Amma özümə də qayğı göstərməliydim. Özüm üçün nəsə istəməyi öyrənmədim. Atan indi o biri otaqda oturub əsəbi halda divarlara baxır. Həkim ona son günlərimi yaşadığımı deyəndə yanıma gəlib söylədi: «Sən ölə bilməzsən! Eşidirsən? Səndən sonra mən nə edəcəyəm?»","Anam bir qədər nəfəsini dərib davam etdi:","— Həftənin yeddi günü sizin üçün çalışdım. Evdə hamıdan əvvəl oyandım, hamıdan sonra yatdım. Yanmış çörəyi, ən kiçik tikəni özümə götürdüm. Yığdığım hər qəpiyi geyiminizə, kitablarınıza xərclədim; bəzən ehtiyacınız olmasa belə. Özümə isə sırf xoşuma gəldiyi üçün gözəl bir şey almadım.","Gözləri qırmızı dona tərəf çevrildi.","— Keçən il ilk dəfə özüm üçün o donu aldım. Paltaryuyan maşının təmirinə ayırdığım bir az pul vardı. Donla evə gələndə atan dedi: «Bunu hara geyinəcəksən? Yoxsa operaya gedəcəksən?»","Anamın səsi titrədi:","— Mən də düşündüm ki, haqlıdır. Elə bil gözəl bir don geyinmək üçün xüsusi səbəbim olmalıydı. Mağazada əynimə keçirib baxdığımdan başqa, bir dəfə də geyinmədim.","Bir az susdu.","— Elə bilirdim, bu dünyada özümü unutsam, o biri dünyada xoşbəxt olaram. İndi başqa cür düşünürəm. İnanmaq istəyirəm ki, Allah bizə verdiyi həyatı da sevməyimizi, arzularımıza sağ ikən yer ayırmağımızı istəyir. Bir möcüzə olsa, bu yataqdan qalxsam, başqa cür yaşayaram.","Sonra əlimi tutdu:","— Qızım, mənim kimi özünü unutma. Söz ver.","Anama söz verdim.","Bunlar onun mənə dediyi son sözlər oldu. Az sonra son nəfəsini verdi.","İbrət: Sevdiklərinə qayğı göstərmək özündən vazkeçmək demək deyil. Başqalarının arzularına yer ayırarkən öz arzularını da yaşat. Sənin həyatın, sevincin və ehtiyacların da dəyərlidir."]},{"stem":"keep-your-hearts-close","title":"Qəlblərinizin ayrılmasına imkan verməyin","hasAudio":false,"hasImage":true,"paragraphs":["Yanımızdakı insan bizi eşidə bildiyi halda mübahisə zamanı niyə səsimizi qaldırırıq?","Bunu belə təsəvvür etmək olar: inciklik artdıqca qəlblər arasındakı məsafə də böyüyür. İnsan səsini yüksəldərək o məsafəni aşmağa çalışır. Amma qışqırıq çox vaxt sözümüzü daha aydın çatdırmır, bir-birimizi eşitməyimizi daha da çətinləşdirir.","Sevgi və etibar olan yerdə isə sakit bir söz də yetər. Bəzən bir pıçıltı, bir baxış, əlini o birinin əlinin üstünə qoymaq uzun cümlələrdən daha çox şey deyir. İnsan özünü dinlənilmiş və anlaşılmış hiss edəndə səsini ucaltmağa ehtiyac duymur.","Yaxınlıq heç vaxt mübahisə etməmək deyil. Fikir ayrılığı içində də bir-birinin qəlbini qorumağı bacarmaqdır.","Ona görə əsəbiləşəndə bir anlıq dayan. Demək istədiyini söylə, amma alçaltma. İncikliyini anlat, amma yaralama. Sakit danışmaq alınmırsa, bir az ara ver, sonra söhbətə qayıt.","Qoy mübahisə bitsin, aranızdakı bağ yox.","İbrət: Mübahisədə məqsəd bir-birini susdurmaq deyil, anlamaq olsun. Elə söz seç ki, qəzəb keçəndən sonra da bir-birinizə yaxınlaşmağa yol qalsın."]},{"stem":"yellow-and-red-flowers","title":"Sarı və qırmızı çiçəklər","hasAudio":false,"hasImage":true,"paragraphs":["Deyilənə görə, keçmişdə pəncərəyə qoyulan çiçəklər bəzən səssiz bir xəbərdarlıq imiş.","Sarı çiçəklər «Bu evdə xəstə var, yanından keçərkən səs-küy salmayın», qırmızı çiçəklər isə «Bu evdə gənc bir qız yaşayır, danışığınıza diqqət edin» mənasını verərmiş.","İbrət: Bəzən zərif bir işarə çox sözün deyə bilmədiyini çatdırır. Nəzakət yalnız özünü ifadə etmək deyil, başqasının səssiz xahişini də duymaqdır."]},{"stem":"five-more-minutes","title":"Sevdiklərinizdən muğayat olun","hasAudio":false,"hasImage":true,"paragraphs":["Günəşli bir gündə parkda oturan qadın yanındakı kişiyə yelləncəkdə oynayan uşağı göstərdi:","— Qırmızı köynəkli oğlan mənim oğlumdur.","Kişi gülümsədi:","— Mavi köynəkli də mənim oğlum Cəmildir.","Bir qədər sonra kişi saatına baxıb səsləndi:","— Cəmil, evə getmək vaxtıdır.","— Daha beş dəqiqə, ata, nə olar!","Ata razılaşdı. Bir az keçəndən sonra oğlunu yenə çağırdı. Cəmil bir beş dəqiqə də istədi. Atası yenə gülümsəyib başı ilə razılıq verdi.","Qadın heyranlıqla dedi:","— Çox səbirli atasınız.","Kişinin üzünə kədərli bir təbəssüm qondu.","— Məsələ səbirdə deyil, — dedi. — Keçən il böyük oğlum Kamalı yaxınlıqdakı yolda sərxoş bir sürücü vurub öldürdü. Ona həmişə az vaxt ayırırdım. Elə bilirdim, birlikdə olmağa hələ çox vaxtımız var. İndi onunla cəmi beş dəqiqə də keçirə bilmək üçün hər şeyimdən keçərdim. Özümə söz vermişəm ki, Cəmillə eyni səhvi təkrarlamayacağam.","Bir an susub oğluna baxdı.","— O elə bilir ki, hər dəfə oynamaq üçün beş dəqiqə də qazanır. Əslində isə o beş dəqiqə mənə də verilir: oğluma baxmaq, gülüşünü eşitmək, yanında olmaq üçün…","İbrət: Sevdiklərimizə ayırdığımız vaxtı sabaha saxlamayaq. Bəzən adi görünən beş dəqiqə həyatın bizə verdiyi ən qiymətli hədiyyədir."]},{"stem":"those-who-give-love-receive-love","title":"Sevgi verən sevgi görər","hasAudio":false,"hasImage":true,"paragraphs":["Qədim bir Çin hekayəsində deyilir ki, Li-Li adlı gənc qadın ailə qurub əri və qayınanası ilə bir evdə yaşamağa başladı.","Çox keçmədi ki, gəlinlə qayınana arasında narazılıqlar yarandı. Xasiyyətləri fərqli idi: birinin adi saydığı söz o birinə ağır gəlir, ən xırda məsələ belə mübahisəyə çevrilirdi. Evdəki gərginlik Li-Lini də, iki doğma insanın arasında qalan ərini də yorurdu.","Bir gün Li-Li atasının köhnə dostu olan, bitkilərdən dərman hazırlayan yaşlı bir adamın yanına getdi. Dərdini danışdı, sonra hirslə dedi: — Daha dözə bilmirəm. Ondan birdəfəlik qurtulmaq istəyirəm.","Yaşlı adam onu dinlədi və bir qab bitki qarışığı gətirdi. Bunun tədricən təsir edən zəhər olduğunu söylədi. Sonra əlavə etdi: — Amma bir şərtim var: qayınananla mehriban davranmalısan. Sözünü kəsmə, hər dediyinə etiraz etmə, qayğısına qal. Aranızdakı düşmənçilik heç kimin diqqətini çəkməsin.","Li-Li evə qayıdıb qarışığı qayınanasının yeməyinə qatmağa başladı. Onun sevdiyi yeməkləri bişirir, halını soruşur, əvvəl mübahisə edəcəyi məqamlarda özünü saxlayıb onu dinləyirdi.","Əvvəlcə bunları şübhə doğurmamaq üçün edirdi. Lakin zaman keçdikcə qayınanasında əvvəllər görmədiyi cəhətləri sezdi. Sərt sözlərinin arxasında bəzən narahatlıq, iradlarının arxasında isə qayğı vardı.","Qayınanası da dəyişirdi. Gəlininin mehribanlığına mehribanlıqla cavab verir, onu öz qızı kimi əzizləyirdi. Evdə mübahisələrin yerini sakit söhbətlər, incikliyin yerini doğmalıq tuturdu.","Bir gün Li-Li qayınanasına baxıb onu itirməkdən qorxduğunu anladı.","Tələsik yaşlı adamın yanına qaçdı: — Yalvarıram, mənə kömək edin! Qayınanamı xilas edəcək bir dərman verin. Mən onu sevirəm. Onun başına bir iş gəlməsini istəmirəm!","Yaşlı adam sakitcə dedi: — Qorxma, Li-Li. Sənə verdiyim qarışıq zəhər deyildi. Qayınananı zəhərləməmisən.","Li-Li heyrətlə ona baxdı.","— Sizin münasibətinizi zəhərləyən içinizdə yığılıb qalan inciklik idi, — qoca sözünə davam etdi. — Sən davranışını dəyişməklə bir-birinizi tanımağınıza və anlamağınıza imkan yaratdın. Mehribanlıq əvvəlcə bir niyyət idi, sonra həqiqi hissə çevrildi.","Li-Linin gözləri doldu. Evə qayıtmağa, qayınanasını qucaqlamağa tələsdi.","İbrət: İnciklik bəzən qarşımızdakı insanın yaxşı cəhətlərini görməyə mane olur. Dinləmək, anlayış göstərmək və qayğı ilə davranmaq münasibətin dəyişməsinə yol aça bilər. Səmimi yaxınlıq isə hər iki tərəfin bir-birinə hörmət etdiyi yerdə yaranır."]},{"stem":"can-a-broken-heart-love-again","title":"Sınan qəlb yenə sevərmi?","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün bir adam dərvişdən soruşdu:","— Sınmış qəlb yenə sevə bilərmi?","— Əlbəttə, sevə bilər, — deyə dərviş cavab verdi.","Adam tərəddüdlə soruşdu:","— Bəs siz heç sınıq qabdan su içmisinizmi?","Dərviş gülümsədi:","— Bəs siz bir qab sındı deyə su içməkdən əl çəkmisinizmi?","İbrət: Qəlbin sınması sevmək qabiliyyətini itirmək deyil. Sağalmaq üçün özünə vaxt ver, amma bir inciklik üzündən ürəyini sevgiyə həmişəlik bağlama."]},{"stem":"mother-of-pearl-flower","title":"Sədəf çiçəyi","hasAudio":false,"hasImage":true,"paragraphs":["Məhkəmədə səksən yaşlı ər-arvadın boşanma işinə baxılırdı. Əlli il birlikdə yaşamış bu iki insanın ayrılmaq istəməsi salondakıları kədərləndirmişdi.","Hakim ağlamaqdan gözləri çökmüş qadına baxıb sakitcə soruşdu:","— De görək, xala, niyə boşanmaq istəyirsən?","Qadın dərindən nəfəs aldı:","— Bu adam məni yordu. Əlli ildir özümü tək hiss edirəm…","Susdu. Salonda yalnız bir fotoaparatın səsi eşidildi. Məhkəməni izləyən jurnalistlər də onun sözünün davamını gözləyirdilər.","— Çox sevdiyim bir sədəf çiçəyim var, — qadın gözlərini silib davam etdi. — Əlli il əvvəl onun mənə gətirdiyi güllərdən birini kökləndirib əkmişdim. Övladımız olmadı. O çiçəyə övladım kimi baxdım.","Bir müddət sonra çiçək solmağa başladı. Onda ərim dedi ki, gecələr qalxıb sulasam, yenidən canlanar. Mən də söz verdim. Əlli ildir hər gecə durub o çiçəyə qulluq edirəm. Bu adam bir dəfə də demədi ki, sən yat, bu gecə mən baxaram.","Qadının səsi titrədi:","— Keçən gecə taqətim qalmamışdı, oyana bilmədim. O da məni oyatmadı. Səhər baxdım ki, çiçək sulanmamış qalıb. Bəlkə, sizə xırda şey kimi görünür. Amma mənə elə gəldi ki, əlli il boyu mənim üçün əziz olan heç nə onun üçün əhəmiyyət daşımayıb.","Hakim üzünü kişiyə çevirdi:","— Sənin demək istədiyin bir söz varmı, baba?","Yaşlı kişi əsasına söykənib ayağa qalxdı:","— Əsgərlikdə bağbanlıq edirdim. Fatiməni də o vaxt tanıdım. Onun üçün ən gözəl güllərdən dəstələr düzəldirdim.","Bir an arvadına baxdı, sonra sözünə davam etdi:","— Təzə evlənmişdik. Boynu ağrıyırdı. Onu həkimə apardım. Yadımda qaldığına görə, həkim uzun müddət hərəkətsiz qalmamasını, arabir qalxıb gəzişməsini demişdi. Amma Fatimə özünə fikir vermirdi. Mən də nigaran qalırdım.","Elə o vaxt çiçək solmağa başladı. Mən ona dedim ki, gecə qalxıb sulasa, çiçək özünə gələr. İstədim ki, heç olmasa, çiçəyə görə qalxıb bir az hərəkət etsin. O da söz verdi.","Kişinin səsi kövrəldi:","— Hər gecə onu oyadır, çiçəyə necə qayğı ilə yanaşdığına baxırdım. O, çiçəyini qoruyurdu, mən də onu qoruduğumu düşünürdüm. Sonra Fatimə yatanda qalxıb dibçəyin altlığında yığılan artıq suyu boşaldırdım ki, kökləri çürüməsin.","Bir qədər susdu:","— Keçən gecə mən də oyana bilmədim. Qocalmışıq… Səhər məndən incidiyini görəndə nə deyəcəyimi bilmədim. Əlli il susmuşdum, yenə susdum.","Salonda heç kim danışmırdı. Jurnalistlərin də gözləri dolmuşdu.","İllərlə eyni evdə yaşayan iki insan ilk dəfə bir-birinin susqunluğunun arxasında nə olduğunu eşidirdi.","İbrət: Səssiz qayğı sevgidən doğa bilər, amma dilə gətirilməyəndə görünməz qalar. Sevgi həm qayğı göstərmək, həm də dinləmək, hisslərini bölüşmək və bir-birini anlamağa çalışmaqdır."]},{"stem":"i-love-you","title":"Səni sevirəm","hasAudio":false,"hasImage":true,"paragraphs":["Deyilənə görə, bir bülbül ağ gülə aşiq olmuşdu. Hər gecə gəlib onun budağına qonar, sevgisini nəğmələri ilə dilə gətirərdi. Ağ gül isə onun hisslərinə laqeyd qalar, nəğmələrinə cavab verməzdi.","Bir gün bülbül yenə cəsarətini toplayıb gülə ürəyini açdı:","— Səni bütün qəlbimlə sevirəm.","Gül isə sərt cavab verdi:","— Məni rahat burax. Mən səni sevmirəm.","Bülbül nə qədər dil töksə də, gülün cavabı dəyişmədi.","Rədd edilməyin ağrısına qapılan bülbül çıxış yolu görmədi və özünə qəsd etdi. Əfsanəyə görə, onun qanı ağ gülün ləçəklərini qırmızıya boyadı.","Gül bülbülün sevgisinin dərinliyini yalnız onu itirəndə anladı. Amma artıq gec idi. Hər gecə eşitdiyi nəğmə əbədi susmuşdu.","Deyirlər, qırmızı gülün «Səni sevirəm» deməsi də bu kədərli əfsanədən qalıb.","İbrət: Qarşılıqsız sevgi ağrılı olsa da, insanın dəyərini azaltmır. Heç bir sevgi özünü məhv etməklə sübut olunmalı deyil. Başqasının hisslərinə həssas yanaşmaq qədər onun seçiminə və öz həyatına hörmət etmək də vacibdir."]},{"stem":"loving-from-afar","title":"Uzaqdan sevmək","hasAudio":false,"hasImage":true,"paragraphs":["İki dost görüşüb söhbət edir:","— Deyəsən, bir qıza vurulmuşam.","— Nə gözəl! Özünün xəbəri var?","— Yox.","— Bəs niyə yaxınlaşıb demirsən?","— Deyərdim, amma rahatlığımın pozulmasından qorxuram. Durduğum yerdə özümə iş açaram. Sonra kinoya, teatra gedərik, əl-ələ gəzərik. Ardınca küsüb-barışmalar, «Ona niyə baxdın?», «Buna niyə gülümsədin?» söhbətləri başlayar. Axırda ayrılacağıqsa, bu qədər həngaməyə nə ehtiyac var?","Bir an susub əlavə edir:","— Yaxşısı budur, mən o qızı elə uzaqdan sevim.","İbrət: Bəzən insan hələ başlamamış bir sevginin sonundan qorxur. Özünü mümkün ayrılıqdan qorumağa çalışarkən yaxınlıq və sevinc yaşamaq imkanından da məhrum olur."]},{"stem":"what-is-loyalty","title":"Vəfa nədir?","hasAudio":false,"hasImage":true,"paragraphs":["Unutmamaqdır,","çətin gündə arxa çevirməmək,","qapını dostun üzünə bağlamamaqdır...","Dostun ağlayanda dərdinə biganə qalmamaq,","ağrısını duymaq, kədərini bölüşməkdir vəfa...","Sadəcə bir söz deyil,","dostunla həmhal olmaqdır.","Yaralıya məlhəm,","susuza su olmaqdır.","Vəfa anlamaqdır —","tikanı var deyə gülü atıb getməməkdir.","İbrət: Vəfa çətin gündə yanında olmaq, qüsurlarına görə sevdiyindən üz döndərməməkdir. Onun dəyəri verilən sözdə deyil, göstərilən qayğıda bilinir."]}]},{"title":"Dostluq və insan münasibətləri","slug":"dostluq-ve-insan-munasibetleri","blurb":"Dost seçimi, mərhəmət və insanlara münasibət.","count":32,"stories":[{"stem":"friendship-of-horses","title":"Atların dostluğu","hasAudio":false,"hasImage":true,"paragraphs":["Evimin yaxınlığındakı fermada iki at yaşayır. Uzaqdan baxanda adi atlara bənzəyirlər. Yaxınlaşanda isə görürsən ki, onlardan birinin gözləri görmür.","Sahibi onu tərk etməyib, rahat və təhlükəsiz yaşaması üçün şərait yaradıb. Amma bu atın həyatını asanlaşdıran bir dostu da var.","Fermaya yaxınlaşanda xəfif zınqırov səsi eşidilir. Səs o biri atın yüyənindən asılmış balaca zınqırovdan gəlir. Gözləri görməyən at dostunun yerini bu səslə tapır, ona qulaq verə-verə yolunu davam etdirir.","Bir müddət dayanıb onları izləsən, aralarındakı səssiz anlaşmanı görərsən. Zınqırovlu at arabir dönüb yoldaşına baxır. O biri də səsə doğru aramla addımlayır.","Axşam tövləyə qayıdanda öndəki at tələsmir. Bir az gedir, dayanıb gözləyir. Dostu yaxınlaşanda yenə hərəkətə gəlir. Sanki deyir:","— Buradayam. Səni gözləyirəm.","Biri yol göstərir, o biri ona güvənir. Beləcə, evə birlikdə qayıdırlar.","İbrət: Rəbbin mərhəmətini bəzən yolumuza çıxan bir dostun qayğısında duyuruq. Həyatda gah bizə yol göstərən bir səsə ehtiyacımız olur, gah da kimisə tək qoymamaq bizim payımıza düşür."]},{"stem":"forgiveness","title":"Bağışlamaq","hasAudio":false,"hasImage":true,"paragraphs":["Birini bağışlamaq onu sevməyə, onunla danışmağa və ya münasibəti davam etdirməyə borclu olmaq demək deyil. Bu, onun günahsız olduğunu və ya haqlı davrandığını qəbul etmək də deyil.","Bağışlamaq incikliyin, küskünlüyün və nifrətin həyatına hökm etməsinə son qoymaq, keçmişin ağrısını tədricən yüngülləşdirməkdir.","Özünə zaman ver. Bağışlamağa hazır olanda o yükü burax, amma yaşadıqlarından aldığın dərsi unutma. Qəlbində rahatlığa yer açarkən sərhədlərini də qoru.","İbrət: Bağışlamaq haqsızlığa haqq qazandırmaq deyil, onun yükünü ömür boyu daşımamaqdır. Bağışlaya bilərsən, amma yenidən etibar etmək və münasibəti davam etdirmək ayrı seçimlərdir."]},{"stem":"respecting-boundaries","title":"Başqalarının həyatına qarışmaq","hasAudio":false,"hasImage":true,"paragraphs":["Allah heç kimi başqalarının həyatına qarışacaq qədər işsiz qoymasın!","İbrət: Qayğı göstərmək başqasının yerinə qərar vermək deyil. İstənməyən məsləhət yükə çevrilə bilər; həqiqi kömək insanın seçiminə və şəxsi sərhədlərinə hörmətlə başlayır."]},{"stem":"pair-of-boots","title":"Bir cüt çəkmə","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün müəllimə şagirdlərinə istədikləri mövzuda hekayə yazmağı tapşırdı. Ən gözəl hekayənin müəllifinə bir cüt çəkmə hədiyyə edəcəyini söylədi.","Uşaqlar yazılarını tamamlayıb müəlliməyə verdilər. Müəllimə hekayələri bir-bir oxudu, hamısını bəyəndi. Aralarından birini seçməkdə çətinlik çəkdiyi üçün qalibi püşklə müəyyənləşdirməyə qərar verdi.","Şagirdlərdən hərəsinə öz adını bir kağıza yazıb qatlamağı və masasındakı qutuya atmağı tapşırdı. Kağızları qarışdırdı, birini çəkib açdı və ucadan oxudu:","— Əminə!","Sinif alqış səsinə büründü. Əminə çəkmələri sinəsinə sıxdı, sevinc göz yaşlarını saxlaya bilmədi.","Axşam evdə müəllimə baş verənləri həyat yoldaşına danışarkən gözləri doldu. Həyat yoldaşı təəccüblə soruşdu:","— Nə gözəl çıxış yolu tapmısan! Bəs niyə ağlayırsan?","Müəllimə cavab verdi:","— Sonra qutudakı bütün kağızları açıb baxdım. Digər uşaqların heç biri öz adını yazmamışdı. Hamısı sinfimizin ən imkansız ailəsindən olan Əminənin adını yazmışdı. Hər biri çəkmələri onun qazanmasını istəyirdi.","İbrət: Başqasının sevincini öz sevincin bilmək də bir qələbədir. Əsl mərhəmət bəzən ehtiyacı olan birinin xeyrinə öz şansından səssizcə keçməkdir."]},{"stem":"handful-of-roasted-chickpeas","title":"Bir ovuc ləbləbi","hasAudio":false,"hasImage":true,"paragraphs":["Bir uşaq anası ilə çərəz dükanına girdi. Ləbləbini görən kimi anasına yalvarmağa başladı:","— Ana, mənə ləbləbi al da!","Anasının almaq niyyətində olmadığını görən satıcı uşağın könlünü almaq istədi:","— Gəl, bala, buradan bir ovuc götür. Məndən sənə hədiyyə olsun.","Uşaq əlini uzatmadı:","— Yox, sən versən, alaram.","Satıcı bir ovuc dolusu ləbləbi götürüb uşağa verdi. Sonra maraqla soruşdu:","— Bəs niyə özün götürmədin? Niyə mənim verməyimi gözlədin?","Uşaq gülümsədi:","— Çünki sənin ovucun mənimkindən böyükdür!","Satıcı da gülməyini saxlaya bilmədi:","— Maşallah, balaca fərasətli!","İbrət: Bəzən kiçik bir fərqi görmək böyük üstünlük qazandırır. Fərasət hamının gördüyündə başqasının diqqətindən qaçanı sezməkdir."]},{"stem":"glass-of-milk","title":"Bir stəkan süd","hasAudio":false,"hasImage":true,"paragraphs":["Doktor Hovard Kelli ilə əlaqələndirilən məşhur bir hekayə var:","Təhsil xərclərini ödəmək üçün qapı-qapı gəzib xırda əşyalar satan gənc bir gün bərk acdı. Cibində yemək almağa pulu qalmamışdı. Qərara aldı ki, növbəti qapıda bir tikə çörək istəsin.","Qapını gənc bir qadın açdı. Oğlan utandığından fikrini deyə bilmədi:","— Bir stəkan su verə bilərsiniz?","Qadın onun yorğun üzünə baxdı, ac olduğunu duydu. Bir az sonra əlində böyük bir stəkan südlə qayıtdı.","Oğlan südü aramla içdi. Sonra soruşdu:","— Sizə nə qədər borcluyam?","— Heç nə, — qadın gülümsədi. — Anam bizə yaxşılığı əvəz gözləmədən etməyi öyrədib.","— Onda sizə ürəkdən təşəkkür edirəm.","Oğlan oradan uzaqlaşanda yalnız aclığı azalmamışdı. Qəlbindəki ümidsizlik də yüngülləşmiş, Allaha və insanların xeyirxahlığına inamı təzələnmişdi.","İllər keçdi. Həmin qadın ağır xəstələndi. Yerli həkimlər onu böyük şəhərdəki xəstəxanaya göndərdilər.","Müalicə ilə bağlı məsləhətləşməyə doktor Hovard Kelli də dəvət olundu. Qadının haradan gəldiyini eşidəndə yadına köhnə bir xatirə düşdü. Palataya girib onu görən kimi tanıdı.","İllər əvvəl ona süd verən qadın idi.","Doktor Kelli onun müalicəsində yaxından iştirak etdi. Uzun müalicədən sonra qadın sağaldı.","Xəstəxanadan çıxacağı gün həkim hesabı əvvəlcə ona gətirmələrini istədi. Kağıza bir neçə söz yazıb qadına göndərdi.","Qadın zərfi açmağa qorxurdu. “Görəsən, bu borcu neçə ilə ödəyə bilərəm?” — deyə düşünürdü.","Nəhayət, hesabı çıxarıb baxdı. Kənarında yazılmış bir cümləni oxuyanda gözləri doldu:","“Bir stəkan südlə tam ödənilib.”","Altında həkimin imzası vardı:","Doktor Hovard Kelli.","İbrət: Yaxşılığı geri qayıdacağı üçün deyil, bir insanın ehtiyacına cavab olduğu üçün et. Kiçik bir qayğı unudulmaz iz qoya, illər sonra başqa bir yaxşılığa yol aça bilər."]},{"stem":"everyone-is-equal-here","title":"Bizdə hamı eynidir","hasAudio":false,"hasImage":true,"paragraphs":["Bələdiyyəyə yeni rəhbər seçilmiş gənc yaşadığı ərazini daha yaxından tanımaq üçün küçələri piyada gəzməyə başladı. Bir qədər dolaşdıqdan sonra ara küçədəki çayxanaya girib çay sifariş verdi.","Bu vaxt on iki-on üç yaşlarında bir oğlan ona yaxınlaşdı:","— Əmi, ayaqqabılarınızı parıldadım?","Ayaqqabıları təmiz olsa da, gənc uşağı əliboş qaytarmaq istəmədi:","— Olar. Yaxşı parıldatsan, sənə ikiqat pul verəcəyəm.","Uşaq sakitcə cavab verdi:","— Mən hamının ayaqqabısını eyni cür yaxşı parıldadıram.","Gənc təəccübləndi:","— Necə yəni?","— Müəllimimiz deyir ki, gördüyün işi hamı üçün vicdanla görməlisən. Birinə yaxşı, o birinə başdansovdu olmaz.","Sonra fırçasını çıxarıb əlavə etdi:","— Bu pulla xəstə anama dərman alıram. İstəyirəm, qazandığım pul halal olsun.","Gənc susdu. Oğlanın sadə sözlərində öz vəzifəsi üçün də mühüm bir dərs vardı: yaxşı xidmət əlavə pulun və ya yüksək mövqenin qarşılığı olmamalı idi.","Oğlan işini bitirəndə gənc ona zəhmət haqqını verdi, əlavə olaraq maddi kömək də etdi. Söhbət zamanı öyrəndi ki, oğlan atasız böyüyür, məktəbə gedir, dərsdən sonra isə anasına kömək etmək üçün işləyir.","Gənc əlaqə nömrəsini verib ailəsinə dəstək olmaq üçün onlarla görüşəcəyini söylədi. Sonralar uşağın müəllimi ilə də görüşüb şagirdlərinə aşıladığı dürüstlüyə görə təşəkkür etdi.","Həmin söhbəti unutmamaq üçün masasındakı ad lövhəsinin özünə baxan tərəfinə bir cümlə yazdırdı:","“Bizdə hamı eynidir.”","Hər qərarında bu sözləri xatırlamağa çalışdı: qarşısında kimin dayanmasından asılı olmayaraq, hər kəs eyni hörmətə və ədalətli münasibətə layiqdir.","İbrət: İşini vicdanla görmək üçün qarşındakının varlı və ya vəzifəli olması lazım deyil. Dürüst xidmətin ölçüsü əlavə qazanc yox, hər insanın haqqına göstərilən hörmətdir."]},{"stem":"gossip","title":"Dedi-qodu","hasAudio":false,"hasImage":true,"paragraphs":["Acıdilli bir adam kənddə kiminsə haqqında dedi-qodu yaymışdı. Məsələ böyüyəndə onu kəndin ağsaqqalının yanına çağırdılar.","— Zarafat etmişdim, vəssalam! — deyə adam özünü müdafiə etdi. — Başqaları sözlərimi yanlış anlayıb. Burada mənim nə günahım var?","Haqqında dedi-qodu yayılan adam isə etiraz etdi:","— Sən mənim təmiz adımı ləkələmisən. Mən ədalət istəyirəm.","Dediklərini daha inkar edə bilməyən adam nəhayət geri çəkildi:","— Yaxşı, bütün sözlərimi geri götürürəm. Məni bağışlayın.","Ağsaqqal onu diqqətlə dinlədi. Adamın etdiyi pisliyin ağırlığını hələ anlamadığını hiss edib dedi:","— Get, quş tükü ilə doldurulmuş bir yastıq gətir. Bazar meydanında onu kəs, tüklərini küləyə səpələ. Sonra hamısını bir-bir yığıb yanıma gətir. Bağışlanmaq barədə ondan sonra danışarıq.","Adam könülsüz razılaşdı. «Bu qoca nə qəribə iş tapşırır», — deyə düşünə-düşünə yastığı meydana apardı, kəsib tüklərini havaya sovurdu.","Külək tükləri bir anda dörd yana dağıtdı. Adam gah sağa, gah sola qaçdı, onları tutmağa çalışdı. Amma nə qədər əlləşdisə də, cəmi bir neçə tük yığa bildi.","Başını aşağı salıb ağsaqqalın yanına qayıtdı:","— Qalanlarını yığmaq mümkün olmadı. Külək hərəsini bir tərəfə apardı.","Ağsaqqal soruşdu:","— Bəs indi dediyin sözləri geri götürməyin nə qədər çətin olduğunu anlayırsanmı?","Adam ovcundakı tüklərə baxıb dərindən köks ötürdü:","— Anlayıram. Sözlərim də bu tüklər kimi yayılıb. «Geri götürürəm» deməklə onları geri qaytara bilmərəm.","İbrət: Dedi-qodu küləyə səpilən tük kimidir: yaymaq asan, geri toplamaq çətindir. Üzr istəmək vacibdir, amma vurulan zərəri həmişə silmir. Ona görə sözü deməzdən əvvəl düşün."]},{"stem":"thoughtfulness","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/thoughtfulness.webp","title":"Diqqət","hasAudio":false,"hasImage":true,"paragraphs":["İnsan həyatının ən qiymətli nemətlərindən biri də diqqət və qayğı görməkdir. Bəzən bir qohumun, dostun və ya tanışın sadəcə hal-əhval tutmaq üçün etdiyi qısa zəng belə insanın qəlbində günəş kimi doğur. O an anlayırsan ki, bu geniş dünyanın harasındasa səni xatırlayan, sənin varlığını önəmli sayan insanlar var.","Hər bir insan sevilməyə, yada salınmağa və dəyər verilməyə ehtiyac duyur. Səmimi bir salam, ürəkdən hal-əhval tutmaq və ya gözlənilmədən edilən bir zəng bəzən ən qiymətli hədiyyədən də dəyərli olur. Çünki bu kiçik jestlər insana cəmiyyətdəki yerini və ətrafındakı insanlar üçün nə qədər qiymətli olduğunu hiss etdirir.","Ola bilsin ki, bir neçə dəqiqəlik diqqət kiminsə gününü işıqlandırsın, qəlbində ümid oyatsın və həyata bağlılığını bir az da artırsın.","Bəzən insan ömrünü uzadan dərmanlar deyil, qəlbə yaxın olan sözlər, duyulan qayğı və hiss edilən mənəvi yaxınlıq olur. Çünki xoşbəxtliyin ən etibarlı ünvanlarından biri də insanın unudulmadığını bilməsidir.","İbrət: Birinin halını soruşmaq, onu yada salmaq kiçik görünsə də, ona böyük mənəvi dayaq ola bilər. Qayğımızı əsirgəməyək ki, heç kim özünü unudulmuş hiss etməsin.","Etibar Siracsoy"]},{"stem":"i-wish-for-a-friend","title":"Dost istərəm","hasAudio":false,"hasImage":true,"paragraphs":["Nə mal istərəm, nə mülk, Mən vəfalı dost istərəm. Hansı mülk sahibinə rəhmət oxuyub? Mən arxamca rəhmət oxuyan dost istərəm.","İbrət: İnsanın əsl sərvəti vəfalı dostlarıdır. Sağlığında yanında olan, dünyadan köçəndə səni rəhmətlə anan dost mal-mülkdən qiymətlidir."]},{"stem":"choosing-friends","title":"Dostluq etməyəcəklərin","hasAudio":false,"hasImage":true,"paragraphs":["Təkəbbürlü ilə dostluq etmə! Halını anlamaz, dərdini dinləməz, könlünü düşünməz — üzülərsən.","Özünü hamıdan ağıllı sayanla dostluq etmə! Çox danışar, az dinləyər, sözləri ilə səni kiçildər — üzülərsən.","Namərdlə dostluq etmə! Sözünün üstündə durmaz, dar gündə yanında olmaz, dostluğun qədrini bilməz — üzülərsən.","İbrət: Dost seçərkən şirin sözə deyil, münasibətə və əmələ bax. Əsl dost səni dinləyər, sənə hörmət edər, çətin gündə yanında olar."]},{"stem":"know-your-friend","title":"Dostunu tanı","hasAudio":false,"hasImage":true,"paragraphs":["Dostunu tanımaq istəyirsənsə, dar gündə, çətinlikdə, münaqişədə necə davrandığına bax. Bir də dostluğunuzla şəxsi mənfəəti arasında seçim etməli olanda…","İbrət: Dostluğun dəyəri yalnız xoş günlərdə deyil, çətinlik və fikir ayrılığı zamanı da üzə çıxır. Əsl dost öz mənfəətini düşünərkən sənin haqqını və aranızdakı etibarı unutmur."]},{"stem":"go-but-come-again","title":"Gedin, amma yenə gəlin","hasAudio":false,"hasImage":true,"paragraphs":["Osmanlı qonaqpərvərliyi haqqında danışılan bir rəvayətə görə, ev sahibləri yenidən görmək istədikləri qonaqların ayaqqabılarını qapının önünə ucları evə tərəf baxacaq şəkildə düzərmişlər.","Bu kiçik jest sözsüz bir dəvət sayılarmış:","— Gedirsiniz, amma yolunuz yenə evimizə düşsün. Qapımız üzünüzə açıqdır.","Qonaq da özü ilə yalnız görüşün xoş xatirəsini deyil, yenidən gözlənildiyini bilməyin sevincini apararmış.","İbrət: Mehribanlıq həmişə böyük sözlər istəmir. Bəzən kiçik bir jest insana ən gözəl duyğunu yaşadır: “Burada mənə yer var, məni yenə gözləyirlər.”"]},{"stem":"permission-or-forgiveness","title":"İcazə almaq, yoxsa üzr istəmək?","hasAudio":false,"hasImage":true,"paragraphs":["Kontr-admiral Qreys Hopperin məşhurlaşdırdığı bir ifadə var:","«Bağışlanma diləmək icazə almaqdan daha asandır.»","Bu fikir bəzən belə anlaşılır: əvvəl işi gör, sonra narazı qalan olsa, üzr istə. Ancaq ifadənin təşəbbüsə çağıran tərəfi ilə məsuliyyətsizliyə bəhanə olan yozumunu ayırmaq lazımdır.","Bəzən uzun-uzadı razılıq gözləmək yaxşı bir fikrin həyata keçməsinə mane olur.","Təsəvvür edin ki, bir şirkətdə hər həftə eyni məlumat bir neçə cədvələ əl ilə köçürülür və buna saatlarla vaxt sərf olunur. Əməkdaşlardan biri bu işi sadə bir avtomatlaşdırma ilə asanlaşdırmağın mümkün olduğunu görür.","Təklif bir rəhbərdən digərinə ötürüldükcə cavab həftələrlə gecikə bilər. Əməkdaş isə mövcud məlumatlara və iş prosesinə toxunmadan ayrıca sınaq nümunəsi hazırlayır. Nəticəni həmkarlarına göstərir: əvvəllər saatlarla görülən iş indi bir neçə dəqiqəyə tamamlanır.","Kimsə sınağın əvvəlcədən razılaşdırılmadığını irad tutanda əməkdaş deyir:","— İşimizi asanlaşdırmaq üçün ayrıca sınaq hazırladım. Mövcud sistemə dəyişiklik etməmişəm. Əvvəlcədən xəbər verməli idimsə, üzr istəyirəm.","Burada məqsəd qaydaları saymamaq deyil, faydalı bir fikri məsuliyyətlə sınaqdan keçirməkdir. Risk azdırsa, səhvi düzəltmək mümkündürsə və başqalarının haqqına toxunulmursa, kiçik bir təşəbbüs uzun müzakirələrdən daha aydın nəticə göstərə bilər.","İbrət: Təşəbbüs məsuliyyətlə birləşəndə dəyər qazanır. Kiçik və geri dönülə bilən addımlarla faydanı göstərmək bəzən sonsuz razılıq gözləməkdən daha səmərəlidir. Amma sonradan üzr istəmək əvvəlcədən düşünmək məsuliyyətini aradan qaldırmır."]},{"stem":"compliment","title":"İltifat","hasAudio":false,"hasImage":true,"paragraphs":["Mariya anası ilə kiçik bir mənzildə yaşayır, böyük bir şirkətdə katibə işləyirdi. Günləri bir-birinə bənzəyirdi. İşdə özünü çox vaxt görünməz hiss edirdi: gəlir, tapşırıqlarını yerinə yetirir, axşam da sakitcə evə qayıdırdı.","Bir səhər yolunun üstündə yeni açılmış papaq mağazası gördü. Vitrindəki papaqlardan biri diqqətini çəkdi və içəri girdi.","Mağazada balaca bir qız anası ilə dayanmışdı. Başqa bir müştəri də papaq seçirdi. Mariya bir neçə papağı sınadı. Axırıncını başına qoyanda balaca qız sevincək səsləndi:","— Ana, bax! O xanım bu papaqda necə də gözəl görünür!","Qızın anası dönüb gülümsədi:","— Doğrudan da, sizə çox yaraşır.","O biri müştəri də başı ilə təsdiqlədi:","— Elə bil sizin üçün tikilib!","Mariya güzgüyə baxdı. Çoxdan idi ki, özünə belə diqqətlə, belə mehriban nəzərlərlə baxmırdı. Dodaqlarına təbəssüm qondu, çiyinlərini dikəltdi.","Papağı almağa qərar verdi. Kassaya yaxınlaşıb pulunu ödədi və mağazadan çıxdı.","Küçə elə həmin küçə idi, amma Mariyaya hər şey başqa cür görünürdü. Gül dükanının qarşısındakı çiçəklər daha əlvan, səhər havası daha təravətli idi. Hətta şəhərin səs-küyündə də xoş bir ahəng duyurdu.","Ofisə çatanda mühafizəçinin salamını gülümsəyərək aldı. Liftdə bir nəfər onun gedəcəyi mərtəbənin düyməsini basdı, Mariya da ürəkdən təşəkkür etdi. İş yoldaşları ilə həmişəkindən daha rahat danışır, söhbətlərə həvəslə qoşulurdu.","— Bu gün üzündən nur yağır! — deyə həmkarlarından biri söylədi.","Günorta rəhbəri onu yeni layihə barədə fikirlərini dinləmək üçün nahara dəvət etdi. Mariya bu dəfə düşüncələrini çəkinmədən bölüşdü.","Axşam evə qayıdanda hələ də gülümsəyirdi. Gün ərzində baş verənləri xatırlayır, öz-özünə düşünürdü: “Bir papaq insanın həyatını necə də dəyişə bilirmiş!”","Qapını açan anası ona baxıb sevindi:","— Mariya, necə gözəl görünürsən! Gözlərin uşaqlığındakı kimi parıldayır.","— Hamısı yeni papağımın sayəsindədir, ana! Bu gün elə gözəl gün keçirmişəm ki!","Anası təəccübləndi:","— Hansı papaq?","Mariya əlini başına apardı. Papaq yox idi.","Bir anlıq çaşdı. Görəsən, taksidə qoymuşdu? Yoxsa ofisdə? Sonra mağazadakı anları bir-bir xatırladı: güzgünü, xoş sözləri, kassaya yaxınlaşmasını… Pul kisəsini çıxarmaq üçün papağı başından götürüb piştaxtaya qoymuşdu.","Və elə oradaca unutmuşdu.","Mariya gülümsədi. Deməli, bütün günü onu dəyişdirən papaq deyilmiş. Bir neçə səmimi söz özünə daha mehriban baxmağa, içindəki sevinci üzə çıxarmağa kömək etmişdi.","Dünya əvvəlki dünya idi. Mariya isə artıq onun içində özünü görünməz hiss etmirdi.","İbrət: Səmimi bir iltifat insanın özündə görmədiyi gözəlliyi ona xatırlada bilər. Xoş sözünüzü əsirgəməyin: bəzən kiminsə özünəinamı bircə cümlədən güc alır."]},{"stem":"how-we-treat-people","title":"İnsanlara olan münasibət","hasAudio":false,"hasImage":true,"paragraphs":["İnsanlarla münasibətində odun qarşısında dayandığın kimi dayan:","Nə çox uzaqlaş ki, soyuqdan donasan, nə də çox yaxınlaş ki, istisindən yanasan.","— Sədi Şiraziyə aid edilən kəlam","İbrət: Münasibətlərdə yaxınlıq qədər şəxsi sərhədlər də vacibdir. Elə bir məsafə saxla ki, həm ünsiyyətin istiliyini duyasan, həm də özünü itirməyəsən."]},{"stem":"humanity","title":"İnsanlıq","hasAudio":false,"hasImage":true,"paragraphs":["Kamal illərlə oxumuş, zəhmət çəkmişdi. Nəhayət, gələcəyini müəyyənləşdirəcək imtahan günü gəlib çatmışdı. Atası Kazım kişi tələbkar adam idi. Oğlunun dərsləri ilə yaxından maraqlanır, onun mütləq uğur qazanacağına inanırdı.","Kamal imtahan verəcəyi otağı tapıb yerinə əyləşdi. Sual vərəqləri paylananda həyəcanlandı, amma sualları oxuduqca sakitləşdi. Cavabları bilirdi, inamla yazırdı.","İmtahanın bitməsinə yarım saat qalmış başını qaldırıb pəncərədən baxdı. Birdən yerindən sıçradı və qapıya tərəf qaçdı.","— Geri qayıt! İndi çıxsan, imtahanın ləğv olunacaq! Bir ilin boşa gedəcək, oğlum! — deyə nəzarətçi müəllim səsləndi.","Kamal dayanmadı. Pilləkənləri qaçaraq enib binanın arxa qapısından çıxdı.","Bir neçə saat sonra evə qayıdanda atası artıq baş verənlərdən xəbər tutmuşdu. Oğlunu danladı, qəzəbini cilovlaya bilməyib üzünə şillə vurdu.","— Niyə çıxdın? Niyə imtahanı yarımçıq qoydun?","Kamal susdu. Atasının o anda onu dinləyəcəyinə inanmırdı. Nə desə, qəzəbini daha da artıracağından qorxurdu.","Kazım kişi il boyu bu hadisəni oğlunun üzünə vurdu. Kamal hər dəfə incidi, amma mübahisə etmədi. Yenidən hazırlaşdı və növbəti il tibb fakültəsinə qəbul oldu.","İllər keçdi. Kamal bacarıqlı, qayğıkeş bir həkim oldu. Şəhərdə böyüsə də, ucqar bir kənd xəstəxanasında işləməyi seçdi. Bir müddət sonra ailəsi onu görməyə gəldi. İmtahan əhvalatı artıq çoxdan dillərinə gətirilmirdi.","Qarlı, şaxtalı bir axşam telefon zəng çaldı. Yaxın kəndlərdən birində bir qadının xəstələndiyini deyib kömək istədilər.","Kamal çantasını götürüb hazırlaşdı. Kazım kişi oğlunu belə havada dağ yollarına tək buraxmaq istəmədi:","— Mən də səninlə gəlirəm.","Çovğunun içində bir saata yaxın piyada yol getdilər. Nəhayət, evi tapıb qapını döydülər. Qapını yaşlı bir kişi açdı:","— Xəstə arvadımdır, həkim. Buyurun, içəri keçin.","Kamal qadını müayinə etdi, ilkin yardım göstərdi və müalicəsini izah etdi.","Qadın ona minnətdarlıqla baxıb titrək səslə dedi:","— Bu soyuqda köməyimizə gəldin, oğlum. Sənin kimi insanlar olmasa, dünyanın halı necə olar? Sən mənə bir oğlanı xatırlatdın…","Bir az nəfəsini dərib sözünə davam etdi:","— İllər əvvəl şəhərə getmişdim. Hamilə idim. Küçədə birdən halım pisləşdi, güclü sancım tutdu. Ətrafda kömək istəyə biləcəyim adam yox idi. Sonradan bildim ki, yaxınlıqdakı binada həmin gün imtahan keçirilirmiş.","Çox keçmədi, bir gənc qaçaraq yanıma gəldi. O istidə məni xəstəxanaya çatdırmaq üçün nə qədər əziyyət çəkdi… Yarım saata çatdıq. Həkim dedi ki, bir az da geciksəydik, həyatım təhlükədə olardı. Oğlum elə həmin gün dünyaya gəldi.","Qadın bir an susub gülümsədi:","— O gəncin adını soruşdum. Kamal olduğunu dedi. Sən demə, imtahanda pəncərədən məni görüb, tək olduğumu anlayanda köməyimə qaçıbmış. «Bir il gec oxuyaram, eybi yoxdur. Sizi orada qoya bilməzdim», — dedi.","Kazım kişi başını qaldırıb oğluna baxdı. Kamal səssizcə qadını dinləyirdi.","— Oğlumun adını Kamal qoydum, — qadın davam etdi. — Onu həmin gəncin yaxşılığını danışa-danışa böyütdüm. İstədim ki, o da belə mərhəmətli insan olsun. İndi müəllimdir. Uşaqlara dərs öyrətməklə yanaşı, insan olmağı da öyrətməyə çalışır.","Qadının gözləri doldu:","— Kaş o oğlanı bir də görəydim. Deyəydim ki, itirdiyi o bir il iki insanın ömrünə çevrildi. Halallıq alaydım… Peşə öyrənmək olar, oğlum. Əsas odur, insanlığını itirməyəsən. O gənc məni küçənin ortasında tək qoymadı.","Kamal qadının əlini yüngülcə tutdu:","— Halal olsun, ana. Ürəyin rahat olsun…","Kazım kişi gözlərini yerə dikdi. Otaqda göz yaşlarını gizlətməyə çalışdı, amma çölə çıxanda özünü saxlaya bilmədi.","Qarlı yolda oğlunun yanında addımlaya-addımlaya ağlayırdı.","— Kamal, oğlum…","Ardını deyə bilmədi. İllər əvvəl dinləmədiyi cavabı bu gecə yad bir evdə eşitmişdi.","İbrət: İnsanın dəyəri yalnız qazandığı peşə ilə deyil, başqasının dar günündə etdiyi seçimlə ölçülür. Bəzən itki sandığımız bir addım neçə-neçə insanın həyatında xeyrə çevrilir. Hökm verməzdən əvvəl dinləməyi unutma."]},{"stem":"compassion","title":"Mərhəmət","hasAudio":false,"hasImage":true,"paragraphs":["Soyuq bir qış gecəsi işdən evə qayıdırdım. Bir qədər irəlidə ayaq üstə güclə dayanan bir adam gördüm. Səndələyir, yıxılmamaq üçün yol kənarındakı dirəkdən yapışırdı.","Otuz yaşlarında, səliqəli geyinmiş bir kişi idi. Yoldan keçənlərdən bəziləri onu sərxoş hesab edib içkinin zərərindən ucadan danışır, bəziləri isə istehza ilə gülürdü. Amma heç kim dayanıb nə baş verdiyini soruşmurdu.","Yaxınlaşdım:","— Özünüzü necə hiss edirsiniz? Kömək lazımdır?","Dodaqları güclə tərpəndi:","— Xəstəyəm…","Yıxılmasın deyə belindən tutub ona dayaq oldum. Sonra yavaş-yavaş yaxınlıqdakı taksi dayanacağına apardım.","Qar yenidən yağmağa başlamışdı. Küçə getdikcə boşalır, soyuq iliyimizə işləyirdi. Elə taksi tapmaqdan ümidimi üzürdüm ki, bir maşın yanımızda dayandı.","Sürücüyə vəziyyəti izah etdim. Birlikdə kişini arxa oturacaqda əyləşdirib xəstəxanaya yollandıq.","Həkimlər dərhal onunla məşğul oldular. Biz isə gözlədik. Sürücü də çıxıb getmədi.","Bir müddət sonra növbətçi həkim dedi:","— Yaxşı ki, onu küçədə qoymamısınız. Bu soyuqda həyatı təhlükədə idi.","Kişi özünə gəldikcə bizə baxıb zəifcə gülümsəyirdi. Hələ danışmağa taqəti çatmırdı, amma baxışları çox şey deyirdi.","Həkimlər evə getməsinə icazə verəndə onu yenə həmin taksiyə mindirdik.","Evinə yaxınlaşanda həyat yoldaşı ilə oğlunu küçədə gördük. Onun şəkərli diabeti olduğunu bilən qadın gecikməsindən narahat olub uşağı ilə birlikdə yolunu gözləməyə çıxmışdı.","Maşın dayanan kimi onlar bizə tərəf qaçdılar. Kişi düşəndə arvadı ilə oğlu ona sarıldılar. Bir müddət eləcə, bir-birindən ayrılmadan dayandılar.","Saatların yorğunluğu bir anda çəkilib getdi. Ailənin sevincini gördükcə bizim də gözlərimiz doldu.","Vidalaşandan sonra sürücüdən soruşdum:","— Nə qədər borcum var?","Başını yellədi:","— Sən mənə borclu deyilsən, dostum. Mən sənə borcluyam. Məni bu yaxşılığa şərik etdin. Bəlkə, iyirmi ildir ağlamırdım… Bu axşam mənə bu hissi yenidən yaşatdın.","Onu qucaqladım. Ayrılanda gecənin soyuğu əvvəlki kimi duyulmurdu. Evə piyada getmək istədim.","Kim bilir, bəlkə, yolda köməyə ehtiyacı olan daha bir insana rast gələcəkdim.","İbrət: Mərhəmət başqasının dərdinə acımaqla bitmir; dayanıb halını soruşmaqdan, əl uzatmaqdan başlayır. Bəzən bir insanı mühakimə etmək əvəzinə ona yaxınlaşmaq bütün bir ailənin dünyasını dəyişir."]},{"stem":"mockery-is-unacceptable","title":"Məsxərə yolverilməzdir","hasAudio":false,"hasImage":true,"paragraphs":["Uşaqlara kiçik yaşdan öyrətmək lazımdır ki, heç kimi görünüşünə və ya başqalarından fərqləndiyinə görə ələ salmaq, alçaltmaq olmaz. Hər insan hörmətə layiqdir.","İbrət: Fərqlilik məsxərə üçün səbəb deyil. Başqasının ləyaqətinə hörmət uşaqlıqdan, böyüklərin sözündən və davranışından öyrənilir."]},{"stem":"relationships","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/relationships.webp","title":"Münasibətlər","hasAudio":false,"hasImage":true,"paragraphs":["İnsan həyatının ən incə və dərin qatlarında bir həqiqət var: münasibətlər bizim mənəvi varlığımızın aynasıdır. Ailə ocağında doğulan istilik, qohumluqda kök salan bağlılıq, dostluqda yaranan qarşılıqlı anlayış — bunların hər biri həyatın ən qiymətli sərvətlərindəndir. İş yoldaşları arasında qurulan hörmət və mehribanlıq isə insanın gündəlik zəhmətinə ruh verən görünməz bir işıq kimidir.","Mehribanlıq sadəcə davranış deyil, bu, insanın daxili zənginliyinin ifadəsidir. O, ürəkləri bir-birinə yaxınlaşdıran, soyuq anları isidən, sözsüz anlaşmanı mümkün edən səssiz bir körpüdür.","Biz bu körpünü qorusaq və möhkəmləndirsək, həyat daha mənalı, insanlar daha yaxın və dünya yaşamaq üçün bir az daha gözəl yer olar.","İbrət: Münasibətlər qarşılıqlı hörmət, anlayış və mehribanlıqla möhkəmlənir. Yaxınlığımızın davam etməsi üçün bir-birimizə qayğı göstərməyi unutmamalıyıq.","Etibar Siracsoy"]},{"stem":"discussion-and-conflict","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/discussion-and-conflict.webp","title":"Müzakirə və münaqişə","hasAudio":false,"hasImage":true,"paragraphs":["Hər gün olduğu kimi, bu gün də Cavid bəy və komandası üzərində işlədikləri layihənin vəziyyətini müzakirə etmək üçün toplantı otağına yığışmışdı. Hər kəs əvvəlki gün əldə etdiyi nəticələr və qarşılaşdığı çətinliklər barədə qısaca məlumat verirdi.","Növbə Kamala çatdı. O da başqaları kimi gördüyü işlər barədə hesabat verdi, amma sanki həmkarlarından kömək umurmuş kimi üzləşdiyi problem haqqında daha ətraflı danışdı. Sözünü bitirər-bitirməz Nadir ittihamedici bir səslə: «Günahkar sən özünsən, sənin üzündən bizim işimiz də dayanıb, heç nə edə bilmirik», — deyə hamının gözü önündə Kamalı sancdı. Otaqdakılar donub qaldı. Kamal çox pərt olmuşdu, nə edəcəyini bilmirdi.","Layihə rəhbəri Cavid bəy söhbətin böyüyüb münaqişəyə çevrilməməsi üçün dərhal araya girdi:","— Uşaqlar, gəlin bugünkü müzakirəni burada bitirək. Bu məsələyə ayrıca baxarıq.","Hamı dağılışdı.","Cavid bəy nə edəcəyini yaxşı bilirdi: Nadirlə təkbətək görüşüb dostcasına söhbət etmək. O, Nadiri bir stəkan çay içmək bəhanəsi ilə şirkətin kafesinə dəvət etdi. Oradan-buradan söhbət etdikdən sonra əsas mətləbə keçib təmkinlə dedi: «Oğlum, bu gün sənin Kamala qarşı rəftarın çox yanlış idi. Məsələnin əslini öyrənmədən kimisə suçlamaq, özü də başqalarının yanında, qəbuledilməzdir. Özünü onun yerinə qoy. Adam bizdən kömək gözlədiyi halda ittiham olunur. Əminəm ki, Kamal birlikdə oturub düşünəcəyimizə, məsələnin həllini birgə tapacağımıza ümid edirdi».","Nadir utandığından başını aşağı saldı. Cavid bəyin nəsihəti bəhrə vermiş, Nadir üçün yaxşı bir dərs olmuşdu; qəbahət etdiyini anlamışdı.","Sonralar Nadir bu söhbəti hər xatırlayanda Cavid bəyə minnətdarlıq edirdi. Bir də ona görə minnətdar idi ki, aralarında olan söhbətdən şirkətdə heç kimin xəbəri yox idi.","İbrət: Münaqişədə kimin haqlı olduğu, müzakirədə isə nəyin doğru olduğu araşdırılır. Doğrunu tapmaq istəyirsənsə, mübahisə yox, müzakirə et.","Bəxtiyar Siracov"]},{"stem":"why-shout","title":"Niyə insanlar mübahisə edəndə qışqırırlar?","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün müəllim dərsdə tələbələrinə sual verdi:","— Niyə insanlar mübahisə edəndə qışqırırlar?","— Əsəblərini cilovlaya bilmədikləri üçün, — deyə bir tələbə cavab verdi.","— Axı qarşısındakı adam yanındadır. Özünü eşitdirmək üçün niyə qışqırmalıdır? Əsəbiləşəndə də sakit danışmaq olmazmı? — deyə müəllim soruşdu.","Tələbələrin hərəsi bir fikir söylədi. Müəllim onları dinləyib dedi:","— Bunu belə təsəvvür edin: insanlar mübahisə etdikcə qəlbləri bir-birindən uzaqlaşır. Sanki aralarındakı məsafəni aşmaq, bir-birinə səsini çatdırmaq üçün qışqırırlar. Səsləri yüksəldikcə qəlbləri daha da uzaqlaşır.","Bir qədər susduqdan sonra sözünə davam etdi:","— Bəs bir-birini sevən insanlara baxın. Çox vaxt astadan danışırlar, çünki qəlbləri yaxındır. Yaxınlıqları artdıqca pıçıltı da kifayət edir. Elə anlar olur ki, sözə belə ehtiyac qalmır: bir baxışla bir-birini anlayırlar.","Sonra müəllim tələbələrinə üz tutdu:","— Siz də mübahisə edəndə qəlblərinizin uzaqlaşmasına imkan verməyin. Aranızdakı məsafəni böyüdəcək sözlər deməyin. Çünki bir gün o məsafə elə böyüyər ki, bir-birinizə qayıdan yolu tapmaq çətin olar.","İbrət: Mübahisədə yalnız özünü eşitdirməyə deyil, qarşındakını eşitməyə də çalış. Təmkin və hörmət qəlbləri yaxın saxlayır; incidən sözlər isə aradakı məsafəni böyüdür."]},{"stem":"time-has-passed","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/time-has-passed.webp","title":"Ötdü dövran","hasAudio":false,"hasImage":true,"paragraphs":["Sərçələrin cəh-cəhiylə açılardı səhərlərim —","Ötüşərdi, yox olardı qüssələrim, kədərlərim","Sabahların xoş havası süzüləndə pəncərədən,","Boylanardı nurlu Günəş zər şəfəqli üfüqlərdən!","Ötdü dövran, dəyişdi o sabahların dəyərləri,","“Qaaa” səsilə qarğalar da əvəzlədi sərçələri!","Bənzəmir heç əvvəlkinə ətrafdakı mənzərələr —","Bilinməyir bundan sonra olacaqdır nələr... nələr!...","Bəzi vaxtlar yaşansa da çətin günlər, gərgin anlar","Dostluq ilə ömrümüzə hasil olur xoş zamanlar!","Yeni, gözəl sabahlara ümidlərlə gedirik biz!","Əziz dostlar var olsunlar — onlar böyük sərvətimiz!","Etibar Siracsoy"]},{"stem":"doorbell","title":"Qapı zənginin səsi...","hasAudio":false,"hasImage":true,"paragraphs":["Keçən qış işdən çıxarıldım. Dolanmaq üçün müvəqqəti olaraq qəzet paylamağa başladım. Bir gün qəzet apardığım evlərdən birinin poçt qutusunun ağzının bağlandığını görüb qapını döydüm. Qapını yaşlı bir kişi açdı.","— Dayı, poçt qutusunun ağzını niyə bağlamısınız? — deyə soruşdum.","— Özüm bağlamışam, qəsdən, — dedi.","Sonra xəfifcə gülümsəyib əlavə etdi:","— Sizdən bir xahişim var. Hər gün qəzeti gətirəndə qapını döyün, ya da zəngi basın. Qəzeti özümə verin, zəhmət olmasa.","Təəccübləndim:","— Verərəm, əlbəttə. Amma qutuya qoysam, ikimiz üçün də daha rahat olmazmı? Sizin də qapıya gəlməyinizə ehtiyac qalmaz.","— Mənim üçün çətin deyil, oğlum. Hər gün evdəyəm.","Bir an susdu, sonra sözünə davam etdi:","— Həyat yoldaşım rəhmətə gedib, oğlum xaricdə yaşayır. Burada təkəm. Kim bilir, nə qədər ömrüm qalıb...","Gözlərinin dolduğunu gördüm.","— Bəs qəzetə oxumaq üçün abunə olmamısınız? — deyə soruşdum.","— Mən qəzet oxumuram, oğlum... Mən qapı zənginin səsinə abunə olmuşam.","Sonra əllərini bir-birinə sıxıb astadan dedi:","— Mənə bir yaxşılıq da et. Bu, oğlumun telefon nömrəsidir. Bir gün qapımı döyəndə məndən səs çıxmasa, ona zəng vur, xəbər ver.","İbrət: Bəzən insanın gözlədiyi qəzet deyil, qapısını döyən birinin varlığıdır. Bir salam, qısa bir söhbət tənha insana unudulmadığını hiss etdirə bilər."]},{"stem":"your-friends","title":"Sənin dostların","hasAudio":false,"hasImage":true,"paragraphs":["Bir gənc evlənməyə hazırlaşırdı. Toy hazırlıqları ilə keçən gərgin bir həftədən sonra atasına dedi:","— Ata, səndən bir xahişim var. Bütün işləri tək çatdıra bilmirəm. Bu siyahıdakı dostlarıma zəng vurub onları toyuma dəvət edərsənmi?","— Gözüm üstə, oğlum! — deyə atası cavab verdi.","Toy günü oğlan narazı halda atasına yaxınlaşdı:","— Ata, axı səndən bütün dostlarıma zəng vurmağını xahiş etmişdim!","— Oğlum, hamısına zəng vurmuşam.","— Siyahıda əlli nəfər vardı. Burada isə cəmi on beşini görürəm!","Ata sakitcə dedi:","— Əlli nəfərin hamısı ilə bir-bir danışdım. Amma onları toya çağırmaq əvəzinə dedim ki, sənin bir çətinliyin var, dostlarının köməyinə ehtiyacın var. Bu gün, bu saatda, bu ünvana gəlmələrini xahiş etdim.","Sonra əlini oğlunun çiyninə qoydu:","— Ətrafına bax, oğlum. Bu insanlar buraya sevincinə şərik olmağa deyil, çətin günündə sənə dayaq olmağa gəliblər.","İbrət: Dostluğun dəyəri sayla deyil, qayğı və etibarla ölçülür. Çətin gündə köməyinə gələn insanın qədrini bil; əsl dostluq zamanla, əməllə özünü göstərir."]},{"stem":"request-for-help","title":"Sizə işi düşən adamlar","hasAudio":false,"hasImage":true,"paragraphs":["Sizi yalnız işi düşəndə axtaranlardan inciməyə tələsməyin. Bəlkə, çətin vəziyyətdədirlər və sizə güvəndikləri üçün kömək istəyirlər. Onların müraciətinə bu gözlə baxmaq ürəyinizdəki incikliyi yüngülləşdirə bilər.","İbrət: Kömək üçün sənə üz tutanın niyyətini dərhal pisə yozma. Bəzən bu müraciətin arxasında ehtiyac və etibar dayanır. Anlayış göstərmək qəlbi yüngülləşdirir."]},{"stem":"beyond-first-impressions","title":"Tanış olmaq və tanımaq","hasAudio":false,"hasImage":true,"paragraphs":["Bəzi insanlar haqqında yalnız bunu demək olur:","Tanış olduq — sevindik, tanıdıq — üzüldük.","İbrət: İlk təəssürat insanı tam tanıtmaz. Tanışlıq bir görüşlə başlayar, insanın xasiyyəti isə zamanla, davranışlarında üzə çıxar."]},{"stem":"unwelcome-gifts","title":"Təhqirləri necə dəf etməli","hasAudio":false,"hasImage":true,"paragraphs":["(Samuray haqqında ibrətamiz bir hekayə)","Yaşlı, müdrik bir samuray şagirdlərinə müdrikliyin və döyüş sənətinin sirlərini öyrədirdi.","Bir gün dərs zamanı kobudluğu və qəddarlığı ilə tanınan bir döyüşçü içəri girdi. Onun həmişə əl atdığı bir üsul vardı: rəqibini təhqir edib hövsələdən çıxarır, sonra qəzəblə etdiyi səhvlərdən yararlanaraq onu məğlub edirdi.","Bu dəfə də eyni üsulla samurayı döyüşə çəkməyə çalışdı. Ona ağır sözlər söylədi, lakin samuray təhqirlərə məhəl qoymadan dərsinə davam etdi.","Döyüşçü sözlərini bir neçə dəfə təkrarladı. Yenə də cavab ala bilmədiyini görüb əsəbi halda çıxıb getdi.","Baş verənləri diqqətlə izləyən şagirdlər soruşdular:","— Ustad, niyə bu təhqirlərə dözdünüz? Niyə onu döyüşə çağırmadınız?","Samuray onlara bir sualla cavab verdi:","— Kimsə sizə hədiyyə gətirsə, siz də onu qəbul etməsəniz, hədiyyə kimdə qalar?","— Onu gətirəndə, — deyə şagirdlər cavab verdilər.","— Paxıllığa, nifrətə və təhqirə də belə baxın. Bu “hədiyyələri” qəbul etməsəniz, onları gətirənin özündə qalar.","İbrət: Başqasının təhqirini özün haqqında həqiqət kimi qəbul etmə. Pisliyə pisliklə deyil, təmkinlə cavab ver ki, başqasının qəzəbi sənin davranışını idarə etməsin."]},{"stem":"being-lonely","title":"Tənha olmaq","hasAudio":false,"hasImage":true,"paragraphs":["Bir tanışımı ziyarətə getmişdim. Otağına girəndə başını aşağı salıb səssizcə oturduğunu gördüm. Qəmli görünürdü.","— Kədərlisən? — deyə soruşdum.","Başını qaldırıb gözlərimə baxdı:","— Yox, tənhayam.","İbrət: Bəzən qəmli baxışların arxasında tənhalıq gizlənir. Yanındakı insanın səssizliyinə diqqət yetirmək, onu dinləmək və yanında olmaq böyük qayğıdır."]},{"stem":"make-time-for-people","title":"Vaxtını insanlarla keçir","hasAudio":false,"hasImage":true,"paragraphs":["Atam pul köçürmək istəyirdi. Onunla banka getdim və orada bir saata yaxın qaldıq. Axırda səbrim tükəndi:","— Ata, gəl sənə bank işlərini internetlə görməyi öyrədim. Nə deyirsən?","Atam təəccüblə mənə baxdı:","— Bunun mənə nə xeyri olacaq, oğlum?","— Pul köçürmək üçün banka gəlib bir saat gözləməyəcəksən. Alış-verişini də internetlə edə bilərsən. Hər şey daha asan, daha rahat olar.","Onu razı salacağımı düşünüb həvəslə izah etməyə davam etdim.","Atam soruşdu:","— Deməli, dediyin kimi etsəm, evdən çıxmağa ehtiyacım qalmayacaq?","— Bəli, ata. Hətta ərzağı da qapına gətirərlər. Amazon kimi xidmətlərdən sifariş verərsən, aldıqlarını evinə çatdırarlar.","Atamın cavabı məni susdurdu:","— Oğlum, sənin itirilmiş vaxt saydığın bu bir saatda mən dörd dostumu gördüm, məni illərdir tanıyan bank işçiləri ilə söhbət etdim.","Bilirsən, çox vaxt özümü tənha hiss edirəm. İnsan görməyə, kiminləsə danışmağa ehtiyacım var. Geyinib evdən çıxmağı, banka gəlməyi xoşlayıram. Vaxtım da var, bu görüşlərdən zövq də alıram.","İki il əvvəl xəstələnəndə həmişə meyvə aldığım dükanın satıcısı məni yoxlamağa gəldi. Xəstələndiyimə ürəkdən üzülmüşdü. Yatağımın yanında oturub halımı soruşdu, mənə ürək-dirək verdi.","Bir müddət əvvəl anan səhər gəzintisində yıxılanda məhəlləmizin baqqalı köməyinə çatdı. Onu qaldırıb maşınına mindirdi, evə gətirdi. Çünki bizi tanıyırdı, harada yaşadığımızı bilirdi.","Hər işimi evdən çıxmadan görsəm, bu tanışlıqlar, bu münasibətlər necə yaranar? Hər şey qapıma gəlsin deyə niyə insanlarla görüşməkdən vazkeçim?","Mən təkcə mal almaq istəmirəm, oğlum. Onu aldığım adamı da tanımaq, halını soruşmaq, bir-iki kəlmə danışmaq istəyirəm. Mənə insanlarla ünsiyyət, doğmalıq lazımdır.","Amazon bunu da qapıma gətirə bilərmi?","Texnologiya həyatı asanlaşdırır, amma həyatın özü deyil. Vaxtını insanlarla keçir, oğlum. Qoy cihazlar buna kömək etsin, mane olmasın.","İbrət: Vaxta qənaət etmək yaxşıdır, amma insanlarla keçən hər saatı itki saymaq olmaz. Texnologiyanın rahatlığından yararlanarkən bir salamın, bir söhbətin, bir-birinə dayaq olmağın dəyərini unutma."]},{"stem":"welcome-home-my-dear","title":"Xoş gəldin, bəyim","hasAudio":false,"hasImage":true,"paragraphs":["Rəhmətlik atam Hafiz Əli Çanaqqalada döyüşəndə anam mənə yeddi aylıq hamilə imiş. Atamı heç görmədim, tanımadım. Ondan bir fotoşəkil belə qalmamışdı.","Çox ağır illər idi. Səfərbərlik, işğal, qurtuluş mübarizəsi, yoxsulluq, sıxıntı...","Uşaqlığımız bir tikə çörək qayğısı ilə, əziyyət içində keçdi.","Anam harasa gedəndə həmişə yanıma gəlib deyərdi:","— Oğlum, bazara gedirəm. Atan gəlsə, dərhal mənə xəbər ver!","— Xalangilə gedirəm. Atan gəlsə, dərhal mənə xəbər ver!","— Qonşuya gedirəm. Atan gəlsə, dərhal mənə xəbər ver!","Anamın gözü həmişə yolda qaldı.","Mən böyüdüm, iş sahibi oldum, bir dükan açdım. Anam isə əvvəlki kimi harasa gedəndə dükana baş çəkər, hara getdiyini deyər, sonra da əlavə edərdi:","— Atan gəlsə, mənə xəbər ver, ha!","İllər keçdi, anam qocaldı. Amma adətindən əl çəkmədi. Əsasına söykənə-söykənə yanıma gəlib yenə deyərdi:","— Atan gəlsə, məni çağır, ha!","Bir gün halı pisləşdi, yatağa düşdü.","Son anlarında bizimlə vidalaşdı:","— Mənə yaxşı baxdınız. Haqqınızı halal edin.","Sonra yavaşca mənə tərəf dönüb dedi:","— Atan gəlsə, ona deyərsən: «Anam səni ömrünün sonuna qədər gözlədi».","Birdən başını qaldırıb qapıya tərəf baxdı. Üzünə təbəssüm qondu:","— Xoş gəldin, bəyim, xoş gəldin!","Bu sözlərlə son nəfəsini verdi.","Balıkəsirdə yaşamış qoca pinəçi Cövdət Alkalpın xatirələri kimi nəql olunur.","Qələmə alan şəxs kimi araşdırmaçı-yazıçı, Bursa Çınar Anadolu Liseyinin coğrafiya müəllimi Mustafa Doğrunun adı göstərilir.","18 mart Çanaqqala dəniz zəfərinin ildönümü və şəhidlərin anım günüdür. 1915-ci ilin həmin günündə Çanaqqala boğazından keçərək İstanbula çatmağa çalışan Müttəfiq donanmasının hücumu dəf edildi.","Bu zəfəri anarkən döyüş meydanında həyatını itirənlərlə yanaşı, illərlə onların yolunu gözləyən ailələri də xatırlayırıq.","Çanaqqalada şəhid olanların hamısının ruhu şad olsun! Heç bir ananın gözü yolda qalmasın!","İbrət: Müharibənin ağrısı döyüş meydanında bitmir; bəzən bir evdə ömürlük intizara çevrilir. Vətən uğrunda canından keçənlərin də, onların yolunu gözləyənlərin də xatirəsini ehtiramla yaşatmaq borcumuzdur."]},{"stem":"sharing-the-burden","title":"Yol yormursa, yoldaşındandır","hasAudio":false,"hasImage":true,"paragraphs":["Anam danışırdı:","— Atanla evlənəndə çox gənc idim. Nə düz-əməlli yemək bişirə bilirdim, nə də tikiş tikməyi yaxşı bacarırdım.","Bir gün qayınanam — sənin nənən — qonşuya getməyə hazırlaşırdı. Yununu yuyub qurutduğu yorğanı önümdə sərib dedi:","— Mən qayıdanadək bunu sırıyıb qurtararsan.","İynəni götürüb işə başladım. Amma nə qədər çalışsam da, iynəni qalın yorğandan keçirməkdə çətinlik çəkirdim. Tez-tez barmağıma batırdı. Axırda ağlamağa başladım. Həm əlim ağrıyırdı, həm də yorğanı bitirə bilməsəm, qayınanama nə deyəcəyimi bilmirdim.","Elə bu vaxt atan nahar fasiləsində evə gəldi. Ağladığımı görəndə yanıma oturub iynəni əlimdən aldı. Yorğanı özü sırıyıb qurtardı. Sonra yeməyini yeyib işinə qayıtdı.","Anasına da heç nə demədi. Qayınanam qayıdıb yorğanı hazır görəndə çox razı qaldı.","Anamın bu xatirəsini hər yada salanda düşünürəm: boş yerə deməyiblər, «Yol yormursa, yoldaşındandır».","İbrət: Həyat yolunu yüngülləşdirən, çətin anda səni qınamaq əvəzinə yükünə şərik olan insandır. Bəzən sevgi böyük sözlərdə deyil, səssizcə uzadılan kömək əlində görünür."]}]},{"title":"Əxlaq və xarakter","slug":"exlaq-ve-xarakter","blurb":"Dürüstlük, səxavət və şəxsi kamillik.","count":42,"stories":[{"stem":"being-human","title":"Adam olmaq","hasAudio":false,"hasImage":true,"paragraphs":["“Alim olmaq asandır, adam olmaq çətin”, — deyirlər. Bəs adam olmaq nə deməkdir?","Vicdanla yaşamaqdır: dürüst və ədalətli davranmaq, öz ləyaqətini qoruyarkən başqasının ləyaqətini alçaltmamaqdır.","Ədəbli, nəzakətli və təvazökar olmaqdır. İnsanlara var-dövlətlərinə, vəzifələrinə görə deyil, insan olduqları üçün hörmət etməkdir. Təkcə başqalarının deyil, özünün də nöqsanlarını görə bilməkdir.","Atdığın addımın nəticəsini düşünmək, səhvini boynuna almaq və əməlinə cavabdeh olmaqdır. Mübahisədə özünü itirməmək, çətinlik qarşısında ruhdan düşməməkdir.","Sərf etməyəndə də sözünün üstündə durmaqdır. Pulu və vəzifəni insanın dəyər ölçüsü saymamaq, başqasının malına göz dikməmək, haqqını yeməməkdir.","Yalan danışmamaq, böhtan atmamaq, qazanc naminə xəyanət etməməkdir. Susmaq daha rahat olsa belə, haqsızlığa uğrayanın müdafiəsinə qalxmaqdır.","İnsanlar arasına nifaq salmamaq, özgənin dərdinə sevinməməkdir. Sevməyi bacarmaq, sevgini yalnız sözdə deyil, qayğıda və əməldə göstərməkdir.","İbrət: Bilik nə öyrəndiyimizi, əməllərimiz isə necə insan olduğumuzu göstərir. Adamlıq gündəlik seçimlərimizdə üzə çıxır: dürüst olmaqda, başqasının ləyaqətini qorumaqda və dərdinə biganə qalmamaqda."]},{"stem":"now-i-understand","title":"Artıq anlayıram","hasAudio":false,"hasImage":true,"paragraphs":["Həyatın bərkini-boşunu görmüş bir insanın dilindən:","Artıq özümü hamıya sevdirməyə çalışmıram. Anlayıram ki, nə etsəm də, məni bəyənməyənlər olacaq.","Artıq öz qədrimi bilirəm. Dəyərimi hər kəsə sübut etməyə borclu deyiləm.","Özünü ucaltmaq üçün başqalarını kiçildən insanları həyatıma yaxın buraxmıram.","Artıq sözlə niyyətin fərqini görürəm: istəyən yol axtarır, istəməyən isə çox vaxt bir “amma” tapır.","Qeybət edənlə sirrimi bölüşmürəm. Başqasının etibarını qorumayanın mənim etibarımı da qoruyacağına arxayın olmuram.","Dinləmək istəməyən adamı razı salmaq üçün özümü yormuram. Hər söhbəti mübahisəyə, hər fikir ayrılığını mübarizəyə çevirmək lazım deyil.","Yalanı, boş vədi və sözündən dönməyi vərdişə çevirənlərə həyatımda yer vermirəm.","Mərhəmətsizliyi və sərtliyi güc sayanlardan uzaq dururam. Səhvini anlayan, üzr istəməyi və davranışını dəyişməyi bacaran insanlara dəyər verirəm.","Artıq anlayıram ki, yanında özüm ola bildiyim insanlarla daha xoşbəxtəm.","İbrət: Əsl yetkinlik başqalarını dəyişməyə çalışmaqdan çox, öz dəyərini və sərhədlərini tanımaqdır. Kimə yaxınlaşacağını, kimdən uzaqlaşacağını bilmək həm özünə hörmət, həm də daxili rahatlıqdır."]},{"stem":"think-before-speaking","title":"Danışmazdan əvvəl düşün","hasAudio":false,"hasImage":true,"paragraphs":["Danışmazdan əvvəl düşün: sözün bir könlə təsəlli, bir çətinliyə çarə, bir qaranlığa işıq olacaqmı?","Xoş danışmaq həqiqəti gizlətmək deyil. Acı həqiqəti də insanı alçaltmadan söyləmək olar. Sözün yalnız yaralamağa xidmət edəcəksə, susmaq daha yaxşıdır.","İbrət: Sözün dəyəri nə qədər gözəl səslənməsində deyil, nə qədər xeyir gətirməsindədir. Həqiqəti hörmətlə söylə, incitmək üçün danışma."]},{"stem":"keep-your-self-respect","title":"Ağızlara söz, ayaqlara toz olma","hasAudio":false,"hasImage":true,"paragraphs":["“Ağızlara söz, ayaqlara toz olma” — yəni sözünlə, əməlinlə ləyaqətini qoru, özünü nə dedi-qodunun oyuncağına çevir, nə də başqalarının səni alçaltmasına razı ol.","Amma unutma: insanların danışdıqları həmişə sənin necə yaşadığını göstərmir. Hər dili susdura bilməzsən. Əsas odur ki, vicdanına qarşı dürüst olasan, özünə hörmətini itirməyəsən.","İbrət: Başqalarının sözünü həyatının ölçüsünə çevirmə. Sözünə və əməlinə cavabdeh ol, sərhədlərini qoru. Nə dedi-qodu, nə də kiminsə səni alçaltması sənin dəyərini müəyyən edir."]},{"stem":"grocers-sticky-fingers","title":"Bal tutan barmağını yalayar","hasAudio":false,"hasImage":true,"paragraphs":["Bir arıçı topladığı şan balını qablara yığıb satmaq üçün baqqalın yanına gətirir. Qiymətdə razılığa gəlib balı çəkməyə başlayırlar.","Baqqalın yalnız bir kiloqramlıq çəki daşı olduğundan şanları əli ilə bölüb balı kilo-kilo çəkir. Amma hər dəfə tərəziyə yeni bir parça qoymazdan əvvəl barmaqlarına bulaşan balı yalayır.","Bir dəfə, iki dəfə, üç dəfə...","Arıçı görür ki, balın bir hissəsi tərəziyə çatmamış baqqalın ağzına gedir. Narazılığını bildirir, amma baqqal heç nə olmamış kimi işinə davam edir.","Axırda arıçının səbri tükənir:","— Ay əmi, belə olmaz axı! Balın yarısını yalayıb qurtardın!","Baqqal ballı barmaqlarını yalaya-yalaya altdan-altdan gülümsəyir:","— Ay qardaş, pis niyyətim yoxdur. Bal tutan barmağını yalayar!","İbrət: İnsan gördüyü işdən az-çox faydalana bilər. Amma bundan bəhanə düzəldib başqasının payından götürmək doğru deyil."]},{"stem":"honey-or-dry-bread","title":"Bal, yoxsa quru çörək?","hasAudio":false,"hasImage":true,"paragraphs":["Cahillə bal yeməkdənsə, müdriklə quru çörək bölüş.","İbrət: Süfrənin zənginliyindən çox, yanında oturanın söhbəti dəyərlidir. Elə insanlarla yoldaşlıq et ki, onlardan ayrılarkən düşüncən zənginləşsin, dünyagörüşün genişlənsin."]},{"stem":"kings-generosity","title":"Bu qədər az verməzdi","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün padşah yolda rast gəldiyi bir uşağı çox bəyəndi və ona bir qızıl pul uzatdı. Uşaq isə pulu götürmədi.","Padşah təəccübləndi:","— Niyə götürmürsən?","— Evə aparsam, anamla atam soruşacaqlar: «Bu pulu haradan oğurlamısan?»","— Sən də deyərsən ki, padşah verib.","Uşaq dərhal cavab verdi:","— Onda heç inanmazlar! Deyərlər ki, padşah versəydi, bu qədər az verməzdi.","Padşah uşağın hazırcavablığına ürəkdən güldü və ona bir kisə qızıl bağışladı.","İbrət: Vaxtında deyilən ağıllı və zarafatlı bir söz uzun söhbətdən daha təsirli ola bilər. Hazırcavablığın gözəlliyi qarşıdakını incitmədən güldürməkdədir."]},{"stem":"avoid-these-questions","title":"Bu suallardan çəkinin","hasAudio":false,"hasImage":true,"paragraphs":["İş axtaran insandan “Hələ də iş tapmamısan?”, işləyəndən “Nə qədər maaş alırsan?”, övladı olmayan cütlükdən “Hələ də uşağınız yoxdur?”, subay insandan “Nə vaxt evlənirsən?” deyə soruşmağa tələsməyin.","Kiminsə bilmədiyi bir şeyə təəccüblənəndə də “Sən bunu da bilmirdin?” deyib onu utandırmayın.","Hər cavabın arxasında insanın bölüşməyə hazır olmadığı bir hekayə ola bilər: narahatlıq, itki, məyusluq və ya sadəcə izah etməyə borclu olmadığı şəxsi seçim.","Bizim üçün ötəri maraq olan bir sual başqasının köhnə yarasını sızıldada bilər. Soruşmazdan əvvəl düşünün: bu insana qayğı göstərmək istəyirsiniz, yoxsa sadəcə öz marağınızı ödəmək?","İbrət: Nəzakət başqasının şəxsi həyatına hörmət etməkdir. Bəzən qayğı sual verməkdə, bəzən də o sualı verməməkdə özünü göstərir."]},{"stem":"do-not-deepen-anothers-pain","title":"Başqasının yarasına toxunma","hasAudio":false,"hasImage":true,"paragraphs":["Maddi sıxıntı çəkənin yanında var-dövlətinlə, xəstənin yanında sağlamlığınla, dərdlinin yanında qayğısız həyatınla öyünmə.","Azadlığından məhrum olanla danışanda azadlığınla, gücsüz qalanla danışanda gücünlə lovğalanma.","Övlad həsrəti çəkənin yanında övladlarından, valideynini itirənin yanında ata-anandan söz açanda həssas ol.","Sevincini bölüş, amma qarşındakının ağrısını da nəzərə al. Bəzən danışmaqdan çox, dinləmək və yanında olmaq lazımdır.","İbrət: Sahib olduğun neməti başqasının yarasına toxunan bir lovğalığa çevirmə. Sözünü anlayışla seç: insanın məhrumiyyətini xatırlatmağa deyil, hisslərini anlamağa çalış."]},{"stem":"beyond-complaining","title":"Şikayətdən həllə doğru","hasAudio":false,"hasImage":true,"paragraphs":["Dünyagörmüş bir adam eyni problemlərdən dönə-dönə şikayətlənən bir qrup insana dərs vermək istəyir.","Onlara gülməli bir lətifə danışır. Hamı ürəkdən gülür.","Bir qədər sonra həmin lətifəni yenidən danışır. Bu dəfə yalnız bir neçəsi gülür.","Lətifəni üçüncü dəfə təkrarlayanda isə artıq heç kim gülümsəmir.","Çarə axtarmadan eyni şikayətləri təkrarlamaq da belədir: bir müddət sonra sözlər təsirini itirir, dinləyənlər yorulur. Problemi dilə gətirmək vacibdir, amma onun haqqında dönə-dönə danışmaq problemi öz-özlüyündə həll etmir.","İbrət: Dərdini bölüşmək yüngüllük gətirə bilər, amma yalnız şikayətlə kifayətlənmək vəziyyəti dəyişmir. Çıxış yolu axtarmaq, kömək istəmək və mümkün olan kiçik bir addımı atmaq dəyişiklik üçün başlanğıcdır."]},{"stem":"flower-of-honesty","title":"Dürüstlük çiçəyi","hasAudio":false,"hasImage":true,"paragraphs":["Bir ölkədə gənc şahzadə taxta çıxmağa hazırlaşırdı. Sarayın adətinə görə, tac qoymazdan əvvəl evlənməli idi. O, gələcək həyat yoldaşını seçmək üçün ölkənin gənc xanımlarını saraya dəvət etdi.","Sarayda çalışan bir qadının qızı da şahzadəni sevirdi. Dəvəti eşidəndə anasına dedi:","— Mən də getmək istəyirəm.","Anası narahat oldu:","— Qızım, ora varlı, adlı-sanlı ailələrin qızları gələcək. Qorxuram, ümidin qırılsın.","— Bilirəm, ana. Amma heç olmasa, bir dəfə onun qarşısına çıxmaq istəyirəm.","Gözlənilən gün sarayın salonu gözəl libaslar geyinmiş gənc xanımlarla doldu. Şahzadə onların hər birinə bir toxum verib dedi:","— Bu toxumu əkin, ona qulluq edin. Altı aydan sonra yetişdirdiyiniz çiçəklə buraya qayıdın. Ən gözəl çiçəyi gətirən xanımla evlənəcəyəm.","Qızlar ümidlə evlərinə döndülər.","Xidmətçinin qızı da toxumu dibçəyə əkdi. Hər gün torpağı yoxlayır, suyunu verir, ilk cücərtini səbirsizliklə gözləyirdi. Amma günlər, həftələr keçdi, torpaqdan heç nə boy göstərmədi.","Qız bağbanlarla məsləhətləşdi, dediklərinə əməl etdi. Yenə də toxum cücərmədi.","Altı ay tamam olanda anası soruşdu:","— Boş dibçəklə gedəcəksən?","Qız dibçəyə baxıb sakitcə dedi:","— Bəli. Əlimdən gələni etmişəm. Başqa bir çiçək aparıb onu mən yetişdirmişəm deyə bilmərəm.","Saraya çatanda hər tərəfdə rəngbərəng çiçəklər gördü. Öz dibçəyində isə yalnız torpaq vardı. Utana-utana bir kənarda dayandı.","Şahzadə salona girib dibçəkləri bir-bir nəzərdən keçirdi. Qızın qarşısında dayananda soruşdu:","— Sənin çiçəyin hanı?","— Toxuma altı ay qulluq etdim, amma cücərmədi, — qız cavab verdi. — Sizə göstərə biləcəyim bir çiçəyim yoxdur.","Şahzadə onu diqqətlə dinlədi. Sonra üzünü salondakılara tutdu:","— Mən öz seçimimi etdim.","O, boş dibçəyi tutan qızı göstərdi.","Salonda təəccüb dolu səslər yüksəldi:","— Axı onun çiçəyi yoxdur!","Şahzadə dedi:","— Sizə verdiyim toxumların heç biri cücərə bilməzdi. Bu xanım isə nəticəni olduğu kimi gətirməyə cəsarət etdi. Onun mənə gətirdiyi ən qiymətli çiçəkdir: dürüstlük çiçəyi.","İbrət: Dürüstlük bəzən hamının qarşısında boş dibçəklə dayanmağa cəsarət etməkdir. İstədiyin nəticəni əldə etməmək ayıb deyil; özünü o nəticəni əldə etmiş kimi göstərmək vicdanına xəyanətdir."]},{"stem":"letting-go-of-painful-thoughts","title":"Düşüncələrimdən necə qurtula bilərəm?","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün bir adam müdrik bir alimin yanına gəlib soruşdu:","— Ağır düşüncələr məni rahat buraxmır. Elə bil onların əsiriyəm. Bu yükdən necə qurtulum?","Alim cavab vermək əvəzinə ayağa qalxdı, yaxınlıqdakı dirəyi qucaqlayıb bərkdən səsləndi:","— Kömək edin! Məni bu dirəkdən qurtarın!","Adam heyrətlə ona baxdı:","— Mən səndən məsləhət almağa gəlmişəm, sən isə nə edirsən? Axı dirək səni tutmayıb, sən onu tutmusan. Əllərini açsan, azad olarsan!","Alim dirəyi buraxıb sakitcə dedi:","— Bax, axtardığın cavabın bir hissəsini özün söylədin. Bəzən ağrılı bir düşüncəyə dönə-dönə qayıdır, onu bu dirək kimi bərk qucaqlayırıq. Hər düşüncəni saxlamaq, hər dəfə onun ardınca getmək məcburiyyətində deyilik.","İbrət: Düşüncələrin gəlməsini həmişə seçə bilmərik, amma onlara necə yanaşmağı öyrənə bilərik. Buraxmaq unutmağa məcbur olmaq deyil; ağrıya bütün həyatımızı idarə etmək haqqı verməməkdir. Bəzən bunun üçün zaman və dəstək lazımdır."]},{"stem":"how-we-express-sorrow","title":"Dərdini anlatmaq","hasAudio":false,"hasImage":true,"paragraphs":["Kimi dərdini danışaraq yüngülləşdirir, kimi sözə çevirib şeirə, hekayəyə köçürür, kimi bir baxışla, bir ahla duyurur, kimi də təbəssümünün arxasında gizlədir.","Hər dərdin səsi eyni deyil. Bəzən dilin söyləmədiyini gözlər danışır, bəzən də gülən bir üzün arxasında yorğun bir qəlb dayanır.","İbrət: İnsanın dərdini yalnız dedikləri ilə ölçmə. Təbəssüm həmişə rahatlıq, sükut həmişə güc demək deyil. Mühakimə etmədən dinlə, danışmaq istəyəndə yanında ol."]},{"stem":"strength-and-sorrow","title":"Güc və dərd","hasAudio":false,"hasImage":true,"paragraphs":["Allahım, mənə ya dərdimə yetəcək güc ver, ya da gücümün yetəcəyi qədər dərd.","İbrət: İnsan hər dərdin qarşısında güclü qala bilməz. Çətin anda güc diləmək, kömək istəmək və öz həddini bilmək zəiflik deyil."]},{"stem":"sunlit-day","title":"Heç nəyə dəyişmərəm","hasAudio":false,"hasImage":true,"paragraphs":["Bir günü, gözəl bir günü, günəşli bir günü heç nəyə dəyişmərəm.","Elə buna görə savaşı sevmərəm, elə buna görə zülmü sevmərəm, elə buna görə yalanı sevmərəm.","Bilirəm, günəş işığında, bilirəm, eşqlə yanaşı yaşaya bilməz nə haqsızlıq, nə qorxu, nə aclıq…","— Necati Cumalı","İbrət: Həyatın gözəlliyini qorumaq sülhün, mərhəmətin və həqiqətin yanında olmaqdır. Günəşli günün dəyəri insanların onu qorxusuz, azad və tox yaşaya bilməsindədir."]},{"stem":"choose-your-confidant","title":"Hər dərdi hər kəsə söyləmə","hasAudio":false,"hasImage":true,"paragraphs":["Hər dərd hər kəsə söylənməz.","Gün gələr, etibar edib açdığın yaranı yenidən incidərlər.","İbrət: Dərdini bölüşmək üçün səni anlayan, etibarını qoruyan insanı seç. Səmimiyyət dəyərlidir, amma onu kimə göstərdiyin də önəmlidir."]},{"stem":"in-your-hands","title":"Seçim bizim əlimizdədir","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün gənc bir oğlan müdrik rahibi çaşdırmaq istədi. Balaca bir quş tutub ovuclarının arasında gizlətdi, əllərini arxasına apardı və soruşdu:","— Ey müdrik qoca, de görüm, əlimdəki quş diridir, yoxsa ölü?","Öz-özünə düşünürdü: “Diri desə, quşu sıxıb öldürərəm. Ölü desə, əllərimi açıb uçuraram. Beləcə, hər iki halda onu haqsız çıxararam.”","Rahib oğlanın üzünə baxıb sakitcə dedi:","— Oğlum, cavab sənin əlindədir.","Oğlan duruxdu, başını aşağı saldı.","Qoca sözünə davam etdi:","— Sən məni yanıltmaq istəyirsən, amma bu quşun taleyi sənin seçimindən asılıdır. Onu incitmək də, azad buraxmaq da əlindədir. İnsanın müdrikliyi başqasını çıxılmaz vəziyyətə salmasında deyil, əlindəki gücdən necə istifadə etməsində görünür.","Oğlan əllərini önünə gətirib ovuclarını açdı. Quş qanad çalıb uzaqlaşdı.","Bu dəfə oğlan haqlı çıxmağa çalışmadı. Doğru olanı seçdi.","İbrət: Həyatda hər şey bizim əlimizdə deyil, amma seçimlərimizə görə məsuliyyət daşıyırıq. Yaxşı niyyət onu həyata keçirən əməllə dəyər qazanır. Gücün çatanda incitməyi deyil, qorumağı seç."]},{"stem":"question-the-question","title":"Sualın əsasını yoxla","hasAudio":false,"hasImage":true,"paragraphs":["Bir rəvayətə görə, Berkli Universitetinin məzunu Nyu-Yorkda yaşayan bir ravvinin yanına gəlib Talmudu öyrənmək istədiyini bildirir.","Ravvin soruşur:","— Aramey dilini bilirsənmi? Bəs ivrit dilini? Uşaqlıqda Tövratla tanış olmusanmı?","Gənc bütün suallara «xeyr» cavabı verir, sonra əlavə edir:","— Amma Sokrat məntiqi mövzusunda dissertasiya müdafiə etmişəm. Talmudu öyrənib təhsilimdəki bəzi boşluqları doldurmaq istəyirəm.","— Talmudu öyrənmək ciddi hazırlıq tələb edir, — ravvin deyir. — Amma bu qədər həvəslisənsə, əvvəlcə bir sual verim. İki nəfər bacadan aşağı enir. Birinin üzü təmizdir, o birinin üzü hisə bulaşıb. Hansı üzünü yuyacaq?","Gənc arxayınlıqla cavab verir:","— Əlbəttə, üzü çirkli olan!","— Bəs belə düşün: üzü təmiz olan yoldaşının üzündəki hisi görüb öz üzünün də çirkli olduğunu zənn edir və yuyunmağa gedir. Üzü çirkli olan isə qarşısındakı təmiz üzü görüb yuyunmağa ehtiyac duymur.","— Maraqlıdır! Mənə bir fürsət də verərsinizmi?","Ravvin eyni sualı təkrarlayır:","— İki nəfər bacadan aşağı enir. Birinin üzü təmizdir, o birinin üzü çirklidir. Hansı üzünü yuyacaq?","— Bu dəfə bilirəm: üzü təmiz olan!","— Amma hər ikisi də yuyuna bilər. Üzü təmiz olan yoldaşına baxıb yuyunmağa gedər. Üzü çirkli olan da yoldaşının ona baxdıqdan sonra yuyunmağa getdiyini görüb öz üzünün çirkli olduğunu anlayar.","Gənc bir an düşünür:","— Bunu nəzərə almamışdım. Bir də soruşun.","Ravvin sualı yenə təkrarlayır. Gənc bu dəfə tərəddüd etmir:","— Hər ikisi üzünü yuyacaq!","— Bəlkə də, heç biri yuyunmayacaq. Üzü çirkli olan yoldaşının təmiz üzünə baxıb yerindən tərpənməz. Üzü təmiz olan isə onun yuyunmadığını görüb özünün də təmiz olduğunu düşünər.","Çaşqın qalan gənc son bir fürsət istəyir. Ravvin başlayır:","— İki nəfər bacadan aşağı enir. Birinin üzü təmizdir, o birinin…","— Heç biri yuyunmayacaq! — gənc tələsik dillənir.","Ravvin gülümsəyir:","— Yenə cavab verməyə tələsdin. Niyə soruşmadın ki, eyni bacadan enən bu iki nəfərdən birinin üzü necə təmiz qalıb? Onların nə gördüyünü, nə düşündüyünü haradan bilirik? Mən hər dəfə yeni bir fərziyyə əlavə etdim, sən isə onu sualın şərti kimi qəbul etdin.","Bir qədər susub davam edir:","— Bəzən məsələ cavabı tapa bilməməkdə deyil, sualın özünü yoxlamadan ona cavab axtarmaqdadır. Əvvəlcə nəyin məlum olduğunu, nəyin isə sadəcə güman edildiyini ayırd etmək lazımdır.","İbrət: Hər sualın tək və qəti cavabı olmur. Düzgün düşünmək cavaba tələsməkdən deyil, sualın əsasını yoxlamaqdan və faktı fərziyyədən ayırmaqdan başlayır."]},{"stem":"shared-goal","title":"Məqsədinizdən əmin olun","hasAudio":false,"hasImage":true,"paragraphs":["İki nəfər ağır bir sandığı qapıdan keçirməyə çalışırdı. Nə qədər güc versələr də, sandıq yerindən tərpənmirdi. Axırda hər ikisi qan-tər içində dayanıb nəfəsini dərdi.","Biri alnının tərini silərək dedi:","— Nə ağır sandıqdır! Bu qədər əlləşdik, yenə də içəri sala bilmədik.","O biri təəccüblə ona baxdı:","— İçəri? Məgər biz onu bayıra çıxarmırdıq?","İbrət: Birgə işə başlamazdan əvvəl məqsədinizin eyni olduğuna əmin olun. Əks halda, bir-birinizə kömək etdiyinizi düşünərək bir-birinizə mane ola bilərsiniz."]},{"stem":"justice-and-compassion","title":"Ədalət və mərhəmət arasında","hasAudio":false,"hasImage":true,"paragraphs":["Çanaqqala döyüşləri haqqında danışılan bir rəvayətə görə, morfin çatışmadığından onu yalnız sağ qalmaq ümidi olan yaralılara vururmuşlar.","Bir gün doktor Tarıq Nüsrətin yanına gətirilən ağır yaralılardan biri öz oğlu olur. Onu xilas etməyin mümkün olmadığını görən həkim oğluna da güzəşt etmir, iynəni vurmur.","İki saat sonra oğlu şəhid olur. Ata övladının cansız bədənini qucaqlayıb pıçıldayır:","— Bağışla məni, oğlum... O sənin haqqın deyildi.","İbrət: Şəxsi bağlılığın qərarına təsir etməsinə yol verməmək ağır sınaqdır. Amma ədalətlə mərhəmət bir-birindən ayrılmamalıdır: insanın sağalmaq ümidi qalmasa da, ağrısı və ləyaqəti diqqətdən kənarda qalmamalıdır."]},{"stem":"alis-unreliable-rope","title":"Onun ipi ilə quyuya enmək olmaz","hasAudio":false,"hasImage":true,"paragraphs":["Bir vaxtlar kətan liflərindən ip hörən Əli adlı bir usta varmış. İşinə səhlənkar yanaşdığından hördüyü iplər davamsız olur, tez-tez qırılıb qəzalara səbəb olurmuş. Elə buna görə də camaat ona «ipi çürük usta Əli» deyirmiş.","Bir gün bir quzu dərin quyuya düşür. Onu çıxarmaq istəyən bir adam quzunun sahibindən ip gətirməsini xahiş edir. Ancaq gətirilən ipi görən kimi başını bulayır:","— Mən bu ipi tanıyıram. Usta Əlinin işidir. Onun ipi ilə quyuya enmək olmaz!","Quzunun sahibi gülümsəyib cavab verir:","— Ustaya haqsızlıq etmə. Onun ipi ilə quyuya enmək olar. Amma həmin iplə geri çıxmaq olarmı — bax, onu deyə bilmərəm!","İbrət: Etibar gördüyün işin keyfiyyəti ilə qazanılır. Səhlənkarlıq isə təkcə adını hörmətdən salmır, sənə güvənənləri də təhlükəyə atır."]},{"stem":"thought-word-and-deed","title":"Yaxşı düşünün, yaxşı danışın, yaxşı davranın","hasAudio":false,"hasImage":true,"paragraphs":["Yaxşı düşünün, çünki düşüncələriniz sözlərinizdə əks olunur.","Yaxşı danışın, çünki sözləriniz əməllərinizə yol açır.","Yaxşı davranın, çünki təkrarlanan davranışlar vərdişə çevrilir.","Yaxşı vərdişlər qazanın, çünki onlar dəyərlərinizi formalaşdırır.","Dəyərlərinizi uca tutun, çünki onlar seçimlərinizə, seçimləriniz isə həyatınıza istiqamət verir.","İbrət: Düşüncələrimizdən sözlərimizə, əməllərimizdən vərdişlərimizə uzanan bir bağ var. Yaxşı niyyətimizi gündəlik davranışlarımızda yaşatdıqca həyatımızı da yaxşılığa doğru yönəldirik."]},{"stem":"facing-a-problem","title":"Problemə münasibət","hasAudio":false,"hasImage":true,"paragraphs":["Həyatında bir problem varmı?","Yoxdursa, niyə narahat olursan?","Varsa, onu həll etmək üçün nə isə edə bilərsənmi?","Edə bilərsənsə, gücünü çarə tapmağa yönəlt.","Edə bilmirsənsə, özünü üzmək nəyi dəyişəcək?","İbrət: Əlindən gələni et, səndən asılı olmayanı isə qəbul etməyi öyrən. Davamlı narahatlıq problemi həll etmir — yalnız gücünü tükədir."]},{"stem":"keeping-your-cool","title":"Soyuqqanlı olmaq","hasAudio":false,"hasImage":true,"paragraphs":["Çətin vəziyyətə düşəndə təlaşa qapılmadan dayanıb düşünün. Baş verənləri sakitcə ölçüb-biçmək daha düzgün qərar verməyə və vəziyyəti xeyrinizə dəyişməyin yolunu tapmağa kömək edər.","İbrət: Təmkin çətinliyi aradan qaldırmasa da, çıxış yolunu görməyi asanlaşdırır. Təlaşa qapılmadan düşün, sonra addım at."]},{"stem":"education-or-character","title":"Təhsil, yoxsa xasiyyət?","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün padşah vəzirindən soruşdu:","— İnsanda hansı daha vacibdir: təhsil, yoxsa xasiyyət?","Vəzir cavab verdi:","— Xasiyyət, padşahım.","Padşah bu cavabla razılaşmadı. Ölkənin ən mahir heyvan təlimçisini tapıb saraya gətirtdi.","— Bir pişiyə məcməyi daşıyıb qonaqlara xidmət etməyi nə qədər vaxta öyrədə bilərsən? — deyə soruşdu.","— Altı aya, padşahım.","Altı ay sonra təlimçi pişiklə birlikdə saraya gəldi. Qonaqlar toplandı, məclis başladı. Pişik məcməyini tutub aramla qonaqlara yaxınlaşırdı. Hamı heyrətlə ona baxırdı.","Padşah vəzirə tərəf dönüb gülümsədi:","— İndi de görüm: təhsil vacibdir, yoxsa xasiyyət?","Vəzir cavab verməzdən əvvəl özü ilə gətirdiyi balaca siçanı yerə buraxdı. Siçanı görən pişik məcməyini atıb onun dalınca qaçdı.","Vəzir sakitcə dedi:","— Xasiyyət, padşahım.","Padşah susdu. Məclisdə hamının heyran qaldığı davranış bir anda yox olmuşdu.","İbrət: Öyrənilmiş davranış hələ möhkəm xarakter demək deyil. Təhsilin dəyəri yalnız bilik və bacarıqda yox, insanın dürüstlüyündə, məsuliyyətində və çətin anda etdiyi seçimlərdə də görünməlidir."]},{"stem":"inner-housekeeping","title":"Təmizliklə məşğul oldum","hasAudio":false,"hasImage":true,"paragraphs":["Bu gün təmizlik etdim. Evimdə yox, içimdə…","Qəlbimin çoxdan baş çəkmədiyim guşələrinə baxdım. İllərlə yığılıb qalmış inciklikləri, puça çıxmış ümidlərin qırıntılarını, dilə gətirmədiyim gileyləri bir-bir üzə çıxardım.","Əvvəlcə məyusluqlardan başladım. Hər birini yenidən yaşamağa, kimin haqlı, kimin haqsız olduğunu araşdırmağa çalışmadım. Sadəcə artıq onları özümlə daşımaq istəmədiyimi anladım.","İçimdə nə qədər yer tuturlarmış… Elə bilirdim, çoxdan unutmuşam. Sən demə, unutmaqla azad olmaq eyni şey deyilmiş.","Bağışlamağa yer açdım — başqalarını da, özümü də bağışlamağa. Baş verənlərə haqq qazandırdığım üçün yox, onların ağrısını ömür boyu daşımaq istəmədiyim üçün.","Sonra qısqanclıqla üzləşdim. Başqalarının həyatına baxa-baxa öz həyatımın gözəlliklərini nə qədər gözdən qaçırmışdım! Kiminsə uğurunu öz məğlubiyyətim saydığım anlar olmuşdu.","Qısqanclığın yerinə minnətdarlıq qoydum. Sahib olduqlarımı, yanımda olanları, hələ edə biləcəklərimi xatırladım. Sanki çoxdan itirdiyim bir şeyi yenidən tapdım: öz həyatımın dəyərini.","Qəlbimə diqqətlə baxdım. Şükür ki, orada kök salmış kinə, nifrətə rast gəlmədim. Amma bəzi incikliklərin hələ də sızıldadığını hiss etdim. Onlara görə özümü qınamadım. Bu yaraların sağalması üçün zaman lazım idi.","Sonra növbə qorxularıma çatdı.","Əvvəlcə onlara toxunmağa belə qorxdum. Onlarla yaşamağa elə alışmışdım ki, yoxluqlarını təsəvvür etmək belə qəribə gəlirdi. Biri o birinə bağlanmışdı: səhv etmək qorxusu, itirmək qorxusu, bəyənilməmək qorxusu…","Hər narahatlıqdan yeni bir qorxu doğmuşdu. Mən də onlara uyub arzularımı, sevincimi, həyatımı sonraya saxlamışdım.","«Bir az da gözləyim…» «Hər şey düzəlsin…» «Sonra başlayaram…»","O «sonra»nı gözləyə-gözləyə nə qədər «bu gün»ü əldən vermişdim.","Qorxularımın hamısını bir gündə yox edə bilmədim. Amma onları dinləyib anlamağa çalışdım: hansı məni qoruyur, hansı yolumu kəsir? Anladım ki, hər qorxu məni dayandırmalı deyil. Bəzən qorxa-qorxa da bir addım atmaq olarmış.","Keçmişdə belə yaşadığıma görə özümü qınamadım. Bu gün anladığımı dünən bilmirdim.","Bu gün içimdə təmizlik etdim.","Sevincə yer açdım. Ümidə, sevgiyə, özümə inama…","Əvəz gözləmədən yaxşılıq etməyə, verməyə, paylaşmağa yer açdım. Başqalarını sevərkən özümü də unutmamağa söz verdim.","Bir az şıltaqlıq, bir az cəsarət, bir az da uşaq səmimiyyəti qaytardım içimə. Gülmək üçün böyük səbəblər gözləməyə ehtiyac olmadığını xatırladım.","Sükuta da yer ayırdım. Çünki bəzən öz səsimi eşitmək üçün içimdəki hay-küyün səngiməsi lazımdır.","Ən sonda qəbul etməyi öyrənməyə başladım: özümü, keçmişimi, dəyişdirə bilmədiklərimi.","Bu, hər şeyə boyun əymək deyildi. Dəyişdirə biləcəyim şeylərə güc ayırmaq üçün dəyişdirə bilmədiklərimlə savaşmağı dayandırmaq idi.","Bu gün içimdə təmizlik etdim. Hələ hər şey bitməmişdi. Amma içimdə nəfəs almağa yer açılmışdı.","İbrət: Qəlbin qayğısına qalmaq hisslərini boğmaq deyil, onları anlamaq və sənə yük olanları tədricən buraxmaqdır. Özünə mərhəmətlə yanaşdıqca içində sevgiyə, ümidə və rahatlığa yer açılır."]},{"stem":"words-to-avoid","title":"Uzaq duracağınız ifadələr","hasAudio":false,"hasImage":true,"paragraphs":["Ailədə fikir ayrılığı ola bilər. Amma narazılığı ifadə etmək üçün seçdiyimiz sözlər bir-birimizi anlamağa da kömək edə, aramızdakı yaxınlığı da zədələyə bilər.","“Boş-boş danışma!”","Bu söz qarşı tərəfə “Sənin fikrinə dəyər vermirəm” mesajını verir. Razılaşmırsınızsa, fikri alçaltmadan münasibətinizi bildirin:","— Mən bu məsələyə başqa cür baxıram. İstəyirəm, sənin düşüncəni də anlayım.","“Şişirtmə!”","Sizə kiçik görünən bir məsələ həyat yoldaşınızı dərindən narahat edə bilər. Onun hisslərini kiçiltmək əvəzinə soruşun:","— Bu məsələdə səni ən çox nə narahat edir? Səni dinləmək istəyirəm.","“Onun ərinə, arvadına bax! Bəs sən?”","Müqayisə insanın özünü dəyərsiz və yetərsiz hiss etməsinə səbəb ola bilər. Başqasını nümunə göstərmək əvəzinə öz ehtiyacınızı konkret söyləyin:","— Ev işlərini bölüşməyimiz mənim üçün vacibdir. Gəl, ikimizə də uyğun bir yol tapaq.","“Sən başa düşməzsən!”","Bu cümlə söhbətin qapısını bağlayır. Fikrinizi ifadə etmək çətindirsə və ya danışmağa hazır deyilsinizsə, bunu açıq deyin:","— Hisslərimi sözlə ifadə etməkdə çətinlik çəkirəm. Mənə bir az vaxt ver, sonra danışaq.","“Ora getmə! Onunla danışma! Bunu geyinmə!”","Həyat yoldaşınızın yerinə qərar vermək haqqınız yoxdur. Narahatlığınızı izah edin, onun fikrini dinləyin, ortaq məsələlərdə razılıq axtarın. Sadəcə əmrin əvvəlinə “zəhmət olmasa” əlavə etmək onu hörmətli xahişə çevirmir; qarşı tərəfin seçim haqqını da qəbul etmək lazımdır.","— Bu məsələ məni narahat edir. Gəl, danışaq, bir-birimizi anlayaq.","İbrət: Hörmət razılaşmadığımız anlarda da qorunmalıdır. Hissini anlat, ehtiyacını açıq söylə, qarşı tərəfi də dinlə. Yaxınlıq bir-birini susdurmaqla deyil, eşitməklə möhkəmlənir."]},{"stem":"letting-go","title":"Vaz keçmək","hasAudio":false,"hasImage":true,"paragraphs":["«Gözəl xasiyyətdir vaz keçmək!»","Qədir-qiymət bilməyəndən,","səmimiyyəti tapdayandan,","mənfəət üçün dəyişəndən,","təkəbbür tuluğu, lovğa kəslərdən,","paxıllıq edəndən, qeybət qırandan,","yalanı özünə adət edəndən,","ədəb-ərkan nədir bilməyəndən,","dəyərlərini puç edənlərdən,","nadanlığa, cahilliyə göz yumanlardan,","vətəninə xor baxandan, millətini danandan,","doğma dilini unudanlardan,","ana sevgisinin, ata izzətinin, övlad məhəbbətinin qədrini bilməyəndən...","«Gözəl xasiyyətdir vaz keçmək!»","Özünü vazkeçilməz sanandan...!","İbrət: Bəzi insanlardan uzaqlaşmaq zəiflik deyil, özünə hörmətdir. Qədrini bilməyənə bel bağlamamaq da bir məziyyətdir."]},{"stem":"strengths-and-vulnerabilities","title":"Üstünlüyümüz bəlamıza çevrilə bilər","hasAudio":false,"hasImage":true,"paragraphs":["Tovuz quşunun düşməni gözəl quyruğudur.","Bülbülü qəfəsə salan şirin nəğməsidir.","Tülkünü tələyə salan gözoxşayan kürküdür.","Özümüzdə bəyənib dəyər verdiyimiz cəhətlər də bəzən zəif nöqtəmizə çevrilir, başımıza bəla gətirir.","İbrət: Üstünlük saydığımız bir xüsusiyyət bəzən bizi təhlükəyə açıq qoyur. Öz dəyərini bilmək qədər güclü tərəflərinin hansı hallarda zəifliyə çevrilə biləcəyini anlamaq da vacibdir."]},{"stem":"telling-lies","title":"Özünə inam və həqiqət","hasAudio":false,"hasImage":true,"paragraphs":["— Yalan danışırsan?","— Hə.","— Necə yalan?","— Yalnız özümə dediyim bir yalan. Hər gün özümə deyirəm: «Sən hamıdan güclüsən, hamıdan savadlısan, hamıdan bacarıqlısan».","— Bəlkə, elə doğrudan da beləsən?","— Yox, bunu demək olmaz. Məndən güclüsü də var, savadlısı da, bacarıqlısı da.","— Bəs niyə özünə belə deyirsən?","— İnanırsan, bu sözlər məni həvəsləndirir. Daha güclü, daha bilikli, daha bacarıqlı olmaq üçün öz üzərimdə çalışmaq istəyirəm.","İbrət: Özünü hamıdan üstün saymağa ehtiyac yoxdur. «Öyrənə bilərəm, bacarığımı artıra bilərəm» demək də insana güc verir. Özünə inam səylə birləşəndə inkişafın dayağına çevrilir.","Bəxtiyar Siracov"]},{"stem":"every-day-has-meaning","title":"Hər günün bir dərsi var","hasAudio":false,"hasImage":true,"paragraphs":["Yaşadığın heç bir günü hədər sayma:","Gözəl günlər sevinc gətirər, çətin günlər təcrübə qazandırar, ən ağır günlər bəzən ən dərin dərsləri verər, ən xoşbəxt günlər isə unudulmaz xatirələrə çevrilər.","İbrət: Hər günün mənası elə həmin gün aydın olmaya bilər. Sevincin qədrini bil, çətinlikdə özünə qarşı mərhəmətli ol. Yaşadıqlarının sənə nə öyrətdiyini anlamaq üçün bəzən zamana ehtiyac var."]},{"stem":"mature-person","title":"Yetkin insan","hasAudio":false,"hasImage":true,"paragraphs":["Elə bir vaxt gəlir ki, köhnə dostların səmimiyyətini daha dərindən qiymətləndirirsən. Sırf ətrafında adam çox olsun deyə yeni tanışlıqlar axtarmırsan. Anlamaq istəməyən insanlarla mübahisəyə girmir, səni daxilən yoran münasibətlərdən uzaqlaşırsan. Onda anlayırsan ki, artıq yetkinləşirsən.","İbrət: Yetkinlik səmimi münasibətlərin qədrini bilmək, sərhədlərini qorumaq və daxili dincliyinə sahib çıxmaqdır. Kimə yaxın olacağını bilmək qədər kimdən və nədən uzaqlaşacağını anlamaq da müdriklikdir."]},{"stem":"plucking-the-goose","title":"Yolunacaq qaz","hasAudio":false,"hasImage":true,"paragraphs":["Soyuq bir qış günü padşah tanınmamaq üçün libasını dəyişib baş vəziri ilə gəzintiyə çıxdı. Bir qədər yol gedəndən sonra dərənin kənarında işləyən ağsaqqal bir kişiyə rast gəldilər. Qoca dəriləri buz kimi suya salıb döyə-döyə aşılayırdı.","Padşah ona salam verdi:","— Əssəlamü-əleyküm, ey piri-fani!","— Əleykümü-əssəlam, ey sərdari-cahan! — deyə qoca cavab verdi.","Padşah soruşdu:","— Altılarda nə etdin?","— Altıya altı qatmayınca otuz ikiyə çatmır, — dedi qoca.","— Bəs gecələr heç qalxmadınmı?","— Qalxdıq, padşahım, amma xeyri başqa ocaqlara dəydi.","Padşah gülümsədi:","— Sənə bir qaz göndərsəm, yolarsanmı?","— Yolaram, padşahım, özü də ciyildətmədən!","Padşahla vəzir yollarına davam etdilər. Bir az uzaqlaşandan sonra padşah soruşdu:","— Söhbətimizdən bir şey anladınmı?","— Xeyr, padşahım, — deyə vəzir boynunu bükdü.","Padşah sərt səslə dedi:","— Axşama qədər bu sözlərin mənasını açmasan, başınla cavab verəcəksən!","Vəzir padşahı saraya ötürüb tələsik dərənin kənarına qayıtdı. Qoca hələ də işləyirdi.","— Ay kişi, padşahla nə danışırdınız? Mənə də başa sal!","Qoca onu başdan-ayağa süzüb dedi:","— Hər cavabın qiyməti yüz qızıldır.","Vəzir əlacsız qalıb yüz qızıl verdi:","— Əvvəlcə de görüm, onun padşah olduğunu haradan bildin?","— Mən dəriçiyəm. Əynindəki kürkün qiymətini bir baxışdan bildim. Beləsini ancaq padşah geyə bilərdi.","Vəzir daha yüz qızıl çıxardı:","— Bəs altı ilə otuz ikinin nə əlaqəsi vardı?","— Padşah soruşurdu ki, yayın altı ayında nə etmisən ki, qışın bu soyuğunda da işləyirsən? Mən də dedim: altı ay yayda, altı ay da qışda işləməsək, bu otuz iki dişə çörək çatdıra bilmərik.","Vəzir üçüncü dəfə yüz qızıl verdi:","— Bəs gecələr qalxmaq nə demək idi?","— Övladımın olub-olmadığını soruşurdu. Mən də dedim ki, var, amma hamısı qızdır. Ərə gedib öz ailələrini qurublar, indi onların qayğısını çəkirlər.","Vəzir bir qədər düşünüb son sualını verdi:","— Bir də sənə qaz göndərəcəyini dedi... O qaz kim idi?","Qoca qızıllara baxıb gülümsədi:","— Onu da özün tap!","İbrət: Sözü eşitmək hələ onun mənasını anlamaq deyil. Vəzifə insana öz-özünə müdriklik qazandırmır; bəzən sarayda açılmayan bir düyünü həyatın içində bişmiş sadə bir insan açır."]},{"stem":"learning-to-say-yet","title":"Düşüncəni dəyiş, yenidən cəhd et","hasAudio":false,"hasImage":true,"paragraphs":["«Mən bu işi bacarmıram» demək əvəzinə, «Hələ öyrənməli olduğum şeylər var. Biliyimi artırıb məşq etdikcə daha yaxşı bacararam» deyin.","«Bu işdən vazkeçdim» demək əvəzinə, «Bəlkə, başqa bir yol sınayım? İndiki üsul alınmadısa, fərqli yanaşma kömək edə bilər» deyin.","«Bu iş çox çətindir» deyib dayanmaq əvəzinə, «Çətindir, amma addım-addım irəliləyə bilərəm. Mənə bir az da vaxt, zəhmət və, bəlkə də, kömək lazımdır» deyin.","«Bundan yaxşısını edə bilmərəm» demək əvəzinə, «İndiki nəticəmdən razıyam, amma öyrənib daha da təkmilləşə bilərəm» deyin.","«Səhv etdim, kaş etməyəydim» deyib özünüzü qınamaq əvəzinə, «Səhvimi necə düzəldə bilərəm? Bundan nə öyrəndim?» deyə düşünün.","«O çox ağıllıdır, mən onun kimi ola bilmərəm» demək əvəzinə, «Onun necə öyrəndiyinə, necə çalışdığına baxıb özüm üçün faydalı bir yol tapa bilərəm» deyin.","İbrət: Özünlə necə danışdığın növbəti addımına təsir edir. «Bacarmıram» sözünə «hələ» əlavə etmək öyrənməyə yer açır. Səhv isə ondan nəticə çıxarıb yenidən çalışanda inkişaf fürsətinə çevrilir."]},{"stem":"try-again","title":"Alınmadısa, yenidən başla","hasAudio":false,"hasImage":true,"paragraphs":["Günlər bir-birini əvəz edir. Bəzisini sevinclə, bəzisini yorğunluq və kədərlə yola salırıq. Bəzən planlaşdırdıqlarımız yarımçıq qalır, nə qədər çalışsaq da, istədiyimiz nəticəni ala bilmirik.","Belə anlarda “çatdırmadım” deyə özünü qınama, “bacarmadım” deyə ümidini kəsmə. Bir işin bu gün alınmaması onun heç vaxt alınmayacağı demək deyil.","Bir az dincəl, gücünü topla. Sabah yenidən cəhd etmək, başqa yol sınamaq, kiçik də olsa bir addım atmaq üçün yeni fürsət ola bilər.","İbrət: Yarımçıq qalan bir iş sənin bacarıqsız olduğunu göstərmir. Özünə vaxt ver: irəliləmək bəzən yenidən başlamaq, bəzən də dincəlib davam etməkdir."]},{"stem":"obstacles-and-opportunities","title":"Çətinliyi fürsətə çevirmək","hasAudio":false,"hasImage":true,"paragraphs":["Həyatda bəzən işlərimiz yolunda gedir, bəzən isə gözləmədiyimiz çətinliklər qarşımıza çıxır. Hər maneəni aradan qaldırmaq asan olmasa da, ondan nəsə öyrənmək, başqa bir yol tapmaq və irəliləmək üçün fürsət yaratmaq mümkündür.","İbrət: Çətinlik qarşısında sarsılmaq zəiflik deyil. Özünə vaxt ver, ehtiyacın varsa, kömək istə və yaşadıqlarından öyrənərək növbəti addımını at. Bəzən yeni bir yol elə maneənin qarşısında görünür."]},{"stem":"believe-in-yourself","title":"Özünə inan","hasAudio":false,"hasImage":true,"paragraphs":["Öz dəyərini bil!","Zəhmətdən çəkinmə!","Gücünü və bacarığını artır!","Ümidini itirmə!","Vicdanının səsinə qulaq as!","Əzmindən dönmə!","Niyyətini təmiz saxla!","Ləyaqətini qoru!","İmanlı ol!","İbrət: Özünə inam hər şeyi bacardığını düşünmək deyil, öyrənə və inkişaf edə biləcəyinə inanmaqdır. Ümid, əzm və ləyaqət bu yolda sənə dayaq olsun."]},{"stem":"other-peoples-thoughts","title":"Özgələrin fikirləri","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün insan vergülü (,) itirdi. Sözləri bir-birinə qarışdı, harada dayanıb nəfəs alacağını unutdu.","Başqa bir gün nöqtəni (.) itirdi. Düşüncələri bitib-tükənmədən uzandı, bir fikri tamamlayıb o birinə keçə bilmədi.","Sonra nida işarəsini (!) itirdi. Sevincinin, qəzəbinin, heyrətinin səsi söndü.","Bir gün də sual işarəsini (?) itirdi. Daha sual vermədi, eşitdiyi hər şeyi sorğu-sualsız qəbul etdi.","Ardınca iki nöqtəni (:) itirdi. Fikirlərini açıqlamağı, dediklərinin səbəbini izah etməyi unutdu.","Ömrünün sonunda əlində yalnız dırnaq işarələri qalmışdı.","Onların içində isə təkcə başqalarının fikirləri vardı.","İbrət: İnsan sual verməkdən, düşünməkdən və hisslərini ifadə etməkdən uzaqlaşdıqca öz səsini itirir. Başqalarından öyrənmək dəyərlidir, amma onların fikirlərini təkrarlamaq öz düşüncənin yerini tutmamalıdır."]},{"stem":"welcoming-smile","title":"Üzünüz daim gülsün","hasAudio":false,"hasImage":true,"paragraphs":["Gülərüz sirkə satanın qaşqabaqlı bal satandan daha çox müştərisi olar.","İbrət: İnsanları cəlb edən təkcə verdiyin deyil, onu necə təqdim etdiyindir. Səmimi təbəssüm və mehriban rəftar ən şirin nemətdən də xoş təsir bağışlaya bilər."]},{"stem":"generous-man","title":"Əliaçıq adam","hasAudio":false,"hasImage":true,"paragraphs":["Əliaçıq bir adamdan soruşdular:","— Ehtiyacı olanlara kömək edirsən. Əvəzində onların sənə minnətdar olmasını gözləyirsənmi?","Adam cavab verdi:","— Mən özümü aşpazın əlindəki çömçə kimi görürəm. Yemək onunla paylanır, amma süfrəni açan çömçə deyil. Mən də Allahın verdiyini bölüşürəm. Buna görə tərif gözləməkdənsə, yaxşılığa vasitə ola bildiyimə şükür edirəm.","İbrət: Yaxşılığı minnətə çevirmə. Sənə verilən neməti bölüşərkən həm təvazökar ol, həm də kömək etdiyin insanın ləyaqətini qoru. Vermək imkanı da şükrə layiq bir nemətdir."]},{"stem":"strongest-shield","title":"Ən güclü qalxan","hasAudio":false,"hasImage":true,"paragraphs":["Həyatda bəzən ən güclü qalxan qorumağı bacardığın məsafədir.","İbrət: Səni incidən münasibətlərdə məsafə saxlamaq özünə hörmətdir. Yaxınlıq dəyərlidir, amma şəxsi sərhədlərini qorumaq da vacibdir."]},{"stem":"three-best-things","title":"Ən yaxşı üç şey","hasAudio":false,"hasImage":true,"paragraphs":["Bir ata oğluna dedi:","— Oğlum, həyatda üç şeyə can atmalıyıq: ən yaxşı yeməyi yeməyə, ən rahat yataqda yatmağa və ən gözəl evdə yaşamağa.","Oğlu təəccübləndi:","— Amma, ata, biz kasıbıq. Bunlara necə sahib ola bilərik?","Ata gülümsəyib cavab verdi:","— Ac olanda yediyin sadə yemək belə sənə ən ləzzətli yemək kimi gələr. Gününü zəhmətlə keçirib yorğun uzananda yatağın sənə ən rahat yataq olar. İnsanlara qəlbində yer verib onların da könlündə yer qazansan, ən gözəl evin orada olar.","İbrət: Həyatın gözəlliyi yalnız bahalı nemətlərdə deyil. Bir tikə yeməyin dadını bilmək, zəhmətdən sonra rahat dincəlmək və könüllərdə yer qazanmaq da böyük xoşbəxtlikdir."]}]},{"title":"Söz, sükut və ünsiyyət","slug":"soz-sukut-ve-unsiyyet","blurb":"Sözün gücü, sükutun hikməti və doğru ünsiyyət.","count":12,"stories":[{"stem":"share-what-you-know","title":"Bildiklərini söylə","hasAudio":false,"hasImage":true,"paragraphs":["Bildiklərini bölüş, amma başqalarına ağıl verməyə çalışma. Deyilənləri diqqətlə dinlə, amma eşitdiyin hər sözü həqiqət sayma.","Susmaq heç nə bilməmək deyil, çox danışmaq da çox bilmək demək deyil. Başqasını alçaltmaq ağılsızlıqdır, yersiz təriflə göylərə qaldırmaq isə qorxaqlıq əlamətidir.","İbrət: Bildiyini təvazökarlıqla bölüş, eşitdiyini düşünərək dəyərləndir, yeri gələndə susmağı bacar. İnsanları nə alçalt, nə də şişirdilmiş təriflərlə ucalt — onları olduqları kimi gör, dəyərlərini ədalətlə müəyyən et."]},{"stem":"knowing-what-you-know","title":"Bilən və bilməyən","hasAudio":false,"hasImage":true,"paragraphs":["(Çin məsəli)","Bilməyən, amma bilmədiyini anlayan öyrənməyə hazırdır. Ona öyrədin!","Bilən, amma bildiyinin fərqində olmayan yuxudadır. Onu oyadın!","Bilməyən, amma bilmədiyini də anlamayan nadandır. Ondan uzaq durun!","Bilən və bildiyinin fərqində olan yol göstərə bilər. Onun ardınca gedin!","İbrət: Müdriklik nəyi bildiyini və nəyi bilmədiyini dərk etməkdən başlayır. Öyrənmək istəyənə kömək et, öz biliyini görməyəni ruhlandır, nadanlığına arxayın olandan çəkin, həqiqətən biləndən öyrən."]},{"stem":"language","title":"Dil","hasAudio":false,"hasImage":true,"paragraphs":["Dil bir çiçəkdir, ağızda bitər, Suvarıb qorumasan, solub gedər.","İbrət: Ana dili qayğı ilə yaşayır. Onu gündəlik danışığında, oxuduğun kitablarda və övladına öyrətdiyin sözlərdə yaşat."]},{"stem":"what-is-a-word","title":"Söz nədir?","hasAudio":false,"hasImage":true,"paragraphs":["Söz var, incidir;","söz var, inci-dir.","İbrət: Sözlə könül sındırmaq da olar, könül almaq da. Sözü inciyə çevirən onu yerində, vaxtında və ürəklə deməkdir."]},{"stem":"words-and-silence","title":"Söz və sükut","hasAudio":false,"hasImage":true,"paragraphs":["Bəzən insan susaraq daha çox şey söyləyir. Çünki söz sadəcə səs deyil — niyyətin aynasıdır.","Bir söz könül qıracaq, bir cümlə ümid söndürəcəksə, onu deməzdən əvvəl dayan, düşün.","Söyləyəcəyin söz nə anlayış gətirəcək, nə təsəlli verəcək, nə də bir xeyrə yarayacaqsa, susmaq daha yaxşıdır.","Unutma: hər kəlmə gül açmır. Bəziləri tikan kimi toxunduğu yeri yaralayır.","Sükut bəzən hikmət, bəzən də ən mənalı cavabdır.","Ürəkdən gələn, düşünülərək deyilən söz insana dayaq olar. Düşünmədən deyilən söz isə qəlbdə uzun müddət sağalmayan yara aça bilər.","Sözünü də, sükutunu da yerində seç. Çünki sükut da danışır — bəzən sözdən daha dərin, daha dürüst.","İbrət: Sözün dəyəri çoxluğunda deyil, gətirdiyi xeyirdədir. Danışanda düşün, susanda da bil ki, sükutun nə deyir."]},{"stem":"well-chosen-words","title":"Sözü yerində söyləmək","hasAudio":false,"hasImage":true,"paragraphs":["Sözünü yerində və düşünərək deyən sonradan peşman olub üzr istəməli olmaz.","İbrət: Danışmazdan əvvəl sözünün qarşı tərəfə necə təsir edəcəyini düşün. Söz vaxtında, yerində və hörmətlə deyiləndə dəyər qazanır."]},{"stem":"silence","title":"Sükut","hasAudio":false,"hasImage":true,"paragraphs":["Bəzi sualların cavabı sükutdur.","Ya cavab verməyin vaxtı çatmayıb, ya da həmsöhbətin o cavaba layiq deyil.","İbrət: Hər suala cavab vermək məcburiyyətində deyilsən. Bəzən doğru anı gözləmək, bəzən də sözünün qədrini bilməyənin qarşısında susmaq daha müdrik seçimdir."]},{"stem":"silent-corridor","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/silent-corridor.webp","title":"Səssiz dəhliz","hasAudio":false,"hasImage":true,"paragraphs":["Birgə fəaliyyət göstərən iki təşkilat var idi — biri sponsor, digəri isə layihə hazırlayan qurum.","Layihə üzərində işləyənlər aylarla zəhmət çəkib sənədləri hazırladılar. İş tamam olanda materialları sponsora göndərib cavab gözlədilər. Günlər, həftələr keçdi, amma səs-soraq gəlmədi.","Komandanın içində qeyri-müəyyənlik böyüyüb dəhliz boyunca uzanan kölgə kimi yayılırdı:","«Sənədlər çatdımı? Onlara baxılıbmı?»","Heç kimin dəqiq məlumatı yox idi. Sponsora edilən müraciətlər isə yalnız üstüörtülü, qeyri-müəyyən cavablar gətirirdi.","Bir neçə aydan sonra məsələni aydınlaşdırmaq üçün sponsorun ofisinə getdilər. Həqiqəti yalnız orada öyrəndilər:","«Bəli, sənədlər gəlib. Amma biz onları qəbul etməmişik. Çünki təqdimat forması düzgün deyil və rəsmi prosedura əməl olunmayıb.»","Bunu eşidəndə yerlərində donub qaldılar.","— Bəs niyə bizə xəbər vermədiniz? — deyə soruşdular.","— Axı biz nöqsanları tezliklə aradan qaldıra bilərdik.","Məyus halda ofisə qayıdan əməkdaşlar öz rəhbərliklərinə irad bildirdilər:","“İşin gedişini izləsəydik, sənədlərin nə yerdə olduğunu vaxtında öyrənsəydik, qarşı tərəflə aydın danışsaydıq, belə olmazdı. Vaxtımız, zəhmətimiz hədər getdi, inamımız sarsıldı. Çünki aramızdakı dəhliz səssiz qaldı.”","İbrət: Aydın ünsiyyət olmayanda ən yaxşı iş də nəzərdən qaça bilər. İşin gedişini izləməmək ən möhkəm əməkdaşlığı da zəiflədir. Bəzən əməkdaşlığa ən böyük zərəri uğursuzluq yox, səssizlik vurur.","Bəxtiyar Siracov"]},{"stem":"call-the-shepherd","title":"Çobanı səsləmək lazımdır","hasAudio":false,"hasImage":true,"paragraphs":["Uzun illər təhsil almış bir tələbə ustadının yanına gəlib yola çıxmazdan əvvəl ondan xeyir-dua istədi.","Ustad dedi:","— Xeyir-duamı verərəm, amma əvvəlcə bir suala cavab verməlisən. Görüm, bu illər ərzində öyrətdiklərimi necə mənimsəmisən.","Tələbə özünə arxayın halda cavab verdi:","— Buyurun, ustadım, soruşun.","— Övladım, təsəvvür et ki, kəndinə qayıdırsan. Yolda bir çobanın itləri üstünə cumur. Özünü qorumaq üçün nə edərsən?","— Yerdən bir neçə daş götürüb itlərə ataram, onları qovaram.","— Birini, ikisini qovdun. Bəs hamısı birdən üstünə gəlsə?","Tələbə bir qədər düşünüb dedi:","— Onda qaçaram.","— İtlər səndən daha sürətli qaçıb səni yaxalasalar, necə?","Tələbə susdu. Başqa çıxış yolu tapa bilmədiyini görüb soruşdu:","— Bəs nə etməliyəm, ustadım?","Ustad cavab verdi:","— Çobanı səsləməlisən, övladım. Ondan itlərini saxlamasını istəməlisən. Sən itlərin hər biri ilə ayrı-ayrılıqda mübarizə aparmağı düşündün, amma onları sakitləşdirə biləcək adamdan kömək istəmək ağlına gəlmədi.","İbrət: Hər çətinliyi təkbaşına və güclə aşmaq olmur. Bəzən ən ağıllı addım vəziyyətə təsir edə bilən adamı tapıb ondan kömək istəməkdir."]},{"stem":"shepherds-word","title":"Çobanın sözü","hasAudio":false,"hasImage":true,"paragraphs":["Bir zamanlar bir kənddə Həsən adlı kasıb, amma dürüst bir çoban yaşayırdı. Bir gün kəndin ağası onu yanına çağırıb dedi:","— Həsən, eşitmişəm, dağ otlaqlarını yaxşı tanıyırsan. Bu yay sürümü sənə tapşırıram. Payızda heyvanlarımı sağlam və kök qaytarsan, sənə bir inək bağışlayacağam.","Həsən razılaşdı. Bütün yayı yağışa, istiyə baxmadan sürünü otardı, gecələr keşiyini çəkdi. Payızda heyvanları əvvəlkindən də kök və sağlam halda kəndə qaytardı.","Vəd olunmuş inəyi almaq ümidi ilə ağanın yanına getdi. Ağa isə istehza ilə gülümsədi:","— Sənə inək vermək fikrim yox idi. O sözü səni işə həvəsləndirmək üçün demişdim. Onsuz da kasıbsan, inəyi neyləyəcəksən?","Həsənin gözləri doldu. Amma özünü ələ alıb sakitcə cavab verdi:","— Düz deyirsən, ağa, mən kasıbam. Amma vicdanım var, verdiyim sözün də üstündə dururam. Sən varlı ola bilərsən, ancaq sözünün dəyəri yoxdursa, əsl kasıb sənsən.","Çobanın sözləri kənddə ağızdan-ağıza yayıldı. Ağa hörmətdən düşdü, camaat onunla iş görməkdən çəkinməyə başladı. O da gec olsa belə anladı: insanın dəyərini mal-dövləti və ya mövqeyi deyil, sözünə nə qədər sadiq qalması göstərir.","İbrət: İnsanın əsl sərvəti vicdanı, sözünə sədaqəti və qazandığı etibardır. Var-dövlət hörmətə zəmanət verməz; tutulmayan söz isə etibarı sarsıdar."]},{"stem":"communication","title":"Ünsiyyət","hasAudio":false,"hasImage":true,"paragraphs":["Yaşlılarla da, uşaqlarla da söhbətə vaxt ayırın. Yaşlıların xatirələrində həyatın təcrübəsini, uşaqların suallarında isə dünyaya təmiz gözlə baxmağın gözəlliyini kəşf edə bilərsiniz.","İbrət: Yaşlıları dinləmək yaşananlardan dərs almağa, uşaqları dinləmək isə adi şeylərə yenidən heyrətlənməyə kömək edir. Hər yaşın bizə öyrədəcəyi bir şey var."]},{"stem":"candles-conversation","title":"Şamların söhbəti","hasAudio":false,"hasImage":true,"paragraphs":["Bir otaqda dörd şam asta-asta yanırdı. Ətraf elə sakit idi ki, onların pıçıltısını belə eşitmək olurdu.","Birinci şam dilləndi:","— Mən İnamam. İnsanlar məni qorumayanda işığım zəifləyir. Artıq sönmək üzrəyəm.","Şöləsi getdikcə kiçildi və nəhayət, söndü.","İkinci şam dedi:","— Mən Vəfayam. Verilən sözlər unudulanda, insanlar bir-birinə arxa çevirəndə mən də gücdən düşürəm. Daha yanmağa taqətim qalmayıb.","Elə bu vaxt əsən xəfif bir yel onun da işığını söndürdü.","Üçüncü şam hüznlə söylədi:","— Mən Sevgiyəm. İnsanlar bir-birinə vaxt ayırmayanda, qayğı göstərməyəndə mənim də işığım azalır. Bəzən ən yaxın adamlar belə bir-birini sevdiklərini deməyi unudur.","Sözünü bitirəndə onun da şöləsi titrəyib söndü.","Bu vaxt otağa bir uşaq girdi. Üç şamın söndüyünü görüb kövrəldi:","— Axı siz yanmalıydınız… Niyə söndünüz?","Uşağın gözləri yaşardı. Elə onda dördüncü şam dilləndi:","— Qorxma. Mən yandıqca o biri şamları yenidən alovlandıra bilərik. Mən Ümidəm.","Uşaq göz yaşlarını sildi. Yanan şamı ehtiyatla əlinə alıb o birilərini bir-bir yandırdı. Otaq yenidən işığa qərq oldu.","İbrət: Ümid inamı, vəfanı və sevgini yenidən dirçəltməyə güc verir. İçimizdəki o işığı qoruyub hərəkətə keçsək, sönmüş bildiyimiz çox şeyi yenidən alovlandıra bilərik."]}]},{"title":"Hikmət və həyat dərsləri","slug":"hikmet-ve-heyat-dersleri","blurb":"Həyatın mənası, seçimlər və düşüncə tərzi.","count":50,"stories":[{"stem":"different-door","title":"Açılmayan qapı, bəlkə də, sənin qapın deyil","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün Camal şirkətin müdiri Səlim bəyin yanına gəldi. Yaxın vaxtlarda vəzifə yüksəlişlərinin olacağını eşitmişdi və özünün də buna ümid etdiyini bildirdi.","Səlim bəy onu dinləyib dedi:","— Camal, işindən razıyam. Amma düşünürəm ki, bu şirkət sənin üçün uyğun yer deyil. Səninlə əməkdaşlığımıza son vermək qərarına gəlmişik.","Yüksəliş gözləyən Camal bu sözlərdən sarsıldı. Məyus halda şirkətdən ayrıldı.","İki il sonra onlar yenidən qarşılaşdılar. Salamlaşıb hal-əhval tutdular. Camal öz şirkətini qurduğunu və işlərinin yaxşı getdiyini söylədi. Səlim bəy bunu eşidib sevindi.","Camal keçmiş müdirinə dedi:","— O vaxt qərarınızı qəbul etmək mənim üçün çox çətin idi. Amma indi geriyə baxanda görürəm ki, işdən ayrılmağım məni başqa imkanlar axtarmağa sövq etdi. Öz işimi qurdum, sevdiyim sahədə çalışmağa başladım. Bu gün həyatımdan razıyam. O ayrılıq mənim üçün yeni bir başlanğıc oldu. Buna görə sizə təşəkkür edirəm.","İbrət: Açılmayan qapı həmişə yolun sonu deyil. Bəzən bir fürsəti itirmək insana özünə daha uyğun yolu axtarmağa təkan verir. Əsas olan məyusluğun içində dayanıb qalmamaq, yeni imkanları görüb addım atmaqdır."]},{"stem":"searching","title":"Axtarmaq","hasAudio":false,"hasImage":true,"paragraphs":["Bir şeyi olmadığı yerdə axtarmaq axtarış deyil, özünü aldatmaqdır — vəfasızda vəfa, həyasızda ədəb, vicdansızda mərhəmət axtarmaq kimi.","İbrət: İnsanları görmək istədiyin kimi deyil, davranışlarında göstərdikləri kimi tanı. Ümidini yalnız gözləntilərinə bağlama; sözə də, əmələ də bax."]},{"stem":"another-day","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/another-day.webp","title":"Bir gün də yaşadım...","hasAudio":false,"hasImage":true,"paragraphs":["Gün başladı... Gün bitdi...","Hər səhər gözlərimizi açanda yeni bir günün başladığını görürük. Amma çox zaman axşamın nə vaxt gəlib çatdığını, bir günün ömrümüzdən nə zaman ayrıldığını hiss etmirik. Zaman sakit bir çay kimi axır; biz isə onun sahilində dayanıb ötən anların arxasınca baxırıq.","Bəzən insan öz-özünə düşünür: Tanrı bu günü mənə hansı hikmətlə bəxş etmişdi? Mən bu ilahi əmanətin qədrini bildimmi? Bu günə nə əlavə etdim, ondan nə götürdüm? Ruhuma hansı işığı gətirdim, hansı fürsəti əldən verdim?","İnsan ömrünün ən böyük sərvəti zamandır. Çünki itirilən hər şey bəzən geri qayıda bilər, amma ötən bir an belə geri dönmür. Buna görə də hər günün, hər saatın, hətta hər nəfəsin öz dəyəri və mənası vardır.","Beləcə, bir gün də yaşadım... Zamanın sonsuz kitabında ömrümün daha bir səhifəsi çevrildi. O səhifədə nə yazıldığını isə ən doğru bilən yalnız Tanrıdır.","İbrət: Hər yeni gün bizə verilən qiymətli bir əmanətdir. Günün sonunda onu necə keçirdiyimizi düşünmək sabahımızı daha mənalı yaşamağa kömək edər.","Etibar Siracsoy"]},{"stem":"free-time","title":"Boş vaxt","hasAudio":false,"hasImage":true,"paragraphs":["Bəziləri səninlə boş vaxtı olanda danışar, bəziləri isə səninlə danışmaq üçün vaxt ayırar.","İbrət: Vaxt geri qaytarılmayan sərvətdir. Səni dinləməyə və yanında olmağa könüllü vaxt ayıran insanın qədrini bil."]},{"stem":"its-pointless","title":"Boşunadır","hasAudio":false,"hasImage":true,"paragraphs":["Söz dinləməyənə nəsihət vermək, anlamaq istəməyənlə mübahisə etmək, ikiüzlü ilə dostluq qurmaq boşunadır.","İbrət: Vaxtını və etibarını kimə verdiyin həyatına təsir edir. Qarşılıqlı hörmət və səmimiyyət olmayan münasibətlərə sərf edilən ömür geri qayıtmır."]},{"stem":"cost-of-indifference","title":"Bu günlərdə etməsəm, dünya dağılmaz ki","hasAudio":false,"hasImage":true,"paragraphs":["Bir əməkdaşımızdan tapşırılan işin nə yerdə olduğunu soruşdum. Cavabı məni çox məyus etdi:","«Bu günlərdə etməsəm, dünya dağılmaz ki…»","Bir anlıq düşündüm: Bəli, dünya dağılmaz. Amma bəs bizim aramızdakı etibar? O da dağılmazmı? Bu münasibət əməkdaşlığımıza, qarşılıqlı hörmətimizə və gördüyümüz ümumi işə zərər vurmazmı?","Məsələ tapşırığın bir neçə gün gecikməsi deyildi. Məsələ insanın üzərinə götürdüyü öhdəliyə münasibəti idi. Çünki məsuliyyət təkcə işi görmək deyil, verilən sözə sahib çıxmaq, qarşı tərəfin etimadını doğrultmaq və insanların sənə arxalana bilməsini təmin etməkdir.","Düşünürəm ki, üzərinə götürdüyün hər hansı bir öhdəliyə bu cür məsuliyyətsiz yanaşmaq doğru deyil. Daha da təəssüf doğuran isə bu yanaşmanın ifadə tərzi idi. Mənə görə, belə bir cavab ən azı kobud səslənir və qarşı tərəfin vaxtına, əməyinə və etimadına yetərincə dəyər verilmədiyini göstərir.","Etiraf edim ki, bu sözlər qəlbimi sındırdı. Həmin an anladım ki, əməkdaşlığımız əvvəlki kimi davam edə bilməyəcək. Çünki istənilən peşəkar münasibətin təməli etibardır. Etibar sarsıldıqda isə iş birliyi də ciddi sınaq qarşısında qalır.","Məni daha çox məyus edən isə odur ki, həmkarım nə dediyi sözün yanlışlığını anladı, nə buna görə üzr istədi, nə də tapşırığı yerinə yetirdi. Ona olan etimadım sarsıldığı üçün problemi başqa yolla həll etməyə məcbur oldum.","Bu hadisə mənə bir daha göstərdi ki, təşkilatlarda ən qiymətli resurs nə vaxtdır, nə puldur, nə də texnologiya. Ən qiymətli resurs insanların bir-birinə olan etimadıdır. Etimadı qazanmaq illər tələb edə bilər, onu itirmək isə bəzən cəmi bir cümlə ilə mümkündür.","İbrət: Etimad təşkilatın ən qiymətli sərvətidir. Onu qazanmaq illər çəkir, itirməyə isə bir cümlə kifayət edir. Sözünün üstündə duran insan bu sərvəti qoruyur.","Bəxtiyar Siracov"]},{"stem":"empty-boat","title":"Bu qayıq da boşdur","hasAudio":false,"hasImage":true,"paragraphs":["Ustadım belə danışardı:","«Gəncliyimdə tez-tez gölə gedər, təkliyə çəkilib düşüncələrə dalardım. Kiçik bir qayığım vardı. Saatlarla göldə üzər, o sakitlikdə hüzur tapardım.","Bir səhər dan yeri yenicə söküləndə yenə qayığımda oturmuş, gözlərimi yumub düşüncələrə dalmışdım.","Birdən başqa bir qayıq qayığıma çırpıldı. Diksinib özümə gəldim, içimi qəzəb bürüdü. Qayığın sahibinə acıqlanmaq üçün gözlərimi açdım. Amma qarşımda boş bir qayıq vardı.","Hirsimi tökəcəyim heç kim yox idi.","Gözlərimi yenidən yumdum. Bir az əvvəl məni bu qədər qəzəbləndirən toqquşma indi əvvəlki kimi görünmürdü: heç kim bunu qəsdən etməmişdi. Günəş doğanda könlüm də sakitləşmişdi.","O boş qayıq mənə unudulmaz bir dərs verdi. O gündən bəri kimsə məni incidəndə öz-özümə deyirəm:","— Bu qayıq da boşdur».","İbrət: Hər xoşagəlməz hadisənin arxasında pis niyyət axtarma. Nə baş verdiyini anlamaq üçün özünə bir anlıq vaxt vermək qəzəbə qapılmadan cavab verməyə kömək edir."]},{"stem":"where-does-this-road-go","title":"Bu yol haraya gedir?","hasAudio":false,"hasImage":true,"paragraphs":["Yolla gedən bir gənc yol kənarında oturmuş yaşlı bir kişiyə rast gəlir və soruşur:","— Dayı, bu yol haraya gedir?","— Heç yerə, oğlum.","— Necə yəni? Heç yerə getməyən yol olar?","— Vallah, əlli ildir buradayam. Bu yol o vaxt harada idisə, indi də elə oradadır. Gedib-gələn insanlardır.","İbrət: Yol öz-özünə səni heç yerə aparmaz. Hara getmək istədiyini müəyyən edən də, o yolda addımlayan da sənsən."]},{"stem":"liver","title":"Ciyər","hasAudio":false,"hasImage":true,"paragraphs":["Niyə çox yaxın dostumuza «can-ciyər», əziz övladımıza «ciyərguşəm», sevdiyimiz insana «ciyərparəm» deyirik? Niyə «ağciyər» sözü məcazi mənada qorxaq adamı bildirir?","Dilimizdə «ciyər» təkcə orqan adı deyil; doğmalığı, sevgini, ağrını və insanın xarakterini ifadə edən sözlərin də tərkibində yaşayır.","Bu təsəvvürlərin qədim mədəniyyətlərdə bənzərləri var. Mesopotamiyada qaraciyər həyatın, ruhun və duyğuların yerləşdiyi mühüm orqan sayılırdı. Qədim insanlar insanın daxili aləmini izah edərkən təkcə ürəyə deyil, qaraciyərə də xüsusi məna verirdilər.","Lakin ayrı-ayrı dillərdəki bütün «ciyər» ifadələrini eyni inancla izah etmək olmaz. Hər ifadənin öz yaranma və inkişaf yolu var.","Bu gün «ciyərparəm» deyəndə anatomiyanı düşünmürük. Qarşımızdakı insanın bizə öz canımızın bir parçası qədər əziz olduğunu bildiririk. Sözün gücü də elə bundadır: bədənə aid bir anlayış ən dərin duyğuların ifadəsinə çevrilir.","İbrət: Dil yalnız fikirlərimizi deyil, keçmişin təsəvvürlərini də yaşadır. Gündəlik işlətdiyimiz bir sözün içində nəsillərin sevgisi, ağrısı və dünyagörüşü gizlənə bilər."]},{"stem":"sharpen-the-axe","title":"Daha səmərəli yol","hasAudio":false,"hasImage":true,"paragraphs":["Meşədən keçən bir ovçu qəribə mənzərə ilə qarşılaşır. Bir odunçu ağacı kəsmək üçün var gücü ilə balta vurur, amma iş irəliləmir. Alnından tər süzülür, hər zərbə ona böyük zəhmət bahasına başa gəlir.","Ovçu yaxınlaşıb deyir:","— Baltanız lap kütləşib. Bəlkə, bir az dayanıb itiləyəsiniz? İşiniz də yüngülləşər.","Odunçu təəccüblə ona baxır:","— Nə danışırsınız? Baltanı itiləməyə vaxtım haradadır? Hələ kəsəcəyim iyirmi ağac da var!","İbrət: Səmərəli işləmək yalnız çox çalışmaq deyil, işin yolunu da düşünməkdir. Hazırlığa və aləti təkmilləşdirməyə ayrılan vaxt itki deyil; sonrakı zəhməti azaldan qazancdır."]},{"stem":"draining-the-coffers","title":"Dibinə darı əkmək","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün padşah əyanları ilə gəzintiyə çıxmışdı. Yolları bir kənddən keçəndə tarlasında fidan əkən yaşlı bir kişiyə rast gəldilər. Padşah ona səsləndi:","— Baba, bu yaşında niyə özünə belə zəhmət verirsən? Maşallah, uzun ömür sürmüsən. Amma bu fidanlar böyüyüb bar verənədək, bəlkə, ömrün çatmayacaq.","İxtiyar cavab verdi:","— Bu ağacların meyvəsini mütləq özümüz yeməli deyilik, övladım. Bizdən əvvəlkilər əkiblər, biz yemişik. İndi də biz əkək, bizdən sonrakılar yesinlər.","Cavab padşahın xoşuna gəldi. İxtiyara bir kisə qızıl verilməsini əmr etdi.","Qoca qızıl kisəsini göstərib gülümsədi:","— Gördünmü, övladım? Bizim fidanlar elə indidən bar verdi.","Padşah bu sözü də bəyənib ona ikinci kisə qızılın verilməsini buyurdu.","Dünyagörmüş kəndli sözünün ardını gətirdi:","— Başqalarının ağacı ildə bir dəfə bar verir, bizimki isə bir gündə iki dəfə bar verdi!","Padşah gülüb üçüncü kisə qızılın da verilməsini əmr etdi. Bu dəfə vəzir tələsik araya girdi:","— Aman, padşahım, gedək buradan! Belə getsə, bu qoca tarlasına fidan əkmək əvəzinə xəzinəmizin dibinə darı əkəcək!","İbrət: Əkdiyin hər ağacın meyvəsini özün yeməyə bilərsən. Amma başqalarının zəhmətindən bəhrələndiyin kimi, sən də gələcək nəsillərə bir yaxşılıq qoymalısan."]},{"stem":"diderot-effect","title":"Didro effekti","hasAudio":false,"hasImage":true,"paragraphs":["XVIII əsr fransız filosofu və yazıçısı Deni Didro “Köhnə xalatımdan ayrılmağıma təəssüf” essesində bir əşyanın insanı necə yeni xərclərə sürükləyə bildiyini təsvir edir.","Hər şey dəbdəbəli qırmızı bir xalatla başlayır.","Didro yeni xalatını geyinəndə əvvəllər rahatlıq tapdığı otaq gözünə başqa cür görünür. Köhnə əşyaların heç biri dəyişməyib, amma indi onlar bu gözəl xalatın yanında sönük və yaraşıqsız görünür.","Bir vaxtlar ona kifayət edən sadə əşyalar artıq ürəyincə deyil.","Beləcə, bir dəyişiklik o birini ardınca gətirir. Sadə stulun yerini dəri kreslo tutur. Kitabların düzüldüyü taxta rəf bəzəkli şkafla əvəz olunur. Divarlardakı təsvirlər, otağın bəzəkləri yenilənir. Axırda köhnə iş masası da yerini bahalı yazı masasına verir.","Otaq gözəlləşir, amma Didronun rahatlığı azalır. Yeni xalat təkcə geyimini deyil, ətrafındakı hər şeyə münasibətini dəyişib. Əvvəllər ehtiyac duymadığı əşyalar indi ona zəruri görünür.","Didro bu vəziyyəti belə ifadə edir:","— Köhnə xalatımın ağası idim, yenisinin isə köləsi oldum.","O, köhnə xalçasını saxlamağa qərar verir. Qoy bu sadə əşya ona əvvəlki həyatını xatırlatsın, dəbdəbənin içində özünü unutmağa qoymasın.","Bir yeni əşyanın ardınca ona uyğun başqa əşyalar almaq istəyinin yaranması bu gün “Didro effekti” adlanır. Bəzən aldığımız bir şey ehtiyacımızı ödəməklə kifayətlənmir, əvvəllər olmayan yeni ehtiyaclar da yaradır.","İbrət: Hər yenilik həyatındakı hər şeyi dəyişməyi tələb etmir. Nəsə almazdan əvvəl özündən soruş: “Buna həqiqətən ehtiyacım var, yoxsa başqa bir əşyaya uyğun olsun deyə istəyirəm?” Əşyalar həyatını rahatlaşdırsın, seçimlərini idarə etməsin."]},{"stem":"place-in-loving-hearts","title":"Dünyada ən gözəl yerlər","hasAudio":false,"hasImage":true,"paragraphs":["Dünyanın ən gözəl yerləri sevdiklərinin düşüncələrində, dualarında və qəlbində sənə ayrılan yerlərdir.","İbrət: Ən gözəl yer həmişə xəritədə olmur. Sevgi ilə xatırlanmaq, bir duada anılmaq, bir qəlbdə əziz tutulmaq insana doğmalıq və hüzur bəxş edir."]},{"stem":"reflections","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/reflections.webp","title":"Düşüncələr","hasAudio":false,"hasImage":true,"paragraphs":["Əl-qolun boşalar, könlün danışmaz","Həyatın sonudur — düşünəndə sən!","Belə fikirlərlə yaşamaq olmaz,","Dünyanın ən gözəl nemətisən sən!","Ömür vəfasızdır, dünya da fani","Gəlişin zamanlı, gedişin ani —","Bu cür düşüncələr üzərlər səni","Gözəl dünyamızın xilqətisən sən!","Eşqdir mehrabı uca göylərin,","Eşqsiz, ey dünya, nədir dəyərin? —","Deyib bir zamanlar böyük Nizami,","Böyük məhəbbətin ürəyisən sən!","Əzəldən belədir dünyanın işi","Sınaqdır həyatda insanın işi","Uzaq tut qəlbindən qəmi, təşvişi","Səni sevənlərin ümidisən sən!","Ev qurub, övladlar böyütdünsə sən","Bir ağac əkərək suvardınsa sən","Çox savab işlərdə çalışdınsa sən","Demək, arzuların əməlisən sən,","Həyatın, varlığın özəyisən sən!","Etibaram, sözüm olsa deyərəm,","Ürəyimi sətirlərə düzərəm,","Şükür edər, el-obamı sevərəm,","Dostlarımla heç zaman yenilmərəm!","Etibar Siracsoy"]},{"stem":"different-path","title":"Fərqli yol","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün bir inək tövləsinə qayıdarkən cığırı olmayan meşədən keçməli oldu. Gah yoxuşa qalxdı, gah enişə düşdü, ağacların və kolların arasından dolana-dolana özünə əyri-üyrü bir cığır açdı.","Ertəsi gün bir it meşənin o biri tərəfinə keçmək üçün həmin cığırla getdi. Ardınca bir qoyun sürüsü gəldi. Çoban hazır cığırı görüb başqa yol axtarmadı, sürünü də oradan apardı.","Çox keçmədi ki, insanlar da bu cığırdan istifadə etməyə başladılar. Gah sağa, gah sola dönür, budaqların altından əyilib keçir, yolun çətinliyindən gileylənirdilər. Amma heç kim dayanıb soruşmurdu:","— Bəlkə, daha rahat bir yol var?","Ayaqlar altında genişlənən cığır zamanla yola çevrildi. Daha düz istiqamət seçsəydilər, yarım saata çata biləcəkləri yerə insanlar və yük heyvanları üç saata gedib çıxırdılar. Yenə də hamı əvvəlkilərin izi ilə gedirdi.","İllər keçdi. Meşənin yerində şəhər böyüdü. Köhnə yol əvvəlcə əsas gediş-gəliş yoluna, sonra şəhərin ən işlək küçəsinə çevrildi. İnəyin ağacların arasından dolanaraq açdığı döngələr olduğu kimi qaldı.","İndi həmin döngələrdə maşınlar sıxışıb qalırdı. Hamı tıxacdan şikayətlənir, amma az adam yolun niyə belə salındığını düşünürdü.","Şəhərin kənarında qalan qoca meşə isə sanki pıçıldayırdı:","— Bir inəyin təsadüfi addımları neçə nəslin yolunu müəyyən etdi…","İbrət: Bir yoldan çoxdan istifadə olunması onun ən yaxşı yol olduğunu göstərmir. Vərdişi davam etdirməzdən əvvəl səbəbini anlamağa çalış. Bəzən irəliləmək üçün addımlarını sürətləndirmək yox, getdiyin yolu dəyişmək lazımdır."]},{"stem":"before-it-is-too-late","title":"Gecikmək nə deməkdir?","hasAudio":false,"hasImage":true,"paragraphs":["Gecikmək bir işi vaxtında görməməkdir. İnsanlarla münasibətdə isə gecikməyin bədəli bəzən daha ağır olur.","Sevgimizi bildirməyin, bizə göstərilən sevgiyə könlümüzü açmağın, qəlbimizi qıranları bağışlamağın, incitdiklərimizdən üzr istəməyin öz vaxtı var. Bunları sonraya saxladıqca aramızdakı məsafə böyüyə, fürsət əldən çıxa bilər.","İnsanı səhvdən sığortalamaq olmaz. Hər birimiz yanılar, düşünmədən söz deyər, kiminsə xətrinə dəyə bilərik. Əsas odur ki, səhvimizi etiraf etməkdə, onu düzəltməkdə və könül almaqda gecikməyək. Həyat qısadır.","Elə yaşamağa çalışaq ki, geriyə baxanda «kaş ki»lərdən çox «nə yaxşı ki»lər deyək. Sevgiyə, barışığa və ədalətə bu gün yer ayıraq ki, sabah peşmanlığa daha az yer qalsın.","İbrət: Sevgini bildirməyi, üzr istəməyi, könül almağı sonraya saxlama. Vaxtında atılan səmimi bir addım sabahkı peşmanlığın qarşısını ala bilər."]},{"stem":"seeing-without-understanding","title":"Gözləri olan korlar","hasAudio":false,"hasImage":true,"paragraphs":["Dünyada elə insanlar var ki, gözləri açıq olduğu üçün hər şeyi gördüklərini sanırlar. Halbuki baxdıqlarının mənasını, yanlarından keçənlərin dərdini, qarşılarında duran həqiqəti görmürlər.","İbrət: Görmək üçün təkcə göz yox, diqqət, düşüncə və duyarlı qəlb də lazımdır. Əsl görmək baxdığını anlamaq, sezə bildiyin dərdə biganə qalmamaqdır."]},{"stem":"flowers","title":"Güllər","hasAudio":false,"hasImage":true,"paragraphs":["Gözəl təbiətin, bağça, bağların","Həyatın bəzəyi, rəmzidir güllər!","Gül gülü çağırar, bülbül bülbülü","Bülbülün nəfəsi, səsidir güllər.","Necə də canlıdır, necə gözəldir","Zəriflik libası onda əzəldir","Sevən ürəklərçin sanki özəldir","Verməz hər adama qoxusun güllər.","Bəzən utancaqlıq rəmzi olar o,","Bəzən etirafa işıq saçar o.","Bəzən də birlik və dostluq olar o","Sadiqlik, səadət rəmzidir güllər.","Nərgizin mənası bahar, günəşdir.","Ağ gülü sevənin qəlbi təmizdir.","Dərməyə qıymırsan, çünki nəfisdir,","İncə ürəklərin bəhəri güllər!","Saralıb solanda bağda güllərim","Başlayar kədərli, qəmli günlərim","Var olun, solmayın, gözəl güllərim,","Bir daha dərmərəm sizi, güllərim!","Etibar Siracsoy"]},{"stem":"price-of-belonging","title":"Çoxluq həmişə haqlı deyil","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün nurani bir kişiyə göylərdən xəbər gəlir:","— Ey insan, sabahdan suların dadı dəyişəcək. O sudan içən hər kəs ağlını itirəcək.","Kişi tələsik evinə qayıdır, əlinə keçən bütün küpləri, qabları su ilə doldurur.","Səhəri gün deyilənlər gerçək olur: sudan içənlər bir-bir ağlını itirməyə başlayırlar. Kişi isə yalnız ehtiyat üçün topladığı sudan içir.","Beləcə, bir-iki həftə keçir. Təklikdən bezən kişi evdən çıxıb insanların arasına qarışır. Amma kiminlə bir-iki kəlmə danışırsa, ona lağ edirlər:","— Sən dəli olmusan? Get, yerin dəlixanadır!","Kişi heç kimə sözünü başa sala bilmir. Axırda bu təzyiqə dözməyib evinə qayıdır, su dolu küpləri, qabları sındırır. Sonra gedib hamının içdiyi çeşmədən su içir və yatmağa uzanır.","İbrət: Çoxluğun razılığı yanlış olanı doğru etmir. İnsan bəzən qəbul olunmaq üçün öz ağlından və inandığı həqiqətdən vazkeçir. Əsl sınaq hamıya bənzəmək deyil, təzyiq qarşısında müstəqil düşüncəni qorumaqdır."]},{"stem":"doctors-office","title":"Həkim qəbulunda","hasAudio":false,"hasImage":true,"paragraphs":["Həkim qəbulunda növbəmi gözləyirdim. Səhər evdə yemək yeməyə vaxt tapmadığım üçün bufetdən bir sendviç və alma şirəsi almışdım.","Yeməyə başlayanda pəncərənin yanında oturan bir oğlanın mənə baxdığını gördüm. Gözlərini əlimdəki yeməkdən çəkmirdi. “Yəqin, acdır”, — deyə düşündüm.","Ürəyim dözmədi. Bufetə qayıdıb ona da sendviçlə şirə aldım. Uşaq təşəkkür edib iştahla yeməyə başladı. Mən isə kiməsə kömək etdiyimi düşünüb sevindim.","Elə bu vaxt anası qeydiyyat otağından çıxdı. Oğlunun əlindəki yeməyi görüb təlaşla yaxınlaşdı:","— Yeməyi siz vermisiniz?","Başımı tərpətdim.","— Həkim demişdi ki, müayinəyə acqarına gəlməlidir… İşdən icazə almışam, uzaqdan gəlmişik. İndi müayinəni başqa günə keçirməli ola bilərik.","Qadının gözləri doldu. Nə deyəcəyimi bilmədim. Bir an əvvəl yaxşılıq etdiyimə əmin idim. İndi isə başa düşürdüm ki, uşağın niyə ac olduğunu heç soruşmamışdım.","— Bağışlayın… Kömək etmək istədim, amma əvvəlcə sizdən soruşmalıydım.","Əlimdə yarımçıq sendviçlə oturub qaldım. Uşağın baxışlarını görmüşdüm, amma vəziyyətini anlamadan qərar vermişdim.","İbrət: Yaxşı niyyət hər zaman yaxşı nəticəyə zəmanət vermir. Kömək etməzdən əvvəl soruşmaq, dinləmək və vəziyyəti anlamaq da mərhəmətin bir hissəsidir."]},{"stem":"light-of-the-world","title":"Həyat dərsi","hasAudio":false,"hasImage":true,"paragraphs":["Ata qurd balasına həyatı öyrədərkən qoyunları göstərib deyir:","— Bax, onların əti dadlı olur.","Sonra çobanı göstərir:","— Onun dəyənəyi isə acı olur. Ehtiyatlı ol.","Bala qurd çobanın yanındakı iti görüb sevinclə deyir:","— Ata, bax, o bizə oxşayır!","Ata qurd cavab verir:","— Onu görən kimi qaç, balam. Biz ən çox bizə oxşayan, amma bizdən olmayanlardan zərər çəkmişik.","İbrət: Bəzən ən böyük zərəri bizə oxşayan, amma niyyəti başqa olanlardan görürük. Özünü qorumaq üçün zahiri bənzərliyə aldanmamaq, ikiüzlülüyü vaxtında sezmək lazımdır."]},{"stem":"what-matters-in-life","title":"Həyatda önəmli olan nədir?","hasAudio":false,"hasImage":true,"paragraphs":["Müəllim sinfə girib şagirdləri salamlayır. Çantasından bir şüşə banka çıxarıb masanın üstünə qoyur və deyir:","— Hər birimizin bir ömrü var. Vaxtımızı nəyə ayırmağımız həyatımızda nəyə yer verdiyimizi müəyyən edir.","Sonra bankanı qolf topları ilə doldurub soruşur:","— Sizcə, banka doludurmu?","— Doludur! — deyə şagirdlər bir ağızdan cavab verirlər.","Müəllim çantasından bir qədər çınqıl çıxarıb bankaya tökür. Bankanı yüngülcə silkələyir, daşlar topların arasındakı boşluqlara dolur.","— Bəs indi, banka doludurmu?","— Bəli! — deyə şagirdlər cavab verirlər.","Müəllim bu dəfə bankaya qum tökür. Qum daşların arasında qalan boşluqları doldurur.","— İndi necə?","Şagirdlər yenə bankanın dolu olduğunu söyləyirlər.","Müəllim gördüklərinin mənasını belə izah edir:","— Bu banka sizin həyatınızdır. Qolf topları ən qiymətli olanları təmsil edir: ailənizi, dostlarınızı, sevdiklərinizi və sağlamlığınızı.","Çınqıl daşları işiniz, eviniz, mal-mülkünüz kimi digər vacib şeylərdir.","Qum isə gündəlik xırda işlər, o qədər də əhəmiyyətli olmayan qayğılardır.","Bankanı əvvəlcə qumla doldursaydım, nə toplara, nə də daşlara yer qalardı. Həyat da belədir. Bütün vaxtınızı və gücünüzü xırda işlərə sərf etsəniz, sizin üçün ən qiymətli olanlara yer qalmayacaq.","Əvvəlcə həyatınızın «qolf topları»nı müəyyən edin və onlara yer ayırın. Qalanlarını sonra yerləşdirərsiniz.","İbrət: Ən qiymətli olanlara vaxt qalmırsa, bəzən vaxtı deyil, seçimlərini yenidən nəzərdən keçirmək lazımdır. Ailəni, sevgini və sağlamlığı xırda qayğıların arxasında qoyma."]},{"stem":"lifes-lessons","title":"Həyatda öyrəndiklərimiz","hasAudio":false,"hasImage":true,"paragraphs":["Bu həyatda daim öyrənirik:","kimindən səbirli olmağı, sevməyi, sədaqətli və vəfalı qalmağı, ləyaqətlə davranmağı;","kimindən isə ikiüzlülüyü, saxtakarlığı, xəbisliyi və xəyanəti tanımağı.","İbrət: Qarşılaşdığımız insanlar bizə müxtəlif dərslər verir: kimisi necə insan olmağı, kimisi isə necə olmamağı öyrədir. Əsas olan bu dərslərdən doğru nəticə çıxarmaqdır."]},{"stem":"hayats-life-story","title":"Həyatın həyat hekayəsi","hasAudio":false,"hasImage":true,"paragraphs":["Anam evdən gedəndə mənim altı, qardaşımın səkkiz yaşı vardı. O yaşımda belə atamdan niyə ayrıldığını anlayırdım. Amma bizi niyə özü ilə aparmadığını anlaya bilmirdim.","Uşaq ağlımla dönə-dönə eyni sualı verirdim: ana da balalarını qoyub gedərmi?","Atam anamı döyürdü. Məni də, qardaşımı da. Elə bilirdim, bütün kişilər belədir; bütün evlərdə qadınlar və uşaqlar döyülür.","Anam gedəndən sonra evimizin dörd divardan ibarət olduğunu hiss etdim. Səhərlər «Əl-üzünüzü yuyun, yeməyiniz hazırdır» deyən yox idi. Ac qalsaq, «Nəsə yemisiniz?» deyə soruşan da yox idi.","Öyrəndiyim ən ağır dərs isə bu oldu: bəzən uşağın böyüməsi üçün illər lazım deyil. Özünü tək hiss etdiyi bir gün bəs edir. Mən altı yaşımda böyüdüm.","Anamın gedişindən təxminən on gün sonra evimizə polis gəldi. Dedilər ki, anam öz həyatına son qoyub. Ondan bir məktub qalmışdı. Zərfin üstündə «Qızıma və oğluma verilsin» yazılmışdı.","Mən hələ oxumağı bilmirdim. Məktubu qardaşım oxudu. O oxuduqca ikimiz də ağladıq.","Anamın o on gündə nələr yaşadığını isə çox sonralar öyrəndim. On doqquz yaşım olanda nənəm ölüm yatağında mənə danışdı.","Anam ata evinə sığınmışdı. Babam isə onu qəbul etmək istəməmişdi. Onun düşüncəsinə görə, qadın nə olursa olsun ər evində qalmalı idi; ağzı qanla dolsa da, «Qırmızı şərbət içmişəm» deməli idi.","Anam yalvarmışdı:","— Bir ay burada qalım. Bir çarə taparam, uşaqlarımı yanıma alıb özümə həyat quraram.","Babam üçün isə qızının çəkdiyi əzabdan çox, camaatın nə deyəcəyi vacib imiş. Qızının ayrılıb tək yaşamasını ailənin namusuna ləkə saymışdı. Hətta «Ölsən, bundan yaxşıdır» demişdi.","Anam həmin axşam həyatına son qoymuşdu.","Atam ölüm xəbərini eşidəndə kədərləndiyini görmədik. Bizi uşaq evinə verəcəyini söylədi. Bundan sonra evimiz ora olacaqdı.","Qardaşımla ayrılacağımızdan qorxurduq. Elə bilirdik, ayrı düşsək, bir gün bir-birimizi unudarıq. Anamın məktubu hər ikimizdə qalmalı idi.","Amma bir məktubu iki yerə necə aparacaqdıq?","Qardaşım qayçı götürüb vərəqi ortadan kəsdi. Cümlələrin əvvəli olan yarısını mənə verdi. Dedi ki, oxumağı öyrənəndə davamını özüm düşünərəm. O isə məktubu artıq əzbər bilirdi.","Xalam bizi uşaq evinə verəcəklərini eşidib gəldi:","— Qız uşağını ora göndərmək olmaz. Həyatı mən götürərəm.","Mənə elə gəldi ki, nəhayət, bir evim olacaq. Amma xalamgilə köçəndən sonra başqa bir şey öyrəndim: onun gözündə mən qayğıya ehtiyacı olan uşaqdan çox, evin işlərini görəcək bir cüt əl idim.","Adımı demək olar ki, eşitmirdim. Mənə «Astagəl» deyirdi:","— Astagəl, su gətir!","— Astagəl, qabları yu!","Qardaşım ayda bir dəfə yanıma gəlirdi. Uşaq evində yaxşı olduğunu deyirdi. Mən də «Mən də yaxşıyam» deyirdim. Onu üzmək istəmirdim.","Görəsən, o da məni üzməmək üçün belə deyirdi?","Bunu soruşmağa cəsarət etmirdim.","Məktəbə başlayanda sinifdə oxumağı ilk öyrənən mən oldum. Axı məni anamın məktubu gözləyirdi.","Məndə qalan hissə belə başlayırdı:","«Həyat, gözəl qızım, mən səni...»","Hər gecə o yarımçıq cümləni başqa cür tamamlayırdım:","«...çox sevirəm.»","«...yenidən qucaqlamaq istəyirəm.»","«...gözləyirəm.»","Sonra yazılmamış sözlərdən özümə bir dünya qururdum. Orada anam vardı. Mən tək deyildim. Heç kim mənə qışqırmırdı.","Gerçək həyat kifayət qədər ağrılı idi. Xəyallarımda heç olmasa xoşbəxt ola bilərdim.","On beş yaşımda xalam dedi ki, məktəb bəsdir. Amma mən oxumaq istəyirdim. Bir peşəm olsun, öz ayağım üstündə dayanım, qardaşımla bir evdə yaşayım istəyirdim.","Həmin yay məhəllə baqqalı Həsən əminin arvadı xərçəngdən vəfat etdi. Üç balası qaldı: altı yaşlı Sami, beş yaşlı Elif, iki yaşlı Zəhra.","Onları düşünüb ağlayırdım. Görəsən, onlar da analarının qoxusunu axtaracaqdılar? Onların da adlarını unudub «Astagəl» deyəcəkdilər?","Mən uşaqların dərdini çəkərkən böyüklər mənim taleyimi həll edirmişlər.","Bir gün bildim ki, məni Həsən əmiyə verirlər. Səkkiz bilərzik və üç min lirə müqabilində.","Rəsmi nikaha yaşım çatmırdı. Qırx gün sonra kəbinimizi kəsdilər.","On beş yaşım vardı. Mən hələ uşaq idim, amma məndən bir kişinin arvadı, üç uşağın anası olmağımı gözləyirdilər.","Xalam üstəlik tələsdirirdi:","— Öz uşağın da olsun ki, bu evdə yerin möhkəmlənsin.","Həsən əmidən ilk şilləni ona «Həsən əmi» dediyim üçün aldım.","— Arvad ərinə əmi deyər?","Mən susdum. Susmağı çoxdan öyrənmişdim.","«Bəs böyük bir kişi on beş yaşlı uşağa arvad deyərmi?» sualı içimdə qaldı.","Üç uşaq atalarının ayaqlarına sarıldı:","— Həyat bacını vurma! O bizimlə oynayır, bizə nağıl danışır!","Onlar məni ana yox, böyük bacı bilirdilər. Mənim onlara danışdığım nağıllar isə öz xəyallarım idi.","Həsən əmi evdən çıxandan sonra güzgünün qarşısına keçdim. Ona sadəcə «Həsən» deməyə çalışdım. Amma dilim dönmürdü. Qarşımda ərimi deyil, həmişə «əmi» dediyim adamı görürdüm.","Altı yaşlı Sami yanıma gəldi:","— Həyat bacı, anam atama «bəy» deyirdi. Sən də elə de.","Əyilib onu öpdüm. «Bəy» deyə bilərdim.","Eliflə Zəhranı da çağırıb yanıma oturtdum. O gün yeni bir nağıla başladım:","— Biri varmış, biri yoxmuş. Nağıl adlı altı yaşlı bir qız varmış. Anasını itirib hər yerdə axtarıbmış. Tapa bilməyəndə xəyallar ölkəsinə gedibmiş. Orada heç kim onu incitmirmiş, heç kim tək qoymurmuş...","Nağıl mənim danışdıqlarımda həmişə gülümsəyirdi. Hər gün onun həyatına bir az da sevinc əlavə edirdim. Uşaqlar dinləyir, mən danışırdım. O anlarda hamımız nəfəs alırdıq.","Həsən əmiyə artıq «bəy» deyirdim. Sakit günlərimiz də olurdu, onun hirsləndiyi günlər də. İllərlə onun qəzəbinə səbəb axtardım, hətta günahı özümdə gördüm: o, evinə arvad gətirdiyini düşünmüşdü, mən isə uşaqlarla oynayan, onlara nağıl danışan bir qız idim.","Halbuki uşaq olmağım mənim günahım deyildi.","Qardaşım yanıma gəlməyə davam edirdi. Hər dəfə məktubun özündəki yarısını mənə vermək istəyirdi. Mən götürmürdüm.","O yarını oxumaqdan qorxurdum. İllərlə boş qalan sətirlərə ümidlərimi yazmışdım. Gerçək sözləri bilsəydim, qurduğum dünya dağılar deyə düşünürdüm.","Qırx yaşıma çatanda nağıllarımı dinləyən uşaqlar böyümüşdülər.","Sami həkim olmuş, başqa şəhərə köçmüşdü. Kədərli olanda zəng edirdi:","— Həyat bacı, mənə bir nağıl danış.","Elif müəllim oldu, ailə qurdu. Qızı doğulanda adını Həyat qoymaq istədi. Razı olmadım.","— Onda Nağıl olsun, — dedi.","Beləcə, nəvəmin adı Nağıl oldu.","Zəhra baytar oldu. Gülə-gülə deyirdi:","— Həyat bacı, qorxan heyvanlara nağıl danışıram. Səsimi eşidib sakitləşirlər.","O da ailə qurdu. Bir oğlan nəvəm də oldu.","Mənim qırx beş yaşım olanda Həsən əmi — illərlə «bəy» dediyim adam — vəfat etdi. Kədərləndim. Son sözləri bunlar oldu:","— Haqqını halal et.","Mən onu ürəkdən bağışladım. Birlikdə keçirdiyimiz illərdə yaxşılığını da görmüşdüm. Amma onu bağışlamağım uşaqlığımda mənə edilənlərə haqq qazandırmırdı.","Haqqımı isə on beş yaşlı qızların evləndirilməsini adi sayanlara;","zorakılıq içində yaşayan qızlarına sığınacaq verməyib «namus» naminə geri göndərənlərə;","çarəsiz uşağın kömək istəyini eşitməyənlərə və bütün bunlara haqq qazandıranlara halal etmirəm.","Çünki mənim adım Həyat idi.","Amma öz həyatımı seçməyə uzun illər haqqım olmadı.","İbrət: Heç bir adət, heç bir «namus» anlayışı zorakılığa və uşağın taleyinin əlindən alınmasına haqq qazandıra bilməz. Uşağın yeri məcburi nikahda deyil, təhlükəsiz evdə və məktəbdədir. Kömək istəyən insanı qınamaq yox, qorumaq lazımdır."]},{"stem":"two-bowls-of-water","title":"İki qab su","hasAudio":false,"hasImage":true,"paragraphs":["Qədim zamanlarda var-dövləti ilə məşhur bir hökmdar yaşayırdı. Getdiyi hər yerə xəzinəsindən bir pay aparar, sərvətini nümayiş etdirməkdən zövq alardı.","Onun çox güvəndiyi müdrik bir müəllimi vardı. Bir gün hökmdar ondan soruşdu:","— Sən dünyagörmüş adamsan. De görüm, mənim hakimiyyətim və sərvətim haqqında nə düşünürsən?","Müdrik cavab əvəzinə bir sual verdi:","— Təsəvvür edin ki, hökmdarım, qızmar, ucsuz-bucaqsız bir səhradasınız. Susuzluqdan ölmək üzrəsiniz. Sizi xilas edəcək bir qab suyun əvəzində sərvətinizin yarısını verərdinizmi?","— Əlbəttə, verərdim!","— Bəs yolunuz uzansa, suyunuz qurtarsa və yenidən susuzluqdan ölüm təhlükəsi ilə üzləşsəniz? İkinci qab su üçün qalan sərvətinizi də verərdinizmi?","Hökmdar bir an düşünüb dedi:","— Sağ qalmaq üçün, əlbəttə, verərdim.","Müdrik xəfifcə gülümsədi:","— Elə isə sərvətinizlə çox öyünməyin, hökmdarım. Görünür, elə bir məqam var ki, bütün var-dövlətiniz cəmi iki qab suya dəyər.","İbrət: Bəzən adi saydığımız bir nemət bütün sərvətimizdən qiymətli olur. Var-dövlətinlə öyünmə; həyatını mümkün edən sadə nemətlərin qədrini bil."]},{"stem":"human-being-emerged","title":"İnsan çıxdı","hasAudio":false,"hasImage":true,"paragraphs":["Düşüncəni qəlbə vurdum — sevgi alındı.","Sevginin üstünə əmək gəldim — vəfa alındı.","Çörəyi vicdanla böldüm — ədalət alındı.","Sevgini, əməyi, vicdanı, vəfanı və ədaləti topladım — insan alındı.","— Yaşar Kamala aid edilən sözlər","İbrət: İnsanı insan edən sevgi, əmək, vicdan, vəfa və ədalətdir. Bu dəyərləri təkcə dilə gətirəndə deyil, əməllərimizdə yaşadanda insanlığımız üzə çıxır."]},{"stem":"istanbul-woman-remembers","title":"Görünən və görünməyən həqiqət","hasAudio":false,"hasImage":true,"paragraphs":["İstanbulun işğal illərindən bəhs edən bir rəvayətdə bir qadının dilindən belə danışılır:","“Məktəbi yenicə bitirmişdim. Bir gün özünü vəkil kimi təqdim edən gənc ailəsi ilə bizə elçi gəldi. Onu bəyəndim, nişanlandıq. Zaman keçdikcə ona bağlandım.","Xoşbəxt bir ev quracağımızı düşünür, gecələr lampa işığında dəsmallar tikir, cehizimi hazırlayırdım.","Bir gün məhəllədə söz yayıldı:","— Ayişənin nişanlısı vəkil deyilmiş. Məscidin qabağında tabut daşıyırmış.","Sarsıldım. Atamla gedib uzaqdan baxdıq. Doğrudan da, başqaları ilə birlikdə tabut daşıyırdı.","Mənim üçün məsələ gördüyü iş deyildi; özünü başqa cür tanıtdığını, məni aldatdığını düşünürdüm. Ondan izahat istəyəndə isə hər şeyi danışa bilməyəcəyini söylədi. Susmasını yalanının etirafı saydım.","Nişanı qaytardıq.","Beş il keçdi. Ailə qurmuşdum, bir oğlum vardı. Bir gün şəhərdə onunla rastlaşdım. Uşağım da yanımda idi.","Məni görüb dayandı.","— Vaxtınız varsa, sizi çaya dəvət etmək istərdim, — dedi.","Razılaşdım. Yaxınlıqdakı iş yerinə getdik. Qapıdakı lövhədə onun adı, altında isə ‘vəkil’ sözü yazılmışdı.","İçəri keçəndə soruşdum:","— Deməli, doğrudan da vəkil idin?","— Bəli.","— Bəs o vaxt daşıdığın tabutlar?..","Bir an susdu, sonra sakitcə danışmağa başladı:","— Şəhər işğal altında idi. Silahları Anadoluya, müqavimət göstərənlərə çatdırmağa kömək edirdik. Bəzi tabutlarda mərhum yox, silah olurdu. Gördüyün iş bunun bir hissəsi idi.","Əlimdəki fincanı masaya qoydum.","— Niyə mənə demədin?","— Deyə bilməzdim. Tək öz həyatımı deyil, başqalarının həyatını da təhlükəyə atardım. Səni itirmək ağır idi. Amma sirri açmağa haqqım yox idi.","Nə deyəcəyimi bilmədim. İllər əvvəl gördüyüm mənzərə doğru idi. Ona verdiyim məna isə yanlış.”","İbrət: Gördüyün hadisə həqiqətin hamısı olmaya bilər. Hökm verməzdən əvvəl soruş, dinlə və bilmədiklərinin olduğunu unutma. Bəzən görünməyən bir fədakarlığı yanlış mühakimənin arxasında itiririk."]},{"stem":"never-lost","title":"İtib-batmaz","hasAudio":false,"hasImage":true,"paragraphs":["Ürəkdən edilən yaxşılıq, sevgi ilə yoğrulmuş davranış, səmimiyyətlə deyilmiş söz, ədəb-ərkanlı rəftar, məhəbbət dolu təbəssüm, haqq-ədalət uğrunda atılan addım, mənəvi dəyərlərə göstərilən ehtiram —","heç vaxt itib-batmaz. Başqalarının yolunu işıqlandırar, sənin də ömrünə nur, könlünə rahatlıq qatar.","İbrət: Səmimi sözün, xeyirxah əməlin izi qalır. Başqasının həyatına gətirdiyin işıq öz ömrünü də nurlandırır."]},{"stem":"learning-from-loss","title":"İtkidən də öyrənmək olar","hasAudio":false,"hasImage":true,"paragraphs":["Həyata yalnız itkilərin gözü ilə baxmayın. Qazandığınız uğurları da, uğursuzluqlardan öyrəndiklərinizi də görün. İstədiyiniz nəticəni əldə etməsəniz belə, qazandığınız təcrübə növbəti addımınıza yol göstərə bilər.","İbrət: Uğursuzluq bütün zəhmətinin hədər getməsi demək deyil. Yaşadıqlarından dərs çıxara bilirsənsə, yoluna daha təcrübəli davam edirsən."]},{"stem":"living-in-the-past","title":"Keçmişdə yaşamaq","hasAudio":false,"hasImage":true,"paragraphs":["Keçmişdə yaşamaq arxaya baxa-baxa yerimək kimidir. Gözün geridə qaldıqca qarşındakı maneələri görməz, büdrəyərsən. Nə arxada qalanları dəyişə bilərsən, nə də önündə açılan imkanları görə bilərsən.","İbrət: Keçmişdən dərs almaq yol göstərir, keçmişdə ilişib qalmaq isə irəliləməyə mane olur. Dünəni dəyişmək mümkün deyil, amma bu gün atacağın addımı seçmək sənin əlindədir."]},{"stem":"small-changes-great-value","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/small-changes-great-value.webp","title":"Kiçik yeniliklər, böyük dəyərlər...","hasAudio":false,"hasImage":true,"paragraphs":["Yeknəsək həyat insan ruhunu səssiz-səssiz yorur. Hər günün dünənkinin eynisi olması, eyni işlərin təkrarlanması, yaxud heç bir iş görmədən zamanın axıb getməsi insanın daxilində görünməz bir boşluq və mənəvi sıxıntı yaradır. Çünki ruh da həyat kimi hərəkət, dəyişiklik və yenilik istəyir.","Bəzən isə həyatımıza kiçik bir yenilik daxil olur və sanki içimizdə yeni bir pəncərə açılır. Adi günlər bir anda rənglənir, könlümüzdə xoş bir həyəcan, yaşamaq həvəsi və gözəl bir əhval yaranır. Əslində, həyatın gözəlliyi yalnız qarşımıza çıxan təsadüflərdə deyil, özümüzün həyatımıza nə qədər gözəllik və yenilik qata bilməyimizdədir.","İnsan öz həyatının yalnız seyrçisi olmamalıdır. Bəzən yeni bir yol seçmək, yeni bir insanla tanış olmaq, yeni bir yer görmək, öyrənmək, yaratmaq, sevdiyimiz bir işə vaxt ayırmaq kifayətdir ki, həyatın rəngi dəyişsin. Çünki yenilik həmişə böyük hadisə deyil; bəzən kiçik bir addım böyük bir ruh yüksəkliyinin başlanğıcı olur.","Həyat bizə verilmiş hazır bir səhifə deyil. Onun hər gününü özümüz yazırıq. Ona görə də ömrün səhifələrini təkrarlarla deyil, yeni duyğularla, yeni arzularla və gözəl xatirələrlə doldurmaq insanın öz əlindədir.","İbrət: Həyatımıza yenilik qatmaq üçün böyük dəyişikliklər gözləməyə ehtiyac yoxdur. Öyrənməyə və sevdiyimiz işlərə ayırdığımız azacıq vaxt belə günümüzə məna verə bilər.","Etibar Siracsoy"]},{"stem":"bookstore","title":"Kitab dükanında","hasAudio":false,"hasImage":true,"paragraphs":["Tibb universitetinin tələbəsi kitab evində uzun axtarışdan sonra lazım olan kitabı tapdı. Sevinc içində kitabı əlinə aldı, amma arxa üzündəki qiyməti görəndə təbəssümü dondu: pulu çatmırdı.","Məyusluğunu büruzə vermədən səhifələri çevirdi, müəllimin tapşırdığı bölməni tapdı. Satıcıların müştərilərlə məşğul olduğunu görüb bir kənarda oxumağa başladı. Bacardığı qədərini yadda saxladı, sonra kitabı yerinə qoyub sakitcə çıxdı.","Bir ay boyunca iki gündən bir dükanın yolunu tutdu. Rəflərin arasında dayanıb dərsini oxuyur, heç kimin diqqətini çəkmədiyini düşünürdü.","Buraxılış imtahanlarına bir həftə qalmış yenə gəldi. Amma bu dəfə kitab yerində yox idi. Rəfləri bir-bir axtardı. Kitabı tapmadıqca ürəyi sıxılırdı.","Əliboş çıxmaq istəyərkən satıcılardan biri onu səslədi:","— Gəl, əyləş. Sənə sözümüz var.","Sonra masanın altından həmin kitabı çıxarıb qarşısına qoydu:","— Bu yaxınlarda bir müştəri bunu almaq istəyirdi. Biz də sənin hələ oxuyub qurtarmadığını görüb kitabı kənara qoyduq. Gələndə burada rahatca oturub oxuyarsan.","Tələbə bir an nə deyəcəyini bilmədi. Diqqət çəkmədiyini sanırdı, halbuki kitab evinin işçiləri onun çətinliyini çoxdan görmüş, qüruruna toxunmadan kömək etmişdi.","İllər sonra həmin gənc həkim oldu. Kitab evində ona edilən yaxşılığı isə heç vaxt unutmadı: imkanı olmayan xəstələrdən pul almadı.","İbrət: İnsanın ləyaqətini qoruyaraq edilən yaxşılıq qəlbdə ömürlük iz qoyur. Bəzən birinə göstərdiyin qayğı onun əli ilə neçə-neçə insana çatır."]},{"stem":"dry-well","title":"Kor quyu","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün kəndlinin uzunqulağı suyu qurumuş köhnə bir quyuya düşdü. Heyvanın acı-acı anqırtısını eşidən sahibi qonşuları köməyə çağırdı.","Saatlarla onu quyudan çıxarmağa çalışdılar. Hərə bir yol təklif etdi, amma heç biri nəticə vermədi. Axırda ümidlərini itirib quyunu torpaqla doldurmağa qərar verdilər.","Hərəsi bir kürək götürüb quyuya torpaq tökməyə başladı. İlk kürək torpaq belinə düşəndə uzunqulaq daha bərkdən anqırdı. Bir qədər sonra isə səsi kəsildi.","Kəndli quyuya boylananda gördüyünə inanmadı: uzunqulaq belinə düşən hər kürək torpağı silkələyib ayaqlarının altına tökür, sonra da üstünə çıxırdı.","Torpaq töküldükcə heyvan bir az da yüksəlirdi. Onu basdırmaq üçün atılan torpaq ayaqlarının altında pilləyə çevrilirdi.","Nəhayət, uzunqulaq quyunun ağzına çatdı və hamının heyrətli baxışları altında sağ-salamat çölə çıxdı.","İbrət: Həyat bəzən üstünə ağır yük qoyar. Bacardıqca o yükün altında qalma: silkələn, özünə dayaq tap və bir addım da yüksəl. Bəzən səni çətinliyə salan şey çıxış yolunun bir hissəsinə çevrilə bilər."]},{"stem":"windmill-turning-without-wind","title":"Küləksiz havada fırlanan yel dəyirmanı","hasAudio":false,"hasImage":true,"paragraphs":["Küləksiz havada fırlanan yel dəyirmanının hökmən bir üfləyəni var.","İbrət: Görünən nəticənin görünməyən səbəbi ola bilər. Təkcə baş verənə baxma, onu hərəkətə gətirən səbəbi də anlamağa çalış."]},{"stem":"do-you-remember-me","title":"Müəllim, salam! Məni xatırladınız?","hasAudio":false,"hasImage":true,"paragraphs":["— Salam, müəllim! Məni xatırladınız? Vaxtilə sizin şagirdiniz olmuşam.","— Bəli, xatırladım. İbtidai sinifdə sənə dərs demişəm. Bu qədər ildən sonra səni görmək nə xoşdur! İndi nə işlə məşğulsan?","— Mən də sizi gördüyümə çox şadam. Sizin kimi müəllim olmuşam.","— Nə gözəl! Bəs bu peşəni niyə seçdin?","— Sizə görə. Mənə örnək oldunuz. İstədim ki, mən də uşaqların yetişməsinə kömək edim, onlara özlərinə inanmağı öyrədim.","— Bunu eşitmək məni çox sevindirdi. Amma de görüm, sənə necə örnək olmuşam?","— Bir gün sinfimizdəki oğlanlardan biri məktəbə təzə saatla gəlmişdi. Valideynləri almışdılar. Mənim ailəmin isə buna imkanı çatmırdı. Saat çox xoşuma gəlmişdi. Böyük tənəffüsdə onu oğlanın cibindən götürdüm.","Tənəffüsdən sonra sinif yoldaşım saatının itdiyini sizə dedi. Siz də hamıya müraciət etdiniz:","“Kim götürübsə, qaytarsın.”","Heç kim dillənmədi. Onda qapını bağlayıb bütün oğlanların ciblərini yoxlayacağınızı söylədiniz. Elə bildim, həyatımın ən utancverici anı gəlib çatdı.","Bizi divar boyu düzdünüz və hamımıza gözlərimizi əllərimizlə örtməyi tapşırdınız. Sonra bir-bir ciblərimizi yoxladınız. Saatı mənim cibimdə tapsanız da, dayanmadınız, qalan uşaqların da ciblərini yoxladınız.","Axırda saatı sahibinə qaytardınız. Amma onu kimin götürdüyünü demədiniz. Nə həmin gün, nə də il ərzində bu hadisə barədə mənimlə, yaxud valideynlərimlə danışdınız.","O gün məni hamının qarşısında utandırmadınız. Bir düşüncəsiz hərəkətimə görə üstümə “oğru” damğası vurulmasına imkan vermədiniz. Səhvimin ağırlığını anladım, amma özümü dəyərsiz hiss etmədim.","Bu, mənim üçün unudulmaz bir dərs oldu. Başa düşdüm ki, müəllim yalnız bilik vermir. O, uşağa səhvini görməyi, ondan nəticə çıxarmağı və daha yaxşı insan ola biləcəyinə inanmağı da öyrədir. Mən də sizin kimi müəllim olmaq istədim.","Müəllim onu diqqətlə dinlədi. Üzündəki təəccübü görən gənc soruşdu:","— Yadınıza düşmədi? Saatı mənim cibimdə tapmışdınız...","— Hadisəni xatırlayıram, oğlum. Amma saatın sənin cibindən çıxdığını bilmirdim.","— Necə yəni bilmirdiniz? Axı onu özünüz tapmışdınız!","Müəllim sakitcə cavab verdi:","— Çünki ciblərinizi yoxlayanda mən də gözlərimi yummuşdum...","İbrət: Əsl tərbiyə səhvi görməzdən gəlmək deyil, onu insanın ləyaqətini alçaltmadan düzəltməyə yol açmaqdır. Bəzən uşağa göstərilən bir incəlik onun bütün həyatına istiqamət verir."]},{"stem":"audience-of-one","title":"Mühazirəçi və mehtər","hasAudio":false,"hasImage":true,"paragraphs":["Bir kəndə maarifləndirici mühazirə söyləmək üçün bir mühazirəçi dəvət edirlər. O, salona girəndə görür ki, içəridə cəmi bir nəfər oturub. Salamlaşıb soruşur:","— Sizdən başqa heç kim gəlməyib. Necə düşünürsünüz, mühazirəni keçək, ya yox?","Yeganə dinləyici cavab verir:","— Müəllim, mən mehtərəm, iyirmi ata baxıram. On doqquzu qaçıb getsə, biri qalsa, onu ac-susuz qoymaram ki! Yenə yemini, suyunu verərəm.","Mühazirəçi bu sözlərdən həvəslənib çıxışına başlayır. Uzun-uzadı danışır. Nəhayət, sözünü bitirib soruşur:","— Necədir, mühazirəmi bəyəndinizmi?","Mehtər cavab verir:","— Mən at baxıcısıyam, dediklərinizin çoxunu anlamadım. Amma bir şeyi bilirəm: bir at qalıb deyə iyirmi atın yemini onun qabağına tökmərəm!","İbrət: Yaxşı danışmaq çox danışmaq deyil. Sözün faydası dinləyicinin ehtiyacına, anlayışına və mənimsəmə imkanına uyğun olmasındadır."]},{"stem":"not-my-concern","title":"Nəyimə lazımdır","hasAudio":false,"hasImage":true,"paragraphs":["Qanuni Sultan Süleyman Osmanlı dövlətini dövrünün ən qüdrətli dövlətlərindən birinə çevirmişdi. Amma bəzən bir fikir onu narahat edirdi:","«Görəsən, gün gələr, Osmanlı dövləti də zəifləyib süqut edərmi?»","Rəvayətə görə, sultan bu narahatlığını süd qardaşı, elminə və mənəvi bəsirətinə güvəndiyi Yəhya Əfəndi ilə bölüşmək qərarına gəlir. Ona məktub yazır:","«Bir dövlət hansı halda çökər? Osmanlı dövlətinin də bir gün süquta uğraması mümkündürmü? Bu barədə fikrini bilmək istəyirəm».","Yəhya Əfəndinin cavabı çox qısa olur:","«Nəyimə lazımdır, sultanım!»","Sultan Topqapı sarayında məktubu oxuyub heyrətə düşür. Yəhya Əfəndinin belə ciddi suala başdansovdu cavab verəcəyinə inanmır.","«Yəqin, bu sözlərin anlamadığım bir mənası var», — deyə düşünüb onun Beşiktaşdakı dərgahına yollanır.","— Ağabəy, sənə mühüm bir məsələ barədə yazmışdım. Nə olar, sualıma ciddi cavab ver, — deyə bir qədər gileyli səslə soruşur.","Yəhya Əfəndi cavab verir:","— Sultanım, sizin sualınıza laqeyd yanaşarammı? Yaxşıca düşündüm, qənaətimi də sizə bildirdim.","— Amma mən cavabından heç nə anlamadım. «Nəyimə lazımdır» yazmısan. Elə bil «məni bu işə qarışdırma» deyirsən.","Yəhya Əfəndi izah edir:","— Sultanım, bir dövlətdə zülm yayılarsa, haqsızlıq baş alıb gedərsə, bunu görənlər də «nəyimə lazımdır» deyib kənara çəkilərsə, o dövlətin dayaqları sarsılar.","Qoyunları qurdlar deyil, onları qorumağa borclu olan çobanlar yeyərsə; həqiqəti bilənlər susub onu gizlədərsə; yoxsulların, möhtacların, kimsəsizlərin fəryadı göyə yüksələr, amma daşlardan başqa heç kim bu fəryadı eşitməzsə, dövlətin sonu yaxınlaşar.","Belə yerdə xəzinə boşalar, xalqın etimadı itər. İdarə edənlərin xalqa hörməti, xalqın da dövlətə inamı qalmayanda asayiş pozular, dövlət içəridən çökər.","Sultan bu sözləri dinləyərkən onun gözləri dolur. Başını aşağı salıb deyilənləri təsdiqləyir. Sonra ona həqiqəti çəkinmədən söyləyən bir alimin varlığına görə Allaha şükür edib oradan ayrılır.","İbrət: Haqsızlıq təkcə onu edənlərin gücü ilə deyil, onu görüb «nəyimə lazımdır» deyənlərin laqeydliyi ilə də yayılır. Cəmiyyəti qorumaq hər kəsin öz məsuliyyətini dərk etməsindən başlayır."]},{"stem":"newtons-second-law","title":"Nyutonun 2-ci qanunu","hasAudio":false,"hasImage":true,"paragraphs":["Fizika müəllimi dərsdən çıxıb müəllimlər otağına girir və həmkarlarına gileylənir:","— Bu şagirdlər heç nə anlamırlar! Nyutonun ikinci qanununu onlara düz üç dəfə izah etdim. Axırda hətta özüm də başa düşdüm, amma onlar hələ də başa düşməyiblər!","İbrət: Öyrətmək anlamaqdan başlayır. Şagird başa düşmürsə, onu günahlandırmazdan əvvəl öz biliyinə və izahına nəzər salmaq lazımdır."]},{"stem":"living-with-loss","title":"Ölən həyatda qalandır","hasAudio":false,"hasImage":true,"paragraphs":["Bir-birini ürəkdən sevən iki insandan biri ölərsə, əsl ölən həyatda qalandır.","İbrət: Bir-birini ürəkdən sevən iki insandan biri dünyadan köçəndə geridə qalan həsrətlə yaşayır, özünü diri ikən ölmüş kimi hiss edir. Ayrılıq sevginin dərinliyini daha da duyurur."]},{"stem":"life-is-short","title":"Ömür qısadır","hasAudio":false,"hasImage":true,"paragraphs":["Ömür qısadır. Onu sənə sevinc bəxş edən, yanında sevildiyini hiss etdiyin insanlarla keçir.","İbrət: Ömrün dəyəri təkcə illərlə deyil, bölüşdüyümüz sevgi və sevinclə ölçülür. Səmimi münasibətlər həyatımıza məna, qəlbimizə rahatlıq gətirir."]},{"stem":"beyond-the-cotton-field","title":"Pambıq tarlasına gedən yol","hasAudio":false,"hasImage":true,"paragraphs":["Hələ düz-əməlli oxuyub-yaza bilmirdik. Bir gün kəndimizə bir müəllim gəldi. O vaxt bilmirdik ki, bu adam bizə təkcə müəllim deyil, böyük qardaş, ata kimi dayaq olacaq.","Aydın müəllim məktəbimizin və bizim ağır vəziyyətimizi görəndə kədərləndi. Məktəbi bitirəndən sonra hamımızın pambıq tarlasında işləməli olacağımızı eşidəndə isə gözləri doldu.","Kəndimizdən uzanan bir yolu göstərib soruşdu:","— Bu yol hara gedir?","— Pambıq tarlasına, — dedik.","Sonra başqa bir yolu göstərdi:","— Bəs o biri?","Cavab verə bilmədik. Heç vaxt kənddən kənara çıxmamışdıq. Elə bilirdik, bütün dünya bizim kənddən ibarətdir.","Həmin gün böyüyəndə kim olmaq istədiyimizi də soruşdu. Yenə susduq. Bu barədə heç düşünməmişdik.","Aydın müəllim qısa müddətdə bizə oxuyub-yazmağı öyrətdi. Günlər keçdikcə daha sərbəst oxuyur, fikirlərimizi kağıza köçürə bilirdik.","Bir gün sinfə bir dəstə məktub gətirdi. Dedi ki, onları həkimlər, mühəndislər, alimlər və başqa peşə sahibləri yazıblar.","— Bundan sonra onlar sizin məktub dostlarınız olacaq, — dedi.","İllərlə üzünü görmədiyimiz o insanlardan məktublar aldıq. Bizə peşələrindən, həyatın mənasından, elmin və təhsilin əhəmiyyətindən yazırdılar. Hər məktub qarşımızda tanımadığımız bir dünyaya pəncərə açırdı.","O vaxta qədər təhsil almağı, pambıqçılıqdan başqa bir işlə məşğul olmağı xəyalımıza belə gətirməmişdik. Elə bilirdik, qarşımızda yalnız bir yol var: pambıq tarlasına gedən yol.","Məktub dostlarımız sayəsində arzularımız yarandı. Kənddən çıxan o biri yolun hara apara biləcəyini anlamağa başladıq.","Aydın müəllimin zəhməti ilə məktəbi bitirib təhsilimizi davam etdirdik. İllər keçdi. Aramızda həkim, mühəndis, müəllim olmağa hazırlaşanlar vardı. Bir vaxt dilə gətirməyə söz tapmadığımız gələcək artıq gözümüzün önündə canlanırdı.","Bir gün daha bir məktub aldıq:","«Əziz övladlarım!","Xəyal qurmaqdan vaz keçməyin. Arzularınız sizə istiqamət verər, zəhmətiniz və əzminiz isə sizi o arzulara yaxınlaşdırar.","Hamınızı ürəkdən təbrik edirəm. Bacaracağınıza həmişə inanmışam.","Sizin məktub dostunuz — Aydın müəllim.»","Hamımız heyrət içində qaldıq. Sən demə, illər boyu ayrı-ayrı peşə sahiblərindən gəldiyini düşündüyümüz məktubların hamısını Aydın müəllim yazırmış.","Bizə başqa yolların da olduğunu göstərən elə öz müəllimimiz imiş.","İbrət: Yaxşı müəllim uşağa yalnız bilik vermir, onun görə bilmədiyi imkanları da göstərir. Qarşısında başqa yolların olduğunu anlayan uşaq gələcəyini seçmək üçün cəsarət tapır."]},{"stem":"pandemic-and-quarantine","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/pandemic-and-quarantine.webp","title":"Pandemiya, karantin","hasAudio":false,"hasImage":true,"paragraphs":["Yayıldı dünyaya virus dalğası","Ellərdə dolaşdı kovid havası","Qarışdı hər kəsin gecə röyası","Niyə gəldin, pandemiya, karantin?","Təmiz hava udmaq dönüb müşkülə","SMS-lə icazə — bir vəlvələ!","Oxşamışıq qəfəsdəki bülbülə","Niyə gəldin, pandemiya,","karantin?","Maska, əlcək — geyim oldu bizlərə,","Spirt vurduq qorxa-qorxa əllərə!","Uzaq düşdük dostlardan, əzizlərdən!","Niyə gəldin, pandemiya, karantin?","Şəhərlər boşaldı, hərəkət dondu,","Səs-küylü küçələr dönüb lal oldu!","İşlər də dayandı, çöhrələr soldu,","Niyə gəldin, pandemiya, karantin?","TV-lər kovidlə adam qorxudur,","Sanki damarlarda qanı dondurur!","Virus xəbəriylə beyinlər dolur!","Niyə gəldin, pandemiya, karantin?","Dünyada baş verən bu cür olaylar","Çox çəkməz, bizlərdən uzaqda qalar!","Verilər hər yerdə bu cür suallar:","Niyə gəldin, pandemiya, karantin?","Gəl cavab ver, pandemiya, karantin!","Etibar Siracsoy"]},{"stem":"pawn-and-the-king","title":"Piyada və şah","hasAudio":false,"hasImage":true,"paragraphs":["Piyadadır deyə kiçik görmə — gün gələr, şah olar.","Şahdır deyə güvənmə — gün gələr, mat olar.","İbrət: Heç kimi bugünkü mövqeyinə görə kiçik görmə, öz mövqeyini də sarsılmaz sayma. Bu gün gücsüz görünən sabah yüksələ, qüdrətli olan isə məğlubiyyətlə üzləşə bilər."]},{"stem":"qualities-of-water","title":"Suyun xassələri","hasAudio":false,"hasImage":true,"paragraphs":["Suyun xassələrinə baxın:","Ağacın kökünə çatsa, ona həyat verər.","Odla qarşılaşsa, onu söndürər.","Çirkə bulaşanı yuyub təmizləyər.","Una qarışsa, xəmir olar, çörəyə çevrilməyə yol açar.","Damcıları günəş işığında göy qurşağına dönər.","Axıb getdiyi yerlərə canlılıq gətirər.","Durğun qalıb təzələnməsə, bulanıb qoxuya bilər.","İnsan qəlbi də suya bənzəyir: səmimi söhbətdən, paylaşılan sevincdən, qarşılıqlı qayğıdan təzələnir. Uzun müddət isti münasibətlərdən uzaq qalanda isə durğunlaşa bilər.","İbrət: Qəlbi canlandıran səmimi ünsiyyət, paylaşmaq və qarşılıqlı qayğıdır. Təklik bəzən dinclik versə də, insanın anlayışa və yaxınlığa ehtiyacı var."]},{"stem":"stronger-together","title":"Tox, ya yox olmaq","hasAudio":false,"hasImage":true,"paragraphs":["Bölüşərək tox olarıq,","bölünərsək yox olarıq.","— Yunus Əmrəyə aid edilən söz","İbrət: Bölüşmək süfrəmizə bərəkət, birliyimizə güc qatar. Bir-birimizdən uzaqlaşdıqca zəifləyər, bir-birimizə dayaq olduqca güclənərik."]},{"stem":"three-statues","title":"Üç heykəl","hasAudio":false,"hasImage":true,"paragraphs":["İki qonşu ölkənin hökmdarları arasında möhkəm dostluq vardı. Bir gün onlardan biri dostuna doğum günü hədiyyəsi göndərmək qərarına gəldi. Ölkəsinin ən mahir heykəltəraşını çağırıb bir qarış hündürlükdə, görünüşcə bir-birinin eyni olan üç qızıl heykəl hazırlamağı tapşırdı. Lakin heykəllərin arasında yalnız hökmdarla ustanın bildiyi gizli bir fərq olacaqdı.","Heykəllər hazır olanda bir məktubla birlikdə qonşu hökmdara göndərildi:","«Doğum gününüz münasibətilə bu üç qızıl heykəli sizə hədiyyə edirəm. İlk baxışda bir-birindən seçilmirlər. Lakin onlardan biri digər ikisindən daha dəyərlidir. Hansı olduğunu tapanda mənə xəbər verin».","Hədiyyəni alan hökmdar əvvəlcə heykəlləri çəkdirdi. Üçünün də çəkisi eyni idi. Onları ölçüb-biçdilər, hər tərəfdən yoxladılar, amma heç bir fərq tapmadılar.","Hökmdar sənətdən başı çıxan adamları saraya çağırdı. Hər kəs heykəlləri diqqətlə nəzərdən keçirdi. Günlər keçsə də, sirr açılmadı.","Nəhayət, hökmdara bu tapmacanı həll edə biləcək bir adamın olduğu xəbəri çatdı. Onu saraya gətirdilər.","Adam heykəlləri diqqətlə yoxlayıb nazik bir tel istədi. Teli birinci heykəlin qulağına saldı. Tel o biri qulağından çıxdı.","İkinci heykəlin qulağına saldığı tel isə ağzından çıxdı.","Teli üçüncü heykəlin qulağına salanda isə tel içəridə qaldı, heç bir yerdən çıxmadı.","Beləcə, heykəllərin sirri açıldı. Hökmdar dostuna belə bir cavab göndərdi:","«Bu üç heykəl üç cür insanı təmsil edir.","Birincisi eşitdiyini bir qulağından alıb o birindən buraxır.","İkincisi eşitdiyini düşünmədən dilinə gətirir.","Üçüncüsü isə eşitdiyini qəlbində saxlayır, nə vaxt susmağı, nə vaxt danışmağı bilir.","Ən dəyərli olan üçüncü heykəldir. Çünki o, dinləməyi, etibarı qorumağı və sözünü yerində deməyi bacaran insanı təmsil edir.","Bu mənalı hədiyyəniz üçün təşəkkür edirəm».","İbrət: Müdriklik yalnız dinləməkdə deyil, eşitdiyinə necə yanaşmaqdadır. Sənə etibar ediləni qoru, danışmazdan əvvəl düşün, sözünü yerində və vaxtında söylə."]},{"stem":"three-scenes","title":"Üç mənzərə","hasAudio":false,"hasImage":true,"paragraphs":["Səfərə çıxan bir gənc yolda üç qəribə mənzərə ilə qarşılaşdı.","Əvvəlcə tarlaya buğda səpən adamlar gördü. Dənlər torpağa düşən kimi cücərir, boy atır, sünbüllənirdi. Amma əkinçilər yetişmiş məhsulu biçmək əvəzinə tarlanı yandırırdılar.","Bir qədər sonra böyük bir daşı qaldırmağa çalışan adama rast gəldi. Adam nə qədər güc versə də, daşı yerindən qaldıra bilmirdi. Daşın üstünə ikincisini qoyanda isə ikisini birlikdə qaldırdı. Üçüncüsünü də əlavə edəndə yükü daha asan götürdü. Gənc gördüyünə məna verə bilməyib yoluna davam etdi.","Üçüncü mənzərə daha qəribə idi: bir adam qoyunun belinə minmiş, bir neçə nəfər də onun çiyinlərindən yapışmışdı. Qoyun sürətlə qaçırdı. Arxadan gələn adamlar nə qədər yüyürsələr də, onlara çata bilmirdilər.","Gənc gördüklərini düşünə-düşünə bir şəhərə çatdı. Şəhərin girişində nurani bir qocaya rast gəlib salam verdi. Qoca onunla söhbətə başladı. Gənc yol boyu gördüyü qəribə mənzərələri danışıb mənasını soruşdu.","Qoca dedi:","— O əkinçilər əvvəlcə yaxşılıq edən, sonra isə etdiklərini öyünə-öyünə danışıb yaxşılıqlarının dəyərini azaldan insanları təmsil edir. Onlar öz əlləri ilə yetişdirdikləri məhsulu yenə öz əlləri ilə yandırırlar.","Sonra sözünə davam etdi:","— Daşları qaldıran adam isə günaha alışmağı göstərir. İlk dəfə yanlış iş görəndə vicdan insana ağırlıq verir. İnsan peşman olub yolunu dəyişməsə, növbəti dəfə eyni işi görmək ona daha asan gələr. Tövbə ilə bağlanmayan bir günah başqasına qapı aça bilər.","— Bəs qoyunla onun belindəki adamlar? — deyə gənc soruşdu.","Qoca cavab verdi:","— Bu rəmzi mənzərədə qoyun insanları cənnətə aparan bir heyvandır. Onun belinə minənlər alimləri, onların çiyinlərindən yapışanlar isə müxtəlif təbəqələrdən olan möminləri təmsil edir. Arxadan qaçıb çata bilməyənlər də imandan uzaq qalanları göstərir.","İbrət: Yaxşılığını öyünməklə kölgədə qoyma, səhvinə alışıb vicdanının səsini susdurma. Yol göstərən seçəndə isə biliyi, dürüstlüyü və əməli bir-birini tamamlayan insanlara üz tut."]},{"stem":"three-questions","title":"Üç sual","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün padşah vəzirini hüzuruna çağırıb dedi:","— Sənə üç sual verəcəyəm. Sabaha qədər cavablarını tapmasan, saraydan qovulacaqsan. Birincisi: Allah nəyə təhəmmül edir? İkincisi: Allah nəyi gizli saxlayır? Üçüncüsü: Allah Öz hikməti və qüdrəti ilə nələri dəyişir?","Vəzir nə qədər düşünüb-daşındısa, cavab tapa bilmədi. Axşam pərişan halda evə qayıtdı. Onun ağıllı, fərasətli bir nökəri vardı. Ağasının qanıqara olduğunu görüb səbəbini soruşdu. Vəzir də başına gələnləri danışdı.","Nökər dedi:","— Hər üç sualın cavabını bilirəm. İkisini indi deyəcəyəm, üçüncüsünü isə sabah. Allah bəndələrinin qəm-qüssə içində etdikləri gileyə səbir göstərir, onların eyiblərini isə örtülü saxlayır.","Ertəsi gün vəzir padşahın yanına gedib bu iki cavabı söylədi. Padşah cavabları bəyəndi:","— Bəs bunları özün tapmısan, yoxsa kimsə sənə öyrədib?","Vəzir düzünü dedi:","— Ağıllı nökərim öyrədib, padşahım.","Padşah nökəri saraya gətirtdi və vəzirə əmr etdi:","— Vəzirlik xələtini çıxarıb ona ver.","Vəzir xələtini çıxardı, nökəri də onu geyindi. Özü isə nökərin köhnə paltarını əyninə keçirdi.","Baş verənlərdən çaş-baş qalmış vəzir soruşdu:","— Bəs üçüncü sualın cavabı? Allah Öz hikməti və qüdrəti ilə nələri dəyişir?","Nökər gülümsədi:","— Hələ də anlamadın? Bir anın içində vəziri nökər, nökəri isə vəzir edir!","İbrət: Vəzifə insana ömürlük verilmir, müdriklik də yalnız yüksək məqam sahiblərində olmur. Kürsünə arxayın olma, heç kimi tutduğu yerə görə kiçik görmə."]},{"stem":"dreaming","title":"Xəyal qurmaq","hasAudio":false,"hasImage":true,"paragraphs":["Allah nəsib etməyəcəyi şeyi xəyal etdirməz.","İbrət: Ürəyə düşən hər xəyalın bir hikməti var. Allah nəsib etməyəcəyi arzunu ürəyə salmaz — ümidini itirmə."]},{"stem":"living-well","title":"Yaxşı yaşamaq üçün sadə vərdişlər","hasAudio":false,"hasImage":true,"paragraphs":["Yeməkdə ölçülü olun, gəzintilərinizi ikiqat, gülüşlərinizi üçqat artırın, sevginizə isə hədd qoymayın.","Tibet məsəli kimi tanınan bir deyim.","İbrət: Qədərində ye, hərəkətli ol, gülməyi unutma, ürəkdən sev. Həyatı gözəlləşdirən bəzən elə bu sadə vərdişlərdir."]}]},{"title":"Əmək, ruzi və sərvət","slug":"emek-ruzi-ve-servet","blurb":"Zəhmət, ruzi və var-dövlətə baxış.","count":19,"stories":[{"stem":"fish-shop","title":"Balıq dükanında","hasAudio":false,"hasImage":true,"paragraphs":["İşdən çıxan bir kişi avtobus dayanacağına gedərkən balıq dükanının qarşısında ayaq saxladı. Həyat yoldaşı ilə qızının balığı çox sevdiyini xatırlayıb içəri girdi.","— Bir kilo çəkin… Yox, elə iki kilo olsun, — deyə satıcıya səsləndi.","Bu vaxt nimdaş paltolu yaşlı bir qadın çəkinə-çəkinə ona yaxınlaşdı:","— Oğlum, mənə də bir az balıq alarsanmı?","Kişi tərəddüd etmədən satıcıya döndü:","— Dörd kilo çəkin. İki kilo bizə, iki kilo da xalaya.","Sonra qadından soruşdu:","— Evdə çörəyin var?","Qadın başını buladı. Kişi qarşıdakı dükana keçib dörd çörək aldı, ikisini ona verdi.","— Başqa nəyə ehtiyacın var, xala?","Qadın cibindən boş bir göz damcısı şüşəsi çıxardı.","— Axırıncı dəfə iki ay əvvəl almışdım. Təzəsini almağa pulum çatmır. Gözlərim də əvvəlki kimi görmür…","Kişi şüşəni götürüb aptekə yollandı. Geri qayıdanda qadının stulda oturduğunu gördü. Balıqçı gözləməkdən yorulmasın deyə ona yer vermişdi. Kişi bunu görüb gülümsədi.","Dərmanı qadına uzatdı, sonra cibində qalan pulu da çıxarıb ovcuna qoydu.","Qadın ona dönə-dönə dua edib evinə yollandı.","Kişi balıqla dolu torbanı götürüb dayanacağa tərəf gedirdi ki, birdən dayandı: balığın pulunu verməmişdi. Geri qayıdıb pərt halda dedi:","— Bağışlayın, hesabı ödəməyi unutdum. Üstümdə də pul qalmayıb. Sonra gətirib verərəm.","Balıqçı gülümsədi:","— Lazım deyil, qardaşım. Qoy bu yaxşılıqda mənim də payım olsun. Halal xoşun olsun.","Kişi təşəkkür etdi. Avtobusa da pulu qalmadığı üçün evə piyada yollandı. Qızına zəng vurdu:","— Balıq almışam. Anana de, gəlirəm, bir az gecikəcəyəm.","Yağış başlamışdı. Addımladıqca günün yorğunluğu yüngülləşirdi. Bir qadının yükünü azalda bildiyinə, bir başqasının da bu yaxşılığa qoşulduğuna görə şükür edirdi.","Yanaqlarından süzülən göz yaşları yağışa qarışırdı.","İbrət: Yaxşılıq etmək üçün varlanmağı gözləmə. İmkanın çatan bir kömək də kiminsə yükünü yüngülləşdirə, başqasını xeyirxahlığa ruhlandıra bilər. Paylaşılan yalnız çörək deyil, mərhəmətdir."]},{"stem":"butter-price-war","title":"Baqqal dükanı və supermarket","hasAudio":false,"hasImage":true,"paragraphs":["Məhəlləmizdə yaşlı bir qadının balaca baqqal dükanı vardı. Bir gün dükanla üzbəüz böyük bir supermarket açıldı.","Hər iki dükan qapısının önündəki lövhəyə ərzaqların qiymətini yazırdı. Supermarketin lövhəsində «Kərə yağı — 70 manat» elanı görünən kimi qadın da öz lövhəsinə yazdı:","«Bizdə kərə yağı — 60 manat».","Ertəsi gün supermarket qiyməti 50 manata endirdi. Qadın da lövhədəki rəqəmi dəyişdi:","«Kərə yağı — 40 manat».","Bu qiymət yarışını görən məhəllə sakinlərindən biri narahat olub qadına dedi:","— Ay xala, bunlarla yarışa girmə. Onların arxasında böyük pul var, zərərə də dözərlər. Sən isə əlində olanı da itirərsən.","Qadın təmkinini pozmadan gülümsədi:","— Mən heç kərə yağı satmıram ki… Qoy camaat heç olmasa oradan ucuz alsın!","İbrət: Hər qazanc cibə girmir. Bəzən insanın sevinci öz xeyrində deyil, başqalarının işinə yaramaqdadır."]},{"stem":"garden-and-the-gardener","title":"Bağ və bağban","hasAudio":false,"hasImage":true,"paragraphs":["Müəllim tələbələrinə dedi:","— Təsəvvür edin ki, bir bağban bağa qulluq edir. Torpağı yumşaldır, ağacları sulayır, qurumuş budaqları kəsir. Bağ da böyüyür, çiçəklənir, bar verir. Bəs bağı böyüdən kimdir?","— Bağban, — deyə tələbələrdən biri cavab verdi.","— Ağaclar özləri böyüyür, — başqası dilləndi.","Müəllim gülümsədi:","— Bağban ağacın yerinə böyüyə bilməz. Amma onun əməyi də əbəs deyil: ağacın böyüməsi üçün şərait yaradır. Ağacın özündə həyat gücü var, bağban isə o gücün üzə çıxmasına kömək edir.","Bir an dayanıb əlavə etdi:","— İnsan da belə yetişir. Nə onun öz səyini unutmaq olar, nə də yolunda ona dayaq olanları.","İbrət: İnkişaf həm öz zəhmətimizin, həm də gördüyümüz qayğının bəhrəsidir. Əməyinin dəyərini bil, sənə kömək edənlərin haqqını da unutma."]},{"stem":"investing-in-people","title":"Baş mühasib və baş direktor","hasAudio":false,"hasImage":true,"paragraphs":["Baş mühasib baş direktordan soruşdu:","— Əməkdaşlarımızın inkişafına vaxt və pul sərf etsək, onlar da sonra şirkətdən getsələr, necə olacaq?","Baş direktor cavabında soruşdu:","— Bəs inkişaflarına heç nə sərf etməsək, onlar da şirkətdə qalsalar, necə olacaq?","İbrət: Əməkdaşların inkişafına qoyulan sərmayə şirkətin gələcəyinə qoyulan sərmayədir. Bu gün təhsilə və inkişafa ayrılan vəsaitə qənaət etmək sabah daha baha başa gələ bilər."]},{"stem":"we-are-rich","title":"Biz zənginik","hasAudio":false,"hasImage":true,"paragraphs":["Rəvayətə görə, Yaponiya imperatoru Nintoku bir gün hündür bir qülləyə qalxıb ətrafı seyr edir. Evlərin heç birindən tüstü qalxmadığını görəndə anlayır ki, xalq yoxsulluq içindədir, ocaqlarda bişirməyə yemək yoxdur.","Dərhal fərman verib əhalini üç il müddətinə vergidən və saray üçün işləməkdən azad edir. İnsanlar bütün zəhmətlərini öz dolanışıqlarına sərf edə bilsinlər deyə sarayın təmirini də təxirə salır.","Üç il keçir. Xalqın güzəranı yaxşılaşır, evlərə bolluq gəlir.","Nintoku yenidən qülləyə qalxır. Hər tərəfdə evlərdən tüstü yüksəldiyini görüb sevinclə yanındakı xanımına deyir:","— İndi biz zənginik!","İmperatriçə isə baxımsızlıqdan köhnəlmiş, damı sızan sarayı göstərib soruşur:","— Buna zənginlik deyirsən?","Nintoku cavab verir:","— Xalqımız yoxsuldursa, biz də yoxsuluq. Xalqımız zəngindirsə, biz də zənginik.","İbrət: Əsl sərvət xəzinənin doluluğu ilə deyil, xalqın güzəranı ilə ölçülür. Rəhbəri böyük edən vəzifəsi yox, insanların həyatını yaxşılaşdırmaq üçün gördüyü işdir."]},{"stem":"without-a-plan","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/without-a-plan.webp","title":"Fəaliyyət planı olmayan təşkilat","hasAudio":false,"hasImage":true,"paragraphs":["Fəaliyyət planı olmayan təşkilat təyinat limanı bəlli olsa da, dəniz xəritəsi, hərəkət marşrutu və ekipaj üzvlərinin vəzifələri müəyyənləşdirilməmiş gəmiyə bənzəyir. Belə gəmi bəzən bəxti gətirdiyi, kapitanı bacarıqlı olduğu və ya hava şəraiti əlverişli keçdiyi üçün limana çata bilər. Ancaq bu, sistemli idarəetmənin deyil, təsadüfün nəticəsi olar. Davamlı uğur isə təsadüflərlə deyil, düzgün planlaşdırılmış və intizamla həyata keçirilən fəaliyyətlə qazanılır.","Fəaliyyət planı olmayan təşkilat zaman keçdikcə üzvlərini də itirir. Çünki insanları təşkilatda saxlayan yalnız ideyalar deyil, həmin ideyaların həyata keçirildiyini görmək ümididir. Ümid sönəndə insanlar uzaqlaşır, insanlar gedəndə isə təşkilat tədricən zəifləyir və fəaliyyətini dayandırır.","İbrət: Məqsəd hara gedəcəyini, plan isə ora necə çatacağını göstərir. Plansız təşkilatın uğuru təsadüfdən asılıdır; davamlı uğur düşünülmüş və ardıcıl iş tələb edir.","Bəxtiyar Siracov"]},{"stem":"everyone-has-work-to-do","image":"wisdom-stories/Bakhtiyar%20Sirajov/illustrations/everyone-has-work-to-do.webp","title":"Hamının işi-gücü var","hasAudio":false,"hasImage":true,"paragraphs":["Çox şanslıyam ki, müdrik müəllimlərim olub. Onlardan biri ədəbiyyat müəllimim, hörmətli Baladadaş müəllim idi. O deyərdi ki, kimsə sizdən nəsə istəmiş və ya sizə bir iş tapşırmışsa, hər hansı bir səbəbdən onu yerinə yetirə bilməsəniz belə, əsla həmin şəxsə «o qədər işim var idi ki, vaxtım olmadı, çatdıra bilmədim» kimi ifadələrlə cavab verməyin — bu, doğru olsa belə. Çünki bu sözlərlə qarşınızdakı insanı «görəsən, mənim işim-gücüm yoxdurmu, onu boş yerə narahat edirəm?» deyə düşünməyə vadar edirsiniz.","Hamının işi-gücü var. İnsan sizi bikarçılıqdan deyil, sizə ehtiyacı olduğundan narahat edir. Sizə edilən müraciəti heç vaxt diqqətdən kənarda qoymayın, susaraq həmin şəxsi gözləməyə məcbur etməyin. Əgər işi yerinə yetirmək imkanınız olmayacaqsa, susub durmayın. Gecikdirmədən bunu ona bildirin, insanı qeyri-müəyyənlik içində saxlamayın. Çünki o sizə ümid bəsləyir, güvənir. Siz isə üstündən xeyli vaxt keçəndən sonra gəlib «vaxtım olmadı» deyirsiniz və bununla da öz etibarınızı yerlə-yeksan edirsiniz.","İbrət: Başqalarının səni etibarsız, güvənilməz bir insan kimi tanıdığını bilə-bilə yaşamaq çox acıdır.","Bəxtiyar Siracov"]},{"stem":"henry-fords-choice","title":"Henri Fordun seçimi","hasAudio":false,"hasImage":true,"paragraphs":["Henri Ford haqqında danışılan bir rəvayətə görə, o, şirkətində işləmək istəyən iki gənc dostu şam yeməyinə dəvət etmişdi. Hər ikisi eyni universiteti bitirmiş, savadlı və istedadlı mütəxəssis idi.","Axşam boyu müxtəlif mövzulardan danışdılar. Yemək bitib restorandan çıxanda Ford gənclərdən birinə iş təklif etdi. Digərinə isə uğurlar arzulayıb onunla işləməyəcəyini bildirdi.","Məyus olan gənc cəsarətini toplayıb soruşdu:","— Cənab Ford, bütün axşam nə avtomobillərdən danışdıq, nə də mühəndislik biliklərimizdən. Bəs niyə dostumu seçdiniz?","Ford cavab verdi:","— Bunun iki səbəbi var. Yemək zamanı hər ikinizin davranışına diqqət yetirdim. Dostunuz əvvəl yeməyin dadına baxdı, sonra duz əlavə etdi. Siz isə dadına baxmadan duz səpdiniz. Mən dəyişiklik etməzdən əvvəl mövcud vəziyyəti öyrənən, ehtimala deyil, müşahidəyə əsaslanan insanlarla işləmək istəyirəm.","Bir an dayanıb davam etdi:","— İkinci səbəb isə insanlarla rəftarınızdır. Dostunuz ofisiantlarla da nəzakətlə danışdı. Siz isə bütün diqqətinizi mənə yönəltdiniz, onlara sanki fikir vermədiniz. Mənim üçün hörmət yalnız vəzifəli adamlara göstərilən münasibət deyil. İnsan qarşısındakına ondan nə qazana biləcəyinə görə yox, insan olduğuna görə dəyər verməlidir.","İbrət: Xarakter kiçik davranışlarda üzə çıxır. Qərar verməzdən əvvəl anlamağa çalış, hörmətini isə insanların vəzifəsinə görə bölüşdürmə."]},{"stem":"hot-bread","title":"İsti çörək","hasAudio":false,"hasImage":true,"paragraphs":["Təndirdən təzəcə çıxmış çörəyin ətri bütün küçəyə yayılmışdı.","Yaşlı kişi çörək dükanının qarşısında ayaq saxladı. Neçə gündür nəvəsi isti çörək istəyirdi. Cibindəki xırda pulları yoxlayıb növbəyə durdu. Cəmi bir çörəklik pulu vardı. İmkanı çatsaydı, ikisini alardı.","Növbəsi çatanda pulu uzatdı. Çörəkçi isə pulu götürmədən ona bir paket verdi:","— Buyur, dayı, nuş olsun.","Paketdə üç çörək vardı.","— Oğlum, mən bir çörək istəyirdim.","— Üçünü də götür, dayı. Evdə yeyərsiniz.","Qoca bir az yaxınlaşıb başqalarının eşitməyəcəyi səslə dedi:","— Mənim ancaq birinə pulum çatır.","Çörəkçi gülümsədi:","— Pul lazım deyil, dayı. Bu gün cümədir. Hər cümə isti çörək paylayırıq. Bu üçü də sizin payınızdır.","— Allah səndən razı olsun, övladım.","— Amin, dayı. Nuş olsun!","Qoca bir neçə addım uzaqlaşmışdı ki, arxadan bir gənc səsləndi:","— Dayı, bir dəqiqə!","Qoca dönüb baxdı.","— Bu, anamın zəkatıdır. Qəbul etsəniz, bizi sevindirərsiniz.","Gənc onun cibinə bir zərf qoydu.","— Allah qəbul etsin, oğlum. Anandan da razı olsun.","Bazarın yanından keçəndə bu dəfə bir qadın onu saxladı. Əlində iki dolu ərzaq torbası vardı.","— Dayıcan, Ramazan münasibətilə ərzaq paylayırıq. Bunları da sən götür.","— Allah qəbul etsin, qızım.","Evə çatanda kişi yorğunluqdan güclə nəfəs alırdı. Qızı qapını açıb əlindəkiləri götürdü.","— Xoş gəldin, ata.","— Anan haradadır?","— Mətbəxdə. İftar üçün qayğanaq hazırlayır. Bilirsən də, Orxan çox sevir.","Nəvəsi qaçıb gəldi:","— Baba, isti çörək almısan?","— Almışam, balam. Özü də üç dənə!","— Yaşasın babam!","Qızı torbalara baxıb təəccübləndi:","— Ata, səhər demək olar ki, pulun yox idi. Bunları necə aldın?","— Allah yetirdi, qızım.","Arvadı da mətbəxdən çıxdı. Kişi başına gələnləri bir-bir danışdı.","Azan səsi eşidiləndə ailə süfrəyə yığışdı. Qayğanağın yanında isti çörək vardı. Torbalardan yağ, pendir, halva və başqa ərzaqlar da çıxdı. Çoxdan idi süfrələri belə bol, ürəkləri belə rahat olmamışdı.","Yeməkdən sonra Orxan ayağa qalxdı:","— Mən otağıma gedib dua edəcəyəm.","Babası gülümsədi:","— Yatmazdan əvvəl edərsən, balam. Hələ tezdir.","— Yox, baba, dünən elə bu vaxt dua etmişdim. Allahdan isti çörəklə pendir istəmişdim. Bu gün də gəldi. İndi istəyəcəyəm ki, sənin dişlərini düzəltdirməyə pul göndərsin. Yeməyi çətinliklə çeynəyirsən axı.","Anasının üzünə kövrək bir təbəssüm qondu:","— Kaş atan sağ olaydı, səni belə görəydi…","— Mən atamı yuxumda görürəm, ana. Yuxuda mənə dua etməyi deyir.","Qocanın birdən cibindəki zərf yadına düşdü. Asılmış pencəyinə yaxınlaşıb zərfi çıxardı. İçində gözlədiyindən qat-qat çox pul vardı.","Gözləri doldu.","Arvadı narahatlıqla soruşdu:","— Nə oldu, ay kişi?","Qoca zərfi ona uzatdı:","— Bir bax… Bu pulla bayrama qədər ikimiz də dişlərimizi düzəltdirə bilərik.","Sonra nəvəsinə baxıb astadan dedi:","— Şükür Sənə, Allahım. Bu gün neçə insanın əli ilə evimizə sevinc göndərdin.","İbrət: Bir uşağın duası ilə bir neçə insanın xeyirxahlığı bu ailənin süfrəsində görüşdü. Ehtiyacı görüb əl tutanda kiminsə ümidinin gerçəkləşməsinə səbəb ola bilərik. Paylaşdığımız çörək bir evə həm ruzi, həm də sevinc gətirər."]},{"stem":"plastic-cup","title":"Keçmiş nazir seminarda","hasAudio":false,"hasImage":true,"paragraphs":["Bir seminara dəvət olunan keçmiş nazir əlində plastik stəkanla kürsüyə qalxdı. Bir neçə cümlə söylədikdən sonra dayandı, əlindəki qəhvəyə baxıb gülümsədi:","— İcazənizlə, fikrimi məşğul edən bir şeyi sizinlə bölüşüm. Keçən il də bu kürsüdə çıxış etmişdim. O vaxt nazir idim.","Zal sakitləşdi.","— Mənə biznes-sinifdə bilet almışdılar. Hava limanında maşın gözləyirdi. Hoteldə rahat bir nömrə ayırmışdılar. Səhər məni buraya gətirdilər, qarşıladılar, yerimi göstərdilər. Çıxışdan əvvəl isə qəhvəmi gözəl bir çini fincanda verdilər.","O, əlindəki stəkanı bir qədər yuxarı qaldırdı:","— Bu dəfə biletimi özüm aldım. Hava limanından hotelə taksi ilə getdim. Səhər buraya gələndə adımı siyahıda yoxlayıb içəri buraxdılar. Zalda boş bir yer tapıb oturdum. Qəhvə istəyəndə dəhlizdəki avtomatı göstərdilər. Mən də gedib bu stəkanı doldurdum.","Zaldan yüngül gülüş səsləri gəldi.","— Əvvəlcə bütün bunlar mənə qəribə gəldi. Sonra başa düşdüm: keçən il çini fincanı mənə yox, vəzifəmə vermişdilər.","Bir anlıq susdu, sonra davam etdi:","— Bunu incikliyimdən danışmıram. Bu gün də çıxış etmək üçün dəvət olunmuşam, siz də məni dinləyirsiniz. Sadəcə indi mənə göstərilən diqqətlə vəzifəmə görə verilən imtiyazları daha aydın ayıra bilirəm.","Stəkanı kürsünün üstünə qoydu:","— Vəzifədə olanda insan ona açılan qapıları, deyilən tərifləri, göstərilən xüsusi münasibəti öz şəxsi böyüklüyü saya bilər. Halbuki bunların bir hissəsi tutduğu yerə aiddir. Sabah o yerdə başqası oturacaq, fincan da ona veriləcək. Bizimlə qalan isə necə insan olduğumuz və başqalarına necə davrandığımızdır.","İbrət: Vəzifənin verdiyi imtiyazları şəxsi dəyərinlə qarışdırma. Nə çini fincan səni ucaldır, nə də plastik stəkan kiçildir. Əsl hörmət tituldan çox, davranışla qazanılır."]},{"stem":"mercedes","title":"Mercedes","hasAudio":false,"hasImage":true,"paragraphs":["«Mercedes» nə şirkət qurucusunun soyadı, nə də əvvəldən mövcud olan avtomobil şirkətinin adı idi. Avtomobillərə böyük həvəsi olan bir atanın qızının adı idi.","Avstriyalı iş adamı Emil Yellinek qızı Mersedesin adını əvvəlcə avtomobil yarışlarında təxəllüs kimi işlədirdi. Sonra Daimler şirkətinə sifariş etdiyi yeni avtomobil də bu adla tanındı.","1901-ci ildə Nitsadakı yarış həftəsində Mercedes avtomobilləri böyük uğur qazandı. 1902-ci ildə «Mercedes» ticarət nişanı kimi qeydiyyata alındı. 1926-cı ildə Daimler və Benz şirkətləri birləşəndə isə «Mercedes-Benz» adı yarandı. Beləcə, bir qızın adı avtomobil tarixinin ayrılmaz hissəsinə çevrildi.","Adı dünyaya yayılsa da, Mersedes Yellinekin öz həyatı asan keçmədi. Birinci evliliyi boşanma ilə bitdi, ikinci həyat yoldaşı isə evləndiklərindən bir neçə ay sonra vəfat etdi. Mersedes 1929-cu ildə, otuz doqquz yaşında sümük xərçəngindən dünyasını dəyişdi və Vyana Mərkəzi Qəbiristanlığında dəfn olundu.","Onun ömrü qısa oldu, adı isə yaşamağa davam etdi. Dünyanın tanıdığı bu adın arxasında bir ata və onun sevdiyi qızı dayanırdı.","İbrət: Bəzən dünyaca məşhur bir adın arxasında çox şəxsi bir sevgi hekayəsi dayanır. Böyük markaları tanıyarkən onlara ad verən insanların həyatını da xatırlamaq dəyərlidir."]},{"stem":"giving-without-money","title":"Pul olmadan da vermək olar","hasAudio":false,"hasImage":true,"paragraphs":["Bir rəvayətə görə, kasıb bir adam Budda ilə qarşılaşıb soruşur:","— Mən niyə kasıbam?","— Bəlkə də, sahib olduğun sərvətləri görmür, onları başqaları ilə bölüşmürsən.","— Axı mənim verməyə heç nəyim yoxdur!","— Bölüşə biləcəyin beş sərvətin var.","— Hansı sərvətlərdir? Zəhmət olmasa, mənə izah edin.","Budda deyir:","— Üzünlə bir insana təbəssüm bəxş edə bilərsən.","— Gözlərinlə ona mərhəmət və sevgi ilə baxa bilərsən.","— Dilinlə xoş söz deyib könlünü ala bilərsən.","— Ürəyində onun xoşbəxtliyini arzulaya bilərsən.","— Əllərinlə ona kömək edib yaxşılıq edə bilərsən.","İbrət: Səxavət üçün varlı olmaq şərt deyil. Təbəssüm, xoş söz, mərhəmətli baxış və kömək əli də dəyərli hədiyyələrdir. Paylaşmağa həmişə bir yaxşılığın var."]},{"stem":"credit-ledger","title":"Nisyə dəftəri","hasAudio":false,"hasImage":true,"paragraphs":["Ramazan günlərindən biri idi. Sadə geyimli, satıcının tanımadığı bir adam məhəllə dükanına girib satıcıya yaxınlaşdı:","— Qardaş, səndən nisyə çörək, çay, yumurta istəsəm, verərsən?","Dükançı mehribanlıqla cavab verdi:","— Niyə vermirəm? Buradan üç aydır nisyə çörək aparan var. Düzünü desəm, borcunu ödəməyə imkanı çatacaqmı, bilmirəm. Amma üç atasız uşaq böyüdür. Balaları ac qoymaq olmaz axı. Allah böyükdür, bizim də ruzimizi yetirər. Sən də ehtiyacın varsa, götür. Çörəyin pulunu düşünmə, halal xoşun olsun.","Yad adamın üzündə təbəssüm yarandı. “Deyəsən, axtardığım yeri tapdım”, — deyə düşündü.","— Bəs nisyə dəftərindəki borcların cəmi nə qədərdir?","Dükançı təəccübləndi:","— Nə üçün soruşursan?","— İstəyirəm, o dəftərdəki bütün borcları ödəyim.","Dükançı gah onun üzünə, gah da piştaxtanın altından çıxardığı köhnə dəftərə baxdı.","— Hamısını?","— Bəli, qardaş. Zəhmət olmasa, hesabla.","Adamın ciddi olduğunu görən dükançı borcları topladı və məbləği dedi. Yad adam pencəyinin iç cibindən pul çıxarıb saydı, piştaxtanın üstünə qoydu.","— Allah səndən razı olsun. Sən bu insanların çətin günündə onlara arxa olmusan. Qoy bu da mənim Ramazan payım olsun. Onlara de ki, əvvəlki borcları ödənilib. Adımı bilmələrinə ehtiyac yoxdur.","Sonra dəftəri göstərdi:","— Bunu da mənə ver. Nə onların adı kiminsə dilinə düşsün, nə də borcları yenidən qarşılarına çıxsın. Allah niyyətimizi bilsin, bəsdir.","Dəftəri götürüb sakitcə çıxdı.","Dükançı pulu kassaya qoysa da, hələ baş verənlərə inana bilmirdi. Balaca pəncərədən küçəyə baxdı. Yad adam görünmürdü. İftara az qalmışdı, hamı evinə tələsirdi.","Elə bu vaxt əri vəfat etmiş Sürəyyanın yeddi yaşlı qızı qapıda göründü. Çəkinə-çəkinə dedi:","— Əhməd əmi, anam deyir ki, iftara bir çörək, üç yumurta versin. Gələn ay dayım bizə gələndə pulunu verərik. — Dükançı qızın sözlərindən elə bil yuxudan ayıldı. Adəti üzrə dəftəri çıxarmaq üçün əlini piştaxtanın altına atdı. Bir an dayandı, gülümsədi və dedi:","— Gəl, ay qızım, yumurta da götür, çörək də, yağ da. Anana da de ki, o dayı gəldi də, getdi də...","İbrət: Əsl səxavət kömək etdiyin insanın ləyaqətini də qorumaqdır. Adını bildirmədən yüngülləşdirdiyin bir yük başqasının ürəyində yeni bir yaxşılığa yol aça bilər."]},{"stem":"baklava","title":"Paxlava","hasAudio":false,"hasImage":true,"paragraphs":["Uşaqlıqda ailəmiz kasıb yaşayırdı. Bir gün atam evə bir az paxlava gətirdi. Axşam çay süfrəsi arxasında yığışdıq. Hərəmizə kiçik bir pay düşdü.","Ertəsi gün məktəbdə bayram şənliyi vardı. Anam çantama bir tikə çörək, bir az zeytun və bir dilim paxlava qoydu.","Sinif yoldaşlarım cürbəcür yeməklər gətirmişdilər. Uşaqlardan biri mənim payıma baxıb güldü: — Bu paxlavanı siçanlar üçün gətirmisən?","Sinif gülüşə boğuldu. Elə bildim, hamının gözü mənim balaca paxlava dilimimdədir. Xəcalətdən üzüm yandı. Göz yaşlarımı saxlaya bilməyib evə qaçdım.","Qapıdan girən kimi anama qışqırdım: — Niyə mənə cəmi bir dilim qoymuşdun? Hamının o qədər yeməyi vardı! Məni rüsvay etdin!","Anam mənə baxıb asta səslə dedi: — O, mənim payım idi, balam. Yemədim, sənə saxladım.","Susdum.","Deməli, dünən axşam anam öz payına əl vurmamışdı. Mənim də bayram süfrəsində şirniyyatım olsun deyə onu mənə saxlamışdı. Mən isə başqalarının məni incitməsinin acığını ondan çıxmışdım.","Ona sarılmaq, üzr istəmək istəyirdim. Amma xəcalətdən başımı qaldıra, bir kəlmə deyə bilmirdim.","O gündən illər keçib. Hər dəfə o anı xatırlayanda anamın sakit səsi yenə qulağımda səslənir. Mən də ürəyimdə ondan bağışlanma diləyirəm.","Paxlavanı isə o gündən bir də dilimə vura bilmədim.","İbrət: Kiminsə kasıblığına gülməyin: kiçik bir payın arxasında böyük bir sevgi dayana bilər. Başqalarının sizi incitməsinin acığını sizi sevənlərdən çıxmayın."]},{"stem":"pay-rent-for-the-water","title":"Su üçün kirayə ödə","hasAudio":false,"hasImage":true,"paragraphs":["Bir adam kəndlidən su quyusu satın alır. Quyudan su çəkmək istəyəndə isə satıcı onun qarşısını kəsir:","— Mən sənə quyunu satmışam, içindəki suyu yox!","Aralarında mübahisə düşür. Heç cür razılığa gələ bilmədikləri üçün hakimin yanına gedirlər.","Hakim hər ikisini dinlədikdən sonra satıcıya deyir:","— Madam su sənindir, onu başqasının quyusunda niyə saxlayırsan? Ya suyunu götür apar, ya da quyu sahibinə kirayə haqqı ödə!","İbrət: Başqasının haqqını hiylə ilə əlindən almaq istəyən öz sözünün tələsinə düşə bilər. Ədalətli düşüncə hiylənin gizlətdiyi ziddiyyəti üzə çıxarır."]},{"stem":"more-than-money","title":"Xərcliyiniz varmı?","hasAudio":false,"hasImage":true,"paragraphs":["Ata-ananızın qədrini sağ ikən bilin. “Xərcliyiniz varmı?” deyə soruşun, amma qayğınızı təkcə bu sualla məhdudlaşdırmayın. Bəzən onlar sizi çətinliyə salmamaq üçün ehtiyaclarını dilə gətirməzlər.","İmkanınız daxilində kömək edin, istəklərini nəzərə alın, ləyaqətlərini qoruyun. Unutmayın ki, ehtiyacları yalnız maddi deyil: səsinizi eşitmək, sizinlə söhbət etmək, bir süfrə arxasında oturmaq da onlar üçün qiymətlidir.","İbrət: Valideynə sevginizi vaxtında göstərin — həm əlinizdən gələn köməklə, həm də ayırdığınız vaxtla. Bəzən “Nəyiniz çatmır?” sualına ən gözəl əlavə “Gəldim, bir az yanınızda olum” sözüdür."]},{"stem":"scarf-seller","title":"Yaylıq satıcısı","hasAudio":false,"hasImage":true,"paragraphs":["Şaxtalı gecə şəhəri bürümüşdü. Yer buz bağlamışdı, ayaq üstə durmaq belə çətin idi. Elə bil nəfəsim də donacaqdı. Sürüşüb yıxılmamaq üçün ehtiyatla addımlayıb avtobusa çatdım.","«Şükür, sağ-salamat gəlib çıxdım», — deyə düşündüm.","Elə bu vaxt əlində yaylıqlar olan bir oğlan mənə yaxınlaşdı. Ona qulaq asmağa halım yox idi; bircə avtobusa minib isinmək istəyirdim.","— Alarsan, bacı? — deyə bir yaylıq uzatdı.","— Yox, istəmirəm, — dedim, söhbəti tez bitirmək üçün.","— Al, bacı, lazım olar.","— Pulum yoxdur, — dedim, məndən əl çəksin deyə.","— Olsun, bacı. Götür, pul istəmirəm. Qoy məndən sənə hədiyyə olsun.","— Yox, olmaz. Yaylığım var, istəmirəm.","Bunu deyib tələsik avtobusa mindim. O anda yalnız özümü düşünürdüm. Uşağın halına fikir vermədən oturacağıma tərəf getdim.","Əyləşməzdən əvvəl telefonumu çıxarmaq üçün əlimi paltomun cibinə saldım. Əlimə bir paket dəydi. Çıxarıb baxanda heyrətləndim: içində yaylıq vardı. Uşaq məndən xəbərsiz onu cibimə qoymuşdu.","Tez avtobusdan düşdüm. Oğlan yenə həmin yerdə dayanıb sərnişinlərə yaylıq təklif edirdi.","On iki-on üç yaşı olardı. Nazik palto geymişdi, əlləri əlcəksiz idi, burnu soyuqdan qızarmışdı. Qara gözləri gecənin içində ulduz kimi parıldayır, gülümsəyəndə ağappaq dişləri görünürdü.","Yaxınlaşıb əlimi çiyninə qoydum, yaylığı göstərdim:","— Bunu sən qoymusan?","Gülümsədi:","— Hə, bacı. Sənə lazım olar. Qoy məndən olsun.","— Axı belə etsən, necə pul qazanacaqsan? Bu soyuqda dayanmaq sənə çətin deyil?","— Bir şey olmaz, bacı, — dedi, üzümə mehribanlıqla baxaraq.","Pulu ona uzatdım.","— Yox, bacı, istəmirəm. Onu sənə bağışlamışam.","O anda «Bəs pulun yox idi, bacı? İndi haradan tapdın?» desəydi, utandığımdan yerin dibinə girərdim. Amma o, məni sorğu-suala tutmadı. Sözümə inanmış, ehtiyacım olduğunu düşünüb əlində olanı mənimlə bölüşmüşdü.","— Götür, — dedim, bu dəfə qətiyyətlə.","İsrar etdiyimi görüb pulu aldı. Sonra qalığını qaytarmaq üçün cibindən xırda pul çıxardı.","— Qalığı qalsın, — dedim.","— Yox, bacı, bu çoxdur. Olmaz.","Tələsik pulları ayırmağa başladı. Qəpiklərin bir neçəsi əlindən yerə düşdü.","— Eybi yoxdur, canın sağ olsun. Bu da məndən sənə, — dedim, gülümsəyərək.","Uşaq bir az utanıb, elə bil buzları əridən o təbəssümü ilə cavab verdi:","— Çox sağ ol, bacı. Allah səndən razı olsun.","«Sən də sağ ol, balaca dostum. İmkanı az, ürəyi geniş, gözü tox balam», — deyə ürəyimdən keçirdim.","Avtobusa qayıdıb yerimə əyləşdim. Bayırda şaxta hələ də tüğyan edirdi. Oğlan isə həmin soyuqda dayanmışdı — insanlara inamını itirməyən, gülüşü ilə qışı bahara çevirən, işləyib ailəsinə kömək etməyə çalışan bir uşaq.","Yola düşdük. Şəhər də, yaylıq satan oğlan da gecənin qaranlığında geridə qaldı. Onu, bir də bu soyuqda sığınmağa yeri olmayan insanları düşünürdüm. Boğazım düyünlənmişdi, göz yaşlarımı güclə saxlayırdım.","Avtobusumuz isə bəmbəyaz qarla örtülmüş dağların arasından dolanan yolla irəliləyirdi.","İbrət: Səxavət sahib olduqlarının çoxluğu ilə deyil, ürəyindəki bölüşmək istəyi ilə ölçülür. Bəzən köməyə möhtac bildiyimiz bir insan bizə insanlığı xatırladır."]},{"stem":"weight-of-the-butter","title":"Yağın çəkisi","hasAudio":false,"hasImage":true,"paragraphs":["Bir çörəkçi kəndlidən müntəzəm olaraq kərə yağı alırmış. Bir müddət sonra aldığı yağın çəkisinin getdikcə azaldığını görüb kəndlini aldatmaqda günahlandırır və qazıya şikayət edir.","Qazı kəndlini çağırıb soruşur:","— Satdığın yağı necə çəkirsən?","Kəndli cavab verir:","— Mənim çəki daşım yoxdur. Tərəzinin bir gözünə hər gün bu çörəkçidən aldığım bir kiloluq çörəyi, o biri gözünə isə satacağım yağı qoyuram. Yağı çörəklə taraz gələnə qədər artırıram.","İbrət: Başqasına tutduğun ölçü bir gün sənə də tutular. Necə çörək verirsənsə, elə də yağ alarsan."]},{"stem":"busy-but-unproductive","title":"Əli işdədir","hasAudio":false,"hasImage":true,"paragraphs":["Bir kişi on yumurtanı on qəpiyə alıb doqquz qəpiyə satırdı. Tanışları təəccüblə soruşdular:","— Hər satışda zərər edirsən. Bəs bu alverin nə mənası var?","Kişi cavab verdi:","— Zərərə baxmayın! Hamı görür ki, alver edirəm, məni tacir sayır. Əsas odur, desinlər ki, əlim işdədir!","İbrət: Məşğul görünmək faydalı iş görmək deyil. İşin dəyəri yaratdığı təəssüratla yox, verdiyi nəticə ilə ölçülür."]}]},{"title":"Ədalət və cəmiyyət","slug":"edalet-ve-cemiyyet","blurb":"Haqq, cəmiyyət və ortaq məsuliyyət.","count":10,"stories":[{"stem":"market-of-good-neighbors","title":"Bu millət ilə dünya fəth edilə bilər","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün padşah xalqın necə dolandığını öyrənmək üçün libasını dəyişib şəhərə çıxır. Bazarı gəzib malların keyfiyyəti, qiymətlər və dükançıların güzəranı ilə maraqlanır.","Küçənin başındakı ilk dükana girib salam verir:","— Mənə yarım batman yağ, yarım batman bal, bir az da pendir verin.","Dükançı müştərini gülərüzlə qarşılayıb yağı çəkir. Qarşısındakının padşah olduğunu bilmədən deyir:","— Ağam, istəsəniz, bal da verərəm, pendir də. Amma bu yağı satmaqla günün ilk alış-verişini — siftahımı — etdim. Qonşum isə hələ heç nə satmayıb. Qalanlarını qarşıdakı dükandan alsanız, məni sevindirərsiniz.","Padşah bu sözlərdən məmnun qalır. Yağın pulunu ödəyib qarşıdakı dükana keçir, bal və pendir istəyir.","Yaşlı dükançı balı çəkib uzadır:","— Allaha şükür, sizin sayənizdə bu gün mən də siftah etdim. Bir xahişim var: pendiri yanımdakı dükançıdan alın. Onun hələ ilk müştərisi gəlməyib.","Padşah üçüncü dükana keçib pendiri də alır. Dükançıların bir-birinin ruzisini düşünməsi ona dərin təsir edir.","Bazardan ayrılarkən razılıqla deyir:","— Belə əxlaqlı bir millətlə dünyanı fəth etmək olar!","İbrət: Öz qazancını düşünərkən qonşunun ruzisini də unutmamaq cəmiyyəti gücləndirir. Əsl qələbə başqasını geridə qoymaqda deyil, birlikdə irəliləməkdədir."]},{"stem":"stolen-camel","title":"Dəvəsi oğurlanmış bədəvinin hekayəsi","hasAudio":false,"hasImage":true,"paragraphs":["Bir bədəvi dəvəsi ilə səhradan keçirdi. Yolda susuzluqdan dodaqları çatlamış, güclə ayaq üstə duran bir adama rast gəldi.","— Su… Mənə bir az su ver, — deyə yad adam yalvardı.","Bədəvi dəvəsindən düşüb su tuluğunu ona uzatdı. Adam doyunca su içdi. Sonra qəflətən xilaskarını itələyib dəvəyə mindi və qaçmağa başladı.","Bədəvi ona çata bilməyəcəyini anlayıb arxasınca səsləndi: — Dəvəni apar! Amma bir xahişim var: onu necə ələ keçirdiyini heç kimə danışma!","Oğru bu sözlərə təəccüblənib dəvəni saxladı və geri boylandı: — Niyə?","— İnsanlar sənə edilən yaxşılığa xəyanətlə cavab verdiyini eşitsələr, sabah susuzluqdan ölən birinə su verməyə qorxarlar. Mən dəvəmi itirdim. İstəmirəm ki, başqaları da kömək tapmaq ümidini itirsin.","İbrət: Bizə əl tutana xəyanət etməklə yalnız onu incitmirik — başqalarının da yaxşılığa inamını sarsıdırıq. Yaxşılığın qədrini bilin, kiminsə nankorluğunun sizi laqeyd insana çevirməsinə imkan verməyin."]},{"stem":"who-was-keeping-watch","title":"Evi qarət olunan qadın","hasAudio":false,"hasImage":true,"paragraphs":["Qədim zamanlarda bir şəhərdə yaşlı bir qadının evi qarət olunur. Qadın pərişan halda padşahın hüzuruna gəlib şikayət edir.","Padşah onu dinləyib hiddətlə soruşur:","— Bəs sən niyə elə dərin yatmışdın ki, evinə oğru girdiyini də hiss etməmisən?","Qadın cavab verir:","— Şah sağ olsun, biz sizin oyaq olduğunuzu düşünürdük. Ona görə də evimizdə arxayın yatmışdıq.","İbrət: Xalqın arxayınlığı ona verilən vədlərdən deyil, təhlükəsizliyinin qorunmasından doğur. Rəhbərin vəzifəsi zərərçəkəni qınamaq yox, üzərinə düşən məsuliyyəti yerinə yetirməkdir."]},{"stem":"choose-justice","title":"Ədalət var ikən haqsızlıq niyə?","hasAudio":false,"hasImage":true,"paragraphs":["Hacı Bektaş Vəliyə aid edilən sözlər:","Sevgi var ikən nifrət niyə?","Barış var ikən savaş niyə?","Qardaşlıq var ikən didişmək niyə?","Dostluq var ikən düşmənlik niyə?","Dözüm var ikən dözümsüzlük niyə?","Azadlıq var ikən əsirlik niyə?","Ədalət var ikən haqsızlıq niyə?","İbrət: Sevgi, sülh və ədalət yalnız arzu deyil, gündəlik seçimlərimizdə yaşatmalı olduğumuz dəyərlərdir. Onları seçmək də, əməllərimizlə qorumaq da bizim məsuliyyətimizdir."]},{"stem":"sharing-justice","title":"Ədaləti paylaşmaq","hasAudio":false,"hasImage":true,"paragraphs":["Ya heç kimin gözündən yaş axmasın, ya da daim gülənlər ağlayanı unutmasın.","Ya pul dediyimiz bu bəla olmasın, ya da varlı olan bölüşməyi bacarsın.","Ya heç kəs «sevirəm» deməsin, ya da əsl sevgini əməli ilə göstərsin.","Ya bayramlar heç gəlməsin, ya da bayramda bir süfrə belə ətsiz qalmasın.","İbrət: Ədalət sevincdən, ruzidən və sevgidən hər kəsə pay çatmasıdır. Əsl insanlıq öz xoş günündə başqasının dərdini də görüb sevincini onunla bölüşməyi bacarmaqdır."]},{"stem":"judges-answer","title":"Frankfurt hakiminin ədalətli hökmü","hasAudio":false,"hasImage":true,"paragraphs":["Rəvayətə görə, 1506-cı ildə Frankfurt şəhərində bir tacir içində 800 qulden olan pul kisəsini itirir. Həmin yoldan keçən bir dülgər kisəni tapır. Dindar və dürüst adam olan dülgər düşünür ki, bu qədər pul itirən şəxs mütləq onu axtaracaq. Kisəni sahibinə qaytarmaq üçün saxlayır.","Bir gün kilsədə ibadət bitəndən sonra keşiş camaata elan edir:","— Şəhərimizə gəlmiş bir tacir 800 qulden itirib. Pulu tapıb qaytarana 100 qulden mükafat vəd edir.","Dülgər bunu eşidən kimi evə gedib kisəni gətirir və keşişə təhvil verir.","Tacir də xəbər tutub kilsəyə gəlir. Pulunu sayır, amma vəd etdiyi 100 qulden əvəzinə dülgərə cəmi 5 qulden uzadır. Dülgər ondan sözünün üstündə durmasını istəyir.","Mükafatı vermək istəməyən tacir isə iddia edir:","— Mənim kisəmdə 800 yox, 900 qulden vardı. Yüzünü artıq özün götürmüsən!","Keşiş araya girir. Dülgəri çoxdan tanıdığını, onun dürüstlüyünə inandığını söyləyir. Mübahisə böyüyəndə məsələni şəhər məhkəməsinə aparırlar.","Hakim əvvəlcə taciri dinləyir:","— Əlini İncilin üstünə qoyub and içə bilərsənmi ki, kisəndə 900 qulden vardı?","Tacir tərəddüd etmədən and içir.","Sonra hakim dülgərdən soruşur:","— Sən də and içirsənmi ki, tapdığın kisədə 800 qulden vardı?","Dülgər də əlini İncilin üstünə qoyub and içir.","Hamı hökmü gözləyərkən hakim sakitcə deyir:","— Məsələ aydındır. Dülgər 800 qulden tapıb, tacir isə 900 qulden itirdiyinə and içib. Deməli, tapılan kisə bu tacirin ola bilməz. Həqiqi sahibi ortaya çıxanadək kisə dülgərdə qalacaq. Tacir isə itirdiyi 900 quldeni axtarmağa davam edə bilər.","İbrət: Tamah insanı qazancını artırmaq istəyərkən əlindəkindən də məhrum edə bilər. Yalanla başqasının haqqını danan bəzən elə öz sözləri ilə özünü ifşa edir."]},{"stem":"humanity-etibar-siracsoy","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/humanity-etibar-siracsoy.webp","title":"İnsanlıq","hasAudio":false,"hasImage":true,"paragraphs":["Dünya nə qədər möcüzəli və incə gözəlliklərlə doludur… Hər bir çiçəkdə, hər bir küləyin pıçıltısında, səmanın rəngində bir hikmət gizlənib. Bu gözəllik sanki insan ruhuna verilmiş səssiz bir əmanətdir. Amma təəssüf ki, bəzən insan öz əli ilə bu harmoniyanı pozur, alovların içində yalnız torpağı deyil, həm də ümidləri, taleləri, xatirələri yandırır.","Müharibə yalnız torpaqları deyil, insanın içindəki işığı da zədələyir. Hər itirilən həyat, əslində, dünyanın bir parçasının susması deməkdir. Halbuki insanın varlıq səbəbi dağıtmaq deyil, qorumaq, yaratmaq və yaşatmaqdır.","Bəlkə də, ən böyük sual budur: insan nə vaxt öz gücünü məhv etməkdə deyil, yaşatmaqda tapacaq? Nə vaxt Yer üzü sükutun deyil, sülhün səsi ilə dolacaq? Bəlkə, o zaman dünya yalnız gözəl olmayacaq — həm də dəyər verilən bir məkan olacaq.","İbrət: İnsanlıq həyatı qorumaqla, sülhə və yaxşılığa xidmət etməklə ucalır. Gücümüzü yaşatmağa sərf etdikcə dünya hamımız üçün daha gözəl bir yerə çevrilər.","Etibar Siracsoy"]},{"stem":"belling-the-cat","title":"Pişiyin boynundan asılacaq zınqırov","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün siçanlar yığışıb məsləhətləşdilər: onlara dinclik verməyən pişikdən necə qorunsunlar?","Hərə bir fikir söylədi, amma heç birini münasib bilmədilər. Nəhayət, cavan bir siçan dilləndi: — Gəlin pişiyin boynundan zınqırov asaq! O yaxınlaşan kimi səsini eşidib gizlənərik. Daha bizi qəfil yaxalaya bilməz.","Siçanlar sevincək bir-birinə baxdılar. Nə gözəl fikirdi! Bunu indiyədək necə düşünməmişdilər? Hamı cavan siçanı alqışladı.","Səs-küy bir qədər səngiyəndə küncdə oturub söhbətə qulaq asan qoca siçan sözə başladı: — Yaxşı fikirdir. Boynunda zınqırov olsa, pişik bizə xəbərsiz yaxınlaşa bilməz. Amma bir məsələ qalıb: zınqırovu onun boynundan kim asacaq?","Bir anın içində hamı susdu. Heç kimdən səs çıxmadı.","İbrət: Yaxşı fikir söyləmək hələ işin yarısıdır. Bir planı alqışlamazdan əvvəl onu kimin və necə həyata keçirəcəyini də düşünmək lazımdır."]},{"stem":"lambs-skins","title":"Quzuların dərisi","hasAudio":false,"hasImage":true,"paragraphs":["«Quzuların dərisini soymaqdansa, qoçların yununu qırxmaq yaxşıdır.»","Bu deyim Osmanlı dövründə Dəməşq valisi olmuş Azmzadə Əsəd Paşanın adı ilə bağlı bir rəvayətdə işlənir.","Deyilənə görə, bir gün xəzinənin boşaldığını görən Əsəd Paşa müşavirlərini yanına çağırıb çıxış yolu axtarır. Onlar Dəməşqdəki toxucuların üzərinə əlavə vergi qoymağı təklif edirlər.","— Bu vergidən nə qədər gəlir əldə edə bilərik? — deyə Paşa soruşur.","— Əlli-altmış kisə qızıl, — deyə cavab verirlər.","— Axı bu adamlar onsuz da güclə dolanırlar. Vergini nə ilə ödəyəcəklər?","— Evlərindəki qızılı, zinət əşyalarını satarlar, Paşa.","Əsəd Paşa bu təkliflə razılaşmır:","— Mən həmin pulu başqa yolla taparam.","Ertəsi gün müftiyə xəbər göndərib onu gecə gizli görüşə çağırır. Müfti gələndə Paşa deyir:","— Müfti əfəndi, bizə məlumat çatıb ki, evinizdə gizlicə içki içirsiniz. Bu, tutduğunuz vəzifəyə və müdafiə etdiyiniz qaydalara ziddir. Məsələni İstanbula bildirməliyəm. Amma əvvəlcə sizinlə danışmaq istədim.","Müfti təşvişə düşüb yalvarmağa başlayır. Xəbərin İstanbula çatmaması üçün min qızıl pul təklif edir. Paşa razılaşmır. Müfti məbləği ikiqat artırır, amma yenə rədd cavabı alır. Nəhayət, altı min qızıl pula razılaşırlar.","Sonrakı gün Paşa qazını yanına çağırır:","— Qazı əfəndi, etibarlı mənbələrdən öyrənmişik ki, rüşvət alır, vəzifənizdən şəxsi qazancınız üçün istifadə edirsiniz.","Qazı da vəzifəsini və nüfuzunu itirməkdən qorxaraq yalvarmağa başlayır:","— Məni vəzifəmdən uzaqlaşdırmayın, əfəndim. El içində rüsvay olaram.","Uzun sövdələşmədən sonra o da altı min qızıl pul verməyə razı olur.","Ardınca Paşa xəzinədarı, asayiş rəisini, tacirləri və başqa varlı adamları bir-bir yanına çağırır. Rəvayətə görə, bu yolla iki yüz kisə qızıl toplayır.","Sonra müşavirlərini yenidən çağırıb soruşur:","— Dəməşq əhalisinə əlavə vergi qoyduğumu eşitmisinizmi?","— Xeyr, Paşa.","— Amma mən əlli deyil, iki yüz kisə qızıl toplamışam.","— Bunu necə bacardınız?","Paşa cavab verir:","— Quzuların dərisini soymaqdansa, qoçların yununu qırxmaq yaxşıdır.","İbrət: Ədalət gücsüzün son tikəsinə əl uzatmaq deyil, yükü insanların imkanına uyğun bölməkdir. Haqsız qazanca görə isə gizli sövdələşmə ilə deyil, hamıya eyni qaydada tətbiq olunan qanun əsasında hesab soruşulmalıdır."]},{"stem":"land-and-homeland","title":"Vətən və torpaq","hasAudio":false,"hasImage":true,"paragraphs":["Torpağa su qatsan, palçıq olar; uğrunda qan tökülsə, Vətən olar.","İbrət: Vətən sadəcə yaşadığımız yer deyil; onu qoruyanların fədakarlığını və xatirəsini yaşadan, bizə əmanət edilmiş yurddur. Bu əmanətə sahib çıxmaq həm keçmişi unutmamaq, həm də gələcək nəsillər üçün əmin-amanlıq içində bir həyat qurmaqdır."]}]},{"title":"Yaşlanma və zaman","slug":"yaslanma-ve-zaman","blurb":"Ömrün fəsilləri və zamanın dəyişdirdikləri.","count":4,"stories":[{"stem":"what-changed-after-sixty","title":"Altmışdan sonra nə dəyişdi?","hasAudio":false,"hasImage":true,"paragraphs":["Altmışı keçib yetmişə yaxınlaşan bir dostumdan yaşa dolduqca özündə hansı dəyişiklikləri hiss etdiyini soruşdum. Belə cavab verdi:","Yaşlılara «Bu əhvalatı artıq danışmısan» demirəm. Qoy danışsınlar. Bəzən bir xatirəni bölüşmək onlara ömrün gözəl anlarını yenidən yaşadır.","Hər səhvi düzəltməyə çalışmıram. Hamını qüsursuz etmək mənim vəzifəm deyil. Könül rahatlığı çox vaxt hər şeyin mükəmməl olmasından daha qiymətlidir.","Xoş sözümü əsirgəmirəm. Səmimi bir iltifat həm qarşımdakı insanın, həm də mənim könlümü açır.","Geyimimdəki kiçik bir qırışığı, bir ləkəni dərd etmirəm. Səliqəli olmaq yaxşıdır, amma insanın dəyəri təkcə görünüşü ilə ölçülmür.","Məni daxilən yoran münasibətlərdən uzaq durmağı öyrəndim. Hər kəslə yaxın olmaq məcburiyyətində deyiləm; qarşılıqlı hörmət və anlayış olan münasibətlərin qədrini bilirəm.","Duyğularımdan utanmıram. Sevinmək də, kövrəlmək də, darıxmaq da insan olmağın bir parçasıdır.","Münasibəti qorumaq üçün yersiz qürurumdan keçməyi öyrəndim. Hər dəfə haqlı çıxmaq insanı xoşbəxt etmir; bəzən bir addım yaxınlaşmaq daha dəyərlidir.","Mənə sevinc verən şeylərə vaxt ayırıram. Öz xoşbəxtliyimin qayğısını da çəkməli olduğumu başa düşmüşəm.","Kömək etməzdən əvvəl buna ehtiyac və istək olub-olmadığını soruşuram. Yaxşı niyyətim başqasının seçiminə hörmət etməyimə mane olmamalıdır.","Sağlamlığımdan, qonşularımdan, qohumlarımdan, təqaüddə olmağımdan durmadan şikayət etmirəm. Çətinlikləri görməzdən gəlmirəm, amma yaşadığıma, sevdiklərimin yanımda olduğuna da şükür edirəm.","Gənclərə «Mən sənin yaşında olanda...» deyib öz həyatımı nümunə göstərməyə tələsmirəm. «Ən yaxşı illərimi sənə verdim» deyərək heç kimi borclu çıxarmıram. Hər dövrün öz şərtləri var; bu günü yalnız keçmişin ölçüsü ilə ölçmək olmaz.","Həyat yoldaşıma daha çox diqqət göstərirəm. Onun bir vaxtlar necə gənc, güclü və şən olduğunu unutmuram. İndi illərin yorğunluğunu daşıyırsa, qayğıma daha çox ehtiyac duyursa, yanında olmağa çalışıram. Birlikdə keçirdiyimiz ömrün qədrini bilirəm.","Hər şeyə görə özümü qınamaqdan əl çəkmişəm. Səhvlərim də olub, amma həm özüm, həm də övladlarım üçün bacardığım qədər çalışmışam. Keçmişdən dərs alıram, özümü onunla cəzalandırmıram.","Və nəhayət, Rəbbimdən dəyişdirə biləcəklərim üçün güc, dəyişdirə bilməyəcəklərim üçün səbir, bunları bir-birindən ayırmaq üçün isə hikmət diləməyi öyrənmişəm. İnsan olduğumu, hər şeyə gücüm çatmadığını qəbul edirəm.","İbrət: Yaşa dolduqca anlayırsan ki, dinclik mükəmməllikdən, anlayış isə hər dəfə haqlı çıxmaqdan daha qiymətlidir. Ömrü gözəlləşdirən özünə və başqalarına mərhəmətlə yanaşmağı bacarmaqdır."]},{"stem":"life-after-sixty","title":"Altmışı haqlayanlara","hasAudio":false,"hasImage":true,"paragraphs":["Altmış yaş həyatın kənarına çəkilmək vaxtı deyil. Bəlkə də, illərlə təxirə saldığın istəklərə yer açmaq, özünə daha çox qayğı göstərmək zamanıdır.","Zəhmətlə qazandığın imkanlardan özün üçün də istifadə et. Gələcək ehtiyaclarını nəzərə alaraq rahatlığına, sevincinə və çoxdan arzuladığın şeylərə pay ayır. Hər şeyi başqalarına saxlamaq üçün özünü hər şeydən məhrum etmə.","Övladlarını, nəvələrini sevməyə və bacardığın qədər dəstəkləməyə davam et. Amma onların bütün qayğılarını öz çiyinlərinə yükləmə. Böyümüş övladlarına öz qərarlarını vermək, məsuliyyət daşımaq və yollarını tapmaq üçün yer ver. Özünə ayırdığın vaxt və imkan səni daha az qayğıkeş etmir.","Bədəninə diqqətlə yanaş. Gücünə və sağlamlığına uyğun hərəkət et, gəz, dincəl. Sağlamlığınla bağlı ehtiyacların barədə həkiminlə danış, müayinələrini onunla birlikdə planlaşdır. Nə özünü gərəksiz yerə yüklə, nə də yaşını bəhanə edib sevdiyin məşğuliyyətlərdən uzaqlaş.","Özünə baxmağı unutma. Təmiz, rahat, zövqünə uyğun geyin. Səliqəni başqalarının bəyənməsi üçün deyil, özünü yaxşı hiss etmək üçün qoru. Yaşın sənin üslubunu və rənglərini əlindən almasın.","Marağını və öyrənmək həvəsini yaşat. Kitab oxu, musiqi dinlə, yeni bir şey öyrən. İstəsən, texnologiyadan yaxınlarınla əlaqə saxlamaq və dünyanı tanımaq üçün istifadə et. Hər yeniliyin ardınca qaçmaq məcburiyyətində deyilsən; sənə fayda və sevinc verəni seç.","Gəncləri dinlə. Onların həyatını öz keçmişinin ölçüsü ilə qiymətləndirmə. Təcrübəni bölüş, amma nəsihət verməzdən əvvəl onların fikrini də soruş. Bəzən sənin onlara öyrədəcəyin qədər onların da sənə öyrədəcəyi var.","“Bizim vaxtımızda…” deyəndə unutma: indi də sənin vaxtındır. Xatirələrin keçmişdə olsa da, həyatın bu gün davam edir.","Sənə hörmət edən, yanında özün ola bildiyin insanlarla münasibətlərini qoru. Başqalarının dərdinə şərik ol, amma səni daim alçaldan və tükəndirən münasibətlərə sərhəd qoy.","Həvəs göstərdiyin işlərdən əl çəkmə. Bağçılıq et, yemək bişir, yaz, rəqs et, səyahətə çıx — imkanın və istəyin nədirsə, ona yer ayır. Böyük planların olmadığı günlərdə də kiçik sevinclər tapmaq olar.","İmkan olduqca evdən çıx. Bir dostla görüş, parkda otur, sərgiyə get. Çölə çıxmaq çətindirsə, bir telefon zəngi, evdə içilən bir stəkan çay da yaxınlıq yarada bilər. Həyatla əlaqəni özünə uyğun yollarla qoru.","İncikliklərini yüngülləşdirməyə çalış. Qəlbini qırdığın insandan üzr istə. Bağışlamağa hazır olmaq isə vaxt ala bilər; özünü tələsdirmə. Bağışlamaq hər şeyi unutmaq və ya səni incidən münasibətə qayıtmaq demək deyil.","Kədərlənəndə danış, köməyə ehtiyacın olanda istə. Həmişə güclü, həmişə gülərüz görünməyə borclu deyilsən.","Sev, gül, maraqlan, plan qur. Özünə yalnız dincəlməyə deyil, yenidən başlamağa da icazə ver. Ömrünün bu çağını başqalarının gözləntilərinə görə deyil, öz dəyərlərinə və imkanlarına uyğun yaşa.","İbrət: Özünə qayğı göstərmək üçün başqalarına sevgini azaltmaq lazım deyil. Yaşın neçə olursa olsun, vaxtının, rahatlığının və arzularının dəyəri var. Bu gün də sənin həyatındır."]},{"stem":"aging","title":"Yaşa dolmaq","hasAudio":false,"hasImage":true,"paragraphs":["Yaşa dolmaq dağa qalxmağa bənzəyir: yüksəldikcə addımların ağırlaşır, nəfəsin təngiyir, amma qarşında daha geniş mənzərə açılır.","İbrət: İllər keçdikcə gücümüz azala bilər, amma qazandığımız təcrübə bizə daha uzağı görməyi, həyatı daha dərindən anlamağı öyrədir."]},{"stem":"life-flows-silently","image":"wisdom-stories/Etibar%20Siracsoy/Illustrations/life-flows-silently.webp","title":"Zaman — səssiz axan ömür","hasAudio":false,"hasImage":true,"paragraphs":["Zaman qəribə bir möcüzədir... Onu nə görmək, nə tutmaq, nə də geri qaytarmaq mümkündür. O, səssizcə keçir — saatların əqrəblərində, günlərin dəyişməsində, saçlara düşən ağlarda, uşaqların böyüməsində, xatirələrin uzaqlaşmasında...","İnsan çox vaxt zamanı yalnız itirdikdən sonra dərk edir. Dünən adi görünən bir gün illər keçəndən sonra ən qiymətli xatirəyə çevrilir. Bir vaxtlar əhəmiyyətsiz hesab etdiyimiz bir söhbət, bir baxış, bir gülüş, sevdiyimiz insanla keçirdiyimiz sadə bir axşam sonralar həyatımızın ən gözəl anlarından birinə çevrilə bilir.","Zaman heç kim üçün dayanmır. Nə var-dövlətə, nə şöhrətə, nə də insanın istəyinə boyun əyir. O, hamıya eyni ölçüdə verilən, lakin hər kəs tərəfindən fərqli qiymətləndirilən ən böyük sərvətdir. İnsanın ömrü, əslində, illərlə deyil, yaşadığı mənalı anlarla ölçülür.","Bəzən düşünürük ki, həyat qarşıdadır və hələ çox vaxtımız var. Sabah edərik, gələn həftə gedərik, bir gün danışarıq, sonra görüşərik... Amma “sonra” dediyimiz zaman heç də həmişə gəlmir.","Zaman bizdən çox şey aparır: gəncliyimizi, bəzi insanları, bəzi arzuları, bəzi fürsətləri... Amma əvəzində bizə xatirələr, təcrübə və həyatın həqiqi mənasını anlamaq imkanı verir.","Ona görə zamanı sadəcə keçən illərlə ölçməyək. Vaxtımızı nə qədər yaşadığımızla deyil, necə yaşadığımızla qiymətləndirək. Sevdiklərimizə sevgimizi bu gün söyləyək. Dostlarımızla görüşməyi sonraya saxlamayaq. Gözəl mənzərələrə baxaq, günəşin doğuşunu seyr edək, dənizin səsini dinləyək, ürəyimizi sevindirən anları yaşayaq.","Çünki zaman keçir...","İbrət: Sevgimizi bildirməyi, doğmalarımıza vaxt ayırmağı sonraya saxlamayaq. Ötən an geri qayıtmır, bu günün qədrini elə bu gün bilmək lazımdır.","Etibar Siracsoy"]}]},{"title":"Təmsillər və məsəllər","slug":"temsiller-ve-meseller","blurb":"Heyvanlar və obrazlarla öyrədən məsəllər.","count":8,"stories":[{"stem":"lions-tracks","title":"Aslanın izi","hasAudio":false,"hasImage":true,"paragraphs":["Qorxaq, amma lovğalanmağı sevən bir ovçu aslan axtara-axtara meşəyə gəlib çıxır. Qarşısına çıxan odunçudan soruşur:","— Qardaş, buralarda aslan görməmisən? Heç olmasa, izinə rast gəlmisən?","Odunçu cavab verir:","— Aslanın özünü görmüşəm. İstəsən, gəl, səni olduğu yerə aparım.","Ovçunun rəngi qaçır:","— Yox, yox, sağ ol! Mən aslanın özünü yox, sadəcə izini axtarırdım.","İbrət: Cəsarət sözdə deyil, sınaq anında üzə çıxır. Lovğalıqla yaradılan qəhrəman obrazı ilk çətinlikdə dağıla bilər."]},{"stem":"donkeys-law","title":"Eşşəyin qanunu","hasAudio":false,"hasImage":true,"paragraphs":["Bir gün eşşək meşənin şahı oldu. Taxta çıxandan bir neçə gün sonra fərman verdi:","— Hamı axşam saat altıda yatmalı, səhər saat altıda oyanmalıdır. Bu on iki saat ərzində meşədə bir səs belə eşidilməməlidir. Qanunu pozan cəzalandırılacaq!","Heyvanlar təəccüblənsələr də, etiraz etmədilər. Axşam düşən kimi meşəni sükut bürüdü.","Bir səhər xoruz saat beşdə banladı. Meşəyə çaxnaşma düşdü. Xoruzu dərhal məhkəməyə çıxardılar və şahın hökmü ilə edam etdilər.","Bundan sonra heç kim qanunu pozmağa cürət etmədi. Hamı həyatını eşşəyin müəyyən etdiyi saatlara uyğunlaşdırdı.","İllər keçdi. Eşşək qocaldı, taqətdən düşdü. Ömrünün son günlərində şir onu görməyə gəldi. Halını soruşandan sonra dedi:","— İllərdir bir sual bizi düşündürür: hamının axşam altıda yatıb səhər altıda oyanmasının hikməti nə idi? Dəfələrlə bu qanuna qarşı çıxmaq istədik. Amma asayiş pozular deyə çəkindik. Düşündük ki, yəqin, sənin bildiyin, bizim anlamadığımız bir şey var.","Eşşək acı-acı gülümsədi:","— Heç bir hikməti yox idi. Eşşəkliyimdən elə bir qanun çıxarmışdım. Məni təəccübləndirən o oldu ki, siz illərlə mənim ağılsızlığımda hikmət axtardınız.","Şir susdu. Eşşək sözünə davam etdi:","— Əvvəlcə məndən qorxdunuz. Sonra öyrəşdiniz. Axırda isə başqa cür yaşamağın mümkün olduğunu unutdunuz.","İbrət: Hər əmrin arxasında hikmət, hər köhnə qaydanın arxasında ağlabatan səbəb olmur. Qorxu ilə qəbul edilən bir qayda zamanla vərdişə, vərdiş isə sorğulanmayan həqiqətə çevrilə bilər. “Bu qayda nəyə xidmət edir?” sualını unutma."]},{"stem":"elephant-and-the-rope","title":"Fil və ip","hasAudio":false,"hasImage":true,"paragraphs":["Bir rəvayətdə deyilir ki, səyyah fillərin saxlandığı bir yerdən keçərkən qəribə mənzərə ilə qarşılaşdı: nəhəng heyvanların hər biri ön ayağından nazik bir iplə qazığa bağlanmışdı. Nə zəncir vardı, nə də qəfəs.","Səyyah düşündü: “Bu qədər güclü heyvanlar istəsələr, ipi asanlıqla qıra bilərlər. Bəs niyə heç cəhd etmirlər?”","Yaxınlıqdakı təlimçidən bunun səbəbini soruşdu.","Təlimçi dedi:","— Balaca olanda onları belə bir iplə bağlayırıq. Nə qədər dartınsalar da, qıra bilmirlər. Bir müddət sonra cəhd etməkdən vaz keçirlər. Böyüyəndə gücləri artır, amma ipi qıra bilməyəcəklərinə inamları dəyişmir.","Səyyah yenidən fillərə baxdı. Onları yerində saxlayan təkcə ayaqlarındakı ip deyildi; keçmişdə bacarmadıqları işi bu gün də bacarmayacaqlarına inanmaları idi.","İbrət: Dünən bacarmadığın bir şeyi bu gün də bacarmayacağını düşünmə. Təcrübən, gücün və imkanların dəyişə bilər. Keçmiş uğursuzluğu gələcəyinin sərhədinə çevirmə."]},{"stem":"two-donkeys","title":"İki uzunqulaq","hasAudio":false,"hasImage":true,"paragraphs":["İki uzunqulaq yolla gedərkən ağacda oturmuş bir meymun görür. Biri o birinə deyir:","— Gəl bu meymuna sataşaq. Soruşaq ki, dostun varmı? «Var» desə, deyərik: «Hansı axmaq səninlə dostluq edir?» «Yoxdur» desə, deyərik: «Hansı axmaq səninlə dost olar ki?»","Ağaca yaxınlaşıb səslənirlər:","— Meymun, sənin dostun varmı?","Meymun yuxarıdan onlara baxıb cavab verir:","— Hara baxıram, ancaq eşşək görürəm. Kimlə dostluq edim?","İbrət: Başqasını gülünc vəziyyətə salmaq istəyən bəzən özü gülüş hədəfinə çevrilir. İnsan başqasını alçaltmaqla ucalmaz."]},{"stem":"fly-in-a-china-shop","title":"Milçək çini qablar dükanında","hasAudio":false,"hasImage":true,"paragraphs":["Bir milçək çini qablarla dolu dükanı dağıtmaq istəsə, buna gücü çatmaz. Amma dükanın içindəki öküzün qulağına girib onu təlaşa salsa, öküz sağa-sola çırpınaraq hər şeyi sındıra bilər.","Bu bənzətmədə milçək yalanı, mövhumatı və qərəzi təmsil edir. Öküz isə eşitdiyini düşünmədən qəbul edən, qəzəbinin və qorxusunun təsiri ilə hərəkətə keçən insanı.","Bəzən böyük dağıntını yaradan yalanın öz gücü deyil, ona inananın düşünmədən işə saldığı gücdür.","İbrət: Eşitdiyin hər sözün ardınca getmə. Mənbəyini yoxla, doğruluğunu araşdır, sonra qərar ver. Başqasının yalanı sənin əlinlə zərərə çevrilməsin."]},{"stem":"lions-untold-story","title":"Ovçunun vəsfi","hasAudio":false,"hasImage":true,"paragraphs":["Aslan yazmağı öyrənənədək bütün hekayələr ovçunu tərifləyəcək.","— Afrika atalar sözü kimi tanınan deyim","İbrət: Hekayəni danışan çox vaxt özünü qəhrəman göstərir. Həqiqəti anlamaq üçün yalnız danışanın deyil, səsi eşidilməyənin də tərəfini dinlə. Öz yaşadıqlarını dilə gətirməsən, sənin hekayəni başqaları öz baxışlarına görə yazar."]},{"stem":"ant-carrying-water","title":"Su daşıyan qarışqa","hasAudio":false,"hasImage":true,"paragraphs":["Rəvayətə görə, zalım hökmdar Nəmrud İbrahim peyğəmbəri oda atdırmaq üçün meydanın ortasında nəhəng bir tonqal qalatdırdı. Alov getdikcə yüksəlir, bütün canlılar dözülməz istidən uzaqlaşmağa çalışırdı.","Təkcə balaca bir qarışqa oda doğru tələsirdi. Ağzında bir damla su aparırdı.","Başqa bir qarışqa onu səslədi: — Hara gedirsən? O boyda alovu görmürsən?","— Nəmrud İbrahim peyğəmbəri yandırmaq istəyir. Odu söndürməyə su aparıram.","— Bir damla su ilə? — o biri qarışqa istehza ilə soruşdu. — O damla heç közə çatmamış buxarlanacaq! Bununla nəyi dəyişə bilərsən?","Su daşıyan qarışqa bir anlıq dayandı: — Bəlkə, bu damla tonqalı söndürməz. Amma heç olmasa, kimin tərəfində olduğum bəlli olar.","Bunu deyib yoluna davam etdi.","İbrət: Zülmün qarşısını almağa hər zaman gücümüz çatmaya bilər. Amma ona laqeyd qalmamaq öz əlimizdədir. Darda olanın müdafiəsi üçün atılan ən kiçik addımın da dəyəri var."]},{"stem":"tortoises-miscalculation","title":"Tısbağanın yanlış hesabı","hasAudio":false,"hasImage":true,"paragraphs":["Tısbağadan soruşdular:","— Yaxınlıqdakı kəndə nə qədər vaxta çatarsan?","— Yağışı, palçığı, küləyi, eniş-yoxuşu nəzərə alsaq, üç günlük yoldur. Amma ehtiyat üçün altı gün deyək, — deyə tısbağa cavab verdi.","Altı gün keçdi, tısbağa isə kəndə çatmadı. Onu axtarmağa çıxdılar və yolun yarısında tapdılar.","— Nə olub? Üç günlük yolu altı günə də gələ bilməmisən? — deyə təəccüblə soruşdular.","Tısbağa pərişan halda cavab verdi:","— Heç soruşmayın, dostlar. Yağışı da, palçığı da, küləyi də, eniş-yoxuşu da hesablamışdım. Bir pis niyyətli adamları unutmuşdum. Hər dəfə bir az sürət yığanda məni tutub arxam üstə çevirirdilər.","İbrət: Yolumuzu təkcə çətin şərait deyil, başqalarının pis niyyəti də kəsə bilər. Allah qarşına səni yıxanları deyil, yıxılanda əlindən tutanları çıxarsın."]}]},{"title":"Tarix və tanınmış şəxsiyyətlər","slug":"tarix-ve-taninmish-shexsiyyetler","blurb":"Tarixdən və tanınmış adlardan ibrət.","count":5,"stories":[{"stem":"albrecht-durer","title":"Albrext Dürer","hasAudio":false,"hasImage":true,"paragraphs":["Albrext Dürer haqqında rəvayət","Deyilənə görə, Nürnberq yaxınlığında yaşayan kasıb, çoxuşaqlı bir ailədə iki qardaş böyüyürdü: Albrext və Albert. Hər ikisi rəssam olmaq arzusunda idi. Səhərdən axşamadək çalışan atalarının isə onları oxutmağa imkanı çatmırdı.","Qardaşlar gecələr şam işığında uzun-uzadı söhbət edir, arzularına yol axtarırdılar. Axırda püşk atmağa qərar verdilər. Birinə oxumaq, o birinə isə mədəndə işləyib qardaşının təhsil xərcini ödəmək düşəcəkdi. Dörd ildən sonra yerlərini dəyişəcəkdilər.","Püşk Albrextə düşdü.","O, rəssamlığı öyrənməyə yollandı, Albert isə mədəndə işə başladı. Biri fırça tutmağın incəliklərini öyrənir, rənglərin dünyasına baş vururdu. Digəri hər gün yerin dərinliklərinə enir, ağır zəhməti ilə qardaşının təhsilini davam etdirməsinə kömək edirdi.","Dörd il keçdi. Albrextin istedadı diqqət çəkdi, əsərləri ona ad-san və qazanc gətirməyə başladı. Evə qayıdanda qardaşını qucaqlayıb sevinclə dedi: — İndi növbə sənindir, Albert. Get, oxu, arzunu gerçəkləşdir. Sən mənə dayaq oldun, indi də mən sənə dayaq olacağam.","Albert isə başını yavaşca buladı: — Yox, qardaşım… Mənim üçün artıq gecdir.","O, əllərini uzatdı. Ovucları qabar bağlamış, barmaqları ağır işdən əyilmişdi. — Bu əllər daha əvvəlki kimi fırça tuta bilməz.","Albrext qardaşının əllərini ehtiyatla ovuclarına aldı. Nəsə demək istədi, amma söz tapa bilmədi. Göz yaşları Albertin yorğun əllərinə damladı.","Öz arzusuna çatmağın qardaşına nəyin bahasına başa gəldiyini yalnız indi bütün ağırlığı ilə anladı.","Rəvayətdə Dürerin məşhur “Dua edən əllər” rəsmi bu fədakarlıqla əlaqələndirilir. O əllər qardaş sevgisinin, minnətdarlığın və başqasının uğuru naminə çəkilən səssiz zəhmətin rəmzi kimi təqdim olunur.","İbrət: Uğurlarımızda vaxtını, gücünü və imkanlarını bizdən əsirgəməyən insanların da payı var. Onların fədakarlığını görmək, unutmamaq və qayğılarına qayğı ilə cavab vermək əsl minnətdarlıqdır."]},{"stem":"sinans-waterless-house","title":"Memar Sinanın susuz evi","hasAudio":false,"hasImage":true,"paragraphs":["Memar Sinan haqqında rəvayət","Qanuni Sultan Süleymanın dövründə İstanbul sürətlə böyüyür, şəhərdə su çatışmazlığı getdikcə artırdı. Rəvayətə görə, bir gün sultan Memar Sinanı hüzuruna çağırıb soruşdu: — Xalq suyu baha qiymətə alır, böyük əziyyət çəkir. İstanbulu bu darlıqdan qurtarmağın bir yolu varmı?","Sinan şəhərin ətrafını araşdırmaq üçün vaxt istədi. Köməkçiləri ilə bulaqları, çay yataqlarını və dərələri gəzdi, suyu şəhərə çatdırmağın yollarını axtardı.","Sonra sultanın yanına qayıdıb dedi: — Su gətirmək mümkündür. Amma bu iş böyük zəhmət və çoxlu vəsait tələb edəcək.","— Təki mümkün olsun, — sultan cavab verdi. — Lazım olan vəsait ayrılacaq.","Sinan işə başladı. Zamanla qurduğu su kəmərləri və tağlı körpülərlə şəhərin çeşmələrinə su gəldi. Əvvəllər hər damlası əziyyətlə əldə olunan su indi insanların gündəlik ehtiyacını ödəyirdi.","Sultan ümumi suyun qorunmasını əmr etmiş, icazəsiz olaraq evlərə ayrıca xətt çəkilməsini qadağan etmişdi. Sinana isə xidmətinin əvəzində bir istisna etdi: evinə su çəkdirməsinə şifahi icazə verdi.","İllər keçdi. Sultan Süleyman dünyadan köçdü. Onun verdiyi icazəni xatırlayan adamlar da getdikcə azaldı.","Bir gün ahıl memarı saraya çağırdılar. Divana şikayət olunmuşdu: başqalarına qadağan olduğu halda, niyə Sinanın evinə ayrıca su gəlirdi?","— Bu, Sultan Süleymanın icazəsi ilə olub, — Sinan izah etdi.","— Yazılı fərmanın varmı?","Sinan sakitcə cavab verdi: — Yoxdur. Sultanın sözünü yetərli bildim. Ondan bir də yazılı sənəd istəməyə çəkindim.","Uzun müzakirədən sonra qərar verdilər: əvvəlki istifadəsinə görə memar cəzalandırılmasın, amma evinə gələn su kəsilsin.","Rəvayətə görə, ömrünün son günlərində ağır xəstələnən Sinan qurumuş dodaqlarını islatmaq üçün su istədi. Lakin evinin kranından su gəlmirdi.","Onda bir şəhəri suya qovuşduran memar asta səslə dedi: — Biz bu işi öz mənfəətimiz üçün deyil, Allah rizası üçün gördük. Mükafatını da Ondan gözləyirik. Evimizdə su olmasa da, çəkdiyimiz zəhmət xalqa xidmət edir.","İbrət: İnsanlar onlara edilən yaxşılığı unuda bilərlər, amma bu, görülən yaxşılığın dəyərini azaltmır. Təmənnasız xidmət etmək insanın ucalığı, ona xidmət edənləri unutmamaq isə cəmiyyətin borcudur."]},{"stem":"mihrimah-and-sinan","title":"Mihrimah Sultan və Memar Sinan","hasAudio":false,"hasImage":true,"paragraphs":["İstanbulun iki məscidini birləşdirən gözəl bir rəvayət var: Mihrimah Sultanla Memar Sinanın hekayəsi.","Qanuni Sultan Süleymanın qızı Mihrimahın adı fars mənşəlidir: «mihr» günəş, «mah» isə ay deməkdir.","Rəvayətə görə, Mihrimah on yeddi yaşına çatanda onunla evlənmək istəyən iki nəfər vardı: Rüstəm Paşa və Memar Sinan. Lakin şahzadə Rüstəm Paşa ilə evləndi. Bu evlilik 1539-cu ildə baş tutmuşdu.","Əfsanəyə görə, o vaxt artıq evli və əlli yaşına yaxın olan Sinan sevgisini qəlbində saxladı. Sevdiyinə qovuşa bilməyən memar duyğularını sənətində yaşatdı.","Sinan əvvəlcə Üsküdarda Mihrimah Sultanın adını daşıyan məscidi inşa etdi. Sonra Ədirnəqapıda onun adına ikinci məscid ucaltdı. Bu iki abidə həqiqətən də Sinanın əsərləridir; onları gizli bir məhəbbətin ifadəsi saymaq isə rəvayətin yozumudur.","Rəvayəti danışanlar Üsküdardakı məscidin siluetində ətəkləri yerə süzülən bir qadın görürlər. Ədirnəqapıdakı məscidin incə minarəsində, işıqlı məkanında və zərif bəzəklərində isə Mihrimahın gözəlliyini axtarırlar. Hətta bəzi naxışları onun uzun saçlarına bənzədirlər.","Hekayənin ən yaddaqalan hissəsi Günəşlə Ayın görüşüdür.","Deyilənə görə, İstanbulda elə bir nöqtə var ki, oradan baxanda Günəş Ədirnəqapıdakı məscidin arxasında batarkən Ay Üsküdardakı məscidin arxasından doğur. Rəvayət bu mənzərəni bahar gecə-gündüz bərabərliyi ilə bağlayır və onu Sinanın sevdiyinə ünvanladığı səssiz bir etiraf kimi təsvir edir.","Mihrimah — Günəş və Ay…","Sinan bu mənzərəni qəsdən yaratmışdı, yoxsa insanlar sonradan onun sənətinə belə bir məna vermişdilər? Bunu təsdiqlənmiş tarix kimi söyləmək mümkün deyil.","Amma rəvayət yaşayır. İki məscidə baxan insan yalnız daş, günbəz və minarə görmür; bəzən orada sözə çevrilməmiş bir duyğunun izini də axtarır.","İbrət: Hər sevgi qovuşmaqla tamamlanmır. İnsan duyğularını yaradıcılığa yönəltdikdə, onlar başqalarına da gözəllik bəxş edən bir əsərdə yaşaya bilər."]},{"stem":"remarkable-lesson","title":"Möhtəşəm dərs","hasAudio":false,"hasImage":true,"paragraphs":["Osmanlı padşahı II Muradla oğlu Mehmed haqqında belə bir rəvayət danışılır.","Gələcəyin Fateh Sultan Mehmedi uşaq vaxtı dərsdə sakit oturmaz, tez-tez dəcəllik edərmiş. Müəllimi Ağşəmsəddin ona irad bildirəndə isə deyərmiş:","— Sən mənə heç nə deyə bilməzsən. Mən padşah oğluyam!","Ağşəmsəddin şahzadənin bu davranışından narahat idi. Əvvəlcə padşaha şikayət etməyə çəkinsə də, bir gün cəsarətini toplayıb onun hüzuruna çıxdı və vəziyyəti danışdı.","II Murad bir qədər düşündü, sonra ağlına gələn planı müəllimin qulağına pıçıldadı. Ağşəmsəddin etiraz etdi:","— Padşahım, mən bunu edə bilmərəm!","Lakin hökmdar qərarından dönmədi:","— Oğlumun dərs alması üçün bunu etməliyik.","Ertəsi gün şahzadə yenə dərsi pozdu. Müəllimin xəbərdarlığına da həmişəki cavabı verdi:","— Mən padşah oğluyam!","Elə bu vaxt qapı açıldı və II Murad sinfə girdi.","Əvvəlcədən razılaşdıqları kimi, Ağşəmsəddin qəzəblənmiş görkəm alıb padşaha tərəf döndü. İcazəsiz içəri girdiyinə görə onu danladı, hətta bir şillə vurub sinifdən çıxmasını tələb etdi.","Padşah başını aşağı saldı, üzr istəyib çıxdı.","Mehmed heyrətdən donub qalmışdı. Hamının qarşısında baş əydiyi atası müəllimin iradını qəbul etmiş, sinfin qaydasına tabe olmuşdu.","Bir az sonra qapı döyüldü. II Murad bu dəfə içəri girmək üçün icazə istədi və yenidən üzr istədi.","Rəvayətə görə, həmin gündən şahzadənin dərsdə davranışı dəyişdi. Atası ona uzun nəsihətlə deyil, öz nümunəsi ilə göstərmişdi ki, padşah oğlu olmaq insana başqalarına hörmətsizlik etmək haqqı vermir.","İbrət: Tərbiyədə şəxsi nümunə uzun nəsihətdən təsirlidir. Valideynin nüfuzu özünü qaydalardan üstün tutmasında deyil, övladından gözlədiyi hörmət və məsuliyyəti öz davranışında göstərməsindədir."]},{"stem":"three-essentials-for-a-city","title":"Şəhər üçün üç vacib şey","hasAudio":false,"hasImage":true,"paragraphs":["Hər şəhərə üç şey lazımdır: kanalizasiya, hamam və kitabxana. Kanalizasiya şəhəri, hamam bədəni, kitabxana isə ruhu təmizləyir.","— Fateh Sultan Mehmedə aid edilən söz","İbrət: Şəhərin və bədənin təmizliyinə olduğu qədər insanın mənəvi dünyasına da qayğı göstərmək lazımdır. Kitab düşüncəni aydınlaşdırır, insanın özünə və dünyaya daha dərindən baxmasına kömək edir."]}]}]};
